class Boundary16Element final : public rti::DataElement {
 public:
  std::unique_ptr<rti::DataElement> clone() const override {
    return std::make_unique<Boundary16Element>();
  }

  rti::VariableLengthData encode() const override {
    rti::VariableLengthData value;
    encode(value);
    return value;
  }

  void encode(rti::VariableLengthData& value) const override {
    std::vector<rti::Octet> bytes(
        16U,
        static_cast<rti::Octet>(0U));
    value.setData(bytes.data(), bytes.size());
  }

  void encodeInto(std::vector<rti::Octet>& bytes) const override {
    bytes.insert(
        bytes.end(),
        16U,
        static_cast<rti::Octet>(0U));
  }

  Boundary16Element& decode(
      rti::VariableLengthData const& value) override {
    if (value.size() != 16U) {
      throw rti::EncoderException(
          L"Boundary16Element has an invalid encoding length.");
    }
    return *this;
  }

  std::size_t decodeFrom(
      std::vector<rti::Octet> const& bytes,
      std::size_t index) override {
    if (index > bytes.size() || bytes.size() - index < 16U) {
      throw rti::EncoderException(
          L"Boundary16Element encoding is truncated.");
    }
    return index + 16U;
  }

  std::size_t getEncodedLength() const override {
    return 16U;
  }

  unsigned int getOctetBoundary() const override {
    return 16U;
  }
};

constexpr std::size_t portableLogicalTimeEncodingSize = sizeof(std::uint64_t);

std::vector<rti::Octet> encodePortableLogicalTimeValue(std::int64_t value) {
  auto const bits = static_cast<std::uint64_t>(value);
  std::vector<rti::Octet> bytes(portableLogicalTimeEncodingSize);
  for (std::size_t index = 0U; index < bytes.size(); ++index) {
    auto const shift = static_cast<unsigned int>(
        (bytes.size() - index - 1U) * 8U);
    bytes[index] = static_cast<rti::Octet>((bits >> shift) & 0xffU);
  }
  return bytes;
}

std::int64_t decodePortableLogicalTimeValue(std::uint8_t const* bytes) {
  std::uint64_t bits = 0U;
  for (std::size_t index = 0U; index < portableLogicalTimeEncodingSize; ++index) {
    bits = (bits << 8U) | static_cast<std::uint64_t>(bytes[index]);
  }
  return static_cast<std::int64_t>(bits);
}

class PortableLogicalTimeInterval;

class PortableLogicalTime final : public rti::LogicalTime {
 public:
  PortableLogicalTime() = default;
  explicit PortableLogicalTime(std::int64_t value) : value_(value) {}

  void setInitial() override { value_ = 0; }
  bool isInitial() const override { return value_ == 0; }
  void setFinal() override { value_ = std::numeric_limits<std::int64_t>::max(); }
  bool isFinal() const override {
    return value_ == std::numeric_limits<std::int64_t>::max();
  }

  PortableLogicalTime& operator=(rti::LogicalTime const& value) override;
  PortableLogicalTime& operator+=(
      rti::LogicalTimeInterval const& addend) override;
  PortableLogicalTime& operator-=(
      rti::LogicalTimeInterval const& subtrahend) override;
  bool operator>(rti::LogicalTime const& value) const override;
  bool operator<(rti::LogicalTime const& value) const override;
  bool operator==(rti::LogicalTime const& value) const override;
  bool operator>=(rti::LogicalTime const& value) const override;
  bool operator<=(rti::LogicalTime const& value) const override;

  rti::VariableLengthData encode() const override {
    auto const bytes = encodePortableLogicalTimeValue(value_);
    return rti::VariableLengthData(bytes.data(), bytes.size());
  }

  std::size_t encode(void* buffer, std::size_t bufferSize) const override {
    if (buffer == nullptr || bufferSize < portableLogicalTimeEncodingSize) {
      throw rti::CouldNotEncode(L"PortableLogicalTime output buffer is too small.");
    }
    auto const bytes = encodePortableLogicalTimeValue(value_);
    auto* output = static_cast<rti::Octet*>(buffer);
    std::copy(bytes.begin(), bytes.end(), output);
    return bytes.size();
  }

  std::size_t encodedLength() const override {
    return portableLogicalTimeEncodingSize;
  }

  void decode(rti::VariableLengthData const& encodedLogicalTime) override {
    if (encodedLogicalTime.size() != portableLogicalTimeEncodingSize) {
      throw rti::CouldNotDecode(L"PortableLogicalTime encoding has the wrong length.");
    }
    value_ = decodePortableLogicalTimeValue(
        static_cast<std::uint8_t const*>(encodedLogicalTime.data()));
  }

  void decode(void const* buffer, std::size_t bufferSize) override {
    if (buffer == nullptr || bufferSize != portableLogicalTimeEncodingSize) {
      throw rti::CouldNotDecode(L"PortableLogicalTime input buffer has the wrong length.");
    }
    value_ = decodePortableLogicalTimeValue(
        static_cast<std::uint8_t const*>(buffer));
  }

  std::wstring toString() const override { return std::to_wstring(value_); }
  std::wstring implementationName() const override {
    return L"PortableLogicalTime";
  }
  std::int64_t value() const { return value_; }

 private:
  std::int64_t value_ = 0;
};

class PortableLogicalTimeInterval final : public rti::LogicalTimeInterval {
 public:
  PortableLogicalTimeInterval() = default;
  explicit PortableLogicalTimeInterval(std::int64_t value) : value_(value) {}

  void setZero() override { value_ = 0; }
  bool isZero() const override { return value_ == 0; }
  void setEpsilon() override { value_ = 1; }
  bool isEpsilon() const override { return value_ == 1; }

  PortableLogicalTimeInterval& operator=(
      rti::LogicalTimeInterval const& value) override;
  PortableLogicalTimeInterval& operator+=(
      rti::LogicalTimeInterval const& addend) override;
  PortableLogicalTimeInterval& operator-=(
      rti::LogicalTimeInterval const& subtrahend) override;
  bool operator>(rti::LogicalTimeInterval const& value) const override;
  bool operator<(rti::LogicalTimeInterval const& value) const override;
  bool operator==(rti::LogicalTimeInterval const& value) const override;
  bool operator>=(rti::LogicalTimeInterval const& value) const override;
  bool operator<=(rti::LogicalTimeInterval const& value) const override;
  void setToDifference(
      rti::LogicalTime const& minuend,
      rti::LogicalTime const& subtrahend) override;

  rti::VariableLengthData encode() const override {
    auto const bytes = encodePortableLogicalTimeValue(value_);
    return rti::VariableLengthData(bytes.data(), bytes.size());
  }

  std::size_t encode(void* buffer, std::size_t bufferSize) const override {
    if (buffer == nullptr || bufferSize < portableLogicalTimeEncodingSize) {
      throw rti::CouldNotEncode(
          L"PortableLogicalTimeInterval output buffer is too small.");
    }
    auto const bytes = encodePortableLogicalTimeValue(value_);
    auto* output = static_cast<rti::Octet*>(buffer);
    std::copy(bytes.begin(), bytes.end(), output);
    return bytes.size();
  }

  std::size_t encodedLength() const override {
    return portableLogicalTimeEncodingSize;
  }

  void decode(rti::VariableLengthData const& encodedValue) override {
    if (encodedValue.size() != portableLogicalTimeEncodingSize) {
      throw rti::CouldNotDecode(
          L"PortableLogicalTimeInterval encoding has the wrong length.");
    }
    value_ = decodePortableLogicalTimeValue(
        static_cast<std::uint8_t const*>(encodedValue.data()));
  }

  void decode(void const* buffer, std::size_t bufferSize) override {
    if (buffer == nullptr || bufferSize != portableLogicalTimeEncodingSize) {
      throw rti::CouldNotDecode(
          L"PortableLogicalTimeInterval input buffer has the wrong length.");
    }
    value_ = decodePortableLogicalTimeValue(
        static_cast<std::uint8_t const*>(buffer));
  }

  std::wstring toString() const override { return std::to_wstring(value_); }
  std::wstring implementationName() const override {
    return L"PortableLogicalTime";
  }
  std::int64_t value() const { return value_; }

 private:
  std::int64_t value_ = 0;
};

std::int64_t portableLogicalTimeValue(rti::LogicalTime const& value) {
  auto const* typed = dynamic_cast<PortableLogicalTime const*>(&value);
  if (typed == nullptr) {
    throw rti::InvalidLogicalTime(L"PortableLogicalTime received an incompatible value.");
  }
  return typed->value();
}

std::int64_t portableLogicalTimeIntervalValue(
    rti::LogicalTimeInterval const& value) {
  auto const* typed = dynamic_cast<PortableLogicalTimeInterval const*>(&value);
  if (typed == nullptr) {
    throw rti::InvalidLogicalTimeInterval(
        L"PortableLogicalTimeInterval received an incompatible value.");
  }
  return typed->value();
}

PortableLogicalTime& PortableLogicalTime::operator=(
    rti::LogicalTime const& value) {
  value_ = portableLogicalTimeValue(value);
  return *this;
}

PortableLogicalTime& PortableLogicalTime::operator+=(
    rti::LogicalTimeInterval const& addend) {
  value_ += portableLogicalTimeIntervalValue(addend);
  return *this;
}

PortableLogicalTime& PortableLogicalTime::operator-=(
    rti::LogicalTimeInterval const& subtrahend) {
  value_ -= portableLogicalTimeIntervalValue(subtrahend);
  return *this;
}

bool PortableLogicalTime::operator>(rti::LogicalTime const& value) const {
  return value_ > portableLogicalTimeValue(value);
}

bool PortableLogicalTime::operator<(rti::LogicalTime const& value) const {
  return value_ < portableLogicalTimeValue(value);
}

bool PortableLogicalTime::operator==(rti::LogicalTime const& value) const {
  return value_ == portableLogicalTimeValue(value);
}

bool PortableLogicalTime::operator>=(rti::LogicalTime const& value) const {
  return value_ >= portableLogicalTimeValue(value);
}

bool PortableLogicalTime::operator<=(rti::LogicalTime const& value) const {
  return value_ <= portableLogicalTimeValue(value);
}

PortableLogicalTimeInterval& PortableLogicalTimeInterval::operator=(
    rti::LogicalTimeInterval const& value) {
  value_ = portableLogicalTimeIntervalValue(value);
  return *this;
}

PortableLogicalTimeInterval& PortableLogicalTimeInterval::operator+=(
    rti::LogicalTimeInterval const& addend) {
  value_ += portableLogicalTimeIntervalValue(addend);
  return *this;
}

PortableLogicalTimeInterval& PortableLogicalTimeInterval::operator-=(
    rti::LogicalTimeInterval const& subtrahend) {
  value_ -= portableLogicalTimeIntervalValue(subtrahend);
  return *this;
}

bool PortableLogicalTimeInterval::operator>(
    rti::LogicalTimeInterval const& value) const {
  return value_ > portableLogicalTimeIntervalValue(value);
}

bool PortableLogicalTimeInterval::operator<(
    rti::LogicalTimeInterval const& value) const {
  return value_ < portableLogicalTimeIntervalValue(value);
}

bool PortableLogicalTimeInterval::operator==(
    rti::LogicalTimeInterval const& value) const {
  return value_ == portableLogicalTimeIntervalValue(value);
}

bool PortableLogicalTimeInterval::operator>= (
    rti::LogicalTimeInterval const& value) const {
  return value_ >= portableLogicalTimeIntervalValue(value);
}

bool PortableLogicalTimeInterval::operator<= (
    rti::LogicalTimeInterval const& value) const {
  return value_ <= portableLogicalTimeIntervalValue(value);
}

void PortableLogicalTimeInterval::setToDifference(
    rti::LogicalTime const& minuend,
    rti::LogicalTime const& subtrahend) {
  value_ = portableLogicalTimeValue(minuend) -
           portableLogicalTimeValue(subtrahend);
}

class PortableLogicalTimeFactory final : public rti::LogicalTimeFactory {
 public:
  std::unique_ptr<rti::LogicalTime> makeInitial() override {
    return std::make_unique<PortableLogicalTime>();
  }
  std::unique_ptr<rti::LogicalTime> makeFinal() override {
    auto result = std::make_unique<PortableLogicalTime>();
    result->setFinal();
    return result;
  }
  std::unique_ptr<rti::LogicalTimeInterval> makeZero() override {
    return std::make_unique<PortableLogicalTimeInterval>();
  }
  std::unique_ptr<rti::LogicalTimeInterval> makeEpsilon() override {
    auto result = std::make_unique<PortableLogicalTimeInterval>();
    result->setEpsilon();
    return result;
  }
  std::unique_ptr<rti::LogicalTime> decodeLogicalTime(
      rti::VariableLengthData const& encodedLogicalTime) override {
    auto result = std::make_unique<PortableLogicalTime>();
    result->decode(encodedLogicalTime);
    return result;
  }
  std::unique_ptr<rti::LogicalTime> decodeLogicalTime(
      void const* buffer,
      std::size_t bufferSize) override {
    auto result = std::make_unique<PortableLogicalTime>();
    result->decode(buffer, bufferSize);
    return result;
  }
  std::unique_ptr<rti::LogicalTimeInterval> decodeLogicalTimeInterval(
      rti::VariableLengthData const& encodedValue) override {
    auto result = std::make_unique<PortableLogicalTimeInterval>();
    result->decode(encodedValue);
    return result;
  }
  std::unique_ptr<rti::LogicalTimeInterval> decodeLogicalTimeInterval(
      void const* buffer,
      std::size_t bufferSize) override {
    auto result = std::make_unique<PortableLogicalTimeInterval>();
    result->decode(buffer, bufferSize);
    return result;
  }
  std::wstring getName() const override { return L"PortableLogicalTime"; }
};

std::size_t adoptedDataDeleteCount = 0U;

void deleteAdoptedData(void* data) {
  ++adoptedDataDeleteCount;
  delete[] static_cast<rti::Octet*>(data);
}

