void scenarioTransportOrder(Options const& options, rti::CallbackModel model) {
  Session owner(options, model, "owner");
  Session observer(options, model, "member");
  auto const federation = federationName(options, "transport-order");
  connectAndJoin(owner, observer, options, federation, options.fom);

  rti::ObjectClassHandle ownerClass;
  rti::AttributeHandle ownerAttribute;
  rti::InteractionClassHandle ownerInteraction;
  rti::ParameterHandle ownerParameter;
  handles(owner, options, ownerClass, ownerAttribute, ownerInteraction, ownerParameter);
  auto const observerClass = observer.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const observerAttribute = observer.rtiAmbassador().getAttributeHandle(
      observerClass, options.attributeName);
  auto const observerInteraction = observer.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  require(observerClass.isValid() && observerAttribute.isValid() &&
              observerInteraction.isValid(),
          "Transport/order observer lookup returned an invalid handle");
  auto const reliable = owner.rtiAmbassador().getTransportationTypeHandle(L"HLAreliable");
  auto const bestEffort = owner.rtiAmbassador().getTransportationTypeHandle(L"HLAbestEffort");
  require(reliable.isValid() && bestEffort.isValid(),
          "Transport/order lookup did not return the standard transportation handles");

  rti::AttributeHandleSet ownerAttributes;
  ownerAttributes.insert(ownerAttribute);
  rti::AttributeHandleSet observerAttributes;
  observerAttributes.insert(observerAttribute);
  rti::ObjectClassHandle const invalidObjectClass;
  rti::ObjectInstanceHandle const invalidObject;
  rti::InteractionClassHandle const invalidInteraction;
  rti::AttributeHandleSet const invalidAttributes{rti::AttributeHandle{}};
  rti::TransportationTypeHandle const invalidTransportation;
  requireException(
      [&] {
        owner.rtiAmbassador().changeDefaultAttributeOrderType(
            invalidObjectClass,
            ownerAttributes,
            rti::RECEIVE);
      },
      L"ObjectClassNotDefined",
      "default attribute order change with an invalid object class");
  requireException(
      [&] {
        owner.rtiAmbassador().changeDefaultAttributeOrderType(
            ownerClass,
            invalidAttributes,
            rti::RECEIVE);
      },
      L"AttributeNotDefined",
      "default attribute order change with an invalid attribute");
  requireException(
      [&] {
        owner.rtiAmbassador().changeDefaultAttributeTransportationType(
            invalidObjectClass,
            ownerAttributes,
            bestEffort);
      },
      L"ObjectClassNotDefined",
      "default attribute transportation change with an invalid object class");
  requireException(
      [&] {
        owner.rtiAmbassador().changeDefaultAttributeTransportationType(
            ownerClass,
            invalidAttributes,
            bestEffort);
      },
      L"AttributeNotDefined",
      "default attribute transportation change with an invalid attribute");
  requireException(
      [&] {
        owner.rtiAmbassador().changeDefaultAttributeTransportationType(
            ownerClass,
            ownerAttributes,
            invalidTransportation);
      },
      L"InvalidTransportationTypeHandle",
      "default attribute transportation change with an invalid transportation handle");
  requireException(
      [&] {
        owner.rtiAmbassador().requestAttributeTransportationTypeChange(
            invalidObject,
            ownerAttributes,
            bestEffort);
      },
      L"ObjectInstanceNotKnown",
      "attribute transportation change for an unknown object");
  requireException(
      [&] {
        owner.rtiAmbassador().queryAttributeTransportationType(
            invalidObject,
            ownerAttribute);
      },
      L"ObjectInstanceNotKnown",
      "attribute transportation query for an unknown object");
  requireException(
      [&] { owner.rtiAmbassador().changeInteractionOrderType(invalidInteraction, rti::RECEIVE); },
      L"InteractionClassNotDefined",
      "interaction order change with an invalid interaction class");
  requireException(
      [&] {
        owner.rtiAmbassador().requestInteractionTransportationTypeChange(
            invalidInteraction,
            bestEffort);
      },
      L"InteractionClassNotDefined",
      "interaction transportation change with an invalid interaction class");
  requireException(
      [&] {
        owner.rtiAmbassador().queryInteractionTransportationType(
            owner.federateHandle(),
            invalidInteraction);
      },
      L"InteractionClassNotDefined",
      "interaction transportation query with an invalid interaction class");
  owner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerAttributes);
  observer.rtiAmbassador().subscribeObjectClassAttributes(
      observerClass, observerAttributes, true, L"");
  requireException(
      [&] {
        owner.rtiAmbassador().changeInteractionOrderType(
            ownerInteraction, rti::RECEIVE);
      },
      L"InteractionClassNotPublished",
      "unpublished interaction order change");
  owner.rtiAmbassador().publishInteractionClass(ownerInteraction);
  observer.rtiAmbassador().subscribeInteractionClass(observerInteraction, true);
  requireException(
      [&] {
        owner.rtiAmbassador().requestInteractionTransportationTypeChange(
            ownerInteraction,
            invalidTransportation);
      },
      L"InvalidTransportationTypeHandle",
      "published interaction transportation change with an invalid transportation handle");

  owner.rtiAmbassador().changeDefaultAttributeOrderType(
      ownerClass, ownerAttributes, rti::RECEIVE);
  auto const first = owner.rtiAmbassador().registerObjectInstance(ownerClass);
  require(first.isValid(), "Transport/order first registration returned an invalid handle");
  requireException(
      [&] {
        owner.rtiAmbassador().changeAttributeOrderType(
            invalidObject,
            ownerAttributes,
            rti::RECEIVE);
      },
      L"ObjectInstanceNotKnown",
      "per-instance attribute order change with an unknown object");
  requireException(
      [&] {
        owner.rtiAmbassador().changeAttributeOrderType(
            first,
            invalidAttributes,
            rti::TIMESTAMP);
      },
      L"AttributeNotDefined",
      "per-instance attribute order change with an invalid attribute");
  requireException(
      [&] {
        owner.rtiAmbassador().requestAttributeTransportationTypeChange(
            first,
            invalidAttributes,
            bestEffort);
      },
      L"AttributeNotDefined",
      "attribute transportation change with an invalid attribute");
  requireException(
      [&] {
        owner.rtiAmbassador().requestAttributeTransportationTypeChange(
            first,
            ownerAttributes,
            invalidTransportation);
      },
      L"InvalidTransportationTypeHandle",
      "attribute transportation change with an invalid transportation handle");
  requireException(
      [&] {
        owner.rtiAmbassador().queryAttributeTransportationType(
            first,
            rti::AttributeHandle{});
      },
      L"AttributeNotDefined",
      "attribute transportation query with an invalid attribute");
  owner.rtiAmbassador().changeAttributeOrderType(
      first, ownerAttributes, rti::TIMESTAMP);
  owner.rtiAmbassador().changeAttributeOrderType(
      first, ownerAttributes, rti::RECEIVE);
  owner.rtiAmbassador().changeInteractionOrderType(ownerInteraction, rti::TIMESTAMP);
  owner.rtiAmbassador().changeInteractionOrderType(ownerInteraction, rti::RECEIVE);

  owner.rtiAmbassador().changeDefaultAttributeTransportationType(
      ownerClass, ownerAttributes, bestEffort);
  auto const second = owner.rtiAmbassador().registerObjectInstance(ownerClass);
  require(second.isValid(), "Transport/order second registration returned an invalid handle");
  waitFor(observer,
          [&] {
            return observer.recorder().hasDiscovery(first) &&
                observer.recorder().hasDiscovery(second);
          },
          options,
          "transport/order object discovery");

  auto sameTransport = [](rti::RTIambassador& inspector,
                          rti::TransportationTypeHandle const& actual,
                          std::wstring const& expectedName) {
    return actual.isValid() &&
        inspector.getTransportationTypeName(actual) == expectedName;
  };

  owner.recorder().clearTransportationRecords();
  owner.rtiAmbassador().queryAttributeTransportationType(first, ownerAttribute);
  owner.rtiAmbassador().queryAttributeTransportationType(second, ownerAttribute);
  waitFor(owner,
          [&] { return owner.recorder().attributeTransportationReports().size() >= 2U; },
          options,
          "attribute transportation query reports");
  auto const attributeReports = owner.recorder().attributeTransportationReports();
  auto const firstReport = std::find_if(
      attributeReports.begin(), attributeReports.end(), [&](auto const& report) {
        return report.object == first && report.attribute == ownerAttribute;
      });
  auto const secondReport = std::find_if(
      attributeReports.begin(), attributeReports.end(), [&](auto const& report) {
        return report.object == second && report.attribute == ownerAttribute;
      });
  require(firstReport != attributeReports.end() && secondReport != attributeReports.end(),
          "Attribute transportation query reports omitted a registered object");
  require(sameTransport(owner.rtiAmbassador(), firstReport->transportation, L"HLAreliable"),
          "first object did not retain the reliable transportation default");
  require(sameTransport(owner.rtiAmbassador(), secondReport->transportation, L"HLAbestEffort"),
          "second object did not capture the best-effort class default");

  owner.recorder().clearTransportationRecords();
  observer.recorder().clearReflection();
  owner.rtiAmbassador().requestAttributeTransportationTypeChange(
      first, ownerAttributes, bestEffort);
  if (model == rti::HLA_EVOKED) {
    requireException(
        [&] {
          owner.rtiAmbassador().requestAttributeTransportationTypeChange(
              first, ownerAttributes, reliable);
        },
        L"AttributeAlreadyBeingChanged",
        "duplicate attribute transportation request");
  } else {
    waitFor(owner,
            [&] {
              return owner.recorder().attributeTransportationConfirmations().size() >= 1U;
            },
            options,
            "immediate attribute transportation confirmation");
  }
  std::vector<std::uint8_t> beforeValueBytes{0x01U};
  std::vector<std::uint8_t> beforeTagBytes{0x01U};
  rti::AttributeHandleValueMap beforeValues;
  beforeValues.emplace(
      ownerAttribute,
      rti::VariableLengthData(beforeValueBytes.data(), beforeValueBytes.size()));
  rti::VariableLengthData beforeTag(beforeTagBytes.data(), beforeTagBytes.size());
  owner.rtiAmbassador().updateAttributeValues(first, beforeValues, beforeTag);
  waitFor(observer,
          [&] { return observer.recorder().reflection().present; },
          options,
          "pre-confirmation attribute update");
  auto const beforeReflection = observer.recorder().reflection();
  require(beforeReflection.object == first &&
              sameTransport(observer.rtiAmbassador(), beforeReflection.transportation,
                            model == rti::HLA_EVOKED ? L"HLAreliable" : L"HLAbestEffort"),
          model == rti::HLA_EVOKED
              ? "pre-confirmation attribute update did not use reliable transport"
              : "immediate attribute transport change did not use best-effort transport");
  waitFor(owner,
          [&] {
            return owner.recorder().attributeTransportationConfirmations().size() >= 1U;
          },
          options,
          "attribute transportation confirmation");
  auto const attributeConfirmations = owner.recorder().attributeTransportationConfirmations();
  auto const& attributeConfirmation = attributeConfirmations.back();
  require(attributeConfirmation.object == first &&
              attributeConfirmation.attributes.count(ownerAttribute) == 1U &&
              sameTransport(owner.rtiAmbassador(), attributeConfirmation.transportation,
                            L"HLAbestEffort"),
          "attribute transportation confirmation did not commit best effort");

  observer.recorder().clearReflection();
  std::vector<std::uint8_t> afterValueBytes{0x02U};
  std::vector<std::uint8_t> afterTagBytes{0x02U};
  rti::AttributeHandleValueMap afterValues;
  afterValues.emplace(
      ownerAttribute,
      rti::VariableLengthData(afterValueBytes.data(), afterValueBytes.size()));
  rti::VariableLengthData afterTag(afterTagBytes.data(), afterTagBytes.size());
  owner.rtiAmbassador().updateAttributeValues(first, afterValues, afterTag);
  waitFor(observer,
          [&] { return observer.recorder().reflection().present; },
          options,
          "post-confirmation attribute update");
  auto const afterReflection = observer.recorder().reflection();
  require(afterReflection.object == first &&
              sameTransport(observer.rtiAmbassador(), afterReflection.transportation,
                            L"HLAbestEffort"),
          "post-confirmation attribute update did not use best-effort transport");
  owner.recorder().clearTransportationRecords();
  owner.rtiAmbassador().queryAttributeTransportationType(first, ownerAttribute);
  waitFor(owner,
          [&] { return owner.recorder().attributeTransportationReports().size() >= 1U; },
          options,
          "final attribute transportation query");
  require(sameTransport(
              owner.rtiAmbassador(),
              owner.recorder().attributeTransportationReports().back().transportation,
              L"HLAbestEffort"),
          "attribute transportation query did not observe the committed change");

  owner.recorder().clearTransportationRecords();
  observer.recorder().clearInteraction();
  owner.rtiAmbassador().requestInteractionTransportationTypeChange(
      ownerInteraction, bestEffort);
  if (model == rti::HLA_EVOKED) {
    requireException(
        [&] {
          owner.rtiAmbassador().requestInteractionTransportationTypeChange(
              ownerInteraction, reliable);
        },
        L"InteractionClassAlreadyBeingChanged",
        "duplicate interaction transportation request");
  } else {
    waitFor(owner,
            [&] {
              return owner.recorder().interactionTransportationConfirmations().size() >= 1U;
            },
            options,
            "immediate interaction transportation confirmation");
  }
  std::vector<std::uint8_t> interactionBeforeTagBytes{0x03U};
  rti::VariableLengthData interactionBeforeTag(
      interactionBeforeTagBytes.data(), interactionBeforeTagBytes.size());
  owner.rtiAmbassador().sendInteraction(
      ownerInteraction, rti::ParameterHandleValueMap{}, interactionBeforeTag);
  waitFor(observer,
          [&] { return observer.recorder().interaction().present; },
          options,
          "pre-confirmation interaction delivery");
  auto const interactionBefore = observer.recorder().interaction();
  require(sameTransport(observer.rtiAmbassador(), interactionBefore.transportation,
                        model == rti::HLA_EVOKED ? L"HLAreliable" : L"HLAbestEffort"),
          model == rti::HLA_EVOKED
              ? "pre-confirmation interaction did not use reliable transport"
              : "immediate interaction transport change did not use best-effort transport");
  waitFor(owner,
          [&] {
            return owner.recorder().interactionTransportationConfirmations().size() >= 1U;
          },
          options,
          "interaction transportation confirmation");
  auto const interactionConfirmations =
      owner.recorder().interactionTransportationConfirmations();
  auto const& interactionConfirmation = interactionConfirmations.back();
  require(interactionConfirmation.interaction == ownerInteraction &&
              sameTransport(owner.rtiAmbassador(), interactionConfirmation.transportation,
                            L"HLAbestEffort"),
          "interaction transportation confirmation did not commit best effort");

  observer.recorder().clearInteraction();
  std::vector<std::uint8_t> interactionAfterTagBytes{0x04U};
  rti::VariableLengthData interactionAfterTag(
      interactionAfterTagBytes.data(), interactionAfterTagBytes.size());
  owner.rtiAmbassador().sendInteraction(
      ownerInteraction, rti::ParameterHandleValueMap{}, interactionAfterTag);
  waitFor(observer,
          [&] { return observer.recorder().interaction().present; },
          options,
          "post-confirmation interaction delivery");
  auto const interactionAfter = observer.recorder().interaction();
  require(sameTransport(observer.rtiAmbassador(), interactionAfter.transportation,
                        L"HLAbestEffort"),
          "post-confirmation interaction did not use best-effort transport");
  owner.recorder().clearTransportationRecords();
  owner.rtiAmbassador().queryInteractionTransportationType(
      owner.federateHandle(), ownerInteraction);
  waitFor(owner,
          [&] { return owner.recorder().interactionTransportationReports().size() >= 1U; },
          options,
          "interaction transportation query");
  auto const interactionReports = owner.recorder().interactionTransportationReports();
  auto const& interactionReport = interactionReports.back();
  require(interactionReport.federate == owner.federateHandle() &&
              interactionReport.interaction == ownerInteraction &&
              sameTransport(owner.rtiAmbassador(), interactionReport.transportation,
                            L"HLAbestEffort"),
          "interaction transportation query did not observe the committed change");

  observer.rtiAmbassador().unsubscribeInteractionClass(observerInteraction);
  observer.rtiAmbassador().unsubscribeObjectClassAttributes(
      observerClass, observerAttributes);
  owner.rtiAmbassador().unpublishInteractionClass(ownerInteraction);
  owner.rtiAmbassador().unpublishObjectClassAttributes(ownerClass, ownerAttributes);
  owner.rtiAmbassador().unpublishObjectClass(ownerClass);
  owner.resign(rti::DELETE_OBJECTS);
  observer.resign(rti::NO_ACTION);
}

void scenarioRelevanceAdvisories(Options const& options, rti::CallbackModel model) {
  Session switchLifecycle(options, model, "support-switch-lifecycle");
  auto checkBooleanSwitchLifecycle = [&](auto getter,
                                         auto setter,
                                         std::wstring const& expected,
                                         std::string const& phase,
                                         std::string const& description) {
    requireException(
        [&] { static_cast<void>(getter()); },
        expected,
        "getting the " + description + " " + phase);
    requireException(
        [&] { setter(false); },
        expected,
        "setting the " + description + " " + phase);
  };
  auto checkReadOnlySwitchLifecycle = [&](auto getter,
                                          std::wstring const& expected,
                                          std::string const& phase,
                                          std::string const& description) {
    requireException(
        [&] { static_cast<void>(getter()); },
        expected,
        "getting the " + description + " " + phase);
  };
  auto checkSwitchLifecycle = [&](std::wstring const& expected,
                                  std::string const& phase) {
    checkBooleanSwitchLifecycle(
        [&] { return switchLifecycle.rtiAmbassador().getObjectClassRelevanceAdvisorySwitch(); },
        [&](bool value) {
          switchLifecycle.rtiAmbassador().setObjectClassRelevanceAdvisorySwitch(value);
        },
        expected,
        phase,
        "object-class relevance advisory switch");
    checkBooleanSwitchLifecycle(
        [&] { return switchLifecycle.rtiAmbassador().getAttributeRelevanceAdvisorySwitch(); },
        [&](bool value) {
          switchLifecycle.rtiAmbassador().setAttributeRelevanceAdvisorySwitch(value);
        },
        expected,
        phase,
        "attribute relevance advisory switch");
    checkBooleanSwitchLifecycle(
        [&] { return switchLifecycle.rtiAmbassador().getAttributeScopeAdvisorySwitch(); },
        [&](bool value) {
          switchLifecycle.rtiAmbassador().setAttributeScopeAdvisorySwitch(value);
        },
        expected,
        phase,
        "attribute scope advisory switch");
    checkBooleanSwitchLifecycle(
        [&] { return switchLifecycle.rtiAmbassador().getInteractionRelevanceAdvisorySwitch(); },
        [&](bool value) {
          switchLifecycle.rtiAmbassador().setInteractionRelevanceAdvisorySwitch(value);
        },
        expected,
        phase,
        "interaction relevance advisory switch");
    checkBooleanSwitchLifecycle(
        [&] { return switchLifecycle.rtiAmbassador().getConveyRegionDesignatorSetsSwitch(); },
        [&](bool value) {
          switchLifecycle.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(value);
        },
        expected,
        phase,
        "convey-region-designator-sets switch");
    requireException(
        [&] {
          static_cast<void>(switchLifecycle.rtiAmbassador().getAutomaticResignDirective());
        },
        expected,
        "getting the automatic resign directive " + phase);
    requireException(
        [&] {
          switchLifecycle.rtiAmbassador().setAutomaticResignDirective(rti::NO_ACTION);
        },
        expected,
        "setting the automatic resign directive " + phase);
    checkBooleanSwitchLifecycle(
        [&] { return switchLifecycle.rtiAmbassador().getServiceReportingSwitch(); },
        [&](bool value) { switchLifecycle.rtiAmbassador().setServiceReportingSwitch(value); },
        expected,
        phase,
        "service-reporting switch");
    checkBooleanSwitchLifecycle(
        [&] { return switchLifecycle.rtiAmbassador().getExceptionReportingSwitch(); },
        [&](bool value) { switchLifecycle.rtiAmbassador().setExceptionReportingSwitch(value); },
        expected,
        phase,
        "exception-reporting switch");
    checkBooleanSwitchLifecycle(
        [&] { return switchLifecycle.rtiAmbassador().getSendServiceReportsToFileSwitch(); },
        [&](bool value) {
          switchLifecycle.rtiAmbassador().setSendServiceReportsToFileSwitch(value);
        },
        expected,
        phase,
        "send-service-reports-to-file switch");
    checkReadOnlySwitchLifecycle(
        [&] { return switchLifecycle.rtiAmbassador().getAutoProvideSwitch(); },
        expected,
        phase,
        "auto-provide switch");
    checkReadOnlySwitchLifecycle(
        [&] { return switchLifecycle.rtiAmbassador().getDelaySubscriptionEvaluationSwitch(); },
        expected,
        phase,
        "delay-subscription-evaluation switch");
    checkReadOnlySwitchLifecycle(
        [&] { return switchLifecycle.rtiAmbassador().getAdvisoriesUseKnownClassSwitch(); },
        expected,
        phase,
        "advisories-use-known-class switch");
    checkReadOnlySwitchLifecycle(
        [&] { return switchLifecycle.rtiAmbassador().getAllowRelaxedDDMSwitch(); },
        expected,
        phase,
        "allow-relaxed-DDM switch");
    checkReadOnlySwitchLifecycle(
        [&] { return switchLifecycle.rtiAmbassador().getNonRegulatedGrantSwitch(); },
        expected,
        phase,
        "non-regulated-grant switch");
  };
  checkSwitchLifecycle(L"NotConnected", "before connect");
  switchLifecycle.connect();
  checkSwitchLifecycle(
      L"FederateNotExecutionMember",
      "after connect before joining an execution");
  switchLifecycle.disconnect();

  Session publisher(options, model, "owner");
  Session subscriber(options, model, "member");
  auto const federation = federationName(options, "relevance-advisories");
  connectAndJoin(publisher, subscriber, options, federation, options.fom);

  auto const publisherClass = publisher.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const subscriberClass = subscriber.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const publisherName = publisher.rtiAmbassador().getAttributeHandle(
      publisherClass, L"Name");
  auto const publisherPayRate = publisher.rtiAmbassador().getAttributeHandle(
      publisherClass, L"PayRate");
  auto const publisherAttribute = publisher.rtiAmbassador().getAttributeHandle(
      publisherClass, options.attributeName);
  auto const subscriberName = subscriber.rtiAmbassador().getAttributeHandle(
      subscriberClass, L"Name");
  auto const subscriberPayRate = subscriber.rtiAmbassador().getAttributeHandle(
      subscriberClass, L"PayRate");
  auto const subscriberAttribute = subscriber.rtiAmbassador().getAttributeHandle(
      subscriberClass, options.attributeName);
  require(publisherClass.isValid() && subscriberClass.isValid() &&
              publisherName.isValid() && publisherPayRate.isValid() &&
              publisherAttribute.isValid() && subscriberName.isValid() &&
              subscriberPayRate.isValid() && subscriberAttribute.isValid(),
          "Relevance advisory attribute lookup returned an invalid handle");

  rti::AttributeHandleSet publisherNameSet;
  publisherNameSet.insert(publisherName);
  rti::AttributeHandleSet publisherAllSet;
  publisherAllSet.insert(publisherName);
  publisherAllSet.insert(publisherPayRate);
  publisherAllSet.insert(publisherAttribute);
  rti::AttributeHandleSet subscriberNameSet;
  subscriberNameSet.insert(subscriberName);
  rti::AttributeHandleSet subscriberPayRateSet;
  subscriberPayRateSet.insert(subscriberPayRate);
  rti::AttributeHandleSet subscriberAttributeSet;
  subscriberAttributeSet.insert(subscriberAttribute);

  auto const publisherInteraction = publisher.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const subscriberInteraction = subscriber.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  require(publisherInteraction.isValid() && subscriberInteraction.isValid(),
          "Relevance advisory interaction lookup returned an invalid handle");

  auto roundTripBooleanSwitch = [&](auto getter, auto setter,
                                    std::string const& description) {
    auto const original = getter();
    setter(false);
    require(!getter(), description + " did not turn off");
    setter(true);
    require(getter(), description + " did not turn on");
    setter(original);
    require(getter() == original, description + " did not restore its state");
  };
  roundTripBooleanSwitch(
      [&] { return publisher.rtiAmbassador().getObjectClassRelevanceAdvisorySwitch(); },
      [&](bool value) {
        publisher.rtiAmbassador().setObjectClassRelevanceAdvisorySwitch(value);
      },
      "object-class relevance advisory switch");
  roundTripBooleanSwitch(
      [&] { return publisher.rtiAmbassador().getAttributeRelevanceAdvisorySwitch(); },
      [&](bool value) {
        publisher.rtiAmbassador().setAttributeRelevanceAdvisorySwitch(value);
      },
      "attribute relevance advisory switch");
  roundTripBooleanSwitch(
      [&] { return publisher.rtiAmbassador().getAttributeScopeAdvisorySwitch(); },
      [&](bool value) {
        publisher.rtiAmbassador().setAttributeScopeAdvisorySwitch(value);
      },
      "attribute scope advisory switch");
  roundTripBooleanSwitch(
      [&] { return publisher.rtiAmbassador().getInteractionRelevanceAdvisorySwitch(); },
      [&](bool value) {
        publisher.rtiAmbassador().setInteractionRelevanceAdvisorySwitch(value);
      },
      "interaction relevance advisory switch");
  roundTripBooleanSwitch(
      [&] { return publisher.rtiAmbassador().getConveyRegionDesignatorSetsSwitch(); },
      [&](bool value) {
        publisher.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(value);
      },
      "convey-region-designator-sets switch");
  roundTripBooleanSwitch(
      [&] { return publisher.rtiAmbassador().getServiceReportingSwitch(); },
      [&](bool value) { publisher.rtiAmbassador().setServiceReportingSwitch(value); },
      "service-reporting switch");
  roundTripBooleanSwitch(
      [&] { return publisher.rtiAmbassador().getExceptionReportingSwitch(); },
      [&](bool value) { publisher.rtiAmbassador().setExceptionReportingSwitch(value); },
      "exception-reporting switch");
  roundTripBooleanSwitch(
      [&] { return publisher.rtiAmbassador().getSendServiceReportsToFileSwitch(); },
      [&](bool value) {
        publisher.rtiAmbassador().setSendServiceReportsToFileSwitch(value);
      },
      "send-service-reports-to-file switch");
  auto checkReadOnlySwitch = [&](auto getter, std::string const& description) {
    auto const first = getter();
    require(getter() == first, description + " was not stable across queries");
  };
  checkReadOnlySwitch(
      [&] { return publisher.rtiAmbassador().getAutoProvideSwitch(); },
      "auto-provide switch");
  checkReadOnlySwitch(
      [&] { return publisher.rtiAmbassador().getDelaySubscriptionEvaluationSwitch(); },
      "delay-subscription-evaluation switch");
  checkReadOnlySwitch(
      [&] { return publisher.rtiAmbassador().getAdvisoriesUseKnownClassSwitch(); },
      "advisories-use-known-class switch");
  checkReadOnlySwitch(
      [&] { return publisher.rtiAmbassador().getAllowRelaxedDDMSwitch(); },
      "allow-relaxed-DDM switch");
  checkReadOnlySwitch(
      [&] { return publisher.rtiAmbassador().getNonRegulatedGrantSwitch(); },
      "non-regulated-grant switch");

  subscriber.rtiAmbassador().subscribeObjectClassAttributes(
      subscriberClass, subscriberNameSet, true, L"");
  publisher.rtiAmbassador().publishObjectClassAttributes(
      publisherClass, publisherAllSet);
  waitFor(publisher,
          [&] { return publisher.recorder().registrationStarts().size() >= 1U; },
          options,
          "active object registration relevance advisory");
  auto const registrationStarts = publisher.recorder().registrationStarts();
  require(registrationStarts.size() == 1U && registrationStarts.at(0) == publisherClass,
          "active object subscription did not produce one start-registration advisory");
  publisher.rtiAmbassador().publishObjectClassAttributes(
      publisherClass, publisherAllSet);
  for (int pass = 0; pass != 8; ++pass) {
    publisher.pump();
  }
  require(publisher.recorder().registrationStarts().size() == 1U,
          "repeated object publication repeated start-registration advisory");

  subscriber.rtiAmbassador().unsubscribeObjectClassAttributes(
      subscriberClass, subscriberNameSet);
  waitFor(publisher,
          [&] { return publisher.recorder().registrationStops().size() >= 1U; },
          options,
          "object registration relevance stop advisory");
  require(publisher.recorder().registrationStops().size() == 1U &&
              publisher.recorder().registrationStops().at(0) == publisherClass,
          "removing active object subscription did not produce one stop-registration advisory");

  subscriber.rtiAmbassador().subscribeObjectClassAttributes(
      subscriberClass, subscriberNameSet, false, L"");
  for (int pass = 0; pass != 8; ++pass) {
    publisher.pump();
  }
  require(publisher.recorder().registrationStarts().size() == 1U &&
              publisher.recorder().registrationStops().size() == 1U,
          "passive object subscription changed registration relevance");
  subscriber.rtiAmbassador().subscribeObjectClassAttributes(
      subscriberClass, subscriberNameSet, true, L"");
  waitFor(publisher,
          [&] { return publisher.recorder().registrationStarts().size() >= 2U; },
          options,
          "active object subscription promotion");
  subscriber.rtiAmbassador().unsubscribeObjectClassAttributes(
      subscriberClass, subscriberNameSet);
  waitFor(publisher,
          [&] { return publisher.recorder().registrationStops().size() >= 2U; },
          options,
          "active object subscription demotion");
  subscriber.rtiAmbassador().unsubscribeObjectClass(subscriberClass);

  subscriber.rtiAmbassador().subscribeInteractionClass(subscriberInteraction, true);
  publisher.rtiAmbassador().publishInteractionClass(publisherInteraction);
  waitFor(publisher,
          [&] { return publisher.recorder().interactionsOn().size() >= 1U; },
          options,
          "active interaction relevance advisory");
  require(publisher.recorder().interactionsOn().size() == 1U &&
              publisher.recorder().interactionsOn().at(0) == publisherInteraction,
          "active interaction subscription did not produce one turn-on advisory");
  publisher.rtiAmbassador().publishInteractionClass(publisherInteraction);
  for (int pass = 0; pass != 8; ++pass) {
    publisher.pump();
  }
  require(publisher.recorder().interactionsOn().size() == 1U,
          "repeated interaction publication repeated turn-on advisory");
  subscriber.rtiAmbassador().unsubscribeInteractionClass(subscriberInteraction);
  waitFor(publisher,
          [&] { return publisher.recorder().interactionsOff().size() >= 1U; },
          options,
          "interaction relevance stop advisory");
  require(publisher.recorder().interactionsOff().size() == 1U &&
              publisher.recorder().interactionsOff().at(0) == publisherInteraction,
          "removing active interaction subscription did not produce one turn-off advisory");
  subscriber.rtiAmbassador().subscribeInteractionClass(subscriberInteraction, false);
  for (int pass = 0; pass != 8; ++pass) {
    publisher.pump();
  }
  require(publisher.recorder().interactionsOn().size() == 1U,
          "passive interaction subscription changed interaction relevance");
  subscriber.rtiAmbassador().subscribeInteractionClass(subscriberInteraction, true);
  waitFor(publisher,
          [&] { return publisher.recorder().interactionsOn().size() >= 2U; },
          options,
          "active interaction subscription promotion");
  subscriber.rtiAmbassador().unsubscribeInteractionClass(subscriberInteraction);
  waitFor(publisher,
          [&] { return publisher.recorder().interactionsOff().size() >= 2U; },
          options,
          "active interaction subscription demotion");
  subscriber.rtiAmbassador().unsubscribeInteractionClass(subscriberInteraction);

  subscriber.rtiAmbassador().subscribeObjectClassAttributes(
      subscriberClass, subscriberNameSet, true, L"");
  auto const object = publisher.rtiAmbassador().registerObjectInstance(publisherClass);
  require(object.isValid(), "Relevance advisory registration returned an invalid object handle");
  waitFor(subscriber,
          [&] { return subscriber.recorder().hasDiscovery(object); },
          options,
          "active object subscriber discovery");
  for (int pass = 0; pass != 8; ++pass) {
    publisher.pump();
  }
  publisher.recorder().clearAdvisories();

  subscriber.rtiAmbassador().subscribeObjectClassAttributes(
      subscriberClass, subscriberPayRateSet, true, L"");
  waitFor(publisher,
          [&] { return publisher.recorder().updatesOn().size() >= 1U; },
          options,
          "unnamed attribute turn-updates-on advisory");
  auto const unnamedUpdatesOn = publisher.recorder().updatesOn();
  require(unnamedUpdatesOn.size() == 1U && unnamedUpdatesOn.at(0).object == object &&
              unnamedUpdatesOn.at(0).attributes.count(publisherPayRate) == 1U &&
              !unnamedUpdatesOn.at(0).updateRateDesignator.has_value(),
          "unnamed turn-updates-on advisory did not preserve instance and attributes");

  subscriber.rtiAmbassador().unsubscribeObjectClassAttributes(
      subscriberClass, subscriberPayRateSet);
  waitFor(publisher,
          [&] { return publisher.recorder().updatesOff().size() >= 1U; },
          options,
          "attribute turn-updates-off advisory");
  auto const unnamedUpdatesOff = publisher.recorder().updatesOff();
  require(unnamedUpdatesOff.size() == 1U && unnamedUpdatesOff.at(0).object == object &&
              unnamedUpdatesOff.at(0).attributes.count(publisherPayRate) == 1U,
          "turn-updates-off advisory did not preserve instance and attributes");

  subscriber.rtiAmbassador().subscribeObjectClassAttributes(
      subscriberClass, subscriberAttributeSet, true, L"High");
  waitFor(publisher,
          [&] { return publisher.recorder().updatesOn().size() >= 2U; },
          options,
          "named attribute turn-updates-on advisory");
  auto const namedUpdatesOn = publisher.recorder().updatesOn();
  require(namedUpdatesOn.size() == 2U && namedUpdatesOn.at(1).object == object &&
              namedUpdatesOn.at(1).attributes.count(publisherAttribute) == 1U &&
              namedUpdatesOn.at(1).updateRateDesignator.has_value() &&
              namedUpdatesOn.at(1).updateRateDesignator.value() == L"High",
          "named turn-updates-on advisory did not preserve its update rate");
  require(
      subscriber.rtiAmbassador().getUpdateRateValue(L"High") == 1.0,
      "named update-rate lookup did not return the configured FOM value");
  require(
      subscriber.rtiAmbassador().getUpdateRateValueForAttribute(
          object, subscriberAttribute) == 1.0,
      "attribute update-rate lookup did not return the active subscription rate");
  subscriber.rtiAmbassador().unsubscribeObjectClassAttributes(
      subscriberClass, subscriberAttributeSet);
  waitFor(publisher,
          [&] { return publisher.recorder().updatesOff().size() >= 2U; },
          options,
          "named attribute turn-updates-off advisory");

  subscriber.rtiAmbassador().unsubscribeObjectClassAttributes(
      subscriberClass, subscriberNameSet);
  subscriber.rtiAmbassador().unsubscribeObjectClass(subscriberClass);
  publisher.rtiAmbassador().unpublishInteractionClass(publisherInteraction);
  publisher.rtiAmbassador().unpublishObjectClassAttributes(publisherClass, publisherAllSet);
  publisher.rtiAmbassador().unpublishObjectClass(publisherClass);
  publisher.resign(rti::DELETE_OBJECTS);
  subscriber.resign(rti::NO_ACTION);
}

void scenarioDelaySubscriptionEvaluationInteraction(
    Options const& options,
    rti::CallbackModel model) {
  require(!options.switchesFom.empty(),
          "switch-declaration FOM input was not supplied by the adapter");

  auto delaySubscriptionEvaluationFomModules =
      [&](bool const delaySubscriptionEvaluationEnabled) {
        std::vector<std::wstring> fomModules{options.fom.wstring()};
        if (delaySubscriptionEvaluationEnabled) {
          fomModules.push_back(options.switchesFom.wstring());
        }
        return fomModules;
      };

  auto callbackBoundary = [&](Session& receiver) {
    if (model == rti::HLA_IMMEDIATE) {
      receiver.rtiAmbassador().enableCallbacks();
    } else {
      while (receiver.rtiAmbassador().evokeCallback(0.0)) {
      }
    }
  };

  auto runConfiguration = [&](bool const delaySubscriptionEvaluationEnabled) {
    Session publisher(options, model, "delay-subscription-publisher");
    Session receiver(options, model, "delay-subscription-receiver");
    auto const federation = federationName(
        options,
        delaySubscriptionEvaluationEnabled
            ? "delay-subscription-evaluation-interaction-enabled"
            : "delay-subscription-evaluation-interaction-disabled");

    publisher.connect();
    receiver.connect();
    auto const fomModules =
        delaySubscriptionEvaluationFomModules(delaySubscriptionEvaluationEnabled);
    publisher.rtiAmbassador().createFederationExecution(
        federation,
        fomModules,
        options.logicalTimeImplementationName);
    publisher.join(
        options.ownerFederateName,
        options.federateType,
        federation);
    receiver.join(
        options.memberFederateName,
        options.federateType,
        federation);

    auto const publisherInteraction =
        publisher.rtiAmbassador().getInteractionClassHandle(
            options.interactionClassName);
    auto const receiverInteraction =
        receiver.rtiAmbassador().getInteractionClassHandle(
            options.interactionClassName);
    require(
        publisherInteraction.isValid() && receiverInteraction.isValid(),
        "delay-subscription interaction lookup returned an invalid handle");
    require(
        publisher.rtiAmbassador().getDelaySubscriptionEvaluationSwitch() ==
                delaySubscriptionEvaluationEnabled &&
            receiver.rtiAmbassador().getDelaySubscriptionEvaluationSwitch() ==
                delaySubscriptionEvaluationEnabled,
        "delay-subscription switch did not match the adapter FOM configuration");

    publisher.rtiAmbassador().publishInteractionClass(publisherInteraction);

    // A receive-order interaction generated before the receiver subscribes is
    // retained only when the federation's standard Delay Subscription
    // Evaluation switch is enabled. Immediate callbacks use the official
    // callback-control services to create the same callback boundary.
    if (model == rti::HLA_IMMEDIATE) {
      receiver.rtiAmbassador().disableCallbacks();
    }
    publisher.rtiAmbassador().sendInteraction(
        publisherInteraction,
        rti::ParameterHandleValueMap{},
        rti::VariableLengthData{});
    receiver.rtiAmbassador().subscribeInteractionClass(receiverInteraction);
    callbackBoundary(receiver);

    auto const firstInteraction = receiver.recorder().interaction();
    require(
        firstInteraction.present == delaySubscriptionEvaluationEnabled,
        delaySubscriptionEvaluationEnabled
            ? "enabled delay-subscription evaluation did not retain the interaction"
            : "disabled delay-subscription evaluation retained an unsubscribed interaction");
    if (delaySubscriptionEvaluationEnabled) {
      require(
          firstInteraction.interaction == receiverInteraction &&
              firstInteraction.parameters.empty() &&
              firstInteraction.tag.empty() &&
              firstInteraction.producer == publisher.federateHandle() &&
              !firstInteraction.regions.has_value(),
          "delayed interaction delivery did not preserve standard callback metadata");
    }

    // A message accepted while subscribed is still re-evaluated at the
    // actual callback boundary. Removing the declaration before that
    // boundary suppresses the ordinary delivery in both callback models.
    if (model == rti::HLA_IMMEDIATE) {
      receiver.rtiAmbassador().disableCallbacks();
    }
    publisher.rtiAmbassador().sendInteraction(
        publisherInteraction,
        rti::ParameterHandleValueMap{},
        rti::VariableLengthData{});
    receiver.rtiAmbassador().unsubscribeInteractionClass(receiverInteraction);
    callbackBoundary(receiver);
    auto const afterUnsubscribe = receiver.recorder().interaction();
    require(
        afterUnsubscribe.present == delaySubscriptionEvaluationEnabled,
        "callback-boundary subscription removal changed the retained interaction state");
    if (delaySubscriptionEvaluationEnabled) {
      require(
          afterUnsubscribe.interaction == receiverInteraction &&
              afterUnsubscribe.parameters.empty() &&
              afterUnsubscribe.tag.empty() &&
              afterUnsubscribe.producer == publisher.federateHandle() &&
              !afterUnsubscribe.regions.has_value(),
          "delayed interaction state changed after unsubscribe suppression");
    }

    receiver.resign(rti::NO_ACTION);
    publisher.resign(rti::NO_ACTION);
    publisher.rtiAmbassador().destroyFederationExecution(federation);
    receiver.disconnect();
    publisher.disconnect();
  };

  runConfiguration(false);
  runConfiguration(true);
}

void scenarioDelaySubscriptionEvaluationDirectedInteraction(
    Options const& options,
    rti::CallbackModel model) {
  require(!options.switchesFom.empty(),
          "switch-declaration FOM input was not supplied by the adapter");

  auto delaySubscriptionEvaluationFomModules =
      [&](bool const delaySubscriptionEvaluationEnabled) {
        std::vector<std::wstring> fomModules{options.fom.wstring()};
        if (delaySubscriptionEvaluationEnabled) {
          fomModules.push_back(options.switchesFom.wstring());
        }
        return fomModules;
      };

  auto callbackBoundary = [&](Session& receiver) {
    if (model == rti::HLA_IMMEDIATE) {
      receiver.rtiAmbassador().enableCallbacks();
    } else {
      while (receiver.rtiAmbassador().evokeCallback(0.0)) {
      }
    }
  };

  auto runConfiguration = [&](bool const delaySubscriptionEvaluationEnabled) {
    Session owner(options, model, "delay-directed-owner");
    Session receiver(options, model, "delay-directed-receiver");
    auto const federation = federationName(
        options,
        delaySubscriptionEvaluationEnabled
            ? "delay-subscription-evaluation-directed-enabled"
            : "delay-subscription-evaluation-directed-disabled");

    owner.connect();
    receiver.connect();
    owner.rtiAmbassador().createFederationExecution(
        federation,
        delaySubscriptionEvaluationFomModules(delaySubscriptionEvaluationEnabled),
        options.logicalTimeImplementationName);
    owner.join(
        options.ownerFederateName + L"-delay-directed-owner",
        options.federateType,
        federation);
    receiver.join(
        options.memberFederateName + L"-delay-directed-receiver",
        options.federateType,
        federation);

    auto const ownerClass = owner.rtiAmbassador().getObjectClassHandle(
        options.objectClassName);
    auto const receiverClass = receiver.rtiAmbassador().getObjectClassHandle(
        options.objectClassName);
    auto const ownerAttribute = owner.rtiAmbassador().getAttributeHandle(
        ownerClass,
        options.attributeName);
    auto const receiverAttribute = receiver.rtiAmbassador().getAttributeHandle(
        receiverClass,
        options.attributeName);
    auto const ownerInteraction = owner.rtiAmbassador().getInteractionClassHandle(
        options.interactionClassName);
    auto const receiverInteraction = receiver.rtiAmbassador().getInteractionClassHandle(
        options.interactionClassName);
    require(
        ownerClass.isValid() && receiverClass.isValid() && ownerAttribute.isValid() &&
            receiverAttribute.isValid() && ownerInteraction.isValid() &&
            receiverInteraction.isValid(),
        "delay-subscription directed lookup returned an invalid handle");
    require(
        owner.rtiAmbassador().getDelaySubscriptionEvaluationSwitch() ==
                delaySubscriptionEvaluationEnabled &&
            receiver.rtiAmbassador().getDelaySubscriptionEvaluationSwitch() ==
                delaySubscriptionEvaluationEnabled,
        "delay-subscription directed switch did not match the adapter FOM configuration");

    rti::AttributeHandleSet const ownerAttributes{ownerAttribute};
    rti::AttributeHandleSet const receiverAttributes{receiverAttribute};
    owner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerAttributes);
    receiver.rtiAmbassador().subscribeObjectClassAttributes(
        receiverClass,
        receiverAttributes,
        true,
        L"");
    rti::InteractionClassHandleSet const ownerDirected{ownerInteraction};
    rti::InteractionClassHandleSet const receiverDirected{receiverInteraction};
    owner.rtiAmbassador().publishObjectClassDirectedInteractions(
        ownerClass,
        ownerDirected);

    auto const object = owner.rtiAmbassador().registerObjectInstance(ownerClass);
    require(object.isValid(), "delay-subscription directed registration returned an invalid handle");
    waitFor(
        receiver,
        [&] { return receiver.recorder().hasDiscovery(object); },
        options,
        "delay-subscription directed object discovery");

    receiver.recorder().clearDirectedInteractions();
    if (model == rti::HLA_IMMEDIATE) {
      receiver.rtiAmbassador().disableCallbacks();
    }
    owner.rtiAmbassador().sendDirectedInteraction(
        ownerInteraction,
        object,
        rti::ParameterHandleValueMap{},
        rti::VariableLengthData{});
    receiver.rtiAmbassador().subscribeObjectClassDirectedInteractions(
        receiverClass,
        receiverDirected,
        true);
    callbackBoundary(receiver);

    auto const expectedCount = delaySubscriptionEvaluationEnabled ? 1U : 0U;
    auto const firstInteractions = receiver.recorder().directedInteractions();
    require(
        firstInteractions.size() == expectedCount,
        delaySubscriptionEvaluationEnabled
            ? "enabled delay-subscription evaluation did not retain the directed interaction"
            : "disabled delay-subscription evaluation retained an unselected directed interaction");
    if (delaySubscriptionEvaluationEnabled) {
      auto const& first = firstInteractions.front();
      require(
          first.interaction == receiverInteraction && first.object == object &&
              first.parameters.empty() && first.tag.empty() &&
              first.producer == owner.federateHandle() && first.transportation.isValid(),
          "delayed directed interaction delivery did not preserve standard callback metadata");
    }

    // A candidate admitted while selected is still re-evaluated at the actual
    // callback boundary. Removing the selector before delivery must suppress
    // the accepted work in both switch modes.
    if (model == rti::HLA_IMMEDIATE) {
      receiver.rtiAmbassador().disableCallbacks();
    }
    owner.rtiAmbassador().sendDirectedInteraction(
        ownerInteraction,
        object,
        rti::ParameterHandleValueMap{},
        rti::VariableLengthData{});
    receiver.rtiAmbassador().unsubscribeObjectClassDirectedInteractions(
        receiverClass,
        receiverDirected);
    callbackBoundary(receiver);
    auto const afterUnsubscribe = receiver.recorder().directedInteractions();
    require(
        afterUnsubscribe.size() == expectedCount,
        "callback-boundary directed subscription removal changed the retained state");
    if (delaySubscriptionEvaluationEnabled) {
      auto const& first = afterUnsubscribe.front();
      require(
          first.interaction == receiverInteraction && first.object == object &&
              first.parameters.empty() && first.tag.empty() &&
              first.producer == owner.federateHandle(),
          "directed interaction state changed after unsubscribe suppression");
    }

    receiver.resign(rti::NO_ACTION);
    owner.resign(rti::DELETE_OBJECTS);
    owner.rtiAmbassador().destroyFederationExecution(federation);
    receiver.disconnect();
    owner.disconnect();
  };

  runConfiguration(false);
  runConfiguration(true);
}

void scenarioDelaySubscriptionEvaluationAttributeUpdate(
    Options const& options,
    rti::CallbackModel model) {
  require(!options.switchesFom.empty(),
          "switch-declaration FOM input was not supplied by the adapter");

  auto runConfiguration = [&](bool const delaySubscriptionEvaluationEnabled) {
    Session publisher(options, model, "delay-subscription-attribute-publisher");
    Session receiver(options, model, "delay-subscription-attribute-receiver");
    auto const federation = federationName(
        options,
        delaySubscriptionEvaluationEnabled
            ? "delay-subscription-evaluation-attribute-enabled"
            : "delay-subscription-evaluation-attribute-disabled");

    publisher.connect();
    receiver.connect();
    std::vector<std::wstring> fomModules{options.fom.wstring()};
    if (delaySubscriptionEvaluationEnabled) {
      fomModules.push_back(options.switchesFom.wstring());
    }
    publisher.rtiAmbassador().createFederationExecution(
        federation,
        fomModules,
        options.logicalTimeImplementationName);
    publisher.join(
        options.ownerFederateName,
        options.federateType,
        federation);
    receiver.join(
        options.memberFederateName,
        options.federateType,
        federation);

    auto const publisherClass =
        publisher.rtiAmbassador().getObjectClassHandle(options.objectClassName);
    auto const receiverClass =
        receiver.rtiAmbassador().getObjectClassHandle(options.objectClassName);
    auto const publisherAttribute = publisher.rtiAmbassador().getAttributeHandle(
        publisherClass,
        options.attributeName);
    auto const receiverAttribute = receiver.rtiAmbassador().getAttributeHandle(
        receiverClass,
        options.attributeName);
    require(
        publisherClass.isValid() && receiverClass.isValid(),
        "delay-subscription attribute object-class lookup returned an invalid handle");
    require(
        publisherAttribute.isValid() && receiverAttribute.isValid(),
        "delay-subscription attribute lookup returned an invalid handle");
    require(
        publisher.rtiAmbassador().getDelaySubscriptionEvaluationSwitch() ==
                delaySubscriptionEvaluationEnabled &&
            receiver.rtiAmbassador().getDelaySubscriptionEvaluationSwitch() ==
                delaySubscriptionEvaluationEnabled,
        "delay-subscription switch did not match the adapter FOM configuration");

    rti::AttributeHandleSet const publisherAttributes{publisherAttribute};
    rti::AttributeHandleSet const receiverAttributes{receiverAttribute};
    publisher.rtiAmbassador().publishObjectClassAttributes(
        publisherClass,
        publisherAttributes);
    receiver.rtiAmbassador().subscribeObjectClassAttributes(
        receiverClass,
        receiverAttributes);
    auto const object = publisher.rtiAmbassador().registerObjectInstance(publisherClass);
    require(object.isValid(), "delay-subscription attribute registration returned an invalid handle");
    if (model == rti::HLA_EVOKED) {
      while (receiver.rtiAmbassador().evokeCallback(0.0)) {
      }
    }
    require(
        receiver.recorder().discovery().present,
        "delay-subscription attribute object discovery did not complete");
    require(
        receiver.rtiAmbassador().getKnownObjectClassHandle(object) == receiverClass,
        "delay-subscription attribute discovery did not establish the known object class");
    receiver.rtiAmbassador().unsubscribeObjectClassAttributes(
        receiverClass,
        receiverAttributes);

    unsigned char const valueBytes[] = {0xD5, 0x45};
    rti::AttributeHandleValueMap values;
    values.emplace(
        publisherAttribute,
        rti::VariableLengthData(valueBytes, sizeof(valueBytes)));

    // The receiver is known but has no active declaration at generation. The
    // enabled switch retains a route until the callback boundary, while the
    // disabled default keeps generation-time ineligibility.
    if (model == rti::HLA_IMMEDIATE) {
      receiver.rtiAmbassador().disableCallbacks();
    }
    publisher.rtiAmbassador().updateAttributeValues(
        object,
        values,
        rti::VariableLengthData{});
    receiver.rtiAmbassador().subscribeObjectClassAttributes(
        receiverClass,
        receiverAttributes);
    if (model == rti::HLA_IMMEDIATE) {
      receiver.rtiAmbassador().enableCallbacks();
    } else {
      while (receiver.rtiAmbassador().evokeCallback(0.0)) {
      }
    }

    auto const firstReflection = receiver.recorder().reflection();
    require(
        firstReflection.present == delaySubscriptionEvaluationEnabled,
        delaySubscriptionEvaluationEnabled
            ? "enabled delay-subscription evaluation did not retain the attribute update"
            : "disabled delay-subscription evaluation retained an unsubscribed attribute update");
    if (delaySubscriptionEvaluationEnabled) {
      require(
          firstReflection.object == object &&
              firstReflection.values.size() == 1U &&
              firstReflection.values.count(receiverAttribute) == 1U &&
              copyBytes(firstReflection.values.at(receiverAttribute)) ==
                  std::vector<std::uint8_t>(valueBytes, valueBytes + sizeof(valueBytes)) &&
              firstReflection.tag.empty() &&
              firstReflection.producer == publisher.federateHandle() &&
              firstReflection.transportation.isValid() &&
              !firstReflection.regions.has_value(),
          "delayed attribute reflection did not preserve standard callback metadata");
    }

    // A recipient accepted while subscribed is still re-evaluated against
    // the current declaration immediately before ordinary delivery.
    if (model == rti::HLA_IMMEDIATE) {
      receiver.rtiAmbassador().disableCallbacks();
    }
    publisher.rtiAmbassador().updateAttributeValues(
        object,
        values,
        rti::VariableLengthData{});
    receiver.rtiAmbassador().unsubscribeObjectClassAttributes(
        receiverClass,
        receiverAttributes);
    if (model == rti::HLA_IMMEDIATE) {
      receiver.rtiAmbassador().enableCallbacks();
    } else {
      while (receiver.rtiAmbassador().evokeCallback(0.0)) {
      }
    }
    auto const afterUnsubscribe = receiver.recorder().reflection();
    require(
        afterUnsubscribe.present == delaySubscriptionEvaluationEnabled,
        "callback-boundary attribute unsubscribe changed the retained reflection state");

    receiver.resign(rti::NO_ACTION);
    publisher.resign(rti::DELETE_OBJECTS);
    publisher.rtiAmbassador().destroyFederationExecution(federation);
    receiver.disconnect();
    publisher.disconnect();
  };

  runConfiguration(false);
  runConfiguration(true);
}

void scenarioDelaySubscriptionEvaluationTimestampedInteraction(
    Options const& options,
    rti::CallbackModel model) {
  require(!options.switchesFom.empty(),
          "switch-declaration FOM input was not supplied by the adapter");
  require(!options.logicalTimeImplementationName.empty(),
          "timestamped delay-subscription scenario requires a logical-time implementation");

  auto runConfiguration = [&](bool const delaySubscriptionEvaluationEnabled) {
    Session publisher(options, model, "delay-subscription-timestamped-publisher");
    Session receiver(options, model, "delay-subscription-timestamped-receiver");
    auto const federation = federationName(
        options,
        delaySubscriptionEvaluationEnabled
            ? "delay-subscription-evaluation-timestamped-interaction-enabled"
            : "delay-subscription-evaluation-timestamped-interaction-disabled");

    publisher.connect();
    receiver.connect();
    std::vector<std::wstring> fomModules{options.fom.wstring()};
    if (delaySubscriptionEvaluationEnabled) {
      fomModules.push_back(options.switchesFom.wstring());
    }
    publisher.rtiAmbassador().createFederationExecution(
        federation,
        fomModules,
        options.logicalTimeImplementationName);
    publisher.join(
        options.ownerFederateName,
        options.federateType,
        federation);
    receiver.join(
        options.memberFederateName,
        options.federateType,
        federation);

    auto const publisherInteraction =
        publisher.rtiAmbassador().getInteractionClassHandle(options.interactionClassName);
    auto const receiverInteraction =
        receiver.rtiAmbassador().getInteractionClassHandle(options.interactionClassName);
    auto const publisherParameter = publisher.rtiAmbassador().getParameterHandle(
        publisherInteraction,
        options.parameterName);
    auto const receiverParameter = receiver.rtiAmbassador().getParameterHandle(
        receiverInteraction,
        options.parameterName);
    require(
        publisherInteraction.isValid() && receiverInteraction.isValid(),
        "delay-subscription timestamped interaction lookup returned an invalid handle");
    require(
        publisherParameter.isValid() && receiverParameter.isValid(),
        "delay-subscription timestamped interaction parameter lookup returned an invalid handle");
    require(
        publisher.rtiAmbassador().getDelaySubscriptionEvaluationSwitch() ==
                delaySubscriptionEvaluationEnabled &&
            receiver.rtiAmbassador().getDelaySubscriptionEvaluationSwitch() ==
                delaySubscriptionEvaluationEnabled,
        "delay-subscription timestamped interaction switch did not match the adapter FOM configuration");
    publisher.rtiAmbassador().publishInteractionClass(publisherInteraction);
    publisher.rtiAmbassador().changeInteractionOrderType(
        publisherInteraction,
        rti::TIMESTAMP);

    auto publisherTime = makeTimeContext(publisher);
    auto receiverTime = makeTimeContext(receiver);
    enableTimestampedRoles(
        publisher,
        receiver,
        publisherTime,
        receiverTime,
        options,
        "delay-subscription timestamped interaction");

    unsigned char const payloadBytes[] = {0xA1};
    rti::ParameterHandleValueMap const parameters{
        {publisherParameter, rti::VariableLengthData(payloadBytes, sizeof(payloadBytes))}};
    auto assertInteraction = [&](TimedInteractionRecord const& record,
                                 std::vector<std::uint8_t> const& expectedTime,
                                 rti::OrderType expectedReceivedOrder,
                                 std::string const& description) {
      require(
          record.interaction == receiverInteraction &&
              record.parameters.size() == 1U &&
              record.parameters.count(receiverParameter) == 1U &&
              copyBytes(record.parameters.at(receiverParameter)) ==
                  std::vector<std::uint8_t>(payloadBytes, payloadBytes + sizeof(payloadBytes)) &&
              record.tag.empty() &&
              record.producer == publisher.federateHandle() &&
              record.transportation.isValid() &&
              !receiver.rtiAmbassador().getTransportationTypeName(record.transportation).empty() &&
              record.time == expectedTime && !record.timeText.empty() &&
              record.sentOrder == rti::TIMESTAMP &&
              record.receivedOrder == expectedReceivedOrder &&
              !record.regions.has_value(),
          description + " did not preserve standard timestamped interaction metadata");
    };

    auto const firstTime = timeAfter(
        *publisherTime.factory,
        *publisherTime.initial,
        *publisherTime.epsilon,
        2U);
    auto const firstReceiverTime = timeAfter(
        *receiverTime.factory,
        *receiverTime.initial,
        *receiverTime.epsilon,
        2U);
    auto const firstRetraction = publisher.rtiAmbassador().sendInteraction(
        publisherInteraction,
        parameters,
        rti::VariableLengthData{},
        *firstTime);
    require(
        firstRetraction.isValid(),
        "delay-subscription timestamped interaction returned an invalid retraction handle");
    receiver.rtiAmbassador().subscribeInteractionClass(receiverInteraction);
    receiver.rtiAmbassador().timeAdvanceRequest(*firstReceiverTime);
    publisher.rtiAmbassador().timeAdvanceRequest(*firstTime);
    auto const expectedFirstCount = delaySubscriptionEvaluationEnabled ? 1U : 0U;
    waitFor(
        publisher,
        receiver,
        [&] {
          return publisher.recorder().timeAdvanceGrants().size() >= 1U &&
              receiver.recorder().timeAdvanceGrants().size() >= 1U &&
              receiver.recorder().timedInteractions().size() >= expectedFirstCount;
        },
        options,
        "delay-subscription timestamped interaction first grant");
    require(
        receiver.recorder().timedInteractions().size() == expectedFirstCount,
        "delay-subscription timestamped interaction delivered the wrong first-message count");
    if (delaySubscriptionEvaluationEnabled) {
      auto const firstInteractions = receiver.recorder().timedInteractions();
      assertInteraction(
          firstInteractions.front(),
          encodeTime(*firstTime),
          rti::TIMESTAMP,
          "first delayed timestamped interaction");
      require(
          firstInteractions.front().retractionPresent &&
              firstInteractions.front().retraction == copyBytes(firstRetraction.encode()),
          "first delayed timestamped interaction returned the wrong retraction handle");
    }

    // The second message is generated while subscribed, but its recipient is
    // removed before the next grant. Generation-time eligibility is not a
    // promise of delivery in either switch mode.
    auto const secondTime = timeAfter(
        *publisherTime.factory,
        *firstTime,
        *publisherTime.epsilon,
        1U);
    auto const secondReceiverTime = timeAfter(
        *receiverTime.factory,
        *firstReceiverTime,
        *receiverTime.epsilon,
        1U);
    auto const secondRetraction = publisher.rtiAmbassador().sendInteraction(
        publisherInteraction,
        parameters,
        rti::VariableLengthData{},
        *secondTime);
    require(
        secondRetraction.isValid(),
        "delay-subscription timestamped interaction returned an invalid second retraction handle");
    receiver.rtiAmbassador().unsubscribeInteractionClass(receiverInteraction);
    receiver.rtiAmbassador().timeAdvanceRequest(*secondReceiverTime);
    publisher.rtiAmbassador().timeAdvanceRequest(*secondTime);
    waitFor(
        publisher,
        receiver,
        [&] {
          return publisher.recorder().timeAdvanceGrants().size() >= 2U &&
              receiver.recorder().timeAdvanceGrants().size() >= 2U;
        },
        options,
        "delay-subscription timestamped interaction second grant");
    require(
        receiver.recorder().timedInteractions().size() == expectedFirstCount,
        "delay-subscription timestamped interaction delivered after unsubscribe");

    receiver.resign(rti::NO_ACTION);
    publisher.resign(rti::NO_ACTION);
    publisher.rtiAmbassador().destroyFederationExecution(federation);
    receiver.disconnect();
    publisher.disconnect();
  };

  runConfiguration(false);
  runConfiguration(true);
}

void scenarioDelaySubscriptionEvaluationTimestampedDirectedInteraction(
    Options const& options,
    rti::CallbackModel model) {
  require(!options.switchesFom.empty(),
          "switch-declaration FOM input was not supplied by the adapter");
  require(!options.logicalTimeImplementationName.empty(),
          "timestamped directed delay-subscription scenario requires a logical-time implementation");

  auto runConfiguration = [&](bool const delaySubscriptionEvaluationEnabled) {
    Session owner(options, model, "delay-tso-directed-owner");
    Session receiver(options, model, "delay-tso-directed-receiver");
    auto const federation = federationName(
        options,
        delaySubscriptionEvaluationEnabled
            ? "delay-subscription-evaluation-timestamped-directed-enabled"
            : "delay-subscription-evaluation-timestamped-directed-disabled");

    owner.connect();
    receiver.connect();
    std::vector<std::wstring> fomModules{options.fom.wstring()};
    if (delaySubscriptionEvaluationEnabled) {
      fomModules.push_back(options.switchesFom.wstring());
    }
    owner.rtiAmbassador().createFederationExecution(
        federation,
        fomModules,
        options.logicalTimeImplementationName);
    owner.join(
        options.ownerFederateName + L"-delay-tso-directed-owner",
        options.federateType,
        federation);
    receiver.join(
        options.memberFederateName + L"-delay-tso-directed-receiver",
        options.federateType,
        federation);

    auto const ownerClass = owner.rtiAmbassador().getObjectClassHandle(
        options.objectClassName);
    auto const receiverClass = receiver.rtiAmbassador().getObjectClassHandle(
        options.objectClassName);
    auto const ownerAttribute = owner.rtiAmbassador().getAttributeHandle(
        ownerClass,
        options.attributeName);
    auto const receiverAttribute = receiver.rtiAmbassador().getAttributeHandle(
        receiverClass,
        options.attributeName);
    auto const ownerInteraction = owner.rtiAmbassador().getInteractionClassHandle(
        options.interactionClassName);
    auto const receiverInteraction = receiver.rtiAmbassador().getInteractionClassHandle(
        options.interactionClassName);
    require(
        ownerClass.isValid() && receiverClass.isValid() && ownerAttribute.isValid() &&
            receiverAttribute.isValid() && ownerInteraction.isValid() &&
            receiverInteraction.isValid(),
        "delay-subscription timestamped directed lookup returned an invalid handle");
    require(
        owner.rtiAmbassador().getDelaySubscriptionEvaluationSwitch() ==
                delaySubscriptionEvaluationEnabled &&
            receiver.rtiAmbassador().getDelaySubscriptionEvaluationSwitch() ==
                delaySubscriptionEvaluationEnabled,
        "delay-subscription timestamped directed switch did not match the adapter FOM configuration");

    rti::AttributeHandleSet const ownerAttributes{ownerAttribute};
    rti::AttributeHandleSet const receiverAttributes{receiverAttribute};
    owner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerAttributes);
    receiver.rtiAmbassador().subscribeObjectClassAttributes(
        receiverClass,
        receiverAttributes,
        true,
        L"");
    rti::InteractionClassHandleSet const ownerDirected{ownerInteraction};
    rti::InteractionClassHandleSet const receiverDirected{receiverInteraction};
    owner.rtiAmbassador().publishObjectClassDirectedInteractions(
        ownerClass,
        ownerDirected);
    owner.rtiAmbassador().changeInteractionOrderType(
        ownerInteraction,
        rti::TIMESTAMP);

    auto const object = owner.rtiAmbassador().registerObjectInstance(ownerClass);
    require(object.isValid(), "delay-subscription timestamped directed registration returned an invalid handle");
    waitFor(
        receiver,
        [&] { return receiver.recorder().hasDiscovery(object); },
        options,
        "delay-subscription timestamped directed object discovery");

    auto ownerTime = makeTimeContext(owner);
    auto receiverTime = makeTimeContext(receiver);
    enableTimestampedRoles(
        owner,
        receiver,
        ownerTime,
        receiverTime,
        options,
        "delay-subscription timestamped directed interaction");

    auto const firstTime = timeAfter(
        *ownerTime.factory,
        *ownerTime.initial,
        *ownerTime.epsilon,
        2U);
    auto const firstReceiverTime = timeAfter(
        *receiverTime.factory,
        *receiverTime.initial,
        *receiverTime.epsilon,
        2U);
    auto const firstRetraction = owner.rtiAmbassador().sendDirectedInteraction(
        ownerInteraction,
        object,
        rti::ParameterHandleValueMap{},
        rti::VariableLengthData{},
        *firstTime);
    require(
        firstRetraction.isValid() == delaySubscriptionEvaluationEnabled,
        "delay-subscription timestamped directed send returned the wrong first retraction state");
    receiver.rtiAmbassador().subscribeObjectClassDirectedInteractions(
        receiverClass,
        receiverDirected,
        true);
    receiver.rtiAmbassador().timeAdvanceRequest(*firstReceiverTime);
    owner.rtiAmbassador().timeAdvanceRequest(*firstTime);
    auto const expectedFirstCount = delaySubscriptionEvaluationEnabled ? 1U : 0U;
    waitFor(
        owner,
        receiver,
        [&] {
          return owner.recorder().timeAdvanceGrants().size() >= 1U &&
              receiver.recorder().timeAdvanceGrants().size() >= 1U &&
              receiver.recorder().timedDirectedInteractions().size() >= expectedFirstCount;
        },
        options,
        "delay-subscription timestamped directed interaction first grant");
    require(
        receiver.recorder().timedDirectedInteractions().size() == expectedFirstCount,
        "delay-subscription timestamped directed interaction delivered the wrong first-message count");
    if (delaySubscriptionEvaluationEnabled) {
      auto const firstInteractions = receiver.recorder().timedDirectedInteractions();
      auto const& first = firstInteractions.front();
      require(
          first.interaction == receiverInteraction && first.object == object &&
              first.parameters.empty() && first.tag.empty() &&
              first.producer == owner.federateHandle() && first.transportation.isValid() &&
              first.time == copyBytes(firstTime->encode()) &&
              first.sentOrder == rti::TIMESTAMP && first.receivedOrder == rti::TIMESTAMP,
          "first delayed timestamped directed interaction did not preserve standard metadata");
    }

    auto const secondTime = timeAfter(
        *ownerTime.factory,
        *firstTime,
        *ownerTime.epsilon,
        1U);
    auto const secondReceiverTime = timeAfter(
        *receiverTime.factory,
        *firstReceiverTime,
        *receiverTime.epsilon,
        1U);
    auto const secondRetraction = owner.rtiAmbassador().sendDirectedInteraction(
        ownerInteraction,
        object,
        rti::ParameterHandleValueMap{},
        rti::VariableLengthData{},
        *secondTime);
    require(
        secondRetraction.isValid(),
        "delay-subscription timestamped directed send returned an invalid second retraction handle");
    receiver.rtiAmbassador().unsubscribeObjectClassDirectedInteractions(
        receiverClass,
        receiverDirected);
    receiver.rtiAmbassador().timeAdvanceRequest(*secondReceiverTime);
    owner.rtiAmbassador().timeAdvanceRequest(*secondTime);
    waitFor(
        owner,
        receiver,
        [&] {
          return owner.recorder().timeAdvanceGrants().size() >= 2U &&
              receiver.recorder().timeAdvanceGrants().size() >= 2U;
        },
        options,
        "delay-subscription timestamped directed interaction second grant");
    require(
        receiver.recorder().timedDirectedInteractions().size() == expectedFirstCount,
        "delay-subscription timestamped directed interaction delivered after unsubscribe");

    receiver.resign(rti::NO_ACTION);
    owner.resign(rti::DELETE_OBJECTS);
    owner.rtiAmbassador().destroyFederationExecution(federation);
    receiver.disconnect();
    owner.disconnect();
  };

  runConfiguration(false);
  runConfiguration(true);
}

void scenarioDelaySubscriptionEvaluationTimestampedAttributeUpdate(
    Options const& options,
    rti::CallbackModel model) {
  require(!options.switchesFom.empty(),
          "switch-declaration FOM input was not supplied by the adapter");
  require(!options.logicalTimeImplementationName.empty(),
          "timestamped delay-subscription scenario requires a logical-time implementation");

  auto runConfiguration = [&](bool const delaySubscriptionEvaluationEnabled) {
    Session publisher(options, model, "delay-subscription-timestamped-attribute-publisher");
    Session receiver(options, model, "delay-subscription-timestamped-attribute-receiver");
    auto const federation = federationName(
        options,
        delaySubscriptionEvaluationEnabled
            ? "delay-subscription-evaluation-timestamped-attribute-enabled"
            : "delay-subscription-evaluation-timestamped-attribute-disabled");

    publisher.connect();
    receiver.connect();
    std::vector<std::wstring> fomModules{options.fom.wstring()};
    if (delaySubscriptionEvaluationEnabled) {
      fomModules.push_back(options.switchesFom.wstring());
    }
    publisher.rtiAmbassador().createFederationExecution(
        federation,
        fomModules,
        options.logicalTimeImplementationName);
    publisher.join(
        options.ownerFederateName,
        options.federateType,
        federation);
    receiver.join(
        options.memberFederateName,
        options.federateType,
        federation);

    auto const publisherClass =
        publisher.rtiAmbassador().getObjectClassHandle(options.objectClassName);
    auto const receiverClass =
        receiver.rtiAmbassador().getObjectClassHandle(options.objectClassName);
    auto const publisherAttribute = publisher.rtiAmbassador().getAttributeHandle(
        publisherClass,
        options.attributeName);
    auto const receiverAttribute = receiver.rtiAmbassador().getAttributeHandle(
        receiverClass,
        options.attributeName);
    require(
        publisherClass.isValid() && receiverClass.isValid(),
        "delay-subscription timestamped attribute object-class lookup returned an invalid handle");
    require(
        publisherAttribute.isValid() && receiverAttribute.isValid(),
        "delay-subscription timestamped attribute lookup returned an invalid handle");
    require(
        publisher.rtiAmbassador().getDelaySubscriptionEvaluationSwitch() ==
                delaySubscriptionEvaluationEnabled &&
            receiver.rtiAmbassador().getDelaySubscriptionEvaluationSwitch() ==
                delaySubscriptionEvaluationEnabled,
        "delay-subscription timestamped attribute switch did not match the adapter FOM configuration");

    rti::AttributeHandleSet const publisherAttributes{publisherAttribute};
    rti::AttributeHandleSet const receiverAttributes{receiverAttribute};
    publisher.rtiAmbassador().publishObjectClassAttributes(
        publisherClass,
        publisherAttributes);
    publisher.rtiAmbassador().changeDefaultAttributeOrderType(
        publisherClass,
        publisherAttributes,
        rti::TIMESTAMP);
    receiver.rtiAmbassador().subscribeObjectClassAttributes(
        receiverClass,
        receiverAttributes);
    auto const object = publisher.rtiAmbassador().registerObjectInstance(publisherClass);
    require(
        object.isValid(),
        "delay-subscription timestamped attribute registration returned an invalid handle");
    if (model == rti::HLA_EVOKED) {
      while (receiver.rtiAmbassador().evokeCallback(0.0)) {
      }
    }
    require(
        receiver.recorder().discovery().present &&
            receiver.rtiAmbassador().getKnownObjectClassHandle(object) == receiverClass,
        "delay-subscription timestamped attribute discovery did not establish the known object");
    receiver.rtiAmbassador().unsubscribeObjectClassAttributes(
        receiverClass,
        receiverAttributes);

    auto publisherTime = makeTimeContext(publisher);
    auto receiverTime = makeTimeContext(receiver);
    enableTimestampedRoles(
        publisher,
        receiver,
        publisherTime,
        receiverTime,
        options,
        "delay-subscription timestamped attribute");

    unsigned char const valueBytes[] = {0xD5, 0x54};
    rti::AttributeHandleValueMap values;
    values.emplace(
        publisherAttribute,
        rti::VariableLengthData(valueBytes, sizeof(valueBytes)));
    auto assertReflection = [&](TimedReflectionRecord const& reflection,
                                std::vector<std::uint8_t> const& expectedTime,
                                rti::OrderType expectedReceivedOrder,
                                std::vector<std::uint8_t> const& expectedRetraction,
                                std::string const& description) {
      require(
          reflection.object == object &&
              reflection.values.size() == 1U &&
              reflection.values.count(receiverAttribute) == 1U &&
              copyBytes(reflection.values.at(receiverAttribute)) ==
                  std::vector<std::uint8_t>(valueBytes, valueBytes + sizeof(valueBytes)) &&
              reflection.tag.empty() &&
              reflection.producer == publisher.federateHandle() &&
              reflection.transportation.isValid() &&
              !receiver.rtiAmbassador().getTransportationTypeName(reflection.transportation).empty() &&
              reflection.time == expectedTime && !reflection.timeText.empty() &&
              reflection.sentOrder == rti::TIMESTAMP &&
              reflection.receivedOrder == expectedReceivedOrder &&
              reflection.retractionPresent &&
              reflection.retraction == expectedRetraction &&
              !reflection.regions.has_value(),
          description + " did not preserve standard timestamped attribute metadata");
    };

    auto const firstTime = timeAfter(
        *publisherTime.factory,
        *publisherTime.initial,
        *publisherTime.epsilon,
        2U);
    auto const firstReceiverTime = timeAfter(
        *receiverTime.factory,
        *receiverTime.initial,
        *receiverTime.epsilon,
        2U);
    auto const firstRetraction = publisher.rtiAmbassador().updateAttributeValues(
        object,
        values,
        rti::VariableLengthData{},
        *firstTime);
    require(
        firstRetraction.isValid(),
        "delay-subscription timestamped attribute update returned an invalid retraction handle");
    receiver.rtiAmbassador().subscribeObjectClassAttributes(
        receiverClass,
        receiverAttributes);
    receiver.rtiAmbassador().timeAdvanceRequest(*firstReceiverTime);
    publisher.rtiAmbassador().timeAdvanceRequest(*firstTime);
    auto const expectedFirstCount = delaySubscriptionEvaluationEnabled ? 1U : 0U;
    waitFor(
        publisher,
        receiver,
        [&] {
          return publisher.recorder().timeAdvanceGrants().size() >= 1U &&
              receiver.recorder().timeAdvanceGrants().size() >= 1U &&
              receiver.recorder().timedReflections().size() >= expectedFirstCount;
        },
        options,
        "delay-subscription timestamped attribute first grant");
    require(
        receiver.recorder().timedReflections().size() == expectedFirstCount,
        "delay-subscription timestamped attribute delivered the wrong first-reflection count");
    if (delaySubscriptionEvaluationEnabled) {
      assertReflection(
          receiver.recorder().timedReflections().front(),
          encodeTime(*firstTime),
          rti::TIMESTAMP,
          copyBytes(firstRetraction.encode()),
          "first delayed timestamped attribute reflection");
    }

    // The second passel is accepted while subscribed but the declaration is
    // removed before the next grant, so current subscription state suppresses
    // it in both switch modes.
    auto const secondTime = timeAfter(
        *publisherTime.factory,
        *firstTime,
        *publisherTime.epsilon,
        1U);
    auto const secondReceiverTime = timeAfter(
        *receiverTime.factory,
        *firstReceiverTime,
        *receiverTime.epsilon,
        1U);
    auto const secondRetraction = publisher.rtiAmbassador().updateAttributeValues(
        object,
        values,
        rti::VariableLengthData{},
        *secondTime);
    require(
        secondRetraction.isValid(),
        "delay-subscription timestamped attribute update returned an invalid second retraction handle");
    receiver.rtiAmbassador().unsubscribeObjectClassAttributes(
        receiverClass,
        receiverAttributes);
    receiver.rtiAmbassador().timeAdvanceRequest(*secondReceiverTime);
    publisher.rtiAmbassador().timeAdvanceRequest(*secondTime);
    waitFor(
        publisher,
        receiver,
        [&] {
          return publisher.recorder().timeAdvanceGrants().size() >= 2U &&
              receiver.recorder().timeAdvanceGrants().size() >= 2U;
        },
        options,
        "delay-subscription timestamped attribute second grant");
    require(
        receiver.recorder().timedReflections().size() == expectedFirstCount,
        "delay-subscription timestamped attribute delivered after unsubscribe");

    receiver.rtiAmbassador().disableTimeConstrained();
    publisher.rtiAmbassador().disableTimeRegulation();
    receiver.resign(rti::NO_ACTION);
    publisher.resign(rti::DELETE_OBJECTS);
    publisher.rtiAmbassador().destroyFederationExecution(federation);
    receiver.disconnect();
    publisher.disconnect();
  };

  runConfiguration(false);
  runConfiguration(true);
}

void scenarioUpdateRateQueries(Options const& options, rti::CallbackModel model) {
  Session publisher(options, model, "owner");
  Session subscriber(options, model, "member");
  auto const federation = federationName(options, "update-rate-queries");
  connectAndJoin(publisher, subscriber, options, federation, options.fom);

  rti::ObjectClassHandle publisherClass;
  rti::AttributeHandle publisherAttribute;
  rti::InteractionClassHandle publisherInteraction;
  rti::ParameterHandle publisherParameter;
  handles(
      publisher,
      options,
      publisherClass,
      publisherAttribute,
      publisherInteraction,
      publisherParameter);
  rti::ObjectClassHandle subscriberClass;
  rti::AttributeHandle subscriberAttribute;
  rti::InteractionClassHandle subscriberInteraction;
  rti::ParameterHandle subscriberParameter;
  handles(
      subscriber,
      options,
      subscriberClass,
      subscriberAttribute,
      subscriberInteraction,
      subscriberParameter);
  require(
      publisherClass == subscriberClass && publisherAttribute == subscriberAttribute &&
          publisherInteraction == subscriberInteraction &&
          publisherParameter == subscriberParameter,
      "Update-rate query handles differed between joined federates");

  rti::AttributeHandleSet publisherAttributes;
  publisherAttributes.insert(publisherAttribute);
  rti::AttributeHandleSet subscriberAttributes;
  subscriberAttributes.insert(subscriberAttribute);
  publisher.rtiAmbassador().publishObjectClassAttributes(
      publisherClass,
      publisherAttributes);
  subscriber.rtiAmbassador().subscribeObjectClassAttributes(
      subscriberClass,
      subscriberAttributes,
      true,
      L"High");

  auto const object = publisher.rtiAmbassador().registerObjectInstance(publisherClass);
  require(object.isValid(), "Update-rate query registration returned an invalid object handle");
  waitFor(
      subscriber,
      [&] { return subscriber.recorder().hasDiscovery(object); },
      options,
      "update-rate query object discovery");

  auto const namedRate = subscriber.rtiAmbassador().getUpdateRateValue(L"High");
  require(namedRate > 0.0, "named update-rate lookup did not return a positive value");
  require(
      subscriber.rtiAmbassador().getUpdateRateValueForAttribute(
          object,
          subscriberAttribute) == namedRate,
      "active named subscription did not determine the per-attribute rate");
  require(
      publisher.rtiAmbassador().getUpdateRateValueForAttribute(
          object,
          publisherAttribute) == 0.0,
      "publisher publication incorrectly contributed to its per-attribute rate");

  requireException(
      [&] {
        static_cast<void>(subscriber.rtiAmbassador().getUpdateRateValue(
            L"cpp-tck-missing-update-rate"));
      },
      L"InvalidUpdateRateDesignator",
      "unknown update-rate designator");

  subscriber.rtiAmbassador().unsubscribeObjectClassAttributes(
      subscriberClass,
      subscriberAttributes);
  require(
      subscriber.rtiAmbassador().getUpdateRateValueForAttribute(
          object,
          subscriberAttribute) == 0.0,
      "per-attribute rate did not reset after unsubscribe");

  subscriber.rtiAmbassador().subscribeObjectClassAttributes(
      subscriberClass,
      subscriberAttributes,
      false,
      L"High");
  require(
      subscriber.rtiAmbassador().getUpdateRateValueForAttribute(
          object,
          subscriberAttribute) == 0.0,
      "passive named subscription incorrectly contributed to the per-attribute rate");

  subscriber.rtiAmbassador().subscribeObjectClassAttributes(
      subscriberClass,
      subscriberAttributes,
      true,
      L"");
  require(
      subscriber.rtiAmbassador().getUpdateRateValueForAttribute(
          object,
          subscriberAttribute) == 0.0,
      "active default subscription did not use the no-reduction rate boundary");

  requireException(
      [&] {
        static_cast<void>(subscriber.rtiAmbassador().getUpdateRateValueForAttribute(
            rti::ObjectInstanceHandle{},
            subscriberAttribute));
      },
      L"ObjectInstanceNotKnown",
      "unknown object in per-attribute rate query");
  requireException(
      [&] {
        static_cast<void>(subscriber.rtiAmbassador().getUpdateRateValueForAttribute(
            object,
            rti::AttributeHandle{}));
      },
      L"AttributeNotDefined",
      "undefined attribute in per-attribute rate query");

  subscriber.rtiAmbassador().unsubscribeObjectClassAttributes(
      subscriberClass,
      subscriberAttributes);
  publisher.rtiAmbassador().unpublishObjectClassAttributes(
      publisherClass,
      publisherAttributes);
  publisher.resign(rti::DELETE_OBJECTS);
  subscriber.resign(rti::NO_ACTION);
}

void scenarioUpdateRateQueriesContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioUpdateRateQueries(options, model);
}

void scenarioFederationTeardownIsolation(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.modelFom.empty(),
      "Federation teardown isolation requires an adapter-supplied rich FOM model");

  Session publisherA(options, model, "owner");
  Session receiverA(options, model, "member");
  Session publisherB(options, model, "owner");
  Session receiverB(options, model, "member");
  auto const federationA = federationName(options, "federation-teardown-isolation");
  auto const federationB = federationA + L"-child";

  publisherA.connect();
  receiverA.connect();
  publisherB.connect();
  receiverB.connect();
  publisherA.rtiAmbassador().createFederationExecution(
      federationA,
      options.modelFom.wstring(),
      options.logicalTimeImplementationName);
  publisherB.rtiAmbassador().createFederationExecution(
      federationB,
      options.modelFom.wstring(),
      options.logicalTimeImplementationName);
  publisherA.join(
      options.ownerFederateName + L"-teardown-a-publisher",
      options.federateType,
      federationA);
  receiverA.join(
      options.memberFederateName + L"-teardown-a-receiver",
      options.federateType,
      federationA);
  publisherB.join(
      options.ownerFederateName + L"-teardown-b-publisher",
      options.federateType,
      federationB);
  receiverB.join(
      options.memberFederateName + L"-teardown-b-receiver",
      options.federateType,
      federationB);

  struct RateFixture {
    rti::ObjectClassHandle publisherClass;
    rti::ObjectClassHandle receiverClass;
    rti::AttributeHandle publisherAttribute;
    rti::AttributeHandle receiverAttribute;
    rti::ObjectInstanceHandle object;
  };

  auto configure = [&](Session& publisher,
                       Session& receiver,
                       std::string const& description) {
    RateFixture fixture;
    fixture.publisherClass = publisher.rtiAmbassador().getObjectClassHandle(
        options.rateObjectClassName);
    fixture.receiverClass = receiver.rtiAmbassador().getObjectClassHandle(
        options.rateObjectClassName);
    fixture.publisherAttribute = publisher.rtiAmbassador().getAttributeHandle(
        fixture.publisherClass,
        options.rateBestEffortAttributeName);
    fixture.receiverAttribute = receiver.rtiAmbassador().getAttributeHandle(
        fixture.receiverClass,
        options.rateBestEffortAttributeName);
    require(
        fixture.publisherClass.isValid() && fixture.receiverClass.isValid() &&
            fixture.publisherAttribute.isValid() && fixture.receiverAttribute.isValid(),
        description + " update-rate isolation lookup returned an invalid handle");

    publisher.rtiAmbassador().publishObjectClassAttributes(
        fixture.publisherClass,
        rti::AttributeHandleSet{fixture.publisherAttribute});
    receiver.rtiAmbassador().subscribeObjectClassAttributes(
        fixture.receiverClass,
        rti::AttributeHandleSet{fixture.receiverAttribute},
        true,
        options.rateDesignatorName);
    require(
        receiver.rtiAmbassador().getUpdateRateValue(options.rateDesignatorName) > 0.0,
        description + " update-rate isolation designator did not resolve");

    fixture.object = publisher.rtiAmbassador().registerObjectInstance(
        fixture.publisherClass);
    require(
        fixture.object.isValid(),
        description + " update-rate isolation registration returned an invalid handle");
    waitFor(
        receiver,
        [&] { return receiver.recorder().hasDiscovery(fixture.object); },
        options,
        description + " update-rate isolation discovery");
    return fixture;
  };

  auto const fixtureA = configure(publisherA, receiverA, "Federation A");
  auto const fixtureB = configure(publisherB, receiverB, "Federation B");

  auto send = [&](Session& publisher, RateFixture const& fixture, std::uint8_t value) {
    std::vector<std::uint8_t> bytes{value};
    rti::AttributeHandleValueMap values;
    values.emplace(
        fixture.publisherAttribute,
        rti::VariableLengthData(bytes.data(), bytes.size()));
    publisher.rtiAmbassador().updateAttributeValues(
        fixture.object,
        values,
        rti::VariableLengthData{});
  };

  auto expectReflection = [&](Session& receiver,
                              RateFixture const& fixture,
                              std::uint8_t expected,
                              std::string const& description) {
    waitFor(
        receiver,
        [&] { return receiver.recorder().reflections().size() >= 1U; },
        options,
        description + " reflection");
    auto const reflections = receiver.recorder().reflections();
    require(
        reflections.size() == 1U,
        description + " delivered an unexpected reflection count");
    auto const& reflection = reflections.front();
    require(
        reflection.object == fixture.object && reflection.values.size() == 1U &&
            reflection.values.count(fixture.receiverAttribute) == 1U &&
            copyBytes(reflection.values.at(fixture.receiverAttribute)) ==
                std::vector<std::uint8_t>{expected},
        description + " delivered the wrong object or value");
  };

  auto observeSuppression = [&](Session& receiver, std::string const& description) {
    auto const deadline = Clock::now() + std::chrono::milliseconds(250);
    while (Clock::now() < deadline) {
      receiver.pump();
      std::this_thread::sleep_for(std::chrono::milliseconds(5));
    }
    require(
        receiver.recorder().reflections().empty(),
        description + " delivered an update inside the active named-rate interval");
  };

  receiverA.recorder().clearReflection();
  send(publisherA, fixtureA, 0x11U);
  expectReflection(receiverA, fixtureA, 0x11U, "Federation A first update");
  receiverA.recorder().clearReflection();
  send(publisherA, fixtureA, 0x12U);
  observeSuppression(receiverA, "Federation A second update");

  receiverB.recorder().clearReflection();
  send(publisherB, fixtureB, 0x21U);
  expectReflection(receiverB, fixtureB, 0x21U, "Federation B first update");
  receiverB.recorder().clearReflection();
  send(publisherB, fixtureB, 0x22U);
  observeSuppression(receiverB, "Federation B second update");

  receiverA.resign(rti::NO_ACTION);
  publisherA.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  publisherA.rtiAmbassador().destroyFederationExecution(federationA);

  receiverB.recorder().clearReflection();
  send(publisherB, fixtureB, 0x23U);
  observeSuppression(
      receiverB,
      "Federation B update after Federation A teardown");

  receiverB.resign(rti::NO_ACTION);
  publisherB.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  publisherB.rtiAmbassador().destroyFederationExecution(federationB);
  receiverA.disconnect();
  publisherA.disconnect();
  receiverB.disconnect();
  publisherB.disconnect();
}

void scenarioMixedUpdateRateSubscriptions(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.modelFom.empty(),
      "Mixed update-rate subscriptions require an adapter-supplied rich FOM model");

  Session publisher(options, model, "owner");
  Session receiver(options, model, "member");
  auto const federation = federationName(
      options,
      "mixed-update-rate-subscriptions");
  connectAndJoin(publisher, receiver, options, federation, options.modelFom);

  auto const publisherClass = publisher.rtiAmbassador().getObjectClassHandle(
      options.rateObjectClassName);
  auto const receiverClass = receiver.rtiAmbassador().getObjectClassHandle(
      options.rateObjectClassName);
  auto const publisherReliable = publisher.rtiAmbassador().getAttributeHandle(
      publisherClass,
      options.rateReliableAttributeName);
  auto const publisherBestEffort = publisher.rtiAmbassador().getAttributeHandle(
      publisherClass,
      options.rateBestEffortAttributeName);
  auto const receiverReliable = receiver.rtiAmbassador().getAttributeHandle(
      receiverClass,
      options.rateReliableAttributeName);
  auto const receiverBestEffort = receiver.rtiAmbassador().getAttributeHandle(
      receiverClass,
      options.rateBestEffortAttributeName);
  require(
      publisherClass.isValid() && receiverClass.isValid(),
      "Mixed update-rate subscription object-class lookup returned an invalid handle");
  require(
      publisherReliable.isValid() && publisherBestEffort.isValid() &&
          receiverReliable.isValid() && receiverBestEffort.isValid(),
      "Mixed update-rate subscription attribute lookup returned an invalid handle");
  require(
      publisherReliable != publisherBestEffort && receiverReliable != receiverBestEffort,
      "Mixed update-rate subscription adapter supplied duplicate attribute names");

  rti::AttributeHandleSet const publisherAttributes{
      publisherReliable,
      publisherBestEffort};
  rti::AttributeHandleSet const receiverAttributes{
      receiverReliable,
      receiverBestEffort};
  publisher.rtiAmbassador().publishObjectClassAttributes(
      publisherClass,
      publisherAttributes);
  receiver.rtiAmbassador().subscribeObjectClassAttributes(
      receiverClass,
      rti::AttributeHandleSet{receiverReliable},
      true,
      L"");
  receiver.rtiAmbassador().subscribeObjectClassAttributes(
      receiverClass,
      rti::AttributeHandleSet{receiverBestEffort},
      true,
      options.rateDesignatorName);

  auto const object = publisher.rtiAmbassador().registerObjectInstance(publisherClass);
  require(
      object.isValid(),
      "Mixed update-rate subscription registration returned an invalid object handle");
  waitFor(
      receiver,
      [&] { return receiver.recorder().hasDiscovery(object); },
      options,
      "mixed update-rate subscription object discovery");

  auto const namedRate = receiver.rtiAmbassador().getUpdateRateValue(
      options.rateDesignatorName);
  require(
      namedRate > 0.0,
      "mixed update-rate subscription named designator did not resolve to a positive rate");
  require(
      receiver.rtiAmbassador().getUpdateRateValueForAttribute(
          object,
          receiverBestEffort) == namedRate,
      "mixed update-rate subscription named attribute did not select its rate");
  require(
      receiver.rtiAmbassador().getUpdateRateValueForAttribute(
          object,
          receiverReliable) == 0.0,
      "mixed update-rate subscription default attribute unexpectedly selected a rate");

  std::vector<std::uint8_t> const firstReliableBytes{0x31U, 0x32U};
  std::vector<std::uint8_t> const firstBestEffortBytes{0x41U, 0x42U};
  std::vector<std::uint8_t> const secondReliableBytes{0x51U, 0x52U};
  std::vector<std::uint8_t> const secondBestEffortBytes{0x61U, 0x62U};
  std::vector<std::uint8_t> const firstTagBytes{0x71U};
  std::vector<std::uint8_t> const secondTagBytes{0x72U};

  auto sendUpdate = [&](std::vector<std::uint8_t> const& reliableBytes,
                        std::vector<std::uint8_t> const& bestEffortBytes,
                        std::vector<std::uint8_t> const& tagBytes) {
    rti::AttributeHandleValueMap values;
    values.emplace(
        publisherReliable,
        rti::VariableLengthData(reliableBytes.data(), reliableBytes.size()));
    values.emplace(
        publisherBestEffort,
        rti::VariableLengthData(bestEffortBytes.data(), bestEffortBytes.size()));
    rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());
    publisher.rtiAmbassador().updateAttributeValues(object, values, tag);
  };

  auto countAttribute = [&](rti::AttributeHandle const& handle) {
    auto const reflections = receiver.recorder().reflections();
    return static_cast<std::size_t>(std::count_if(
        reflections.begin(),
        reflections.end(),
        [&](ReflectionRecord const& reflection) {
          return reflection.present && reflection.values.count(handle) == 1U;
        }));
  };
  auto assertPassel = [&](std::size_t begin,
                          std::vector<std::uint8_t> const& expectedReliable,
                          std::vector<std::uint8_t> const& expectedBestEffort,
                          std::vector<std::uint8_t> const& expectedTag,
                          bool expectBestEffort,
                          std::string const& description) {
    auto const reflections = receiver.recorder().reflections();
    require(
        begin <= reflections.size(),
        description + " began after the recorded reflection sequence");
    std::size_t reliableCount = 0U;
    std::size_t bestEffortCount = 0U;
    for (auto index = begin; index < reflections.size(); ++index) {
      auto const& reflection = reflections[index];
      require(
          reflection.present && reflection.object == object &&
              reflection.tag == expectedTag &&
              reflection.producer == publisher.federateHandle() &&
              !reflection.regions.has_value() && reflection.transportation.isValid(),
          description + " returned non-standard reflection metadata");
      auto const transportation = receiver.rtiAmbassador().getTransportationTypeName(
          reflection.transportation);
      for (auto const& [attribute, value] : reflection.values) {
        if (attribute == receiverReliable) {
          ++reliableCount;
          require(
              value.size() == expectedReliable.size() &&
                  copyBytes(value) == expectedReliable &&
                  transportation == L"HLAreliable",
              description + " returned the wrong reliable attribute value or transport");
        } else if (attribute == receiverBestEffort) {
          ++bestEffortCount;
          require(
              expectBestEffort && value.size() == expectedBestEffort.size() &&
                  copyBytes(value) == expectedBestEffort &&
                  transportation == L"HLAbestEffort",
              description + " returned the wrong best-effort attribute value or transport");
        } else {
          throw std::runtime_error(
              description + " returned an unexpected attribute handle");
        }
      }
    }
    require(
        reliableCount == 1U && bestEffortCount == (expectBestEffort ? 1U : 0U),
        description + " did not deliver the expected attributes exactly once");
  };

  auto const firstReflectionBegin = receiver.recorder().reflections().size();
  sendUpdate(firstReliableBytes, firstBestEffortBytes, firstTagBytes);
  waitFor(
      receiver,
      [&] {
        return countAttribute(receiverReliable) >= 1U &&
            countAttribute(receiverBestEffort) >= 1U;
      },
      options,
      "mixed update-rate subscription first reflection passel");
  auto const firstReflections = receiver.recorder().reflections();
  require(
      firstReflections.size() > firstReflectionBegin,
      "mixed update-rate subscription first update produced no reflection callback");
  assertPassel(
      firstReflectionBegin,
      firstReliableBytes,
      firstBestEffortBytes,
      firstTagBytes,
      true,
      "mixed update-rate subscription first passel");

  auto const secondReflectionBegin = receiver.recorder().reflections().size();
  sendUpdate(secondReliableBytes, secondBestEffortBytes, secondTagBytes);
  waitFor(
      receiver,
      [&] { return countAttribute(receiverReliable) >= 2U; },
      options,
      "mixed update-rate subscription second reliable reflection");
  auto const secondReflections = receiver.recorder().reflections();
  require(
      secondReflections.size() > secondReflectionBegin,
      "mixed update-rate subscription second update produced no reflection callback");
  require(
      countAttribute(receiverBestEffort) == 1U,
      "mixed update-rate subscription delivered a named-rate best-effort attribute twice");
  assertPassel(
      secondReflectionBegin,
      secondReliableBytes,
      secondBestEffortBytes,
      secondTagBytes,
      false,
      "mixed update-rate subscription second passel");

  receiver.rtiAmbassador().unsubscribeObjectClassAttributes(
      receiverClass,
      receiverAttributes);
  publisher.rtiAmbassador().unpublishObjectClassAttributes(
      publisherClass,
      publisherAttributes);
  publisher.resign(rti::DELETE_OBJECTS);
  receiver.resign(rti::NO_ACTION);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  receiver.disconnect();
  publisher.disconnect();
}

void scenarioTimestampedAttributeUpdateRateReduction(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.modelFom.empty(),
      "Timestamped update-rate reduction requires an adapter-supplied rich FOM model");
  require(
      !options.logicalTimeImplementationName.empty(),
      "Timestamped update-rate reduction requires an adapter-supplied logical-time implementation");

  Session publisher(options, model, "owner");
  Session receiver(options, model, "member");
  auto const federation = federationName(
      options,
      "timestamped-attribute-update-rate-reduction");
  connectAndJoin(publisher, receiver, options, federation, options.modelFom);

  auto const publisherClass = publisher.rtiAmbassador().getObjectClassHandle(
      options.rateObjectClassName);
  auto const receiverClass = receiver.rtiAmbassador().getObjectClassHandle(
      options.rateObjectClassName);
  auto const publisherReliable = publisher.rtiAmbassador().getAttributeHandle(
      publisherClass,
      options.rateReliableAttributeName);
  auto const publisherBestEffort = publisher.rtiAmbassador().getAttributeHandle(
      publisherClass,
      options.rateBestEffortAttributeName);
  auto const receiverReliable = receiver.rtiAmbassador().getAttributeHandle(
      receiverClass,
      options.rateReliableAttributeName);
  auto const receiverBestEffort = receiver.rtiAmbassador().getAttributeHandle(
      receiverClass,
      options.rateBestEffortAttributeName);
  require(
      publisherClass.isValid() && receiverClass.isValid(),
      "Timestamped update-rate reduction object-class lookup returned an invalid handle");
  require(
      publisherReliable.isValid() && publisherBestEffort.isValid() &&
          receiverReliable.isValid() && receiverBestEffort.isValid(),
      "Timestamped update-rate reduction attribute lookup returned an invalid handle");
  require(
      publisherReliable != publisherBestEffort && receiverReliable != receiverBestEffort,
      "Timestamped update-rate reduction adapter supplied duplicate attribute names");

  rti::AttributeHandleSet const publisherAttributes{
      publisherReliable,
      publisherBestEffort};
  rti::AttributeHandleSet const receiverAttributes{
      receiverReliable,
      receiverBestEffort};
  publisher.rtiAmbassador().publishObjectClassAttributes(
      publisherClass,
      publisherAttributes);
  receiver.rtiAmbassador().subscribeObjectClassAttributes(
      receiverClass,
      rti::AttributeHandleSet{receiverReliable},
      true,
      L"");
  receiver.rtiAmbassador().subscribeObjectClassAttributes(
      receiverClass,
      rti::AttributeHandleSet{receiverBestEffort},
      true,
      options.rateDesignatorName);
  publisher.rtiAmbassador().changeDefaultAttributeOrderType(
      publisherClass,
      publisherAttributes,
      rti::TIMESTAMP);

  auto const object = publisher.rtiAmbassador().registerObjectInstance(publisherClass);
  require(
      object.isValid(),
      "Timestamped update-rate reduction registration returned an invalid object handle");
  waitFor(
      receiver,
      [&] { return receiver.recorder().hasDiscovery(object); },
      options,
      "Timestamped update-rate reduction object discovery");

  auto publisherTime = makeTimeContext(publisher);
  auto receiverTime = makeTimeContext(receiver);
  require(
      publisherTime.factory->getName() == receiverTime.factory->getName(),
      "Timestamped update-rate reduction members selected different logical-time factories");
  auto const lookaheadTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      5U);
  auto lookahead = publisherTime.factory->makeZero();
  require(
      lookahead != nullptr,
      "Timestamped update-rate reduction could not allocate a lookahead interval");
  lookahead->setToDifference(*lookaheadTime, *publisherTime.initial);
  receiver.rtiAmbassador().enableTimeConstrained();
  waitFor(
      receiver,
      [&] { return receiver.recorder().timeConstrainedEnabled().size() >= 1U; },
      options,
      "Timestamped update-rate reduction time-constrained callback");
  publisher.rtiAmbassador().enableTimeRegulation(*lookahead);
  waitFor(
      publisher,
      [&] { return publisher.recorder().timeRegulationEnabled().size() >= 1U; },
      options,
      "Timestamped update-rate reduction time-regulation callback");

  auto const namedRate = receiver.rtiAmbassador().getUpdateRateValue(
      options.rateDesignatorName);
  require(
      namedRate > 0.0,
      "Timestamped update-rate reduction named designator did not resolve to a positive rate");
  require(
      receiver.rtiAmbassador().getUpdateRateValueForAttribute(
          object,
          receiverBestEffort) == namedRate,
      "Timestamped update-rate reduction active named subscription did not select its rate");
  require(
      receiver.rtiAmbassador().getUpdateRateValueForAttribute(
          object,
          receiverReliable) == 0.0,
      "Timestamped update-rate reduction default subscription unexpectedly selected a rate");

  std::vector<std::uint8_t> const reliableBytes{0x71U, 0x72U};
  std::vector<std::uint8_t> const bestEffortBytes{0x81U, 0x82U};
  std::vector<std::uint8_t> const tagBytes{0x91U};
  rti::AttributeHandleValueMap values;
  values.emplace(
      publisherReliable,
      rti::VariableLengthData(reliableBytes.data(), reliableBytes.size()));
  values.emplace(
      publisherBestEffort,
      rti::VariableLengthData(bestEffortBytes.data(), bestEffortBytes.size()));
  rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());

  auto const publisherTargetOne = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      2U);
  auto const firstTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      6U);
  auto const secondTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      7U);
  auto const thirdTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      8U);
  auto const firstRetraction = publisher.rtiAmbassador().updateAttributeValues(
      object,
      values,
      tag,
      *firstTime);
  require(
      firstRetraction.isValid(),
      "Timestamped update-rate reduction first update returned an invalid retraction handle");
  receiver.rtiAmbassador().timeAdvanceRequest(*firstTime);
  publisher.rtiAmbassador().timeAdvanceRequest(*publisherTargetOne);
  waitForSessions(
      {&publisher, &receiver},
      [&] {
        return publisher.recorder().timeAdvanceGrants().size() >= 1U &&
            receiver.recorder().timeAdvanceGrants().size() >= 1U &&
            receiver.recorder().timedReflections().size() >= 2U;
      },
      options,
      "Timestamped update-rate reduction first reflections and grants");

  auto countAttribute = [&](rti::AttributeHandle const& handle) {
    std::size_t count = 0U;
    for (auto const& reflection : receiver.recorder().timedReflections()) {
      if (reflection.values.count(handle) == 1U) {
        ++count;
      }
    }
    return count;
  };
  auto assertReflection = [&](TimedReflectionRecord const& reflection,
                              rti::AttributeHandle const& expectedAttribute,
                              std::vector<std::uint8_t> const& expectedValue,
                              std::vector<std::uint8_t> const& expectedTime,
                              std::vector<std::uint8_t> const& expectedRetraction,
                              std::wstring const& expectedTransportation) {
    require(
        reflection.object == object && reflection.values.size() == 1U &&
            reflection.values.count(expectedAttribute) == 1U &&
            copyBytes(reflection.values.at(expectedAttribute)) == expectedValue,
        "Timestamped update-rate reduction reflection returned the wrong object, attribute, or value");
    require(
        reflection.tag == tagBytes && reflection.producer == publisher.federateHandle() &&
            reflection.time == expectedTime && !reflection.timeText.empty(),
        "Timestamped update-rate reduction reflection changed standard delivery metadata");
    require(
        reflection.transportation.isValid() &&
            receiver.rtiAmbassador().getTransportationTypeName(reflection.transportation) ==
                expectedTransportation,
        "Timestamped update-rate reduction reflection returned the wrong transportation type");
    require(
        reflection.sentOrder == rti::TIMESTAMP &&
            reflection.receivedOrder == rti::TIMESTAMP &&
            reflection.retractionPresent && reflection.retraction == expectedRetraction,
        "Timestamped update-rate reduction reflection returned the wrong order or retraction metadata");
  };
  auto const firstReflections = receiver.recorder().timedReflections();
  require(
      firstReflections.size() == 2U && countAttribute(receiverReliable) == 1U &&
          countAttribute(receiverBestEffort) == 1U,
      "Timestamped update-rate reduction first passel did not deliver both attributes once");
  for (auto const& reflection : firstReflections) {
    if (reflection.values.count(receiverReliable) == 1U) {
      assertReflection(
          reflection,
          receiverReliable,
          reliableBytes,
          encodeTime(*firstTime),
          copyBytes(firstRetraction.encode()),
          L"HLAreliable");
    } else {
      assertReflection(
          reflection,
          receiverBestEffort,
          bestEffortBytes,
          encodeTime(*firstTime),
          copyBytes(firstRetraction.encode()),
          L"HLAbestEffort");
    }
  }

  auto const secondRetraction = publisher.rtiAmbassador().updateAttributeValues(
      object,
      values,
      tag,
      *secondTime);
  require(
      secondRetraction.isValid(),
      "Timestamped update-rate reduction second update returned an invalid retraction handle");
  receiver.rtiAmbassador().timeAdvanceRequest(*secondTime);
  publisher.rtiAmbassador().timeAdvanceRequest(*publisherTargetOne);
  waitForSessions(
      {&publisher, &receiver},
      [&] {
        return publisher.recorder().timeAdvanceGrants().size() >= 2U &&
            receiver.recorder().timeAdvanceGrants().size() >= 2U &&
            receiver.recorder().timedReflections().size() >= 3U;
      },
      options,
      "Timestamped update-rate reduction second reflections and grants");
  auto const secondReflections = receiver.recorder().timedReflections();
  require(
      secondReflections.size() == 3U && countAttribute(receiverReliable) == 2U &&
          countAttribute(receiverBestEffort) == 1U,
      "Timestamped update-rate reduction suppressed the wrong second passel");
  auto const& secondReliableReflection = secondReflections.back();
  require(
      secondReliableReflection.values.count(receiverReliable) == 1U,
      "Timestamped update-rate reduction second delivery was not the reliable attribute");
  assertReflection(
      secondReliableReflection,
      receiverReliable,
      reliableBytes,
      encodeTime(*secondTime),
      copyBytes(secondRetraction.encode()),
      L"HLAreliable");

  rti::AttributeHandleValueMap bestEffortOnly;
  bestEffortOnly.emplace(
      publisherBestEffort,
      rti::VariableLengthData(bestEffortBytes.data(), bestEffortBytes.size()));
  auto const suppressedRetraction = publisher.rtiAmbassador().updateAttributeValues(
      object,
      bestEffortOnly,
      tag,
      *thirdTime);
  require(
      suppressedRetraction.isValid(),
      "Timestamped update-rate reduction suppressed update returned an invalid retraction handle");
  receiver.rtiAmbassador().timeAdvanceRequest(*thirdTime);
  publisher.rtiAmbassador().timeAdvanceRequest(*publisherTargetOne);
  waitForSessions(
      {&publisher, &receiver},
      [&] {
        return publisher.recorder().timeAdvanceGrants().size() >= 3U;
      },
      options,
      "Timestamped update-rate reduction suppressed passel grant");
  require(
      receiver.recorder().timedReflections().size() == 3U,
      "Timestamped update-rate reduction delivered an all-best-effort suppressed passel");
  publisher.rtiAmbassador().retract(suppressedRetraction);
  requireException(
      [&] { publisher.rtiAmbassador().retract(suppressedRetraction); },
      L"MessageCanNoLongerBeRetracted",
      "Timestamped update-rate reduction second suppressed-passel retraction");

  receiver.rtiAmbassador().disableTimeConstrained();
  publisher.rtiAmbassador().disableTimeRegulation();
  receiver.rtiAmbassador().unsubscribeObjectClassAttributes(
      receiverClass,
      receiverAttributes);
  publisher.rtiAmbassador().unpublishObjectClassAttributes(
      publisherClass,
      publisherAttributes);
  receiver.resign(rti::NO_ACTION);
  publisher.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  receiver.disconnect();
  publisher.disconnect();
}

void scenarioHandleWireFormats(Options const& options, rti::CallbackModel model) {
  Session publisher(options, model, "owner");
  Session receiver(options, model, "member");
  auto const federation = federationName(options, "handle-wire-formats");
  connectAndJoin(publisher, receiver, options, federation, options.ddmFom);

  auto const publisherHandles = ddmHandles(publisher, options);
  auto const receiverHandles = ddmHandles(receiver, options);
  require(
      publisherHandles.objectClass == receiverHandles.objectClass &&
          publisherHandles.attribute == receiverHandles.attribute &&
          publisherHandles.interactionClass == receiverHandles.interactionClass &&
          publisherHandles.parameter == receiverHandles.parameter &&
          publisherHandles.firstDimension == receiverHandles.firstDimension &&
          publisherHandles.secondDimension == receiverHandles.secondDimension,
      "handle wire-format setup returned different ordinary or dimension handles");
  verifyDdmClassDimensions(
      publisher,
      options,
      publisherHandles,
      "handle wire-format");

  auto const region = createDdmRegion(
      publisher,
      publisherHandles,
      1UL,
      5UL,
      2UL,
      7UL);
  verifyDdmRegion(
      publisher,
      publisherHandles,
      region,
      1UL,
      5UL,
      2UL,
      7UL,
      "handle wire-format region");

  auto requireHandleRoundTrip = [&](auto const& handle, auto decoder,
                                    std::string const& description) {
    auto const encoded = handle.encode();
    require(encoded.size() == handle.encodedLength(),
            description + " reported an inconsistent encoded length");
    require(encoded.size() > 0U, description + " produced an empty encoding");
    require(decoder(encoded) == handle, description + " did not round-trip");
  };
  requireHandleRoundTrip(
      publisherHandles.firstDimension,
      [&](rti::VariableLengthData const& encoded) {
        return publisher.rtiAmbassador().decodeDimensionHandle(encoded);
      },
      "Dimension handle");
  requireHandleRoundTrip(
      region,
      [&](rti::VariableLengthData const& encoded) {
        return publisher.rtiAmbassador().decodeRegionHandle(encoded);
      },
      "Region handle");

  rti::AttributeHandleSet publisherAttributes;
  publisherAttributes.insert(publisherHandles.attribute);
  rti::AttributeHandleSet receiverAttributes;
  receiverAttributes.insert(receiverHandles.attribute);
  publisher.rtiAmbassador().publishObjectClassAttributes(
      publisherHandles.objectClass,
      publisherAttributes);
  publisher.rtiAmbassador().changeDefaultAttributeOrderType(
      publisherHandles.objectClass,
      publisherAttributes,
      rti::TIMESTAMP);
  receiver.rtiAmbassador().subscribeObjectClassAttributes(
      receiverHandles.objectClass,
      receiverAttributes,
      true,
      L"");
  auto const object = publisher.rtiAmbassador().registerObjectInstance(
      publisherHandles.objectClass);
  require(object.isValid(), "handle wire-format registration returned an invalid object");
  waitFor(
      receiver,
      [&] { return receiver.recorder().hasDiscovery(object); },
      options,
      "handle wire-format object discovery");

  auto publisherTime = makeTimeContext(publisher);
  auto receiverTime = makeTimeContext(receiver);
  enableTimestampedRoles(
      publisher,
      receiver,
      publisherTime,
      receiverTime,
      options,
      "handle wire-format");
  auto const messageTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      3U);
  std::vector<std::uint8_t> valueBytes{0x71U, 0x72U, 0x73U};
  std::vector<std::uint8_t> tagBytes{0x48U, 0x57U, 0x46U};
  rti::AttributeHandleValueMap values;
  values.emplace(
      publisherHandles.attribute,
      rti::VariableLengthData(valueBytes.data(), valueBytes.size()));
  rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());
  auto const retraction = publisher.rtiAmbassador().updateAttributeValues(
      object,
      values,
      tag,
      *messageTime);
  require(
      retraction.isValid(),
      "handle wire-format timestamped update returned an invalid retraction handle");
  requireHandleRoundTrip(
      retraction,
      [&](rti::VariableLengthData const& encoded) {
        return publisher.rtiAmbassador().decodeMessageRetractionHandle(encoded);
      },
      "Message retraction handle");
  requirePortableHandleEncoding(
      publisherHandles.firstDimension,
      "Dimension handle");
  requirePortableHandleEncoding(region, "Region handle");
  requirePortableHandleEncoding(retraction, "Message retraction handle");

  auto requireEmptyDecodeRejected = [&](auto decoder, std::string const& description) {
    requireException(
        [&] { static_cast<void>(decoder(rti::VariableLengthData{})); },
        L"CouldNotDecode",
        description + " accepted an empty encoding");
  };
  requireEmptyDecodeRejected(
      [&](rti::VariableLengthData const& encoded) {
        return publisher.rtiAmbassador().decodeDimensionHandle(encoded);
      },
      "Dimension handle decoder");
  requireEmptyDecodeRejected(
      [&](rti::VariableLengthData const& encoded) {
        return publisher.rtiAmbassador().decodeRegionHandle(encoded);
      },
      "Region handle decoder");
  requireEmptyDecodeRejected(
      [&](rti::VariableLengthData const& encoded) {
        return publisher.rtiAmbassador().decodeMessageRetractionHandle(encoded);
      },
      "Message retraction handle decoder");

  publisher.rtiAmbassador().retract(retraction);
  receiver.rtiAmbassador().disableTimeConstrained();
  publisher.rtiAmbassador().disableTimeRegulation();
  receiver.rtiAmbassador().unsubscribeObjectClassAttributes(
      receiverHandles.objectClass,
      receiverAttributes);
  publisher.rtiAmbassador().unpublishObjectClassAttributes(
      publisherHandles.objectClass,
      publisherAttributes);
  publisher.rtiAmbassador().deleteRegion(region);
  receiver.resign(rti::NO_ACTION);
  publisher.resign(rti::DELETE_OBJECTS);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
}

void scenarioOrdinaryEdges(Options const& options, rti::CallbackModel model) {
  Session owner(options, model, "owner");
  Session member(options, model, "member");
  Session passive(options, model, "passive");
  auto const federation = federationName(options, "ordinary-edges");
  connectAndJoin(owner, member, options, federation, options.fom);
  passive.connect();
  passive.join(
      options.memberFederateName + L"-passive",
      options.federateType,
      federation);

  rti::ObjectClassHandle ownerClass;
  rti::AttributeHandle ownerAttribute;
  rti::InteractionClassHandle ownerInteraction;
  rti::ParameterHandle ownerParameter;
  handles(owner, options, ownerClass, ownerAttribute, ownerInteraction, ownerParameter);
  auto const memberClass = member.rtiAmbassador().getObjectClassHandle(options.objectClassName);
  auto const memberAttribute =
      member.rtiAmbassador().getAttributeHandle(memberClass, options.attributeName);
  auto const memberInteraction =
      member.rtiAmbassador().getInteractionClassHandle(options.interactionClassName);
  auto const passiveClass =
      passive.rtiAmbassador().getObjectClassHandle(options.objectClassName);
  auto const passiveAttribute =
      passive.rtiAmbassador().getAttributeHandle(passiveClass, options.attributeName);
  auto const passiveInteraction =
      passive.rtiAmbassador().getInteractionClassHandle(options.interactionClassName);
  require(memberClass.isValid() && memberAttribute.isValid(),
          "Ordinary-edge member handle lookup returned an invalid handle");
  require(memberInteraction.isValid(),
          "Ordinary-edge member interaction lookup returned an invalid handle");
  require(passiveClass.isValid() && passiveAttribute.isValid(),
          "Ordinary-edge passive handle lookup returned an invalid handle");
  require(passiveInteraction.isValid(),
          "Ordinary-edge passive interaction lookup returned an invalid handle");

  rti::AttributeHandleSet ownerAttributes;
  ownerAttributes.insert(ownerAttribute);
  rti::AttributeHandleSet memberAttributes;
  memberAttributes.insert(memberAttribute);
  rti::AttributeHandleSet passiveAttributes;
  passiveAttributes.insert(passiveAttribute);
  owner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerAttributes);
  owner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerAttributes);
  member.rtiAmbassador().subscribeObjectClassAttributes(
      memberClass, memberAttributes, true, L"");
  member.rtiAmbassador().subscribeObjectClassAttributes(
      memberClass, memberAttributes, true, L"");
  passive.rtiAmbassador().subscribeObjectClassAttributes(
      passiveClass, passiveAttributes, false, L"");
  owner.rtiAmbassador().publishInteractionClass(ownerInteraction);
  owner.rtiAmbassador().publishInteractionClass(ownerInteraction);
  member.rtiAmbassador().subscribeInteractionClass(memberInteraction, true);
  member.rtiAmbassador().subscribeInteractionClass(memberInteraction, true);
  passive.rtiAmbassador().subscribeInteractionClass(passiveInteraction, false);

  std::vector<std::uint8_t> interactionValue{0x71U, 0x72U};
  std::vector<std::uint8_t> interactionTagBytes{0x81U, 0x82U};
  rti::VariableLengthData interactionTag(
      interactionTagBytes.data(), interactionTagBytes.size());
  rti::ParameterHandleValueMap interactionParameters;
  interactionParameters.emplace(
      ownerParameter,
      rti::VariableLengthData(interactionValue.data(), interactionValue.size()));
  owner.rtiAmbassador().sendInteraction(
      ownerInteraction, interactionParameters, interactionTag);
  waitFor(member, [&] { return member.recorder().interaction().present; }, options,
          "ordinary-edge interaction delivery");
  auto const receivedInteraction = member.recorder().interaction();
  require(receivedInteraction.interaction == memberInteraction,
          "Ordinary-edge interaction delivery returned the wrong class");
  require(receivedInteraction.parameters.size() == 1U &&
              receivedInteraction.parameters.count(ownerParameter) == 1U &&
              copyBytes(receivedInteraction.parameters.at(ownerParameter)) == interactionValue,
          "Ordinary-edge interaction delivery returned the wrong parameter value");
  require(receivedInteraction.tag == interactionTagBytes,
          "Ordinary-edge interaction delivery returned the wrong tag");
  require(receivedInteraction.producer == owner.federateHandle(),
          "Ordinary-edge interaction delivery returned the wrong producer");
  for (int pass = 0; pass != 8; ++pass) {
    passive.pump();
  }
  require(passive.recorder().interaction().present == false,
          "Passive interaction declaration unexpectedly received an interaction");

  requireException(
      [&] {
        passive.rtiAmbassador().sendInteraction(
            passiveInteraction, interactionParameters, interactionTag);
      },
      L"InteractionClassNotPublished",
      "ordinary-edge interaction send without publication");
  rti::ParameterHandleValueMap invalidInteractionParameters;
  invalidInteractionParameters.emplace(rti::ParameterHandle{}, rti::VariableLengthData{});
  requireException(
      [&] {
        owner.rtiAmbassador().sendInteraction(
            ownerInteraction, invalidInteractionParameters, interactionTag);
      },
      L"InteractionParameterNotDefined",
      "ordinary-edge interaction send with an undefined parameter");
  member.recorder().clearInteraction();
  member.rtiAmbassador().unsubscribeInteractionClass(memberInteraction);
  owner.rtiAmbassador().sendInteraction(
      ownerInteraction, interactionParameters, interactionTag);
  for (int pass = 0; pass != 8; ++pass) {
    member.pump();
  }
  require(!member.recorder().interaction().present,
          "Unsubscribed member unexpectedly received a later interaction");
  owner.rtiAmbassador().unpublishInteractionClass(ownerInteraction);
  requireException(
      [&] {
        owner.rtiAmbassador().sendInteraction(
            ownerInteraction, interactionParameters, interactionTag);
      },
      L"InteractionClassNotPublished",
      "ordinary-edge interaction send after unpublication");

  auto const object = owner.rtiAmbassador().registerObjectInstance(ownerClass);
  require(object.isValid(), "Ordinary-edge registration returned an invalid handle");
  waitFor(member, [&] { return member.recorder().discovery().present; }, options,
          "ordinary-edge discovery");
  auto const knownObject = member.recorder().discovery().object;
  require(knownObject == object, "Ordinary-edge discovery returned the wrong object");
  for (int pass = 0; pass != 8; ++pass) {
    passive.pump();
  }
  require(!passive.recorder().discovery().present,
          "Passive declaration unexpectedly produced object discovery");

  rti::AttributeHandleValueMap ownerValues;
  std::vector<std::uint8_t> valueBytes{0x11U, 0x22U};
  ownerValues.emplace(
      ownerAttribute,
      rti::VariableLengthData(valueBytes.data(), valueBytes.size()));
  requireException(
      [&] {
        owner.rtiAmbassador().updateAttributeValues(
            rti::ObjectInstanceHandle{},
            ownerValues,
            rti::VariableLengthData{});
      },
      L"ObjectInstanceNotKnown",
      "ordinary update for an unknown object instance");
  owner.rtiAmbassador().updateAttributeValues(object, ownerValues, rti::VariableLengthData{});
  waitFor(member, [&] { return member.recorder().reflection().present; }, options,
          "ordinary-edge reflection");
  require(copyBytes(member.recorder().reflection().values.at(memberAttribute)) == valueBytes,
          "Ordinary-edge reflection returned the wrong value");
  for (int pass = 0; pass != 8; ++pass) {
    passive.pump();
  }
  require(!passive.recorder().reflection().present,
          "Passive declaration unexpectedly produced attribute reflection");

  rti::AttributeHandleValueMap memberValues;
  memberValues.emplace(
      memberAttribute,
      rti::VariableLengthData(valueBytes.data(), valueBytes.size()));
  requireException(
      [&] {
        member.rtiAmbassador().updateAttributeValues(
            knownObject, memberValues, rti::VariableLengthData{});
      },
      L"AttributeNotOwned",
      "non-owner ordinary attribute update");
  requireException(
      [&] {
        member.rtiAmbassador().requestAttributeValueUpdate(
            rti::ObjectInstanceHandle{}, memberAttributes, rti::VariableLengthData{});
      },
      L"ObjectInstanceNotKnown",
      "unknown object attribute-value request");
  requireException(
      [&] {
        static_cast<void>(member.rtiAmbassador().getKnownObjectClassHandle(
            rti::ObjectInstanceHandle{}));
      },
      L"ObjectInstanceNotKnown",
      "unknown object class lookup");
  rti::AttributeHandleValueMap invalidValues;
  invalidValues.emplace(rti::AttributeHandle{}, rti::VariableLengthData{});
  requireException(
      [&] {
        owner.rtiAmbassador().updateAttributeValues(
            object, invalidValues, rti::VariableLengthData{});
      },
      L"AttributeNotDefined",
      "ordinary update with an undefined attribute");

  member.recorder().clearReflection();
  member.rtiAmbassador().unsubscribeObjectClassAttributes(memberClass, memberAttributes);
  owner.rtiAmbassador().updateAttributeValues(object, ownerValues, rti::VariableLengthData{});
  for (int pass = 0; pass != 8; ++pass) {
    member.pump();
  }
  require(!member.recorder().reflection().present,
          "Unsubscribed member unexpectedly received an attribute reflection");
  passive.rtiAmbassador().unsubscribeObjectClassAttributes(passiveClass, passiveAttributes);
  passive.rtiAmbassador().unsubscribeInteractionClass(passiveInteraction);
  owner.rtiAmbassador().unpublishObjectClassAttributes(ownerClass, ownerAttributes);

  owner.resign(rti::DELETE_OBJECTS);
  member.resign(rti::NO_ACTION);
  passive.resign(rti::NO_ACTION);
}

void scenarioNamedRegistration(Options const& options, rti::CallbackModel model) {
  Session owner(options, model, "owner");
  Session member(options, model, "member");
  auto const federation = federationName(options, "named-registration");
  connectAndJoin(owner, member, options, federation, options.fom);

  rti::ObjectClassHandle objectClass;
  rti::AttributeHandle attribute;
  rti::InteractionClassHandle interactionClass;
  rti::ParameterHandle parameter;
  handles(owner, options, objectClass, attribute, interactionClass, parameter);
  rti::AttributeHandleSet attributes;
  attributes.insert(attribute);
  owner.rtiAmbassador().publishObjectClassAttributes(objectClass, attributes);
  member.rtiAmbassador().subscribeObjectClassAttributes(objectClass, attributes, true, L"");
  requireException(
      [&] { owner.rtiAmbassador().reserveObjectInstanceName(L""); },
      L"IllegalName",
      "reserving an empty object instance name");

  auto const releasedName = federation + L"-released-name";
  owner.rtiAmbassador().reserveObjectInstanceName(releasedName);
  waitFor(owner, [&] { return owner.recorder().reservationSucceeded(releasedName); }, options,
          "single object-name reservation");
  owner.rtiAmbassador().releaseObjectInstanceName(releasedName);
  owner.recorder().clearReservations();
  owner.rtiAmbassador().reserveObjectInstanceName(releasedName);
  waitFor(owner, [&] { return owner.recorder().reservationSucceeded(releasedName); }, options,
          "reuse of a released object name");
  owner.rtiAmbassador().releaseObjectInstanceName(releasedName);
  requireException(
      [&] { owner.rtiAmbassador().releaseObjectInstanceName(releasedName); },
      L"ObjectInstanceNameNotReserved",
      "second release of an object name");

  std::set<std::wstring> batchNames{
      federation + L"-batch-a",
      federation + L"-batch-b"};
  owner.recorder().clearReservations();
  owner.rtiAmbassador().reserveMultipleObjectInstanceNames(batchNames);
  waitFor(owner, [&] { return owner.recorder().multipleReservationSucceeded(batchNames); }, options,
          "multiple object-name reservation");
  owner.rtiAmbassador().releaseMultipleObjectInstanceNames(batchNames);
  owner.recorder().clearReservations();
  owner.rtiAmbassador().reserveObjectInstanceName(*batchNames.begin());
  waitFor(owner, [&] {
    return owner.recorder().reservationSucceeded(*batchNames.begin());
  }, options, "reuse of a released multiple reservation");
  owner.rtiAmbassador().releaseObjectInstanceName(*batchNames.begin());

  auto const name = federation + L"-named-object";
  owner.rtiAmbassador().reserveObjectInstanceName(name);
  waitFor(owner, [&] { return owner.recorder().reservationSucceeded(name); }, options,
          "named object reservation");
  auto const object = owner.rtiAmbassador().registerObjectInstance(objectClass, name);
  require(object.isValid(), "Named registration returned an invalid handle");
  require(owner.rtiAmbassador().getObjectInstanceHandle(name) == object,
          "Named registration lookup did not round-trip at the owner");

  waitFor(member, [&] { return member.recorder().discovery().present; }, options,
          "named object discovery");
  auto const discovered = member.recorder().discovery();
  require(discovered.object == object, "Named discovery returned the wrong object handle");
  require(discovered.name == name, "Named discovery returned the wrong instance name");
  require(member.rtiAmbassador().getObjectInstanceHandle(name) == object,
          "Named registration lookup did not round-trip at the member");

  auto const unreservedName = federation + L"-unreserved-name";
  requireException(
      [&] {
        static_cast<void>(owner.rtiAmbassador().registerObjectInstance(
            objectClass,
            unreservedName));
      },
      L"ObjectInstanceNameNotReserved",
      "named registration with an unreserved object name");

  member.recorder().clearReservations();
  member.rtiAmbassador().reserveObjectInstanceName(name);
  waitFor(member, [&] { return member.recorder().reservationFailed(name); }, options,
          "reservation failure for an in-use object name");

  owner.resign(rti::DELETE_OBJECTS);
  member.resign(rti::NO_ACTION);
}

void scenarioLocalDeleteObjectInstance(
    Options const& options,
    rti::CallbackModel model) {
  Session unjoined(options, model, "local-delete-unjoined");
  Session owner(options, model, "owner");
  Session requester(options, model, "requester");
  auto const federation = federationName(options, "local-delete-object-instance");

  requireException(
      [&] { owner.rtiAmbassador().localDeleteObjectInstance(rti::ObjectInstanceHandle{}); },
      L"NotConnected",
      "local deletion before connect");
  unjoined.connect();
  requireException(
      [&] {
        unjoined.rtiAmbassador().localDeleteObjectInstance(rti::ObjectInstanceHandle{});
      },
      L"FederateNotExecutionMember",
      "local deletion after connect before join");

  connectAndJoin(owner, requester, options, federation, options.fom);

  auto const ownerClass = owner.rtiAmbassador().getObjectClassHandle(options.objectClassName);
  auto const ownerAttribute = owner.rtiAmbassador().getAttributeHandle(
      ownerClass,
      options.attributeName);
  auto const requesterClass = requester.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const requesterAttribute = requester.rtiAmbassador().getAttributeHandle(
      requesterClass,
      options.attributeName);
  require(
      ownerClass.isValid() && ownerAttribute.isValid() && requesterClass.isValid() &&
          requesterAttribute.isValid(),
      "Local deletion handle lookup returned an invalid handle");
  rti::AttributeHandleSet const ownerAttributes{ownerAttribute};
  rti::AttributeHandleSet const requesterAttributes{requesterAttribute};

  owner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerAttributes);
  requester.rtiAmbassador().subscribeObjectClassAttributes(
      requesterClass,
      requesterAttributes,
      true,
      L"");

  auto const object = owner.rtiAmbassador().registerObjectInstance(ownerClass);
  require(object.isValid(), "Local deletion registration returned an invalid object handle");
  waitFor(
      requester,
      [&] { return requester.recorder().hasDiscovery(object); },
      options,
      "local deletion object discovery");
  auto const discovery = requester.recorder().discovery();
  require(
      discovery.object == object && discovery.objectClass == requesterClass &&
          requester.rtiAmbassador().getKnownObjectClassHandle(object) == requesterClass,
      "Local deletion discovery did not establish object identity");

  requireException(
      [&] { owner.rtiAmbassador().localDeleteObjectInstance(object); },
      L"FederateOwnsAttributes",
      "local deletion while owning object attributes");

  std::vector<std::uint8_t> acquisitionTagBytes{0x51U, 0x18U};
  rti::VariableLengthData const acquisitionTag(
      acquisitionTagBytes.data(),
      acquisitionTagBytes.size());
  requester.rtiAmbassador().publishObjectClassAttributes(
      requesterClass,
      requesterAttributes);
  requester.rtiAmbassador().attributeOwnershipAcquisition(
      object,
      requesterAttributes,
      acquisitionTag);
  requireException(
      [&] { requester.rtiAmbassador().localDeleteObjectInstance(object); },
      L"OwnershipAcquisitionPending",
      "local deletion while ownership acquisition is pending");
  requester.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);

  // Rejoin a fresh requester so the successful local-delete transition is
  // independent of the canceled ownership-acquisition request.
  Session freshRequester(options, model, "local-delete-requester-fresh");
  freshRequester.connect();
  freshRequester.join(
      options.memberFederateName + L"-fresh",
      options.federateType,
      federation);
  auto const freshClass = freshRequester.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const freshAttribute = freshRequester.rtiAmbassador().getAttributeHandle(
      freshClass,
      options.attributeName);
  require(
      freshClass.isValid() && freshAttribute.isValid(),
      "Fresh local deletion handle lookup returned an invalid handle");
  rti::AttributeHandleSet const freshAttributes{freshAttribute};
  freshRequester.rtiAmbassador().subscribeObjectClassAttributes(
      freshClass,
      freshAttributes,
      true,
      L"");
  waitFor(
      freshRequester,
      [&] { return freshRequester.recorder().hasDiscovery(object); },
      options,
      "fresh requester object discovery");

  freshRequester.rtiAmbassador().localDeleteObjectInstance(object);
  requireException(
      [&] { static_cast<void>(freshRequester.rtiAmbassador().getKnownObjectClassHandle(object)); },
      L"ObjectInstanceNotKnown",
      "object identity after local deletion");

  freshRequester.recorder().clearDiscovery();
  freshRequester.rtiAmbassador().subscribeObjectClassAttributes(
      freshClass,
      freshAttributes,
      true,
      L"");
  waitFor(
      freshRequester,
      [&] { return freshRequester.recorder().hasDiscovery(object); },
      options,
      "rediscovery after local deletion");
  require(
      freshRequester.rtiAmbassador().getKnownObjectClassHandle(object) == freshClass,
      "Rediscovery after local deletion did not restore object identity");

  freshRequester.recorder().clearReflection();
  std::vector<std::uint8_t> valueBytes{0x04U, 0x20U};
  rti::AttributeHandleValueMap values;
  values.emplace(
      ownerAttribute,
      rti::VariableLengthData(valueBytes.data(), valueBytes.size()));
  std::vector<std::uint8_t> updateTagBytes{0x7AU};
  rti::VariableLengthData const updateTag(updateTagBytes.data(), updateTagBytes.size());
  owner.rtiAmbassador().updateAttributeValues(object, values, updateTag);
  waitFor(
      freshRequester,
      [&] { return freshRequester.recorder().reflectionCount() == 1U; },
      options,
      "post-local-delete attribute reflection");
  auto const reflection = freshRequester.recorder().reflection();
  require(
      reflection.present && reflection.object == object && reflection.tag == updateTagBytes &&
          reflection.producer == owner.federateHandle() &&
          reflection.values.find(freshAttribute) != reflection.values.end() &&
          copyBytes(reflection.values.at(freshAttribute)) == valueBytes,
      "Post-local-delete reflection returned the wrong metadata or value");

  freshRequester.resign(rti::NO_ACTION);
  owner.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  unjoined.disconnect();
  requester.disconnect();
  freshRequester.disconnect();
  owner.disconnect();
}

void scenarioObjectNameReservationLifecycle(
    Options const& options,
    rti::CallbackModel model) {
  Session unjoined(options, model, "unjoined");
  Session owner(options, model, "owner");
  Session peer(options, model, "member");
  auto const federation = federationName(options, "object-name-reservation-lifecycle");
  std::set<std::wstring> const lifecycleNames{
      L"tck-lifecycle-reservation-a",
      L"tck-lifecycle-reservation-b"};

  auto requireReservationLifecycle = [&](std::wstring const& expected,
                                          std::string const& phase) {
    requireException(
        [&] { unjoined.rtiAmbassador().reserveObjectInstanceName(*lifecycleNames.begin()); },
        expected,
        "reserving an object name " + phase);
    requireException(
        [&] { unjoined.rtiAmbassador().releaseObjectInstanceName(*lifecycleNames.begin()); },
        expected,
        "releasing an object name " + phase);
    requireException(
        [&] { unjoined.rtiAmbassador().reserveMultipleObjectInstanceNames(lifecycleNames); },
        expected,
        "reserving multiple object names " + phase);
    requireException(
        [&] { unjoined.rtiAmbassador().releaseMultipleObjectInstanceNames(lifecycleNames); },
        expected,
        "releasing multiple object names " + phase);
  };

  requireReservationLifecycle(L"NotConnected", "before connect");
  unjoined.connect();
  requireReservationLifecycle(L"FederateNotExecutionMember", "after connect before join");

  owner.connect();
  peer.connect();
  owner.rtiAmbassador().createFederationExecution(
      federation,
      options.fom.wstring(),
      options.logicalTimeImplementationName);
  owner.join(options.ownerFederateName, options.federateType, federation);
  peer.join(options.memberFederateName, options.federateType, federation);

  requireException(
      [&] { owner.rtiAmbassador().reserveObjectInstanceName(L""); },
      L"IllegalName",
      "reserving an empty object name");
  requireException(
      [&] { owner.rtiAmbassador().reserveObjectInstanceName(L"HLA.TckReserved"); },
      L"IllegalName",
      "reserving an HLA-namespace object name");
  requireException(
      [&] { owner.rtiAmbassador().reserveMultipleObjectInstanceNames({}); },
      L"NameSetWasEmpty",
      "reserving an empty object-name set");
  requireException(
      [&] {
        owner.rtiAmbassador().reserveMultipleObjectInstanceNames(
            {L"tck-valid-object-name", L"HLA.TckInvalidObjectName"});
      },
      L"IllegalName",
      "reserving a set containing an HLA-namespace object name");

  auto const singleName = federation + L"-single-reservation";
  owner.recorder().clearReservations();
  owner.rtiAmbassador().reserveObjectInstanceName(singleName);
  if (model == rti::HLA_EVOKED) {
    require(
        !owner.recorder().reservationSucceeded(singleName),
        "evoked reservation callback arrived before callback servicing");
  }
  waitFor(
      owner,
      [&] { return owner.recorder().reservationSucceeded(singleName); },
      options,
      "single object-name reservation success");

  peer.recorder().clearReservations();
  peer.rtiAmbassador().reserveObjectInstanceName(singleName);
  if (model == rti::HLA_EVOKED) {
    require(
        !peer.recorder().reservationFailed(singleName),
        "evoked reservation failure callback arrived before callback servicing");
  }
  waitFor(
      peer,
      [&] { return peer.recorder().reservationFailed(singleName); },
      options,
      "contended object-name reservation failure");

  owner.rtiAmbassador().releaseObjectInstanceName(singleName);
  requireException(
      [&] { owner.rtiAmbassador().releaseObjectInstanceName(singleName); },
      L"ObjectInstanceNameNotReserved",
      "releasing an object name twice");

  peer.recorder().clearReservations();
  peer.rtiAmbassador().reserveObjectInstanceName(singleName);
  waitFor(
      peer,
      [&] { return peer.recorder().reservationSucceeded(singleName); },
      options,
      "reusing a released object name");
  peer.rtiAmbassador().releaseObjectInstanceName(singleName);

  auto const multipleA = federation + L"-multiple-a";
  auto const multipleB = federation + L"-multiple-b";
  auto const multipleC = federation + L"-multiple-c";
  std::set<std::wstring> const ownerNames{multipleA, multipleB};
  std::set<std::wstring> const peerNames{multipleB, multipleC};
  std::set<std::wstring> const peerSucceeded{multipleC};
  std::set<std::wstring> const peerFailed{multipleB};

  owner.recorder().clearReservations();
  owner.rtiAmbassador().reserveMultipleObjectInstanceNames(ownerNames);
  if (model == rti::HLA_EVOKED) {
    require(
        !owner.recorder().multipleReservationSucceeded(ownerNames),
        "evoked multiple-reservation callback arrived before callback servicing");
  }
  waitFor(
      owner,
      [&] { return owner.recorder().multipleReservationSucceeded(ownerNames); },
      options,
      "multiple object-name reservation success");

  peer.recorder().clearReservations();
  peer.rtiAmbassador().reserveMultipleObjectInstanceNames(peerNames);
  if (model == rti::HLA_EVOKED) {
    require(
        !peer.recorder().multipleReservationSucceeded(peerSucceeded) &&
            !peer.recorder().multipleReservationFailed(peerFailed),
        "evoked mixed multiple-reservation callbacks arrived before callback servicing");
  }
  waitFor(
      peer,
      [&] {
        return peer.recorder().multipleReservationSucceeded(peerSucceeded) &&
            peer.recorder().multipleReservationFailed(peerFailed);
      },
      options,
      "mixed multiple object-name reservation results");

  requireException(
      [&] {
        owner.rtiAmbassador().releaseMultipleObjectInstanceNames(
            {multipleA, multipleC});
      },
      L"ObjectInstanceNameNotReserved",
      "releasing a mixed-owner object-name set");
  peer.rtiAmbassador().releaseObjectInstanceName(multipleC);
  owner.rtiAmbassador().releaseMultipleObjectInstanceNames(ownerNames);
  owner.rtiAmbassador().releaseMultipleObjectInstanceNames({});

  auto const resignedName = federation + L"-released-on-resign";
  owner.recorder().clearReservations();
  owner.rtiAmbassador().reserveObjectInstanceName(resignedName);
  waitFor(
      owner,
      [&] { return owner.recorder().reservationSucceeded(resignedName); },
      options,
      "object-name reservation before resignation");
  owner.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);

  peer.recorder().clearReservations();
  peer.rtiAmbassador().reserveObjectInstanceName(resignedName);
  waitFor(
      peer,
      [&] { return peer.recorder().reservationSucceeded(resignedName); },
      options,
      "object-name reuse after owner resignation");
  peer.rtiAmbassador().releaseObjectInstanceName(resignedName);

  peer.resign(rti::NO_ACTION);
  peer.rtiAmbassador().destroyFederationExecution(federation);
  unjoined.disconnect();
  owner.disconnect();
  peer.disconnect();
}

void scenarioFinalFederateResignationCleanup(
    Options const& options,
    rti::CallbackModel model) {
  Session lifecycle(options, model, "final-federate-lifecycle");
  auto const federation = federationName(
      options,
      "final-federate-resignation-cleanup");
  lifecycle.connect();
  lifecycle.rtiAmbassador().createFederationExecution(
      federation,
      options.fom.wstring(),
      options.logicalTimeImplementationName);
  lifecycle.join(
      options.ownerFederateName + L"-final-federate-first",
      options.federateType,
      federation);

  auto const firstClass = lifecycle.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const firstAttribute = lifecycle.rtiAmbassador().getAttributeHandle(
      firstClass,
      options.attributeName);
  require(
      firstClass.isValid() && firstAttribute.isValid(),
      "Final-federate resignation lookup returned an invalid handle");
  rti::AttributeHandleSet const firstAttributes{firstAttribute};
  lifecycle.rtiAmbassador().publishObjectClassAttributes(
      firstClass,
      firstAttributes);

  auto const originalObject = lifecycle.rtiAmbassador().registerObjectInstance(firstClass);
  require(
      originalObject.isValid(),
      "Final-federate resignation returned an invalid original object handle");
  auto const reusableName = lifecycle.rtiAmbassador().getObjectInstanceName(originalObject);
  require(
      !reusableName.empty(),
      "Final-federate resignation returned an empty object instance name");

  // IEEE 1516.1 final-federate resignation applies the cleanup directive
  // required to delete owned objects even when the caller supplies NO_ACTION.
  lifecycle.resign(rti::NO_ACTION);
  lifecycle.join(
      options.ownerFederateName + L"-final-federate-rejoined",
      options.federateType,
      federation);

  auto const secondClass = lifecycle.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const secondAttribute = lifecycle.rtiAmbassador().getAttributeHandle(
      secondClass,
      options.attributeName);
  require(
      secondClass.isValid() && secondAttribute.isValid(),
      "Final-federate rejoin lookup returned an invalid handle");
  rti::AttributeHandleSet const secondAttributes{secondAttribute};
  lifecycle.rtiAmbassador().publishObjectClassAttributes(
      secondClass,
      secondAttributes);

  lifecycle.recorder().clearReservations();
  lifecycle.rtiAmbassador().reserveObjectInstanceName(reusableName);
  if (model == rti::HLA_EVOKED) {
    require(
        !lifecycle.recorder().reservationSucceeded(reusableName),
        "Evoked final-federate reservation callback arrived before servicing");
  }
  waitFor(
      lifecycle,
      [&] { return lifecycle.recorder().reservationSucceeded(reusableName); },
      options,
      "object-name reuse after final-federate resignation");
  auto const replacementObject = lifecycle.rtiAmbassador().registerObjectInstance(
      secondClass,
      reusableName);
  require(
      replacementObject.isValid(),
      "Final-federate resignation did not release the reusable object name");
  require(
      lifecycle.rtiAmbassador().getObjectInstanceHandle(reusableName) == replacementObject,
      "Final-federate named registration did not round-trip its object handle");

  lifecycle.resign(rti::NO_ACTION);
  lifecycle.rtiAmbassador().destroyFederationExecution(federation);
  lifecycle.disconnect();
}

void scenarioFinalFederateResignationCleanupContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioFinalFederateResignationCleanup(options, model);
}

void scenarioObjectRegistrationDiscoveryLifecycle(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.modelFom.empty(),
      "object registration/discovery lifecycle requires an adapter-supplied rich FOM");

  Session unjoined(options, model, "unjoined");
  Session publisher(options, model, "owner");
  Session exact(options, model, "member");
  Session base(options, model, "member-base");
  Session cancelled(options, model, "member-cancelled");
  Session late(options, model, "member-late");
  auto const federation = federationName(options, "object-registration-discovery-lifecycle");

  rti::ObjectClassHandle const invalidObjectClass;
  requireException(
      [&] {
        static_cast<void>(unjoined.rtiAmbassador().registerObjectInstance(invalidObjectClass));
      },
      L"NotConnected",
      "registering an object before connect");
  unjoined.connect();
  requireException(
      [&] {
        static_cast<void>(unjoined.rtiAmbassador().registerObjectInstance(invalidObjectClass));
      },
      L"FederateNotExecutionMember",
      "registering an object after connect before join");

  publisher.connect();
  exact.connect();
  base.connect();
  cancelled.connect();
  late.connect();
  publisher.rtiAmbassador().createFederationExecution(
      federation,
      options.modelFom.wstring(),
      options.logicalTimeImplementationName);
  publisher.join(options.ownerFederateName, options.federateType, federation);
  exact.join(
      options.memberFederateName + L"-exact",
      options.federateType,
      federation);
  base.join(
      options.memberFederateName + L"-base",
      options.federateType,
      federation);
  cancelled.join(
      options.memberFederateName + L"-cancelled",
      options.federateType,
      federation);
  late.join(
      options.memberFederateName + L"-late",
      options.federateType,
      federation);

  auto const publisherClass = publisher.rtiAmbassador().getObjectClassHandle(
      options.typedDerivedObjectClassName);
  auto const exactClass = exact.rtiAmbassador().getObjectClassHandle(
      options.typedDerivedObjectClassName);
  auto const baseClass = base.rtiAmbassador().getObjectClassHandle(
      options.typedObjectClassName);
  auto const cancelledClass = cancelled.rtiAmbassador().getObjectClassHandle(
      options.typedDerivedObjectClassName);
  auto const lateClass = late.rtiAmbassador().getObjectClassHandle(
      options.typedDerivedObjectClassName);
  require(
      publisherClass.isValid() && exactClass.isValid() && baseClass.isValid() &&
          cancelledClass.isValid() && lateClass.isValid(),
      "object registration/discovery FOM class lookup returned an invalid handle");

  auto const publisherIdentity = publisher.rtiAmbassador().getAttributeHandle(
      publisherClass,
      options.typedIdentityAttributeName);
  auto const publisherDerived = publisher.rtiAmbassador().getAttributeHandle(
      publisherClass,
      options.typedDerivedAttributeName);
  auto const exactDerived = exact.rtiAmbassador().getAttributeHandle(
      exactClass,
      options.typedDerivedAttributeName);
  auto const baseIdentity = base.rtiAmbassador().getAttributeHandle(
      baseClass,
      options.typedIdentityAttributeName);
  auto const cancelledDerived = cancelled.rtiAmbassador().getAttributeHandle(
      cancelledClass,
      options.typedDerivedAttributeName);
  auto const lateDerived = late.rtiAmbassador().getAttributeHandle(
      lateClass,
      options.typedDerivedAttributeName);
  require(
      publisherIdentity.isValid() && publisherDerived.isValid() &&
          exactDerived.isValid() && baseIdentity.isValid() &&
          cancelledDerived.isValid() && lateDerived.isValid(),
      "object registration/discovery FOM attribute lookup returned an invalid handle");

  auto const publisherBaseIdentity = publisher.rtiAmbassador().getAttributeHandle(
      publisher.rtiAmbassador().getObjectClassHandle(options.typedObjectClassName),
      options.typedIdentityAttributeName);
  require(
      publisherBaseIdentity == publisherIdentity && baseIdentity == publisherIdentity,
      "inherited object registration/discovery attribute handle changed across classes");

  rti::AttributeHandleSet const publishedAttributes{publisherIdentity, publisherDerived};
  rti::AttributeHandleSet const exactAttributes{exactDerived};
  rti::AttributeHandleSet const baseAttributes{baseIdentity};
  rti::AttributeHandleSet const cancelledAttributes{cancelledDerived};
  rti::AttributeHandleSet const lateAttributes{lateDerived};

  requireException(
      [&] {
        static_cast<void>(publisher.rtiAmbassador().registerObjectInstance(invalidObjectClass));
      },
      L"ObjectClassNotDefined",
      "registering an object for an invalid object class");
  requireException(
      [&] { static_cast<void>(publisher.rtiAmbassador().registerObjectInstance(publisherClass)); },
      L"ObjectClassNotPublished",
      "registering an object before publication");

  exact.rtiAmbassador().subscribeObjectClassAttributes(
      exactClass,
      exactAttributes,
      true,
      L"");
  base.rtiAmbassador().subscribeObjectClassAttributes(
      baseClass,
      baseAttributes,
      true,
      L"");
  cancelled.rtiAmbassador().subscribeObjectClassAttributes(
      cancelledClass,
      cancelledAttributes,
      true,
      L"");
  publisher.rtiAmbassador().publishObjectClassAttributes(
      publisherClass,
      publishedAttributes);

  auto const object = publisher.rtiAmbassador().registerObjectInstance(publisherClass);
  require(object.isValid(), "object registration/discovery returned an invalid object handle");
  auto const objectName = publisher.rtiAmbassador().getObjectInstanceName(object);
  require(!objectName.empty(), "object registration/discovery returned an empty object name");
  require(
      publisher.rtiAmbassador().getObjectInstanceHandle(objectName) == object &&
          publisher.rtiAmbassador().getKnownObjectClassHandle(object) == publisherClass,
      "publisher object identity lookup did not round-trip");

  requireException(
      [&] { static_cast<void>(late.rtiAmbassador().getObjectInstanceHandle(objectName)); },
      L"ObjectInstanceNotKnown",
      "looking up an undiscovered object by name");
  if (model == rti::HLA_EVOKED) {
    require(
        exact.recorder().discoveryCount() == 0U &&
            base.recorder().discoveryCount() == 0U &&
            cancelled.recorder().discoveryCount() == 0U,
        "evoked discovery callback arrived before callback servicing");
    requireException(
        [&] { static_cast<void>(exact.rtiAmbassador().getKnownObjectClassHandle(object)); },
        L"ObjectInstanceNotKnown",
        "looking up an evoked object before discovery");
  } else {
    require(
        exact.recorder().discoveryCount() == 1U &&
            base.recorder().discoveryCount() == 1U &&
            cancelled.recorder().discoveryCount() == 1U,
        "immediate registration did not deliver one discovery callback per subscriber");
  }

  if (model == rti::HLA_EVOKED) {
    cancelled.rtiAmbassador().unsubscribeObjectClassAttributes(
        cancelledClass,
        cancelledAttributes);
    require(
        !cancelled.evokeMultipleCallbacks(0.0, 0.0),
        "cancelled discovery callback remained queued after unsubscribe");
  }

  late.rtiAmbassador().subscribeObjectClassAttributes(
      lateClass,
      lateAttributes,
      true,
      L"");

  auto requireDiscovery = [&](Session& session,
                              rti::ObjectClassHandle const& expectedClass,
                              std::string const& description) {
    waitFor(
        session,
        [&] { return session.recorder().discovery().present; },
        options,
        description);
    auto const discovery = session.recorder().discovery();
    require(
        discovery.object == object && discovery.objectClass == expectedClass &&
            discovery.name == objectName,
        description + " returned the wrong object identity");
    require(
        session.rtiAmbassador().getKnownObjectClassHandle(object) == expectedClass &&
            session.rtiAmbassador().getObjectInstanceHandle(objectName) == object &&
            session.rtiAmbassador().getObjectInstanceName(object) == objectName,
        description + " did not establish stable identity lookups");
  };

  requireDiscovery(exact, exactClass, "exact object discovery");
  requireDiscovery(base, baseClass, "base-class object discovery");
  requireDiscovery(late, lateClass, "late object discovery");
  if (model == rti::HLA_EVOKED) {
    require(
        cancelled.recorder().discoveryCount() == 0U,
        "unsubscribed evoked subscriber received object discovery");
    requireException(
        [&] { static_cast<void>(cancelled.rtiAmbassador().getObjectInstanceName(object)); },
        L"ObjectInstanceNotKnown",
        "looking up an unsubscribed object by handle");
  } else {
    cancelled.rtiAmbassador().unsubscribeObjectClassAttributes(
        cancelledClass,
        cancelledAttributes);
    require(
        cancelled.recorder().discoveryCount() == 1U,
        "immediate subscriber changed a delivered discovery count after unsubscribe");
  }

  exact.rtiAmbassador().subscribeObjectClassAttributes(
      exactClass,
      exactAttributes,
      true,
      L"");
  require(
      !exact.evokeMultipleCallbacks(0.0, 0.0) && exact.recorder().discoveryCount() == 1U,
      "repeating an object subscription generated a duplicate discovery callback");

  late.resign(rti::NO_ACTION);
  cancelled.resign(rti::NO_ACTION);
  base.resign(rti::NO_ACTION);
  exact.resign(rti::NO_ACTION);
  publisher.resign(rti::DELETE_OBJECTS);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  unjoined.disconnect();
  late.disconnect();
  cancelled.disconnect();
  base.disconnect();
  exact.disconnect();
  publisher.disconnect();
}

