void scenarioOwnership(Options const& options, rti::CallbackModel model) {
  Session lifecycle(options, model, "ownership-lifecycle");
  rti::ObjectInstanceHandle const lifecycleInvalidObject;
  rti::AttributeHandle const lifecycleInvalidAttribute;
  rti::AttributeHandleSet const emptyAttributes;
  rti::VariableLengthData const emptyTag;
  auto checkOwnershipLifecycle = [&](std::wstring const& expected,
                                     std::string const& phase) {
    requireException(
        [&] {
          lifecycle.rtiAmbassador().unconditionalAttributeOwnershipDivestiture(
              lifecycleInvalidObject,
              emptyAttributes,
              emptyTag);
        },
        expected,
        phase + " unconditional divestiture");
    requireException(
        [&] {
          lifecycle.rtiAmbassador().negotiatedAttributeOwnershipDivestiture(
              lifecycleInvalidObject,
              emptyAttributes,
              emptyTag);
        },
        expected,
        phase + " negotiated divestiture");
    requireException(
        [&] {
          lifecycle.rtiAmbassador().confirmDivestiture(
              lifecycleInvalidObject,
              emptyAttributes,
              emptyTag);
        },
        expected,
        phase + " divestiture confirmation");
    requireException(
        [&] {
          lifecycle.rtiAmbassador().attributeOwnershipAcquisition(
              lifecycleInvalidObject,
              emptyAttributes,
              emptyTag);
        },
        expected,
        phase + " ownership acquisition");
    requireException(
        [&] {
          lifecycle.rtiAmbassador().attributeOwnershipAcquisitionIfAvailable(
              lifecycleInvalidObject,
              emptyAttributes,
              emptyTag);
        },
        expected,
        phase + " If Available ownership acquisition");
    requireException(
        [&] {
          lifecycle.rtiAmbassador().attributeOwnershipReleaseDenied(
              lifecycleInvalidObject,
              emptyAttributes,
              emptyTag);
        },
        expected,
        phase + " ownership release denial");
    rti::AttributeHandleSet divestedAttributes;
    requireException(
        [&] {
          lifecycle.rtiAmbassador().attributeOwnershipDivestitureIfWanted(
              lifecycleInvalidObject,
              emptyAttributes,
              emptyTag,
              divestedAttributes);
        },
        expected,
        phase + " If Wanted divestiture");
    requireException(
        [&] {
          lifecycle.rtiAmbassador().cancelNegotiatedAttributeOwnershipDivestiture(
              lifecycleInvalidObject,
              emptyAttributes);
        },
        expected,
        phase + " negotiated divestiture cancellation");
    requireException(
        [&] {
          lifecycle.rtiAmbassador().cancelAttributeOwnershipAcquisition(
              lifecycleInvalidObject,
              emptyAttributes);
        },
        expected,
        phase + " acquisition cancellation");
    requireException(
        [&] {
          lifecycle.rtiAmbassador().queryAttributeOwnership(
              lifecycleInvalidObject,
              emptyAttributes);
        },
        expected,
        phase + " ownership query");
    requireException(
        [&] {
          static_cast<void>(lifecycle.rtiAmbassador().isAttributeOwnedByFederate(
              lifecycleInvalidObject,
              lifecycleInvalidAttribute));
        },
        expected,
        phase + " ownership status query");
  };
  checkOwnershipLifecycle(L"NotConnected", "before connect");
  lifecycle.connect();
  checkOwnershipLifecycle(L"FederateNotExecutionMember", "before joining an execution");
  lifecycle.disconnect();

  Session owner(options, model, "owner");
  Session acquirer(options, model, "acquirer");
  auto const federation = federationName(options, "ownership");
  connectAndJoin(owner, acquirer, options, federation, options.fom);

  auto const ownerClass = owner.rtiAmbassador().getObjectClassHandle(options.objectClassName);
  auto const acquirerClass =
      acquirer.rtiAmbassador().getObjectClassHandle(options.objectClassName);
  auto const ownerAttribute =
      owner.rtiAmbassador().getAttributeHandle(ownerClass, options.attributeName);
  auto const acquirerAttribute =
      acquirer.rtiAmbassador().getAttributeHandle(acquirerClass, options.attributeName);
  require(ownerClass.isValid() && acquirerClass.isValid(),
          "Ownership object class lookup returned an invalid handle");
  require(ownerAttribute.isValid() && acquirerAttribute.isValid(),
          "Ownership attribute lookup returned an invalid handle");

  rti::AttributeHandleSet ownerAttributes;
  ownerAttributes.insert(ownerAttribute);
  rti::AttributeHandleSet acquirerAttributes;
  acquirerAttributes.insert(acquirerAttribute);
  owner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerAttributes);
  acquirer.rtiAmbassador().publishObjectClassAttributes(acquirerClass, acquirerAttributes);
  owner.rtiAmbassador().subscribeObjectClassAttributes(
      ownerClass, ownerAttributes, true, L"");
  acquirer.rtiAmbassador().subscribeObjectClassAttributes(
      acquirerClass, acquirerAttributes, true, L"");

  auto const object = owner.rtiAmbassador().registerObjectInstance(ownerClass);
  require(object.isValid(), "Ownership registration returned an invalid object handle");
  waitFor(acquirer, [&] { return acquirer.recorder().discovery().present; }, options,
          "ownership object discovery");
  auto const discovered = acquirer.recorder().discovery();
  require(discovered.object == object,
          "Ownership discovery returned the wrong object handle");

  rti::AttributeHandleSet const invalidAttributes{rti::AttributeHandle{}};
  requireException(
      [&] {
        acquirer.rtiAmbassador().queryAttributeOwnership(
            rti::ObjectInstanceHandle{},
            acquirerAttributes);
      },
      L"ObjectInstanceNotKnown",
      "querying ownership for an unknown object instance");
  requireException(
      [&] {
        acquirer.rtiAmbassador().queryAttributeOwnership(
            object,
            invalidAttributes);
      },
      L"AttributeNotDefined",
      "querying ownership for an undefined attribute");
  requireException(
      [&] {
        static_cast<void>(acquirer.rtiAmbassador().isAttributeOwnedByFederate(
            rti::ObjectInstanceHandle{},
            acquirerAttribute));
      },
      L"ObjectInstanceNotKnown",
      "checking ownership for an unknown object instance");
  requireException(
      [&] {
        static_cast<void>(acquirer.rtiAmbassador().isAttributeOwnedByFederate(
            object,
            rti::AttributeHandle{}));
      },
      L"AttributeNotDefined",
      "checking ownership for an undefined attribute");
  rti::ObjectInstanceHandle const invalidObject;
  rti::VariableLengthData const emptyOwnershipTag;
  rti::AttributeHandleSet ignoredIfWanted;
  requireException(
      [&] {
        owner.rtiAmbassador().unconditionalAttributeOwnershipDivestiture(
            invalidObject,
            ownerAttributes,
            emptyOwnershipTag);
      },
      L"ObjectInstanceNotKnown",
      "unconditional divestiture for an unknown object");
  requireException(
      [&] {
        owner.rtiAmbassador().negotiatedAttributeOwnershipDivestiture(
            invalidObject,
            ownerAttributes,
            emptyOwnershipTag);
      },
      L"ObjectInstanceNotKnown",
      "negotiated divestiture for an unknown object");
  requireException(
      [&] {
        owner.rtiAmbassador().confirmDivestiture(
            invalidObject,
            ownerAttributes,
            emptyOwnershipTag);
      },
      L"ObjectInstanceNotKnown",
      "divestiture confirmation for an unknown object");
  requireException(
      [&] {
        owner.rtiAmbassador().cancelNegotiatedAttributeOwnershipDivestiture(
            invalidObject,
            ownerAttributes);
      },
      L"ObjectInstanceNotKnown",
      "negotiated divestiture cancellation for an unknown object");
  requireException(
      [&] {
        owner.rtiAmbassador().attributeOwnershipDivestitureIfWanted(
            invalidObject,
            ownerAttributes,
            emptyOwnershipTag,
            ignoredIfWanted);
      },
      L"ObjectInstanceNotKnown",
      "If Wanted divestiture for an unknown object");
  requireException(
      [&] {
        owner.rtiAmbassador().attributeOwnershipReleaseDenied(
            invalidObject,
            ownerAttributes,
            emptyOwnershipTag);
      },
      L"ObjectInstanceNotKnown",
      "ownership release denial for an unknown object");
  requireException(
      [&] {
        acquirer.rtiAmbassador().attributeOwnershipAcquisition(
            invalidObject,
            acquirerAttributes,
            emptyOwnershipTag);
      },
      L"ObjectInstanceNotKnown",
      "ownership acquisition for an unknown object");
  requireException(
      [&] {
        acquirer.rtiAmbassador().attributeOwnershipAcquisitionIfAvailable(
            invalidObject,
            acquirerAttributes,
            emptyOwnershipTag);
      },
      L"ObjectInstanceNotKnown",
      "If Available acquisition for an unknown object");
  requireException(
      [&] {
        acquirer.rtiAmbassador().cancelAttributeOwnershipAcquisition(
            invalidObject,
            acquirerAttributes);
      },
      L"ObjectInstanceNotKnown",
      "acquisition cancellation for an unknown object");

  require(owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerAttribute),
          "Owner did not initially own the published attribute");
  require(!acquirer.rtiAmbassador().isAttributeOwnedByFederate(object, acquirerAttribute),
          "Acquirer initially reported ownership of the attribute");

  // Querying through the subscriber exercises the owner report and the
  // standard cross-federate handle identity.
  acquirer.recorder().clearOwnershipRecords();
  acquirer.rtiAmbassador().queryAttributeOwnership(object, acquirerAttributes);
  waitFor(acquirer, [&] {
    return acquirer.recorder().ownershipInformation().has_value();
  }, options, "the ownership query report");
  auto const information = acquirer.recorder().ownershipInformation();
  require(information->object == object && information->attributes == acquirerAttributes,
          "Ownership query returned the wrong object or attribute set");
  require(information->owner == owner.federateHandle(),
          "Ownership query did not identify the owning federate");

  // Negotiated acquisition: the acquirer's tag reaches the owner's request,
  // and the owner's confirmation tag reaches the acquisition notification.
  acquirer.recorder().clearOwnershipRecords();
  owner.recorder().clearOwnershipRecords();
  std::vector<std::uint8_t> divestitureTagBytes{0x10U};
  std::vector<std::uint8_t> acquisitionRequestTagBytes{0x20U};
  std::vector<std::uint8_t> confirmationTagBytes{0x30U};
  rti::VariableLengthData divestitureTag(
      divestitureTagBytes.data(), divestitureTagBytes.size());
  rti::VariableLengthData acquisitionRequestTag(
      acquisitionRequestTagBytes.data(), acquisitionRequestTagBytes.size());
  rti::VariableLengthData confirmationTag(
      confirmationTagBytes.data(), confirmationTagBytes.size());
  owner.rtiAmbassador().negotiatedAttributeOwnershipDivestiture(
      object, ownerAttributes, divestitureTag);
  acquirer.rtiAmbassador().attributeOwnershipAcquisition(
      object, acquirerAttributes, acquisitionRequestTag);
  waitFor(owner, [&] {
    return owner.recorder().divestitureConfirmation().has_value();
  }, options, "the negotiated divestiture confirmation request");
  auto const divestitureConfirmation = owner.recorder().divestitureConfirmation();
  require(divestitureConfirmation->object == object &&
              divestitureConfirmation->attributes == ownerAttributes,
          "Negotiated divestiture returned the wrong object or attributes");
  require(divestitureConfirmation->tag == acquisitionRequestTagBytes,
          "Negotiated divestiture did not preserve the acquisition tag");

  owner.rtiAmbassador().confirmDivestiture(object, ownerAttributes, confirmationTag);
  waitFor(acquirer, [&] {
    return acquirer.recorder().ownershipAcquisition().has_value();
  }, options, "the negotiated acquisition notification");
  auto const acquisition = acquirer.recorder().ownershipAcquisition();
  require(acquisition->object == object && acquisition->attributes == acquirerAttributes,
          "Acquisition notification returned the wrong object or attributes");
  require(acquisition->tag == confirmationTagBytes,
          "Acquisition notification did not preserve the confirmation tag");
  require(!owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerAttribute),
          "Owner retained ownership after confirmed divestiture");
  require(acquirer.rtiAmbassador().isAttributeOwnedByFederate(object, acquirerAttribute),
          "Acquirer did not gain ownership after confirmation");

  // The If Wanted service is valid for an owner even when there is no pending
  // acquisition. The returned set is provider-arbitrated by the standard API.
  rti::AttributeHandleSet wanted;
  std::vector<std::uint8_t> noPendingDivestitureTagBytes{0x31U};
  rti::VariableLengthData noPendingDivestitureTag(
      noPendingDivestitureTagBytes.data(), noPendingDivestitureTagBytes.size());
  acquirer.rtiAmbassador().attributeOwnershipDivestitureIfWanted(
      object,
      acquirerAttributes,
      noPendingDivestitureTag,
      wanted);
  require(wanted.empty(),
          "If Wanted unexpectedly divested an attribute without a pending acquirer");

  // An unconditional divestiture makes the attribute immediately available;
  // the owner can then reacquire it through the If Available service.
  acquirer.recorder().clearOwnershipRecords();
  owner.recorder().clearOwnershipRecords();
  std::vector<std::uint8_t> unconditionalTagBytes{0x40U};
  std::vector<std::uint8_t> ifAvailableTagBytes{0x50U};
  rti::VariableLengthData unconditionalTag(
      unconditionalTagBytes.data(), unconditionalTagBytes.size());
  rti::VariableLengthData ifAvailableTag(
      ifAvailableTagBytes.data(), ifAvailableTagBytes.size());
  acquirer.rtiAmbassador().unconditionalAttributeOwnershipDivestiture(
      object, acquirerAttributes, unconditionalTag);
  waitFor(owner, [&] {
    return owner.recorder().ownershipAssumption().has_value();
  }, options, "the ownership assumption offer");
  auto const assumption = owner.recorder().ownershipAssumption();
  require(assumption->object == object && assumption->attributes == ownerAttributes,
          "Ownership assumption returned the wrong object or attributes");
  require(assumption->tag == unconditionalTagBytes,
          "Ownership assumption did not preserve the divestiture tag");

  owner.recorder().clearOwnershipRecords();
  owner.rtiAmbassador().queryAttributeOwnership(object, ownerAttributes);
  waitFor(owner, [&] {
    return owner.recorder().ownershipNotOwned().has_value();
  }, options, "the unowned ownership query report");
  auto const unowned = owner.recorder().ownershipNotOwned();
  require(unowned->object == object && unowned->attributes == ownerAttributes,
          "Unowned ownership query returned the wrong object or attributes");

  owner.recorder().clearOwnershipRecords();
  owner.rtiAmbassador().attributeOwnershipAcquisitionIfAvailable(
      object, ownerAttributes, ifAvailableTag);
  waitFor(owner, [&] {
    return owner.recorder().ownershipAcquisition().has_value();
  }, options, "the If Available acquisition notification");
  auto const ifAvailableAcquisition = owner.recorder().ownershipAcquisition();
  require(ifAvailableAcquisition->object == object &&
              ifAvailableAcquisition->attributes == ownerAttributes,
          "If Available acquisition returned the wrong object or attributes");
  require(ifAvailableAcquisition->tag == ifAvailableTagBytes,
          "If Available acquisition did not preserve its user tag");
  require(owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerAttribute),
          "Owner did not regain ownership through If Available acquisition");
  require(!acquirer.rtiAmbassador().isAttributeOwnedByFederate(object, acquirerAttribute),
          "Acquirer retained ownership after unconditional divestiture");

  // A pending regular acquisition can also be satisfied directly by the
  // current owner through Divestiture If Wanted. The divestiture tag, rather
  // than the older acquisition tag, is delivered to the new owner.
  owner.recorder().clearOwnershipRecords();
  acquirer.recorder().clearOwnershipRecords();
  std::vector<std::uint8_t> ifWantedAcquisitionTagBytes{0xA0U};
  std::vector<std::uint8_t> ifWantedDivestitureTagBytes{0xA1U};
  rti::VariableLengthData ifWantedAcquisitionTag(
      ifWantedAcquisitionTagBytes.data(), ifWantedAcquisitionTagBytes.size());
  rti::VariableLengthData ifWantedDivestitureTag(
      ifWantedDivestitureTagBytes.data(), ifWantedDivestitureTagBytes.size());
  acquirer.rtiAmbassador().attributeOwnershipAcquisition(
      object, acquirerAttributes, ifWantedAcquisitionTag);
  rti::AttributeHandleSet ifWantedDivestedAttributes;
  owner.rtiAmbassador().attributeOwnershipDivestitureIfWanted(
      object,
      ownerAttributes,
      ifWantedDivestitureTag,
      ifWantedDivestedAttributes);
  require(ifWantedDivestedAttributes == ownerAttributes,
          "If Wanted did not return the transferred attribute set");
  for (int pass = 0; pass != 8; ++pass) {
    owner.pump();
  }
  waitFor(acquirer, [&] {
    return acquirer.recorder().ownershipAcquisition().has_value();
  }, options, "the If Wanted acquisition notification");
  auto const ifWantedAcquisition = acquirer.recorder().ownershipAcquisition();
  require(ifWantedAcquisition->object == object &&
              ifWantedAcquisition->attributes == acquirerAttributes,
          "If Wanted acquisition returned the wrong object or attributes");
  require(ifWantedAcquisition->tag == ifWantedDivestitureTagBytes,
          "If Wanted acquisition did not preserve the divestiture tag");
  require(!owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerAttribute),
          "Owner retained ownership after If Wanted transfer");
  require(acquirer.rtiAmbassador().isAttributeOwnedByFederate(object, acquirerAttribute),
          "Acquirer did not gain ownership through If Wanted transfer");

  // Return the attribute to the owner so the denial and cancellation checks
  // start from the same owner-held state as the Java parity scenario.
  owner.recorder().clearOwnershipRecords();
  acquirer.recorder().clearOwnershipRecords();
  std::vector<std::uint8_t> returnAcquisitionTagBytes{0xB0U};
  std::vector<std::uint8_t> returnDivestitureTagBytes{0xB1U};
  rti::VariableLengthData returnAcquisitionTag(
      returnAcquisitionTagBytes.data(), returnAcquisitionTagBytes.size());
  rti::VariableLengthData returnDivestitureTag(
      returnDivestitureTagBytes.data(), returnDivestitureTagBytes.size());
  acquirer.rtiAmbassador().unconditionalAttributeOwnershipDivestiture(
      object,
      acquirerAttributes,
      returnDivestitureTag);
  waitFor(owner, [&] {
    return owner.recorder().ownershipAssumption().has_value();
  }, options, "the return ownership assumption offer");
  owner.recorder().clearOwnershipRecords();
  owner.rtiAmbassador().attributeOwnershipAcquisitionIfAvailable(
      object, ownerAttributes, returnAcquisitionTag);
  waitFor(owner, [&] {
    return owner.recorder().ownershipAcquisition().has_value();
  }, options, "the return If Available acquisition notification");
  require(owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerAttribute),
          "Owner did not regain ownership before denial checks");

  // A regular acquisition asks the current owner to release. Denying it must
  // preserve ownership and deliver the denial tag as Unavailable.
  owner.recorder().clearOwnershipRecords();
  acquirer.recorder().clearOwnershipRecords();
  std::vector<std::uint8_t> deniedAcquisitionTagBytes{0x60U};
  std::vector<std::uint8_t> denialTagBytes{0x70U};
  rti::VariableLengthData deniedAcquisitionTag(
      deniedAcquisitionTagBytes.data(), deniedAcquisitionTagBytes.size());
  rti::VariableLengthData denialTag(denialTagBytes.data(), denialTagBytes.size());
  acquirer.rtiAmbassador().attributeOwnershipAcquisition(
      object, acquirerAttributes, deniedAcquisitionTag);
  waitFor(owner, [&] {
    return owner.recorder().ownershipReleaseRequest().has_value();
  }, options, "the ownership release request");
  auto const releaseRequest = owner.recorder().ownershipReleaseRequest();
  require(releaseRequest->object == object && releaseRequest->attributes == ownerAttributes,
          "Ownership release request returned the wrong object or attributes");
  require(releaseRequest->tag == deniedAcquisitionTagBytes,
          "Ownership release request did not preserve the acquisition tag");
  owner.rtiAmbassador().attributeOwnershipReleaseDenied(object, ownerAttributes, denialTag);
  waitFor(acquirer, [&] {
    return acquirer.recorder().ownershipUnavailable().has_value();
  }, options, "the ownership-unavailable denial callback");
  auto const unavailable = acquirer.recorder().ownershipUnavailable();
  require(unavailable->object == object && unavailable->attributes == acquirerAttributes,
          "Ownership-unavailable callback returned the wrong object or attributes");
  require(unavailable->tag == denialTagBytes,
          "Ownership-unavailable callback did not preserve the denial tag");
  require(owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerAttribute),
          "Owner lost ownership after denying the acquisition");

  // A second pending acquisition can be canceled, and the requester receives
  // the standard confirmation callback.
  owner.recorder().clearOwnershipRecords();
  acquirer.recorder().clearOwnershipRecords();
  std::vector<std::uint8_t> cancellationAcquisitionTagBytes{0x80U};
  rti::VariableLengthData cancellationAcquisitionTag(
      cancellationAcquisitionTagBytes.data(), cancellationAcquisitionTagBytes.size());
  acquirer.rtiAmbassador().attributeOwnershipAcquisition(
      object, acquirerAttributes, cancellationAcquisitionTag);
  waitFor(owner, [&] {
    return owner.recorder().ownershipReleaseRequest().has_value();
  }, options, "the cancelable ownership release request");
  acquirer.rtiAmbassador().cancelAttributeOwnershipAcquisition(object, acquirerAttributes);
  waitFor(acquirer, [&] {
    return acquirer.recorder().ownershipAcquisitionCancellation().has_value();
  }, options, "the ownership acquisition cancellation confirmation");
  auto const cancellation = acquirer.recorder().ownershipAcquisitionCancellation();
  require(cancellation->object == object && cancellation->attributes == acquirerAttributes,
          "Ownership cancellation returned the wrong object or attributes");
  require(owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerAttribute),
          "Owner lost ownership after acquisition cancellation");

  std::vector<std::uint8_t> canceledDivestitureTagBytes{0x90U};
  rti::VariableLengthData canceledDivestitureTag(
      canceledDivestitureTagBytes.data(), canceledDivestitureTagBytes.size());
  owner.rtiAmbassador().negotiatedAttributeOwnershipDivestiture(
      object, ownerAttributes, canceledDivestitureTag);
  owner.rtiAmbassador().cancelNegotiatedAttributeOwnershipDivestiture(
      object, ownerAttributes);
  require(owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerAttribute),
          "Owner lost ownership after negotiated divestiture cancellation");

  // If Available must fail immediately while another federate still owns the
  // attribute.  It does not ask the owner to release anything; the requester
  // receives exactly one Unavailable callback carrying its original tag.
  owner.recorder().clearOwnershipRecords();
  acquirer.recorder().clearOwnershipRecords();
  std::vector<std::uint8_t> unavailableIfAvailableTagBytes{0xC0U};
  rti::VariableLengthData unavailableIfAvailableTag(
      unavailableIfAvailableTagBytes.data(), unavailableIfAvailableTagBytes.size());
  acquirer.rtiAmbassador().attributeOwnershipAcquisitionIfAvailable(
      object,
      acquirerAttributes,
      unavailableIfAvailableTag);
  waitFor(acquirer, [&] {
    return acquirer.recorder().ownershipUnavailableEvents().size() >= 1U;
  }, options, "the If Available unavailable callback");
  auto const unavailableIfAvailableEvents =
      acquirer.recorder().ownershipUnavailableEvents();
  require(
      unavailableIfAvailableEvents.size() == 1U &&
          unavailableIfAvailableEvents.front().object == object &&
          unavailableIfAvailableEvents.front().attributes == acquirerAttributes &&
          unavailableIfAvailableEvents.front().tag == unavailableIfAvailableTagBytes,
      "If Available unavailable callback returned the wrong object, attributes, or tag");
  for (int pass = 0; pass != 8; ++pass) {
    acquirer.pump();
    owner.pump();
  }
  require(
      acquirer.recorder().ownershipUnavailableEvents().size() == 1U,
      "If Available unavailable callback was delivered more than once");
  require(
      !owner.recorder().ownershipReleaseRequest().has_value() &&
          !acquirer.recorder().ownershipAcquisition().has_value() &&
          owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerAttribute) &&
          !acquirer.rtiAmbassador().isAttributeOwnedByFederate(object, acquirerAttribute),
      "If Available unavailable changed ownership or requested owner release");

  owner.resign(rti::DELETE_OBJECTS);
  acquirer.resign(rti::NO_ACTION);
}

void scenarioPartialAttributeOwnershipTransfer(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.multiAttributeFom.empty(),
      "Partial attribute ownership testing requires an adapter-supplied multi-attribute FOM");

  Session owner(options, model, "owner");
  Session acquirer(options, model, "member");
  auto const federation = federationName(
      options,
      "partial-attribute-ownership-transfer");
  owner.connect();
  acquirer.connect();
  owner.rtiAmbassador().createFederationExecution(
      federation,
      options.multiAttributeFom.wstring(),
      options.logicalTimeImplementationName);
  owner.join(
      options.ownerFederateName + L"-partial-ownership-owner",
      options.federateType,
      federation);
  acquirer.join(
      options.memberFederateName + L"-partial-ownership-acquirer",
      options.federateType,
      federation);

  auto const ownerClass = owner.rtiAmbassador().getObjectClassHandle(
      options.multiAttributeObjectClassName);
  auto const acquirerClass = acquirer.rtiAmbassador().getObjectClassHandle(
      options.multiAttributeObjectClassName);
  auto const ownerFirst = owner.rtiAmbassador().getAttributeHandle(
      ownerClass,
      options.multiAttributeFirstName);
  auto const ownerSecond = owner.rtiAmbassador().getAttributeHandle(
      ownerClass,
      options.multiAttributeSecondName);
  auto const acquirerFirst = acquirer.rtiAmbassador().getAttributeHandle(
      acquirerClass,
      options.multiAttributeFirstName);
  auto const acquirerSecond = acquirer.rtiAmbassador().getAttributeHandle(
      acquirerClass,
      options.multiAttributeSecondName);
  require(
      ownerClass.isValid() && acquirerClass.isValid(),
      "partial ownership object-class lookup returned an invalid handle");
  require(
      ownerFirst.isValid() && ownerSecond.isValid() && acquirerFirst.isValid() &&
          acquirerSecond.isValid(),
      "partial ownership attribute lookup returned an invalid handle");
  require(
      ownerFirst != ownerSecond,
      "partial ownership adapter supplied duplicate attribute names");

  rti::AttributeHandleSet const ownerAttributes{ownerFirst, ownerSecond};
  rti::AttributeHandleSet const acquirerAttributes{acquirerFirst, acquirerSecond};
  rti::AttributeHandleSet const ownerSecondOnly{ownerSecond};
  rti::AttributeHandleSet const acquirerFirstOnly{acquirerFirst};
  rti::AttributeHandleSet const acquirerSecondOnly{acquirerSecond};
  owner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerAttributes);
  acquirer.rtiAmbassador().publishObjectClassAttributes(
      acquirerClass,
      acquirerAttributes);
  acquirer.rtiAmbassador().subscribeObjectClassAttributes(
      acquirerClass,
      acquirerAttributes,
      true,
      L"");

  auto const object = owner.rtiAmbassador().registerObjectInstance(ownerClass);
  require(
      object.isValid(),
      "partial ownership registration returned an invalid object handle");
  waitFor(
      acquirer,
      [&] { return acquirer.recorder().discovery().present; },
      options,
      "partial ownership object discovery");
  require(
      acquirer.recorder().discovery().object == object,
      "partial ownership discovery returned the wrong object handle");

  require(
      owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerFirst) &&
          owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerSecond),
      "partial ownership owner did not initially own both attributes");
  require(
      !acquirer.rtiAmbassador().isAttributeOwnedByFederate(object, acquirerFirst) &&
          !acquirer.rtiAmbassador().isAttributeOwnedByFederate(object, acquirerSecond),
      "partial ownership acquirer initially owned an attribute");

  std::vector<std::uint8_t> const acquisitionTagBytes{0x50U, 0x41U, 0x52U};
  std::vector<std::uint8_t> const divestitureTagBytes{0x44U, 0x49U, 0x56U};
  rti::VariableLengthData const acquisitionTag(
      acquisitionTagBytes.data(),
      acquisitionTagBytes.size());
  rti::VariableLengthData const divestitureTag(
      divestitureTagBytes.data(),
      divestitureTagBytes.size());

  // Establish one regular acquisition for both attributes, then cancel only
  // the first one. The owner must be able to satisfy the remaining request
  // without transferring the canceled attribute.
  owner.recorder().clearOwnershipRecords();
  acquirer.recorder().clearOwnershipRecords();
  acquirer.rtiAmbassador().attributeOwnershipAcquisition(
      object,
      acquirerAttributes,
      acquisitionTag);
  waitFor(
      owner,
      [&] { return owner.recorder().ownershipReleaseRequest().has_value(); },
      options,
      "partial ownership release request");
  auto const releaseRequest = owner.recorder().ownershipReleaseRequest();
  require(
      releaseRequest->object == object &&
          releaseRequest->attributes == ownerAttributes &&
          releaseRequest->tag == acquisitionTagBytes,
      "partial ownership release request returned the wrong attributes or tag");

  acquirer.rtiAmbassador().cancelAttributeOwnershipAcquisition(
      object,
      acquirerFirstOnly);
  waitFor(
      acquirer,
      [&] { return acquirer.recorder().ownershipAcquisitionCancellation().has_value(); },
      options,
      "partial ownership cancellation confirmation");
  auto const cancellation = acquirer.recorder().ownershipAcquisitionCancellation();
  require(
      cancellation->object == object &&
          cancellation->attributes == acquirerFirstOnly,
      "partial ownership cancellation returned the wrong attribute set");

  owner.recorder().clearOwnershipRecords();
  acquirer.recorder().clearOwnershipRecords();
  rti::AttributeHandleSet divestedAttributes;
  owner.rtiAmbassador().attributeOwnershipDivestitureIfWanted(
      object,
      ownerAttributes,
      divestitureTag,
      divestedAttributes);
  require(
      divestedAttributes == ownerSecondOnly,
      "partial ownership If Wanted returned more than the uncanceled attribute");
  waitFor(
      acquirer,
      [&] { return acquirer.recorder().ownershipAcquisition().has_value(); },
      options,
      "partial ownership acquisition notification");
  auto const acquisition = acquirer.recorder().ownershipAcquisition();
  require(
      acquisition->object == object &&
          acquisition->attributes == acquirerSecondOnly &&
          acquisition->tag == divestitureTagBytes,
      "partial ownership acquisition notification returned the wrong attribute set or tag");
  require(
      owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerFirst) &&
          !owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerSecond),
      "partial ownership transferred the canceled attribute or retained the other attribute");
  require(
      !acquirer.rtiAmbassador().isAttributeOwnedByFederate(object, acquirerFirst) &&
          acquirer.rtiAmbassador().isAttributeOwnedByFederate(object, acquirerSecond),
      "partial ownership did not transfer exactly the uncanceled attribute");

  acquirer.rtiAmbassador().unsubscribeObjectClassAttributes(
      acquirerClass,
      acquirerAttributes);
  acquirer.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  owner.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  acquirer.disconnect();
  owner.disconnect();
}

void scenarioPartialAttributeOwnershipTransferContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioPartialAttributeOwnershipTransfer(options, model);
}

void scenarioDivestitureIfWantedMixedAcquirers(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.multiAttributeFom.empty(),
      "Divestiture If Wanted testing requires an adapter-supplied multi-attribute FOM");

  Session owner(options, model, "divestiture-if-wanted-owner");
  Session firstRequester(options, model, "divestiture-if-wanted-first");
  Session secondRequester(options, model, "divestiture-if-wanted-second");
  auto const federation = federationName(
      options,
      "divestiture-if-wanted-mixed-acquirers");
  owner.connect();
  firstRequester.connect();
  secondRequester.connect();
  owner.rtiAmbassador().createFederationExecution(
      federation,
      options.multiAttributeFom.wstring(),
      options.logicalTimeImplementationName);
  owner.join(
      options.ownerFederateName + L"-if-wanted-owner",
      options.federateType,
      federation);
  firstRequester.join(
      options.memberFederateName + L"-if-wanted-first",
      options.federateType,
      federation);
  secondRequester.join(
      options.memberFederateName + L"-if-wanted-second",
      options.federateType,
      federation);

  auto const ownerClass = owner.rtiAmbassador().getObjectClassHandle(
      options.multiAttributeObjectClassName);
  auto const firstClass = firstRequester.rtiAmbassador().getObjectClassHandle(
      options.multiAttributeObjectClassName);
  auto const secondClass = secondRequester.rtiAmbassador().getObjectClassHandle(
      options.multiAttributeObjectClassName);
  auto const ownerFirst = owner.rtiAmbassador().getAttributeHandle(
      ownerClass,
      options.multiAttributeFirstName);
  auto const ownerSecond = owner.rtiAmbassador().getAttributeHandle(
      ownerClass,
      options.multiAttributeSecondName);
  auto const firstAttribute = firstRequester.rtiAmbassador().getAttributeHandle(
      firstClass,
      options.multiAttributeFirstName);
  auto const secondAttribute = secondRequester.rtiAmbassador().getAttributeHandle(
      secondClass,
      options.multiAttributeSecondName);
  require(
      ownerClass.isValid() && firstClass.isValid() && secondClass.isValid(),
      "Divestiture If Wanted object-class lookup returned an invalid handle");
  require(
      ownerFirst.isValid() && ownerSecond.isValid() && firstAttribute.isValid() &&
          secondAttribute.isValid(),
      "Divestiture If Wanted attribute lookup returned an invalid handle");
  require(
      ownerFirst != ownerSecond,
      "Divestiture If Wanted adapter supplied duplicate attribute names");

  rti::AttributeHandleSet const ownerAttributes{ownerFirst, ownerSecond};
  rti::AttributeHandleSet const firstAttributes{firstAttribute};
  rti::AttributeHandleSet const secondAttributes{secondAttribute};
  owner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerAttributes);
  firstRequester.rtiAmbassador().publishObjectClassAttributes(
      firstClass,
      firstAttributes);
  secondRequester.rtiAmbassador().publishObjectClassAttributes(
      secondClass,
      secondAttributes);
  firstRequester.rtiAmbassador().subscribeObjectClassAttributes(
      firstClass,
      firstAttributes,
      true,
      L"");
  secondRequester.rtiAmbassador().subscribeObjectClassAttributes(
      secondClass,
      secondAttributes,
      true,
      L"");

  auto const object = owner.rtiAmbassador().registerObjectInstance(ownerClass);
  require(
      object.isValid(),
      "Divestiture If Wanted registration returned an invalid object handle");
  waitFor(
      firstRequester,
      [&] { return firstRequester.recorder().hasDiscovery(object); },
      options,
      "Divestiture If Wanted first-requester discovery");
  waitFor(
      secondRequester,
      [&] { return secondRequester.recorder().hasDiscovery(object); },
      options,
      "Divestiture If Wanted second-requester discovery");

  firstRequester.rtiAmbassador().publishObjectClassAttributes(
      firstClass,
      firstAttributes);
  secondRequester.rtiAmbassador().publishObjectClassAttributes(
      secondClass,
      secondAttributes);
  require(
      owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerFirst) &&
          owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerSecond),
      "Divestiture If Wanted owner did not initially own both attributes");

  rti::VariableLengthData const emptyTag;
  rti::AttributeHandleSet divestedAttributes{ownerFirst};
  owner.rtiAmbassador().attributeOwnershipDivestitureIfWanted(
      object,
      ownerAttributes,
      emptyTag,
      divestedAttributes);
  require(
      divestedAttributes.empty(),
      "Divestiture If Wanted returned attributes without pending acquirers");
  require(
      owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerFirst) &&
          owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerSecond),
      "Divestiture If Wanted changed ownership without pending acquirers");

  owner.recorder().clearOwnershipRecords();
  firstRequester.recorder().clearOwnershipRecords();
  secondRequester.recorder().clearOwnershipRecords();
  std::vector<std::uint8_t> const firstAcquisitionTagBytes{0xa1U, 0x25U};
  std::vector<std::uint8_t> const secondAcquisitionTagBytes{0xa2U, 0x25U};
  std::vector<std::uint8_t> const divestitureTagBytes{0xd1U, 0x25U};
  rti::VariableLengthData const firstAcquisitionTag(
      firstAcquisitionTagBytes.data(),
      firstAcquisitionTagBytes.size());
  rti::VariableLengthData const secondAcquisitionTag(
      secondAcquisitionTagBytes.data(),
      secondAcquisitionTagBytes.size());
  rti::VariableLengthData const divestitureTag(
      divestitureTagBytes.data(),
      divestitureTagBytes.size());

  firstRequester.rtiAmbassador().attributeOwnershipAcquisition(
      object,
      firstAttributes,
      firstAcquisitionTag);
  if (model == rti::HLA_EVOKED) {
    secondRequester.rtiAmbassador().attributeOwnershipAcquisitionIfAvailable(
        object,
        secondAttributes,
        secondAcquisitionTag);
  } else {
    // Immediate delivery reports If Available as unavailable before the owner
    // can divest. Use a regular pending acquisition to keep this service test
    // at the same pending-transfer boundary under both callback models.
    secondRequester.rtiAmbassador().attributeOwnershipAcquisition(
        object,
        secondAttributes,
        secondAcquisitionTag);
  }

  // A synchronous provider may already have reported a release or unavailable
  // callback. Clear those records so the post-divestiture assertions detect only
  // stale callbacks that survive the ownership transfer.
  owner.recorder().clearOwnershipRecords();
  firstRequester.recorder().clearOwnershipRecords();
  secondRequester.recorder().clearOwnershipRecords();
  divestedAttributes = rti::AttributeHandleSet{ownerFirst};
  owner.rtiAmbassador().attributeOwnershipDivestitureIfWanted(
      object,
      ownerAttributes,
      divestitureTag,
      divestedAttributes);
  require(
      divestedAttributes == ownerAttributes,
      "Divestiture If Wanted did not transfer exactly the pending attributes");
  require(
      !owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerFirst) &&
          !owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerSecond),
      "Divestiture If Wanted left an attribute with the former owner");
  require(
      firstRequester.rtiAmbassador().isAttributeOwnedByFederate(
          object,
          firstAttribute) &&
          secondRequester.rtiAmbassador().isAttributeOwnedByFederate(
              object,
              secondAttribute),
      "Divestiture If Wanted did not transfer each requested attribute");

  waitFor(
      firstRequester,
      [&] { return firstRequester.recorder().ownershipAcquisition().has_value(); },
      options,
      "Divestiture If Wanted first acquisition notification");
  waitFor(
      secondRequester,
      [&] { return secondRequester.recorder().ownershipAcquisition().has_value(); },
      options,
      "Divestiture If Wanted second acquisition notification");
  auto const firstAcquisition = firstRequester.recorder().ownershipAcquisition();
  auto const secondAcquisition = secondRequester.recorder().ownershipAcquisition();
  require(
      firstAcquisition->object == object &&
          firstAcquisition->attributes == firstAttributes &&
          firstAcquisition->tag == divestitureTagBytes,
      "Divestiture If Wanted first notification returned the wrong object, attributes, or tag");
  require(
      secondAcquisition->object == object &&
          secondAcquisition->attributes == secondAttributes &&
          secondAcquisition->tag == divestitureTagBytes,
      "Divestiture If Wanted second notification returned the wrong object, attributes, or tag");

  for (int pass = 0; pass != 8; ++pass) {
    owner.pump();
  }
  require(
      !owner.recorder().ownershipReleaseRequest().has_value(),
      "Divestiture If Wanted delivered a stale owner-release callback");

  firstRequester.rtiAmbassador().unpublishObjectClassAttributes(
      firstClass,
      firstAttributes);
  secondRequester.rtiAmbassador().unpublishObjectClassAttributes(
      secondClass,
      secondAttributes);
  owner.rtiAmbassador().unpublishObjectClassAttributes(ownerClass, ownerAttributes);
  firstRequester.resign(rti::NO_ACTION);
  secondRequester.resign(rti::NO_ACTION);
  owner.resign(rti::DELETE_OBJECTS);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  firstRequester.disconnect();
  secondRequester.disconnect();
  owner.disconnect();
}

void scenarioDivestitureIfWantedMixedAcquirersContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioDivestitureIfWantedMixedAcquirers(options, model);
}

void scenarioNegotiatedDivestiturePartialAcquisitionCancellation(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.multiAttributeFom.empty(),
      "Partial negotiated divestiture testing requires an adapter-supplied multi-attribute FOM");

  Session owner(options, model, "negotiated-partial-cancel-owner");
  Session requester(options, model, "negotiated-partial-cancel-requester");
  auto const federation = federationName(
      options,
      "negotiated-divestiture-partial-acquisition-cancellation");
  owner.connect();
  requester.connect();
  owner.rtiAmbassador().createFederationExecution(
      federation,
      options.multiAttributeFom.wstring(),
      options.logicalTimeImplementationName);
  owner.join(
      options.ownerFederateName + L"-negotiated-partial-owner",
      options.federateType,
      federation);
  requester.join(
      options.memberFederateName + L"-negotiated-partial-requester",
      options.federateType,
      federation);

  auto const ownerClass = owner.rtiAmbassador().getObjectClassHandle(
      options.multiAttributeObjectClassName);
  auto const requesterClass = requester.rtiAmbassador().getObjectClassHandle(
      options.multiAttributeObjectClassName);
  auto const ownerFirst = owner.rtiAmbassador().getAttributeHandle(
      ownerClass,
      options.multiAttributeFirstName);
  auto const ownerSecond = owner.rtiAmbassador().getAttributeHandle(
      ownerClass,
      options.multiAttributeSecondName);
  auto const requesterFirst = requester.rtiAmbassador().getAttributeHandle(
      requesterClass,
      options.multiAttributeFirstName);
  auto const requesterSecond = requester.rtiAmbassador().getAttributeHandle(
      requesterClass,
      options.multiAttributeSecondName);
  require(
      ownerClass.isValid() && requesterClass.isValid(),
      "Partial negotiated divestiture object-class lookup returned an invalid handle");
  require(
      ownerFirst.isValid() && ownerSecond.isValid() && requesterFirst.isValid() &&
          requesterSecond.isValid(),
      "Partial negotiated divestiture attribute lookup returned an invalid handle");
  require(
      ownerFirst != ownerSecond,
      "Partial negotiated divestiture adapter supplied duplicate attribute names");

  rti::AttributeHandleSet const ownerAttributes{ownerFirst, ownerSecond};
  rti::AttributeHandleSet const requesterAttributes{requesterFirst, requesterSecond};
  rti::AttributeHandleSet const ownerCancelledAttributes{ownerFirst};
  rti::AttributeHandleSet const ownerRetainedAttributes{ownerSecond};
  rti::AttributeHandleSet const requesterCancelledAttributes{requesterFirst};
  rti::AttributeHandleSet const requesterRetainedAttributes{requesterSecond};
  owner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerAttributes);
  requester.rtiAmbassador().publishObjectClassAttributes(
      requesterClass,
      requesterAttributes);
  requester.rtiAmbassador().subscribeObjectClassAttributes(
      requesterClass,
      requesterAttributes,
      true,
      L"");

  auto const object = owner.rtiAmbassador().registerObjectInstance(ownerClass);
  require(
      object.isValid(),
      "Partial negotiated divestiture registration returned an invalid object handle");
  waitFor(
      requester,
      [&] { return requester.recorder().hasDiscovery(object); },
      options,
      "partial negotiated divestiture discovery");
  require(
      owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerFirst) &&
          owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerSecond),
      "Partial negotiated divestiture owner did not initially own both attributes");

  std::vector<std::uint8_t> const acquisitionTagBytes{0xc3U, 0x25U};
  std::vector<std::uint8_t> const divestitureTagBytes{0xd3U, 0x25U};
  std::vector<std::uint8_t> const confirmationTagBytes{0xe3U, 0x25U};
  rti::VariableLengthData const acquisitionTag(
      acquisitionTagBytes.data(),
      acquisitionTagBytes.size());
  rti::VariableLengthData const divestitureTag(
      divestitureTagBytes.data(),
      divestitureTagBytes.size());
  rti::VariableLengthData const confirmationTag(
      confirmationTagBytes.data(),
      confirmationTagBytes.size());

  owner.recorder().clearOwnershipRecords();
  requester.recorder().clearOwnershipRecords();
  requester.rtiAmbassador().attributeOwnershipAcquisition(
      object,
      requesterAttributes,
      acquisitionTag);
  owner.rtiAmbassador().negotiatedAttributeOwnershipDivestiture(
      object,
      ownerAttributes,
      divestitureTag);
  require(
      owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerFirst) &&
          owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerSecond),
      "Partial negotiated divestiture changed ownership before cancellation");

  requester.rtiAmbassador().cancelAttributeOwnershipAcquisition(
      object,
      requesterCancelledAttributes);
  waitFor(
      requester,
      [&] { return requester.recorder().ownershipAcquisitionCancellation().has_value(); },
      options,
      "partial negotiated acquisition cancellation confirmation");
  auto const cancellation = requester.recorder().ownershipAcquisitionCancellation();
  require(
      cancellation->object == object &&
          cancellation->attributes == requesterCancelledAttributes,
      "Partial negotiated acquisition cancellation returned the wrong attribute set");
  require(
      !requester.recorder().ownershipAcquisition().has_value(),
      "Partial negotiated acquisition notified the requester before confirmation");

  if (model == rti::HLA_EVOKED) {
    waitFor(
        owner,
        [&] { return owner.recorder().divestitureConfirmation().has_value(); },
        options,
        "partial negotiated divestiture confirmation");
    auto const confirmation = owner.recorder().divestitureConfirmation();
    require(
        confirmation->object == object &&
            confirmation->attributes == ownerRetainedAttributes &&
            confirmation->tag == acquisitionTagBytes,
        "Partial negotiated divestiture confirmation did not retain the uncanceled attribute");
  } else {
    require(
        owner.recorder().divestitureConfirmation().has_value(),
        "Immediate negotiated divestiture did not report its confirmation request");
  }

  owner.rtiAmbassador().confirmDivestiture(
      object,
      ownerRetainedAttributes,
      confirmationTag);
  require(
      owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerFirst) &&
          !owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerSecond),
      "Partial negotiated divestiture transferred the canceled attribute");
  require(
      !requester.rtiAmbassador().isAttributeOwnedByFederate(object, requesterFirst) &&
          requester.rtiAmbassador().isAttributeOwnedByFederate(object, requesterSecond),
      "Partial negotiated divestiture did not transfer exactly the retained attribute");

  waitFor(
      requester,
      [&] { return requester.recorder().ownershipAcquisition().has_value(); },
      options,
      "partial negotiated acquisition notification");
  auto const acquisition = requester.recorder().ownershipAcquisition();
  require(
      acquisition->object == object &&
          acquisition->attributes == requesterRetainedAttributes &&
          acquisition->tag == confirmationTagBytes,
      "Partial negotiated acquisition notification returned the wrong attribute set or tag");

  owner.rtiAmbassador().cancelNegotiatedAttributeOwnershipDivestiture(
      object,
      ownerCancelledAttributes);
  require(
      owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerFirst),
      "Partial negotiated cancellation did not retain the canceled attribute");

  requester.rtiAmbassador().unpublishObjectClassAttributes(
      requesterClass,
      requesterRetainedAttributes);
  owner.rtiAmbassador().unpublishObjectClassAttributes(ownerClass, ownerAttributes);
  requester.resign(rti::NO_ACTION);
  owner.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  requester.disconnect();
  owner.disconnect();
}

void scenarioNegotiatedDivestiturePartialAcquisitionCancellationContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioNegotiatedDivestiturePartialAcquisitionCancellation(options, model);
}

void scenarioOwnershipAcquisitionCancellationTransferRace(
    Options const& options,
    rti::CallbackModel model) {
  Session owner(options, model, "ownership-race-owner");
  Session requester(options, model, "ownership-race-requester");
  auto const federation = federationName(
      options,
      "ownership-acquisition-cancellation-transfer-race");
  connectAndJoin(owner, requester, options, federation, options.fom);

  rti::ObjectClassHandle ownerClass;
  rti::AttributeHandle ownerAttribute;
  rti::InteractionClassHandle ownerInteraction;
  rti::ParameterHandle ownerParameter;
  handles(owner, options, ownerClass, ownerAttribute, ownerInteraction, ownerParameter);
  auto const requesterClass = requester.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const requesterAttribute = requester.rtiAmbassador().getAttributeHandle(
      requesterClass,
      options.attributeName);
  require(
      ownerClass.isValid() && ownerAttribute.isValid() && requesterClass.isValid() &&
          requesterAttribute.isValid(),
      "Ownership cancellation race lookup returned an invalid handle");

  rti::AttributeHandleSet const ownerAttributes{ownerAttribute};
  rti::AttributeHandleSet const requesterAttributes{requesterAttribute};
  owner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerAttributes);
  requester.rtiAmbassador().subscribeObjectClassAttributes(
      requesterClass,
      requesterAttributes,
      true,
      L"");
  auto const object = owner.rtiAmbassador().registerObjectInstance(ownerClass);
  require(
      object.isValid(),
      "Ownership cancellation race registration returned an invalid object handle");
  waitFor(
      requester,
      [&] { return requester.recorder().hasDiscovery(object); },
      options,
      "ownership cancellation race discovery");
  requester.rtiAmbassador().publishObjectClassAttributes(
      requesterClass,
      requesterAttributes);
  for (int pass = 0; pass != 8; ++pass) {
    owner.pump();
    requester.pump();
  }

  std::vector<std::uint8_t> const acquisitionTagBytes{0xc1U, 0x25U};
  std::vector<std::uint8_t> const divestitureTagBytes{0xd1U, 0x25U};
  rti::VariableLengthData const acquisitionTag(
      acquisitionTagBytes.data(),
      acquisitionTagBytes.size());
  rti::VariableLengthData const divestitureTag(
      divestitureTagBytes.data(),
      divestitureTagBytes.size());
  owner.recorder().clearOwnershipRecords();
  requester.recorder().clearOwnershipRecords();

  std::mutex coordinationMutex;
  std::condition_variable coordination;
  bool releaseCallbackEntered = false;
  bool cancellationCompleted = false;
  std::exception_ptr cancellationFailure;
  std::exception_ptr divestitureFailure;
  owner.recorder().setOwnershipReleaseHook(
      [&](rti::ObjectInstanceHandle const& callbackObject,
          rti::AttributeHandleSet const& callbackAttributes,
          rti::VariableLengthData const&) {
        {
          std::lock_guard<std::mutex> lock(coordinationMutex);
          releaseCallbackEntered = true;
        }
        coordination.notify_all();

        std::unique_lock<std::mutex> lock(coordinationMutex);
        bool const observedCancellation = coordination.wait_for(
            lock,
            std::chrono::milliseconds(options.timeoutMilliseconds),
            [&] { return cancellationCompleted; });
        lock.unlock();
        if (!observedCancellation) {
          std::lock_guard<std::mutex> failureLock(coordinationMutex);
          divestitureFailure = std::make_exception_ptr(
              std::runtime_error(
                  "Ownership cancellation race did not observe cancellation"));
          return;
        }

        try {
          rti::AttributeHandleSet divestedAttributes;
          owner.rtiAmbassador().attributeOwnershipDivestitureIfWanted(
              callbackObject,
              callbackAttributes,
              divestitureTag,
              divestedAttributes);
          require(
              divestedAttributes == callbackAttributes,
              "Ownership cancellation race Divestiture If Wanted returned the wrong set");
        } catch (...) {
          std::lock_guard<std::mutex> failureLock(coordinationMutex);
          divestitureFailure = std::current_exception();
        }
      });

  std::thread canceller([&] {
    std::unique_lock<std::mutex> lock(coordinationMutex);
    bool const observedRelease = coordination.wait_for(
        lock,
        std::chrono::milliseconds(options.timeoutMilliseconds),
        [&] { return releaseCallbackEntered; });
    lock.unlock();
    if (!observedRelease) {
      cancellationFailure = std::make_exception_ptr(
          std::runtime_error(
              "Ownership cancellation race did not observe the release callback"));
    } else {
      try {
        requester.rtiAmbassador().cancelAttributeOwnershipAcquisition(
            object,
            requesterAttributes);
      } catch (...) {
        cancellationFailure = std::current_exception();
      }
    }
    {
      std::lock_guard<std::mutex> completionLock(coordinationMutex);
      cancellationCompleted = true;
    }
    coordination.notify_all();
  });

  std::exception_ptr driverFailure;
  try {
    requester.rtiAmbassador().attributeOwnershipAcquisition(
        object,
        requesterAttributes,
        acquisitionTag);
    owner.pump();
  } catch (...) {
    driverFailure = std::current_exception();
  }
  canceller.join();
  owner.recorder().setOwnershipReleaseHook({});
  if (driverFailure) {
    std::rethrow_exception(driverFailure);
  }
  auto describeFailure = [](std::exception_ptr const& failure) {
    if (!failure) {
      return std::string{};
    }
    try {
      std::rethrow_exception(failure);
    } catch (rti::Exception const& error) {
      return toNarrow(error.name());
    } catch (std::exception const& error) {
      return std::string(error.what());
    } catch (...) {
      return std::string("unknown exception");
    }
  };
  require(
      !cancellationFailure,
      "Ownership cancellation race acquisition cancellation failed: " +
          describeFailure(cancellationFailure));
  require(
      !divestitureFailure,
      "Ownership cancellation race divestiture failed: " +
          describeFailure(divestitureFailure));

  waitFor(
      requester,
      [&] { return requester.recorder().ownershipAcquisition().has_value(); },
      options,
      "ownership cancellation race acquisition notification");
  require(
      !requester.recorder().ownershipAcquisitionCancellation().has_value(),
      "Ownership cancellation race delivered a stale cancellation confirmation");
  auto const notification = requester.recorder().ownershipAcquisition();
  require(
      notification->object == object &&
          notification->attributes == requesterAttributes &&
          notification->tag == divestitureTagBytes,
      "Ownership cancellation race acquisition notification returned the wrong data");
  require(
      !owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerAttribute) &&
          requester.rtiAmbassador().isAttributeOwnedByFederate(
              object,
              requesterAttribute),
      "Ownership cancellation race did not transfer ownership");

  requester.rtiAmbassador().unpublishObjectClassAttributes(
      requesterClass,
      requesterAttributes);
  owner.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  requester.resign(rti::NO_ACTION);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  requester.disconnect();
  owner.disconnect();
}

void scenarioNegotiatedDivestitureCancellation(
    Options const& options,
    rti::CallbackModel model) {
  Session owner(options, model, "negotiated-divestiture-owner");
  Session requester(options, model, "negotiated-divestiture-requester");
  auto const federation = federationName(options, "negotiated-divestiture-cancellation");
  connectAndJoin(owner, requester, options, federation, options.fom);

  rti::ObjectClassHandle ownerClass;
  rti::AttributeHandle ownerAttribute;
  rti::InteractionClassHandle ownerInteraction;
  rti::ParameterHandle ownerParameter;
  handles(owner, options, ownerClass, ownerAttribute, ownerInteraction, ownerParameter);
  auto const requesterClass = requester.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const requesterAttribute = requester.rtiAmbassador().getAttributeHandle(
      requesterClass,
      options.attributeName);
  require(
      ownerClass.isValid() && ownerAttribute.isValid() && requesterClass.isValid() &&
          requesterAttribute.isValid(),
      "Negotiated divestiture cancellation lookup returned an invalid handle");

  rti::AttributeHandleSet const ownerAttributes{ownerAttribute};
  rti::AttributeHandleSet const requesterAttributes{requesterAttribute};
  owner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerAttributes);
  requester.rtiAmbassador().publishObjectClassAttributes(
      requesterClass,
      requesterAttributes);
  requester.rtiAmbassador().subscribeObjectClassAttributes(
      requesterClass,
      requesterAttributes,
      true,
      L"");

  auto const object = owner.rtiAmbassador().registerObjectInstance(ownerClass);
  require(object.isValid(),
          "Negotiated divestiture cancellation returned an invalid object handle");
  waitFor(
      requester,
      [&] { return requester.recorder().hasDiscovery(object); },
      options,
      "negotiated divestiture cancellation discovery");

  owner.recorder().clearOwnershipRecords();
  requester.recorder().clearOwnershipRecords();
  std::vector<std::uint8_t> acquisitionTagBytes{0x49U, 0xa7U, 0x11U};
  std::vector<std::uint8_t> divestitureTagBytes{0x52U, 0xa7U, 0x11U};
  rti::VariableLengthData acquisitionTag(
      acquisitionTagBytes.data(),
      acquisitionTagBytes.size());
  rti::VariableLengthData divestitureTag(
      divestitureTagBytes.data(),
      divestitureTagBytes.size());

  requester.rtiAmbassador().attributeOwnershipAcquisition(
      object,
      requesterAttributes,
      acquisitionTag);
  owner.rtiAmbassador().negotiatedAttributeOwnershipDivestiture(
      object,
      ownerAttributes,
      divestitureTag);
  waitFor(
      owner,
      [&] { return owner.recorder().divestitureConfirmation().has_value(); },
      options,
      "negotiated divestiture confirmation request");
  auto const confirmation = owner.recorder().divestitureConfirmation();
  require(
      confirmation->object == object && confirmation->attributes == ownerAttributes &&
          confirmation->tag == acquisitionTagBytes,
      "negotiated divestiture confirmation did not preserve the acquisition request");
  if (model == rti::HLA_EVOKED) {
    require(
        !owner.recorder().ownershipReleaseRequest().has_value(),
        "negotiated divestiture delivered an ordinary release request before cancellation");
  }

  owner.rtiAmbassador().cancelNegotiatedAttributeOwnershipDivestiture(
      object,
      ownerAttributes);
  waitFor(
      owner,
      [&] { return owner.recorder().ownershipReleaseRequest().has_value(); },
      options,
      "ordinary release request after negotiated divestiture cancellation");
  auto const releaseRequest = owner.recorder().ownershipReleaseRequest();
  require(
      releaseRequest->object == object && releaseRequest->attributes == ownerAttributes &&
          releaseRequest->tag == acquisitionTagBytes,
      "canceled negotiated divestiture did not restore the ordinary release request");
  require(
      owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerAttribute) &&
          !requester.rtiAmbassador().isAttributeOwnedByFederate(object, requesterAttribute),
      "canceled negotiated divestiture changed ownership");

  requester.rtiAmbassador().cancelAttributeOwnershipAcquisition(
      object,
      requesterAttributes);
  waitFor(
      requester,
      [&] { return requester.recorder().ownershipAcquisitionCancellation().has_value(); },
      options,
      "ownership acquisition cancellation after negotiated divestiture cancellation");
  auto const cancellation = requester.recorder().ownershipAcquisitionCancellation();
  require(
      cancellation->object == object && cancellation->attributes == requesterAttributes,
      "ownership acquisition cancellation returned the wrong object or attributes");
  require(
      owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerAttribute) &&
          !requester.rtiAmbassador().isAttributeOwnedByFederate(object, requesterAttribute),
      "ownership acquisition cancellation changed ownership");

  requester.rtiAmbassador().unpublishObjectClassAttributes(
      requesterClass,
      requesterAttributes);
  owner.rtiAmbassador().unpublishObjectClassAttributes(ownerClass, ownerAttributes);
  owner.resign(rti::DELETE_OBJECTS);
  requester.resign(rti::NO_ACTION);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  requester.disconnect();
  owner.disconnect();
}

void scenarioNegotiatedDivestitureCancellationContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioNegotiatedDivestitureCancellation(options, model);
}

void scenarioNegotiatedDivestiturePreDeliveryCancellation(
    Options const& options,
    rti::CallbackModel model) {
  Session owner(options, model, "negotiated-pre-delivery-owner");
  Session requester(options, model, "negotiated-pre-delivery-requester");
  auto const federation = federationName(
      options,
      "negotiated-divestiture-pre-delivery-cancellation");
  connectAndJoin(owner, requester, options, federation, options.fom);

  rti::ObjectClassHandle ownerClass;
  rti::AttributeHandle ownerAttribute;
  rti::InteractionClassHandle ownerInteraction;
  rti::ParameterHandle ownerParameter;
  handles(owner, options, ownerClass, ownerAttribute, ownerInteraction, ownerParameter);
  auto const requesterClass = requester.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const requesterAttribute = requester.rtiAmbassador().getAttributeHandle(
      requesterClass,
      options.attributeName);
  require(
      ownerClass.isValid() && ownerAttribute.isValid() && requesterClass.isValid() &&
          requesterAttribute.isValid(),
      "Pre-delivery negotiated cancellation lookup returned an invalid handle");

  rti::AttributeHandleSet const ownerAttributes{ownerAttribute};
  rti::AttributeHandleSet const requesterAttributes{requesterAttribute};
  requester.rtiAmbassador().subscribeObjectClassAttributes(
      requesterClass,
      requesterAttributes,
      true,
      L"");
  owner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerAttributes);
  auto const object = owner.rtiAmbassador().registerObjectInstance(ownerClass);
  require(
      object.isValid(),
      "Pre-delivery negotiated cancellation returned an invalid object handle");
  waitFor(
      requester,
      [&] { return requester.recorder().hasDiscovery(object); },
      options,
      "pre-delivery negotiated cancellation discovery");
  requester.rtiAmbassador().publishObjectClassAttributes(
      requesterClass,
      requesterAttributes);

  owner.recorder().clearOwnershipRecords();
  requester.recorder().clearOwnershipRecords();
  std::vector<std::uint8_t> acquisitionTagBytes{0xc2U, 0x25U};
  std::vector<std::uint8_t> divestitureTagBytes{0xd2U, 0x25U};
  rti::VariableLengthData acquisitionTag(
      acquisitionTagBytes.data(),
      acquisitionTagBytes.size());
  rti::VariableLengthData divestitureTag(
      divestitureTagBytes.data(),
      divestitureTagBytes.size());

  requester.rtiAmbassador().attributeOwnershipAcquisition(
      object,
      requesterAttributes,
      acquisitionTag);
  owner.rtiAmbassador().negotiatedAttributeOwnershipDivestiture(
      object,
      ownerAttributes,
      divestitureTag);
  if (model == rti::HLA_EVOKED) {
    require(
        !owner.recorder().divestitureConfirmation().has_value() &&
            !owner.recorder().ownershipReleaseRequest().has_value(),
        "evoked negotiated divestiture crossed the callback boundary before cancellation");
  }

  requester.rtiAmbassador().cancelAttributeOwnershipAcquisition(
      object,
      requesterAttributes);
  waitFor(
      requester,
      [&] { return requester.recorder().ownershipAcquisitionCancellation().has_value(); },
      options,
      "pre-delivery ownership acquisition cancellation");
  auto const cancellation = requester.recorder().ownershipAcquisitionCancellation();
  require(
      cancellation->object == object && cancellation->attributes == requesterAttributes,
      "pre-delivery ownership cancellation returned the wrong object or attributes");

  if (model == rti::HLA_EVOKED) {
    for (int pass = 0; pass != 8; ++pass) {
      owner.pump();
    }
    require(
        !owner.recorder().divestitureConfirmation().has_value() &&
            !owner.recorder().ownershipReleaseRequest().has_value(),
        "pre-delivery acquisition cancellation delivered stale owner callbacks");
    owner.rtiAmbassador().cancelNegotiatedAttributeOwnershipDivestiture(
        object,
        ownerAttributes);
  }

  require(
      owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerAttribute) &&
          !requester.rtiAmbassador().isAttributeOwnedByFederate(
              object,
              requesterAttribute),
      "pre-delivery negotiated cancellation changed ownership");

  requester.rtiAmbassador().unpublishObjectClassAttributes(
      requesterClass,
      requesterAttributes);
  owner.rtiAmbassador().unpublishObjectClassAttributes(ownerClass, ownerAttributes);
  owner.resign(rti::DELETE_OBJECTS);
  requester.resign(rti::NO_ACTION);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  requester.disconnect();
  owner.disconnect();
}

void scenarioNegotiatedWillingToAcquireContinuation(
    Options const& options,
    rti::CallbackModel model) {
  Session owner(options, model, "negotiated-continuation-owner");
  Session firstCandidate(options, model, "negotiated-continuation-first");
  Session secondCandidate(options, model, "negotiated-continuation-second");
  auto const federation = federationName(
      options,
      "negotiated-willing-to-acquire-continuation");

  owner.connect();
  firstCandidate.connect();
  secondCandidate.connect();
  owner.rtiAmbassador().createFederationExecution(
      federation,
      options.fom.wstring(),
      options.logicalTimeImplementationName);
  owner.join(
      options.ownerFederateName + L"-wta-continuation-owner",
      options.federateType,
      federation);
  firstCandidate.join(
      options.memberFederateName + L"-wta-continuation-first",
      options.federateType,
      federation);
  secondCandidate.join(
      options.memberFederateName + L"-wta-continuation-second",
      options.federateType,
      federation);

  rti::ObjectClassHandle ownerClass;
  rti::AttributeHandle ownerAttribute;
  rti::InteractionClassHandle ownerInteraction;
  rti::ParameterHandle ownerParameter;
  handles(owner, options, ownerClass, ownerAttribute, ownerInteraction, ownerParameter);
  auto const firstClass = firstCandidate.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const firstAttribute = firstCandidate.rtiAmbassador().getAttributeHandle(
      firstClass,
      options.attributeName);
  auto const secondClass = secondCandidate.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const secondAttribute = secondCandidate.rtiAmbassador().getAttributeHandle(
      secondClass,
      options.attributeName);
  require(
      ownerClass.isValid() && ownerAttribute.isValid() && firstClass.isValid() &&
          firstAttribute.isValid() && secondClass.isValid() &&
          secondAttribute.isValid(),
      "Willing-to-acquire continuation lookup returned an invalid handle");

  rti::AttributeHandleSet const ownerAttributes{ownerAttribute};
  rti::AttributeHandleSet const firstAttributes{firstAttribute};
  rti::AttributeHandleSet const secondAttributes{secondAttribute};
  firstCandidate.rtiAmbassador().subscribeObjectClassAttributes(
      firstClass,
      firstAttributes,
      true,
      L"");
  secondCandidate.rtiAmbassador().subscribeObjectClassAttributes(
      secondClass,
      secondAttributes,
      true,
      L"");
  owner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerAttributes);
  auto const object = owner.rtiAmbassador().registerObjectInstance(ownerClass);
  require(
      object.isValid(),
      "Willing-to-acquire continuation returned an invalid object handle");
  waitFor(
      firstCandidate,
      [&] { return firstCandidate.recorder().hasDiscovery(object); },
      options,
      "Willing-to-acquire continuation first-candidate discovery");
  waitFor(
      secondCandidate,
      [&] { return secondCandidate.recorder().hasDiscovery(object); },
      options,
      "Willing-to-acquire continuation second-candidate discovery");
  firstCandidate.rtiAmbassador().publishObjectClassAttributes(
      firstClass,
      firstAttributes);
  secondCandidate.rtiAmbassador().publishObjectClassAttributes(
      secondClass,
      secondAttributes);

  owner.recorder().clearOwnershipRecords();
  firstCandidate.recorder().clearOwnershipRecords();
  secondCandidate.recorder().clearOwnershipRecords();
  std::vector<std::uint8_t> const firstWillingTagBytes{0x81U, 0xA7U, 0x25U};
  std::vector<std::uint8_t> const firstRegularTagBytes{0x85U, 0xA7U, 0x25U};
  std::vector<std::uint8_t> const secondWillingTagBytes{0x82U, 0xA7U, 0x25U};
  std::vector<std::uint8_t> const divestitureTagBytes{0x83U, 0xA7U, 0x25U};
  std::vector<std::uint8_t> const confirmationTagBytes{0x84U, 0xA7U, 0x25U};
  rti::VariableLengthData const firstWillingTag(
      firstWillingTagBytes.data(),
      firstWillingTagBytes.size());
  rti::VariableLengthData const firstRegularTag(
      firstRegularTagBytes.data(),
      firstRegularTagBytes.size());
  rti::VariableLengthData const secondWillingTag(
      secondWillingTagBytes.data(),
      secondWillingTagBytes.size());
  rti::VariableLengthData const divestitureTag(
      divestitureTagBytes.data(),
      divestitureTagBytes.size());
  rti::VariableLengthData const confirmationTag(
      confirmationTagBytes.data(),
      confirmationTagBytes.size());

  auto cancelFirstCandidate = [&] {
    firstCandidate.rtiAmbassador().attributeOwnershipAcquisition(
        object,
        firstAttributes,
        firstRegularTag);
    firstCandidate.rtiAmbassador().cancelAttributeOwnershipAcquisition(
        object,
        firstAttributes);
    waitFor(
        firstCandidate,
        [&] {
          return firstCandidate.recorder().ownershipAcquisitionCancellation().has_value();
        },
        options,
        "Willing-to-acquire first-candidate cancellation");
    auto const cancellation = firstCandidate.recorder().ownershipAcquisitionCancellation();
    require(
        cancellation->object == object && cancellation->attributes == firstAttributes,
        "Willing-to-acquire cancellation returned the wrong object or attributes");
    require(
        !firstCandidate.recorder().ownershipAcquisition().has_value(),
        "Canceled Willing-to-Acquire candidate received an acquisition notification");
  };

  // Both candidates remain Willing to Acquire until the owner-side
  // negotiated-divestiture callback is delivered. This retained reservation
  // is intentionally an evoked-callback scenario; immediate delivery reports
  // the unavailable state at the If Available callback boundary.
  firstCandidate.rtiAmbassador().attributeOwnershipAcquisitionIfAvailable(
      object,
      firstAttributes,
      firstWillingTag);
  secondCandidate.rtiAmbassador().attributeOwnershipAcquisitionIfAvailable(
      object,
      secondAttributes,
      secondWillingTag);
  require(
      !firstCandidate.recorder().ownershipAcquisition().has_value() &&
          !secondCandidate.recorder().ownershipAcquisition().has_value(),
      "Willing-to-acquire reservation transferred ownership before divestiture");

  owner.rtiAmbassador().negotiatedAttributeOwnershipDivestiture(
      object,
      ownerAttributes,
      divestitureTag);
  require(
      owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerAttribute) &&
          !firstCandidate.rtiAmbassador().isAttributeOwnedByFederate(
              object,
              firstAttribute) &&
          !secondCandidate.rtiAmbassador().isAttributeOwnedByFederate(
              object,
              secondAttribute),
      "Negotiated Willing-to-Acquire divestiture changed ownership before confirmation");
  if (model == rti::HLA_EVOKED) {
    require(
        !owner.recorder().divestitureConfirmation().has_value() &&
            !owner.recorder().ownershipReleaseRequest().has_value(),
        "Evoked negotiated continuation crossed the callback boundary before cancellation");
    cancelFirstCandidate();
  }

  waitFor(
      owner,
      [&] { return owner.recorder().divestitureConfirmation().has_value(); },
      options,
      "Willing-to-acquire continuation divestiture confirmation");
  auto const confirmation = owner.recorder().divestitureConfirmation();
  require(
      confirmation->object == object && confirmation->attributes == ownerAttributes &&
          confirmation->tag == secondWillingTagBytes,
      "Continuation confirmation did not select the second Willing-to-Acquire tag");
  require(
      !owner.recorder().ownershipReleaseRequest().has_value() &&
          !secondCandidate.recorder().ownershipAcquisition().has_value(),
      "Stale first-candidate work produced an owner release or early acquisition callback");

  owner.rtiAmbassador().confirmDivestiture(
      object,
      ownerAttributes,
      confirmationTag);
  require(
      !owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerAttribute) &&
          !firstCandidate.rtiAmbassador().isAttributeOwnedByFederate(
              object,
              firstAttribute) &&
          secondCandidate.rtiAmbassador().isAttributeOwnedByFederate(
              object,
              secondAttribute),
      "Negotiated continuation confirmation did not transfer ownership to the second candidate");
  waitFor(
      secondCandidate,
      [&] { return secondCandidate.recorder().ownershipAcquisition().has_value(); },
      options,
      "Willing-to-acquire continuation acquisition notification");
  auto const acquisition = secondCandidate.recorder().ownershipAcquisition();
  require(
      acquisition->object == object && acquisition->attributes == secondAttributes &&
          acquisition->tag == confirmationTagBytes,
      "Continuation acquisition notification returned the wrong object, attributes, or tag");

  firstCandidate.rtiAmbassador().unpublishObjectClassAttributes(
      firstClass,
      firstAttributes);
  secondCandidate.rtiAmbassador().unpublishObjectClassAttributes(
      secondClass,
      secondAttributes);
  owner.rtiAmbassador().unpublishObjectClassAttributes(ownerClass, ownerAttributes);
  owner.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  firstCandidate.resign(rti::NO_ACTION);
  secondCandidate.resign(rti::NO_ACTION);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  firstCandidate.disconnect();
  secondCandidate.disconnect();
  owner.disconnect();
}

void scenarioNegotiatedDivestiturePreDeliveryCancellationContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioNegotiatedDivestiturePreDeliveryCancellation(options, model);
}

void scenarioResignPendingAcquisitionRejection(
    Options const& options,
    rti::CallbackModel model) {
  Session pending(options, model, "pending-acquisition");
  Session currentOwner(options, model, "current-owner");
  auto const federation = federationName(options, "resign-pending-acquisition-rejection");
  connectAndJoin(pending, currentOwner, options, federation, options.fom);

  rti::ObjectClassHandle pendingClass;
  rti::AttributeHandle pendingAttribute;
  rti::InteractionClassHandle pendingInteraction;
  rti::ParameterHandle pendingParameter;
  handles(
      pending,
      options,
      pendingClass,
      pendingAttribute,
      pendingInteraction,
      pendingParameter);
  auto const ownerClass = currentOwner.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const ownerAttribute = currentOwner.rtiAmbassador().getAttributeHandle(
      ownerClass,
      options.attributeName);
  require(
      pendingClass.isValid() && pendingAttribute.isValid() && ownerClass.isValid() &&
          ownerAttribute.isValid(),
      "pending-acquisition resignation lookup returned an invalid handle");

  rti::AttributeHandleSet const pendingAttributes{pendingAttribute};
  rti::AttributeHandleSet const ownerAttributes{ownerAttribute};
  pending.rtiAmbassador().subscribeObjectClassAttributes(
      pendingClass,
      pendingAttributes,
      true,
      L"");
  currentOwner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerAttributes);
  auto const object = currentOwner.rtiAmbassador().registerObjectInstance(ownerClass);
  require(object.isValid(),
          "pending-acquisition resignation returned an invalid object handle");
  waitFor(
      pending,
      [&] { return pending.recorder().hasDiscovery(object); },
      options,
      "pending-acquisition resignation discovery");

  pending.rtiAmbassador().publishObjectClassAttributes(pendingClass, pendingAttributes);
  pending.recorder().clearOwnershipRecords();
  currentOwner.recorder().clearOwnershipRecords();
  std::vector<std::uint8_t> acquisitionTagBytes{0xd2U, 0x25U};
  rti::VariableLengthData acquisitionTag(
      acquisitionTagBytes.data(),
      acquisitionTagBytes.size());
  pending.rtiAmbassador().attributeOwnershipAcquisition(
      object,
      pendingAttributes,
      acquisitionTag);

  requireException(
      [&] { pending.resign(rti::UNCONDITIONALLY_DIVEST_ATTRIBUTES); },
      L"OwnershipAcquisitionPending",
      "unconditional resignation with a pending ownership acquisition");
  require(
      pending.rtiAmbassador().getFederateHandle(options.ownerFederateName).isValid(),
      "pending-acquisition federate left the execution after rejected resignation");

  pending.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  for (int pass = 0; pass != 8; ++pass) {
    currentOwner.pump();
  }
  if (model == rti::HLA_EVOKED) {
    require(
        !currentOwner.recorder().ownershipReleaseRequest().has_value(),
        "canceling the pending acquisition delivered a stale owner-release callback");
  }

  currentOwner.resign(rti::DELETE_OBJECTS);
  currentOwner.rtiAmbassador().destroyFederationExecution(federation);
  pending.disconnect();
  currentOwner.disconnect();
}

void scenarioResignPendingAcquisitionRejectionContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioResignPendingAcquisitionRejection(options, model);
}

void scenarioResignCancelPendingAcquisition(
    Options const& options,
    rti::CallbackModel model) {
  Session requester(options, model, "resign-cancel-requester");
  Session owner(options, model, "resign-cancel-owner");
  auto const federation = federationName(options, "resign-cancel-pending-acquisition");
  connectAndJoin(requester, owner, options, federation, options.fom);

  rti::ObjectClassHandle requesterClass;
  rti::AttributeHandle requesterAttribute;
  rti::InteractionClassHandle requesterInteraction;
  rti::ParameterHandle requesterParameter;
  handles(
      requester,
      options,
      requesterClass,
      requesterAttribute,
      requesterInteraction,
      requesterParameter);
  auto const ownerClass = owner.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const ownerAttribute = owner.rtiAmbassador().getAttributeHandle(
      ownerClass,
      options.attributeName);
  require(
      requesterClass.isValid() && requesterAttribute.isValid() && ownerClass.isValid() &&
          ownerAttribute.isValid(),
      "resign cancellation lookup returned an invalid handle");

  rti::AttributeHandleSet const requesterAttributes{requesterAttribute};
  rti::AttributeHandleSet const ownerAttributes{ownerAttribute};
  requester.rtiAmbassador().subscribeObjectClassAttributes(
      requesterClass,
      requesterAttributes,
      true,
      L"");
  owner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerAttributes);
  auto const object = owner.rtiAmbassador().registerObjectInstance(ownerClass);
  require(object.isValid(), "resign cancellation returned an invalid object handle");
  waitFor(
      requester,
      [&] { return requester.recorder().hasDiscovery(object); },
      options,
      "resign cancellation discovery");

  requester.rtiAmbassador().publishObjectClassAttributes(
      requesterClass,
      requesterAttributes);
  requester.recorder().clearOwnershipRecords();
  owner.recorder().clearOwnershipRecords();
  std::vector<std::uint8_t> const acquisitionTagBytes{0xd8U, 0x25U};
  rti::VariableLengthData const acquisitionTag(
      acquisitionTagBytes.data(),
      acquisitionTagBytes.size());
  requester.rtiAmbassador().attributeOwnershipAcquisition(
      object,
      requesterAttributes,
      acquisitionTag);
  require(
      owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerAttribute) &&
          !requester.rtiAmbassador().isAttributeOwnedByFederate(
              object,
              requesterAttribute),
      "pending acquisition changed ownership before resignation cancellation");

  // Clear any immediate callback before exercising the cancellation boundary. The
  // cancellation must prevent an evoked callback that was still queued, while an
  // immediate provider may already have delivered the request synchronously.
  owner.recorder().clearOwnershipRecords();
  requester.resign(rti::CANCEL_PENDING_OWNERSHIP_ACQUISITIONS);
  for (int pass = 0; pass != 8; ++pass) {
    owner.pump();
  }
  require(
      !owner.recorder().ownershipReleaseRequest().has_value(),
      "canceling pending acquisition delivered a stale owner-release callback");
  require(
      owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerAttribute),
      "canceling pending acquisition changed the current owner");

  owner.resign(rti::DELETE_OBJECTS);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  requester.disconnect();
  owner.disconnect();
}

void scenarioResignCancelPendingAcquisitionContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioResignCancelPendingAcquisition(options, model);
}

void scenarioResignCancelIfAvailablePending(
    Options const& options,
    rti::CallbackModel model) {
  Session owner(options, model, "resign-cancel-if-available-owner");
  Session requester(options, model, "resign-cancel-if-available-requester");
  auto const federation = federationName(
      options,
      "resign-cancel-if-available-pending");
  connectAndJoin(owner, requester, options, federation, options.fom);

  rti::ObjectClassHandle ownerClass;
  rti::AttributeHandle ownerAttribute;
  rti::InteractionClassHandle ownerInteraction;
  rti::ParameterHandle ownerParameter;
  handles(owner, options, ownerClass, ownerAttribute, ownerInteraction, ownerParameter);
  auto const requesterClass = requester.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const requesterAttribute = requester.rtiAmbassador().getAttributeHandle(
      requesterClass,
      options.attributeName);
  require(
      ownerClass.isValid() && ownerAttribute.isValid() && requesterClass.isValid() &&
          requesterAttribute.isValid(),
      "If Available resignation lookup returned an invalid handle");

  rti::AttributeHandleSet const ownerAttributes{ownerAttribute};
  rti::AttributeHandleSet const requesterAttributes{requesterAttribute};
  owner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerAttributes);
  requester.rtiAmbassador().subscribeObjectClassAttributes(
      requesterClass,
      requesterAttributes,
      true,
      L"");
  auto const object = owner.rtiAmbassador().registerObjectInstance(ownerClass);
  require(object.isValid(), "If Available resignation returned an invalid object handle");
  waitFor(
      requester,
      [&] { return requester.recorder().hasDiscovery(object); },
      options,
      "If Available resignation discovery");

  requester.rtiAmbassador().publishObjectClassAttributes(
      requesterClass,
      requesterAttributes);
  requester.recorder().clearOwnershipRecords();
  std::vector<std::uint8_t> const acquisitionTagBytes{0xe5U, 0x25U};
  rti::VariableLengthData const acquisitionTag(
      acquisitionTagBytes.data(),
      acquisitionTagBytes.size());
  requester.rtiAmbassador().attributeOwnershipAcquisitionIfAvailable(
      object,
      requesterAttributes,
      acquisitionTag);
  require(
      owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerAttribute) &&
          !requester.rtiAmbassador().isAttributeOwnedByFederate(
              object,
              requesterAttribute),
      "If Available acquisition changed ownership before resignation cancellation");

  // Immediate delivery may report the unavailable result before the request is
  // canceled. Clear that already-delivered record so the post-resignation pump
  // specifically checks for stale callback delivery.
  requester.recorder().clearOwnershipRecords();
  requester.resign(rti::CANCEL_PENDING_OWNERSHIP_ACQUISITIONS);
  for (int pass = 0; pass != 8; ++pass) {
    requester.pump();
  }
  require(
      !requester.recorder().ownershipUnavailable().has_value() &&
          !requester.recorder().ownershipAcquisition().has_value(),
      "canceling pending If Available acquisition delivered a stale callback");
  require(
      owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerAttribute),
      "canceling pending If Available acquisition changed the current owner");

  owner.resign(rti::DELETE_OBJECTS);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  requester.disconnect();
  owner.disconnect();
}

void scenarioResignCancelIfAvailablePendingContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioResignCancelIfAvailablePending(options, model);
}

void scenarioResignCancelNegotiatedPending(
    Options const& options,
    rti::CallbackModel model) {
  Session owner(options, model, "resign-cancel-negotiated-owner");
  Session requester(options, model, "resign-cancel-negotiated-requester");
  auto const federation = federationName(
      options,
      "resign-cancel-negotiated-pending");
  connectAndJoin(owner, requester, options, federation, options.fom);

  rti::ObjectClassHandle ownerClass;
  rti::AttributeHandle ownerAttribute;
  rti::InteractionClassHandle ownerInteraction;
  rti::ParameterHandle ownerParameter;
  handles(owner, options, ownerClass, ownerAttribute, ownerInteraction, ownerParameter);
  auto const requesterClass = requester.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const requesterAttribute = requester.rtiAmbassador().getAttributeHandle(
      requesterClass,
      options.attributeName);
  require(
      ownerClass.isValid() && ownerAttribute.isValid() && requesterClass.isValid() &&
          requesterAttribute.isValid(),
      "Negotiated resignation lookup returned an invalid handle");

  rti::AttributeHandleSet const ownerAttributes{ownerAttribute};
  rti::AttributeHandleSet const requesterAttributes{requesterAttribute};
  owner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerAttributes);
  requester.rtiAmbassador().publishObjectClassAttributes(
      requesterClass,
      requesterAttributes);
  requester.rtiAmbassador().subscribeObjectClassAttributes(
      requesterClass,
      requesterAttributes,
      true,
      L"");

  auto const object = owner.rtiAmbassador().registerObjectInstance(ownerClass);
  require(
      object.isValid(),
      "Negotiated resignation returned an invalid object handle");
  waitFor(
      requester,
      [&] { return requester.recorder().hasDiscovery(object); },
      options,
      "negotiated resignation discovery");

  owner.recorder().clearOwnershipRecords();
  requester.recorder().clearOwnershipRecords();
  std::vector<std::uint8_t> const acquisitionTagBytes{0xe6U, 0x25U};
  std::vector<std::uint8_t> const divestitureTagBytes{0xe7U, 0x25U};
  rti::VariableLengthData const acquisitionTag(
      acquisitionTagBytes.data(),
      acquisitionTagBytes.size());
  rti::VariableLengthData const divestitureTag(
      divestitureTagBytes.data(),
      divestitureTagBytes.size());

  requester.rtiAmbassador().attributeOwnershipAcquisition(
      object,
      requesterAttributes,
      acquisitionTag);
  owner.rtiAmbassador().negotiatedAttributeOwnershipDivestiture(
      object,
      ownerAttributes,
      divestitureTag);
  if (model == rti::HLA_EVOKED) {
    require(
        !owner.recorder().divestitureConfirmation().has_value() &&
            !owner.recorder().ownershipReleaseRequest().has_value(),
        "evoked negotiated resignation crossed the callback boundary before resignation");
  }
  require(
      owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerAttribute) &&
          !requester.rtiAmbassador().isAttributeOwnedByFederate(
              object,
              requesterAttribute),
      "negotiated resignation changed ownership before cancellation");

  // Immediate delivery may already have reported the negotiated request. Clear
  // that state so the post-resignation pump specifically checks for stale owner
  // callbacks after the requester has left the federation.
  owner.recorder().clearOwnershipRecords();
  requester.resign(rti::CANCEL_PENDING_OWNERSHIP_ACQUISITIONS);
  for (int pass = 0; pass != 8; ++pass) {
    owner.pump();
  }
  require(
      !owner.recorder().divestitureConfirmation().has_value() &&
          !owner.recorder().ownershipReleaseRequest().has_value(),
      "canceling pending negotiated acquisition delivered a stale owner callback");
  require(
      owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerAttribute),
      "canceling pending negotiated acquisition changed the current owner");

  owner.resign(rti::DELETE_OBJECTS);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  requester.disconnect();
  owner.disconnect();
}

void scenarioResignCancelNegotiatedPendingContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioResignCancelNegotiatedPending(options, model);
}

void scenarioOwnershipTransferRegionalUpdate(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.ddmFom.empty(),
      "Ownership transfer/update-region testing requires an adapter-supplied dimensional FOM");

  Session owner(options, model, "owner");
  Session newOwner(options, model, "member");
  Session receiver(options, model, "receiver");
  auto const federation = federationName(options, "ownership-transfer-regional-update");
  owner.connect();
  newOwner.connect();
  receiver.connect();
  owner.rtiAmbassador().createFederationExecution(
      federation,
      options.ddmFom.wstring(),
      options.logicalTimeImplementationName);
  owner.join(options.ownerFederateName, options.federateType, federation);
  newOwner.join(
      options.memberFederateName + L"-ownership-transfer",
      options.federateType,
      federation);
  receiver.join(
      options.memberFederateName + L"-ownership-receiver",
      options.federateType,
      federation);

  auto const ownerHandles = ddmHandles(owner, options);
  auto const newOwnerHandles = ddmHandles(newOwner, options);
  auto const receiverHandles = ddmHandles(receiver, options);
  verifyDdmClassDimensions(
      owner,
      options,
      ownerHandles,
      "ownership transfer/update-region");

  rti::AttributeHandleSet const ownerAttributes{ownerHandles.attribute};
  rti::AttributeHandleSet const newOwnerAttributes{newOwnerHandles.attribute};
  rti::AttributeHandleSet const receiverAttributes{receiverHandles.attribute};
  owner.rtiAmbassador().publishObjectClassAttributes(
      ownerHandles.objectClass,
      ownerAttributes);
  newOwner.rtiAmbassador().publishObjectClassAttributes(
      newOwnerHandles.objectClass,
      newOwnerAttributes);

  auto const ownerRegion = createDdmRegion(
      owner,
      ownerHandles,
      1UL,
      3UL,
      1UL,
      3UL);
  auto const newOwnerRegion = createDdmRegion(
      newOwner,
      newOwnerHandles,
      1UL,
      3UL,
      1UL,
      3UL);
  auto const receiverOwnerRegion = createDdmRegion(
      receiver,
      receiverHandles,
      1UL,
      3UL,
      1UL,
      3UL);
  auto const receiverReplacementRegion = createDdmRegion(
      receiver,
      receiverHandles,
      6UL,
      8UL,
      6UL,
      8UL);

  rti::AttributeHandleSetRegionHandleSetPairVector const ownerPair{{
      ownerAttributes,
      rti::RegionHandleSet{ownerRegion},
  }};
  rti::AttributeHandleSetRegionHandleSetPairVector const newOwnerPair{{
      newOwnerAttributes,
      rti::RegionHandleSet{newOwnerRegion},
  }};
  rti::AttributeHandleSetRegionHandleSetPairVector const receiverPair{{
      receiverAttributes,
      rti::RegionHandleSet{receiverOwnerRegion, receiverReplacementRegion},
  }};

  receiver.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  require(
      receiver.rtiAmbassador().getConveyRegionDesignatorSetsSwitch(),
      "ownership transfer receiver did not enable region designator callbacks");
  newOwner.rtiAmbassador().subscribeObjectClassAttributesWithRegions(
      newOwnerHandles.objectClass,
      newOwnerPair,
      true,
      L"");
  receiver.rtiAmbassador().subscribeObjectClassAttributesWithRegions(
      receiverHandles.objectClass,
      receiverPair,
      true,
      L"");

  auto const object = owner.rtiAmbassador().registerObjectInstanceWithRegions(
      ownerHandles.objectClass,
      ownerPair);
  require(
      object.isValid(),
      "ownership transfer/update-region registration returned an invalid object handle");
  waitForSessions(
      {&owner, &newOwner, &receiver},
      [&] {
        return newOwner.recorder().hasDiscovery(object) &&
            receiver.recorder().hasDiscovery(object);
      },
      options,
      "ownership transfer/update-region object discovery");

  std::vector<std::uint8_t> ownerValue{0x4FU, 0x4CUL, 0x44U, 0x25U};
  std::vector<std::uint8_t> defaultValue{0x44U, 0x45U, 0x46U, 0x25U};
  std::vector<std::uint8_t> replacementValue{0x4EU, 0x45U, 0x57U, 0x25U};
  std::vector<std::uint8_t> acquisitionTagBytes{0x41U, 0x43U, 0x51U, 0x25U};
  std::vector<std::uint8_t> divestitureTagBytes{0x44U, 0x49U, 0x56U, 0x25U};
  rti::VariableLengthData const acquisitionTag(
      acquisitionTagBytes.data(),
      acquisitionTagBytes.size());
  rti::VariableLengthData const divestitureTag(
      divestitureTagBytes.data(),
      divestitureTagBytes.size());

  rti::AttributeHandleValueMap ownerValues;
  ownerValues.emplace(
      ownerHandles.attribute,
      rti::VariableLengthData(ownerValue.data(), ownerValue.size()));
  owner.rtiAmbassador().updateAttributeValues(object, ownerValues, divestitureTag);
  waitFor(
      receiver,
      [&] { return receiver.recorder().reflection().present; },
      options,
      "ownership transfer/update-region initial reflection");
  auto const initialReflection = receiver.recorder().reflection();
  require(
      initialReflection.object == object &&
          initialReflection.values.size() == 1U &&
          initialReflection.values.count(receiverHandles.attribute) == 1U,
      "ownership transfer/update-region initial reflection returned the wrong attribute set");
  require(
      copyBytes(initialReflection.values.at(receiverHandles.attribute)) == ownerValue &&
          initialReflection.tag == divestitureTagBytes &&
          initialReflection.producer == owner.federateHandle() &&
          initialReflection.transportation.isValid(),
      "ownership transfer/update-region initial reflection lost message metadata");
  require(
      initialReflection.regions.has_value() &&
          initialReflection.regions->size() == 1U &&
          initialReflection.regions->count(ownerRegion) == 1U,
      "ownership transfer/update-region initial reflection lost the source region");

  newOwner.recorder().clearOwnershipRecords();
  rti::AttributeHandleSet divestedAttributes;
  newOwner.rtiAmbassador().attributeOwnershipAcquisitionIfAvailable(
      object,
      newOwnerAttributes,
      acquisitionTag);
  require(
      !newOwner.recorder().ownershipAcquisition().has_value(),
      "If Available acquisition completed before the current owner divested");
  owner.rtiAmbassador().attributeOwnershipDivestitureIfWanted(
      object,
      ownerAttributes,
      divestitureTag,
      divestedAttributes);
  require(
      divestedAttributes == ownerAttributes,
      "If Wanted divestiture returned the wrong attribute set");
  require(
      !owner.rtiAmbassador().isAttributeOwnedByFederate(object, ownerHandles.attribute) &&
          newOwner.rtiAmbassador().isAttributeOwnedByFederate(
              object,
              newOwnerHandles.attribute),
      "ownership transfer did not move the attribute to the pending acquirer");
  waitFor(
      newOwner,
      [&] { return newOwner.recorder().ownershipAcquisition().has_value(); },
      options,
      "ownership transfer/update-region acquisition notification");
  auto const acquisition = newOwner.recorder().ownershipAcquisition();
  require(
      acquisition->object == object &&
          acquisition->attributes == newOwnerAttributes &&
          acquisition->tag == divestitureTagBytes,
      "ownership transfer/update-region acquisition callback returned the wrong data");

  receiver.recorder().clearReflection();
  requireException(
      [&] {
        owner.rtiAmbassador().updateAttributeValues(object, ownerValues, divestitureTag);
      },
      L"AttributeNotOwned",
      "former owner update after ownership transfer");

  rti::AttributeHandleValueMap defaultValues;
  defaultValues.emplace(
      newOwnerHandles.attribute,
      rti::VariableLengthData(defaultValue.data(), defaultValue.size()));
  newOwner.rtiAmbassador().updateAttributeValues(object, defaultValues, divestitureTag);
  waitFor(
      receiver,
      [&] { return receiver.recorder().reflection().present; },
      options,
      "ownership transfer/update-region default-source reflection");
  auto const defaultReflection = receiver.recorder().reflection();
  require(
      defaultReflection.object == object &&
          defaultReflection.values.size() == 1U &&
          defaultReflection.values.count(receiverHandles.attribute) == 1U &&
          copyBytes(defaultReflection.values.at(receiverHandles.attribute)) == defaultValue,
      "ownership transfer/update-region default-source reflection returned the wrong value");
  require(
      defaultReflection.tag == divestitureTagBytes &&
          defaultReflection.producer == newOwner.federateHandle() &&
          defaultReflection.transportation.isValid(),
      "ownership transfer/update-region default-source reflection lost message metadata");
  require(
      !defaultReflection.regions.has_value() || defaultReflection.regions->empty(),
      "former owner's source region was incorrectly inherited by the new owner");

  receiver.recorder().clearReflection();
  newOwner.rtiAmbassador().setRangeBounds(
      newOwnerRegion,
      newOwnerHandles.firstDimension,
      rti::RangeBounds(6UL, 8UL));
  newOwner.rtiAmbassador().setRangeBounds(
      newOwnerRegion,
      newOwnerHandles.secondDimension,
      rti::RangeBounds(6UL, 8UL));
  newOwner.rtiAmbassador().commitRegionModifications(
      rti::RegionHandleSet{newOwnerRegion});
  newOwner.rtiAmbassador().associateRegionsForUpdates(object, newOwnerPair);
  rti::AttributeHandleValueMap replacementValues;
  replacementValues.emplace(
      newOwnerHandles.attribute,
      rti::VariableLengthData(replacementValue.data(), replacementValue.size()));
  newOwner.rtiAmbassador().updateAttributeValues(
      object,
      replacementValues,
      acquisitionTag);
  waitFor(
      receiver,
      [&] { return receiver.recorder().reflection().present; },
      options,
      "ownership transfer/update-region replacement reflection");
  auto const replacementReflection = receiver.recorder().reflection();
  require(
      replacementReflection.object == object &&
          replacementReflection.values.size() == 1U &&
          replacementReflection.values.count(receiverHandles.attribute) == 1U &&
          copyBytes(replacementReflection.values.at(receiverHandles.attribute)) ==
              replacementValue,
      "ownership transfer/update-region replacement reflection returned the wrong value");
  require(
      replacementReflection.tag == acquisitionTagBytes &&
          replacementReflection.producer == newOwner.federateHandle() &&
          replacementReflection.transportation.isValid(),
      "ownership transfer/update-region replacement reflection lost message metadata");
  require(
      replacementReflection.regions.has_value() &&
          replacementReflection.regions->size() == 1U &&
          replacementReflection.regions->count(newOwnerRegion) == 1U,
      "new owner replacement association did not supply its source region");

  receiver.rtiAmbassador().unsubscribeObjectClassAttributesWithRegions(
      receiverHandles.objectClass,
      receiverPair);
  newOwner.rtiAmbassador().unsubscribeObjectClassAttributesWithRegions(
      newOwnerHandles.objectClass,
      newOwnerPair);
  newOwner.rtiAmbassador().unassociateRegionsForUpdates(object, newOwnerPair);
  owner.rtiAmbassador().unpublishObjectClassAttributes(
      ownerHandles.objectClass,
      ownerAttributes);
  newOwner.rtiAmbassador().unpublishObjectClassAttributes(
      newOwnerHandles.objectClass,
      newOwnerAttributes);
  receiver.rtiAmbassador().deleteRegion(receiverOwnerRegion);
  receiver.rtiAmbassador().deleteRegion(receiverReplacementRegion);
  newOwner.rtiAmbassador().deleteRegion(newOwnerRegion);
  owner.rtiAmbassador().deleteRegion(ownerRegion);

  receiver.resign(rti::NO_ACTION);
  newOwner.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  owner.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  receiver.disconnect();
  newOwner.disconnect();
  owner.disconnect();
}

void scenarioRegionLifecycle(Options const& options, rti::CallbackModel model) {
  Session lifecycle(options, model, "region-lifecycle-boundary");
  rti::ObjectClassHandle const invalidRegionObjectClass;
  rti::InteractionClassHandle const invalidRegionInteractionClass;
  rti::ObjectInstanceHandle const invalidRegionObjectInstance;
  rti::DimensionHandle const invalidRegionDimension;
  rti::DimensionHandleSet const emptyDimensions;
  rti::RegionHandle const invalidRegion;
  rti::RegionHandleSet const emptyRegions;
  rti::AttributeHandleSetRegionHandleSetPairVector const emptyAttributeRegionPairs;
  rti::ParameterHandleValueMap const emptyRegionParameters;
  rti::VariableLengthData const emptyRegionTag;
  rti::RangeBounds const lifecycleRangeBounds(0UL, 1UL);
  auto checkRegionServiceLifecycle = [&](std::wstring const& expected,
                                          std::string const& phase) {
    requireException(
        [&] { static_cast<void>(lifecycle.rtiAmbassador().createRegion(emptyDimensions)); },
        expected,
        "region creation " + phase);
    requireException(
        [&] { lifecycle.rtiAmbassador().commitRegionModifications(emptyRegions); },
        expected,
        "region commit " + phase);
    requireException(
        [&] { lifecycle.rtiAmbassador().deleteRegion(invalidRegion); },
        expected,
        "region deletion " + phase);
    requireException(
        [&] {
          static_cast<void>(lifecycle.rtiAmbassador().registerObjectInstanceWithRegions(
              invalidRegionObjectClass,
              emptyAttributeRegionPairs));
        },
        expected,
        "region-qualified object registration " + phase);
    requireException(
        [&] {
          static_cast<void>(lifecycle.rtiAmbassador().registerObjectInstanceWithRegions(
              invalidRegionObjectClass,
              emptyAttributeRegionPairs,
              L"tck-region-lifecycle-object"));
        },
        expected,
        "named region-qualified object registration " + phase);
    requireException(
        [&] {
          lifecycle.rtiAmbassador().associateRegionsForUpdates(
              invalidRegionObjectInstance,
              emptyAttributeRegionPairs);
        },
        expected,
        "region association " + phase);
    requireException(
        [&] {
          lifecycle.rtiAmbassador().unassociateRegionsForUpdates(
              invalidRegionObjectInstance,
              emptyAttributeRegionPairs);
        },
        expected,
        "region unassociation " + phase);
    requireException(
        [&] {
          lifecycle.rtiAmbassador().subscribeObjectClassAttributesWithRegions(
              invalidRegionObjectClass,
              emptyAttributeRegionPairs,
              false,
              L"");
        },
        expected,
        "regional attribute subscription " + phase);
    requireException(
        [&] {
          lifecycle.rtiAmbassador().unsubscribeObjectClassAttributesWithRegions(
              invalidRegionObjectClass,
              emptyAttributeRegionPairs);
        },
        expected,
        "regional attribute unsubscription " + phase);
    requireException(
        [&] {
          lifecycle.rtiAmbassador().subscribeInteractionClassWithRegions(
              invalidRegionInteractionClass,
              emptyRegions,
              false);
        },
        expected,
        "regional interaction subscription " + phase);
    requireException(
        [&] {
          lifecycle.rtiAmbassador().unsubscribeInteractionClassWithRegions(
              invalidRegionInteractionClass,
              emptyRegions);
        },
        expected,
        "regional interaction unsubscription " + phase);
    requireException(
        [&] {
          lifecycle.rtiAmbassador().sendInteractionWithRegions(
              invalidRegionInteractionClass,
              emptyRegionParameters,
              emptyRegions,
              emptyRegionTag);
        },
        expected,
        "regional interaction send " + phase);
    requireException(
        [&] {
          lifecycle.rtiAmbassador().requestAttributeValueUpdateWithRegions(
              invalidRegionObjectClass,
              emptyAttributeRegionPairs,
              emptyRegionTag);
        },
        expected,
        "regional attribute update request " + phase);
    requireException(
        [&] {
          static_cast<void>(lifecycle.rtiAmbassador().getRangeBounds(
              invalidRegion,
              invalidRegionDimension));
        },
        expected,
        "range lookup " + phase);
    requireException(
        [&] {
          lifecycle.rtiAmbassador().setRangeBounds(
              invalidRegion,
              invalidRegionDimension,
              lifecycleRangeBounds);
        },
        expected,
        "range update " + phase);
    requireException(
        [&] {
          static_cast<void>(lifecycle.rtiAmbassador().decodeRegionHandle(
              rti::VariableLengthData{}));
        },
        expected,
        "region-handle decoding " + phase);
    requireException(
        [&] { static_cast<void>(lifecycle.rtiAmbassador().getDimensionHandleSet(invalidRegion)); },
        expected,
        "dimension lookup for a region " + phase);
  };
  checkRegionServiceLifecycle(L"NotConnected", "before connect");
  lifecycle.connect();
  checkRegionServiceLifecycle(L"FederateNotExecutionMember", "before joining an execution");
  lifecycle.disconnect();

  Session owner(options, model, "owner");
  Session member(options, model, "member");
  auto const federation = federationName(options, "region-lifecycle");
  connectAndJoin(owner, member, options, federation, options.ddmFom);

  auto lifecycleTime = makeTimeContext(owner);
  requireException(
      [&] {
        static_cast<void>(lifecycle.rtiAmbassador().sendInteractionWithRegions(
            invalidRegionInteractionClass,
            emptyRegionParameters,
            emptyRegions,
            emptyRegionTag,
            *lifecycleTime.initial));
      },
      L"NotConnected",
      "timestamped regional interaction send before connect");
  lifecycle.connect();
  requireException(
      [&] {
        static_cast<void>(lifecycle.rtiAmbassador().sendInteractionWithRegions(
            invalidRegionInteractionClass,
            emptyRegionParameters,
            emptyRegions,
            emptyRegionTag,
            *lifecycleTime.initial));
      },
      L"FederateNotExecutionMember",
      "timestamped regional interaction send before joining an execution");
  lifecycle.disconnect();

  auto const ownerHandles = ddmHandles(owner, options);
  auto const memberHandles = ddmHandles(member, options);
  verifyDdmClassDimensions(owner, options, ownerHandles, "region lifecycle");
  verifyDdmClassDimensions(member, options, memberHandles, "region lifecycle member");
  require(
      owner.rtiAmbassador().getDimensionUpperBound(ownerHandles.firstDimension) ==
              member.rtiAmbassador().getDimensionUpperBound(memberHandles.firstDimension) &&
          owner.rtiAmbassador().getDimensionUpperBound(ownerHandles.secondDimension) ==
              member.rtiAmbassador().getDimensionUpperBound(memberHandles.secondDimension),
      "region lifecycle members reported different dimension upper bounds");

  auto const ownerRegion = createDdmRegion(owner, ownerHandles, 1UL, 5UL, 2UL, 7UL);
  auto const memberRegion = createDdmRegion(member, memberHandles, 1UL, 5UL, 2UL, 7UL);
  verifyDdmRegion(
      owner,
      ownerHandles,
      ownerRegion,
      1UL,
      5UL,
      2UL,
      7UL,
      "owner region metadata");
  verifyDdmRegion(
      member,
      memberHandles,
      memberRegion,
      1UL,
      5UL,
      2UL,
      7UL,
      "member region metadata");

  owner.rtiAmbassador().setRangeBounds(
      ownerRegion,
      ownerHandles.firstDimension,
      rti::RangeBounds(0UL, 4UL));
  owner.rtiAmbassador().commitRegionModifications(rti::RegionHandleSet{ownerRegion});
  verifyDdmRegion(
      owner,
      ownerHandles,
      ownerRegion,
      0UL,
      4UL,
      2UL,
      7UL,
      "committed region modification");

  auto const oneDimensionRegion = owner.rtiAmbassador().createRegion(
      rti::DimensionHandleSet{ownerHandles.firstDimension});
  require(oneDimensionRegion.isValid(), "one-dimensional DDM region creation failed");
  requireException(
      [&] {
        static_cast<void>(owner.rtiAmbassador().getRangeBounds(
            oneDimensionRegion, ownerHandles.secondDimension));
      },
      L"RegionDoesNotContainSpecifiedDimension",
      "range lookup for a dimension absent from a region");
  requireException(
      [&] {
        owner.rtiAmbassador().setRangeBounds(
            oneDimensionRegion,
            ownerHandles.secondDimension,
            rti::RangeBounds(0UL, 1UL));
      },
      L"RegionDoesNotContainSpecifiedDimension",
      "range update for a dimension absent from a region");
  owner.rtiAmbassador().deleteRegion(oneDimensionRegion);

  requireException(
      [&] {
        owner.rtiAmbassador().setRangeBounds(
            ownerRegion,
            ownerHandles.firstDimension,
            rti::RangeBounds(4UL, 4UL));
      },
      L"InvalidRangeBound",
      "region range with equal lower and upper bounds");
  requireException(
      [&] {
        owner.rtiAmbassador().setRangeBounds(
            ownerRegion,
            ownerHandles.secondDimension,
            rti::RangeBounds(0UL, owner.rtiAmbassador().getDimensionUpperBound(
                ownerHandles.secondDimension) + 1UL));
      },
      L"InvalidRangeBound",
      "region range beyond the dimension upper bound");

  owner.rtiAmbassador().deleteRegion(ownerRegion);
  member.rtiAmbassador().deleteRegion(memberRegion);
  requireException(
      [&] { static_cast<void>(owner.rtiAmbassador().getDimensionHandleSet(ownerRegion)); },
      L"InvalidRegion",
      "dimension lookup after region deletion");

  owner.resign(rti::NO_ACTION);
  member.resign(rti::NO_ACTION);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  owner.disconnect();
  member.disconnect();
}

void scenarioRegionLifecycleContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioRegionLifecycle(options, model);
}

void scenarioRegionalUnpublishRegionRelease(Options const& options, rti::CallbackModel model) {
  require(!options.ddmFom.empty(),
          "regional unpublish region release requires an adapter-supplied dimensional FOM");

  Session owner(options, model, "regional-unpublish-owner");
  auto const federation = federationName(options, "regional-unpublish-region-release");
  owner.connect();
  owner.rtiAmbassador().createFederationExecution(
      federation,
      options.ddmFom.wstring(),
      options.logicalTimeImplementationName);
  owner.join(options.ownerFederateName, options.federateType, federation);

  auto const handles = ddmHandles(owner, options);
  verifyDdmClassDimensions(owner, options, handles, "regional unpublish region release");

  rti::AttributeHandleSet const attributes{handles.attribute};
  owner.rtiAmbassador().publishObjectClassAttributes(
      handles.objectClass,
      attributes);

  auto const region = createDdmRegion(owner, handles, 1UL, 5UL, 1UL, 5UL);
  rti::AttributeHandleSetRegionHandleSetPairVector const attributeRegions{{
      attributes,
      rti::RegionHandleSet{region},
  }};
  auto const object = owner.rtiAmbassador().registerObjectInstanceWithRegions(
      handles.objectClass,
      attributeRegions);
  require(object.isValid(),
          "regional unpublish region release returned an invalid object handle");

  requireException(
      [&] { owner.rtiAmbassador().deleteRegion(region); },
      L"RegionInUseForUpdateOrSubscription",
      "deletion of a region used by an object update association");

  owner.rtiAmbassador().unpublishObjectClassAttributes(
      handles.objectClass,
      attributes);
  owner.rtiAmbassador().deleteRegion(region);
  requireException(
      [&] { static_cast<void>(owner.rtiAmbassador().getDimensionHandleSet(region)); },
      L"InvalidRegion",
      "dimension lookup after unpublishing releases the region");

  owner.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  owner.disconnect();
}

void scenarioRegionalUnpublishRegionReleaseContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioRegionalUnpublishRegionRelease(options, model);
}

void scenarioRegionalObjectUpdate(Options const& options, rti::CallbackModel model) {
  Session owner(options, model, "owner");
  Session overlap(options, model, "member");
  Session disjoint(options, model, "passive");
  auto const federation = federationName(options, "regional-object-update");
  connectAndJoin(owner, overlap, options, federation, options.ddmFom);
  disjoint.connect();
  disjoint.join(
      options.memberFederateName + L"-regional-disjoint",
      options.federateType,
      federation);

  auto const ownerHandles = ddmHandles(owner, options);
  auto const overlapHandles = ddmHandles(overlap, options);
  auto const disjointHandles = ddmHandles(disjoint, options);
  verifyDdmClassDimensions(owner, options, ownerHandles, "regional object update");

  rti::AttributeHandleSet const ownerAttributes{ownerHandles.attribute};
  rti::AttributeHandleSet const overlapAttributes{overlapHandles.attribute};
  rti::AttributeHandleSet const disjointAttributes{disjointHandles.attribute};
  owner.rtiAmbassador().publishObjectClassAttributes(
      ownerHandles.objectClass, ownerAttributes);

  auto const sourceRegion = createDdmRegion(owner, ownerHandles, 1UL, 5UL, 1UL, 5UL);
  auto const disjointSourceRegion =
      createDdmRegion(owner, ownerHandles, 7UL, 9UL, 7UL, 9UL);
  auto const overlapRegion =
      createDdmRegion(overlap, overlapHandles, 2UL, 6UL, 2UL, 6UL);
  auto const disjointRegion =
      createDdmRegion(disjoint, disjointHandles, 7UL, 9UL, 7UL, 9UL);

  rti::AttributeHandleSetRegionHandleSetPairVector const sourcePair{{
      ownerAttributes,
      rti::RegionHandleSet{sourceRegion},
  }};
  rti::AttributeHandleSetRegionHandleSetPairVector const disjointSourcePair{{
      ownerAttributes,
      rti::RegionHandleSet{disjointSourceRegion},
  }};
  rti::AttributeHandleSetRegionHandleSetPairVector const overlapPair{{
      overlapAttributes,
      rti::RegionHandleSet{overlapRegion},
  }};
  rti::AttributeHandleSetRegionHandleSetPairVector const disjointPair{{
      disjointAttributes,
      rti::RegionHandleSet{disjointRegion},
  }};

  overlap.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  disjoint.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  require(overlap.rtiAmbassador().getConveyRegionDesignatorSetsSwitch(),
          "overlap receiver did not enable region designator callbacks");
  require(disjoint.rtiAmbassador().getConveyRegionDesignatorSetsSwitch(),
          "disjoint receiver did not enable region designator callbacks");
  auto verifyTransportation = [&](Session& receiver,
                                  rti::TransportationTypeHandle const& transportation,
                                  std::string const& description) {
    require(transportation.isValid(), description + " returned an invalid transportation handle");
    if (options.requireCustomTransportation) {
      require(
          receiver.rtiAmbassador().getTransportationTypeName(transportation) ==
              options.fomCustomTransportationName,
          description + " changed the adapter-declared custom transport");
    }
  };
  overlap.rtiAmbassador().subscribeObjectClassAttributesWithRegions(
      overlapHandles.objectClass, overlapPair, true, L"");
  disjoint.rtiAmbassador().subscribeObjectClassAttributesWithRegions(
      disjointHandles.objectClass, disjointPair, true, L"");

  auto const objectName = federation + L"-regional-object";
  owner.rtiAmbassador().reserveObjectInstanceName(objectName);
  waitFor(
      owner,
      [&] { return owner.recorder().reservationSucceeded(objectName); },
      options,
      "regional named object reservation");
  auto const object = owner.rtiAmbassador().registerObjectInstanceWithRegions(
      ownerHandles.objectClass,
      sourcePair,
      objectName);
  require(object.isValid(), "regional object registration returned an invalid handle");
  waitFor(
      overlap,
      [&] { return overlap.recorder().hasDiscovery(object); },
      options,
      "regional overlapping object discovery");
  for (int pass = 0; pass != 8; ++pass) {
    disjoint.pump();
  }
  require(!disjoint.recorder().hasDiscovery(object),
          "disjoint regional subscription discovered the object");

  std::vector<std::uint8_t> firstValue{0x11U, 0x22U, 0x33U};
  std::vector<std::uint8_t> firstTag{0x52U, 0x31U};
  rti::AttributeHandleValueMap firstValues;
  firstValues.emplace(
      ownerHandles.attribute,
      rti::VariableLengthData(firstValue.data(), firstValue.size()));
  rti::VariableLengthData firstUserTag(firstTag.data(), firstTag.size());
  owner.rtiAmbassador().updateAttributeValues(object, firstValues, firstUserTag);
  waitFor(
      overlap,
      [&] { return overlap.recorder().reflection().present; },
      options,
      "regional ordinary attribute reflection");
  auto const firstReflection = overlap.recorder().reflection();
  require(firstReflection.object == object &&
              firstReflection.values.size() == 1U &&
              firstReflection.values.count(overlapHandles.attribute) == 1U,
          "regional reflection returned the wrong object or attribute set");
  require(copyBytes(firstReflection.values.at(overlapHandles.attribute)) == firstValue,
          "regional reflection returned the wrong attribute value");
  require(firstReflection.tag == firstTag &&
              firstReflection.producer == owner.federateHandle() &&
              firstReflection.transportation.isValid(),
          "regional reflection did not preserve ordinary metadata");
  verifyTransportation(overlap, firstReflection.transportation, "regional reflection");
  require(firstReflection.regions.has_value() &&
              firstReflection.regions->size() == 1U &&
              firstReflection.regions->count(sourceRegion) == 1U,
          "regional reflection did not convey the source region designator set");
  for (int pass = 0; pass != 8; ++pass) {
    disjoint.pump();
  }
  require(!disjoint.recorder().discovery().present &&
              !disjoint.recorder().reflection().present,
          "disjoint regional subscription received the initial update");

  std::vector<std::uint8_t> requestTagBytes{0x52U, 0x51U};
  rti::VariableLengthData requestTag(requestTagBytes.data(), requestTagBytes.size());
  overlap.recorder().clearReflection();
  owner.recorder().clearProvidedUpdates();
  overlap.rtiAmbassador().requestAttributeValueUpdateWithRegions(
      overlapHandles.objectClass,
      overlapPair,
      requestTag);
  waitFor(
      owner,
      [&] {
        auto const requests = owner.recorder().providedUpdates();
        return !requests.empty() && requests.back().object == object &&
            requests.back().attributes == ownerAttributes &&
            requests.back().tag == requestTagBytes;
      },
      options,
      "regional attribute-value request callback");
  auto const requests = owner.recorder().providedUpdates();
  require(requests.back().object == object &&
              requests.back().attributes == ownerAttributes &&
              requests.back().tag == requestTagBytes,
          "regional attribute-value request returned the wrong callback data");
  std::vector<std::uint8_t> responseValue{0x44U, 0x55U, 0x66U};
  std::vector<std::uint8_t> responseTag{0x52U, 0x53U};
  rti::AttributeHandleValueMap responseValues;
  responseValues.emplace(
      ownerHandles.attribute,
      rti::VariableLengthData(responseValue.data(), responseValue.size()));
  rti::VariableLengthData responseUserTag(responseTag.data(), responseTag.size());
  owner.rtiAmbassador().updateAttributeValues(object, responseValues, responseUserTag);
  waitFor(
      overlap,
      [&] { return overlap.recorder().reflection().present; },
      options,
      "regional attribute-value response reflection");
  auto const responseReflection = overlap.recorder().reflection();
  require(copyBytes(responseReflection.values.at(overlapHandles.attribute)) == responseValue &&
              responseReflection.tag == responseTag,
          "regional attribute-value response did not preserve data");
  verifyTransportation(
      overlap,
      responseReflection.transportation,
      "regional attribute-value response reflection");

  owner.rtiAmbassador().associateRegionsForUpdates(object, disjointSourcePair);
  owner.rtiAmbassador().unassociateRegionsForUpdates(object, sourcePair);
  waitFor(
      disjoint,
      [&] { return disjoint.recorder().hasDiscovery(object); },
      options,
      "regional disjoint object discovery after association");
  overlap.recorder().clearReflection();
  disjoint.recorder().clearReflection();
  std::vector<std::uint8_t> disjointValue{0x77U, 0x88U};
  rti::AttributeHandleValueMap disjointValues;
  disjointValues.emplace(
      ownerHandles.attribute,
      rti::VariableLengthData(disjointValue.data(), disjointValue.size()));
  owner.rtiAmbassador().updateAttributeValues(object, disjointValues, responseUserTag);
  waitFor(
      disjoint,
      [&] { return disjoint.recorder().reflection().present; },
      options,
      "regional associated attribute reflection");
  auto const associatedReflection = disjoint.recorder().reflection();
  require(copyBytes(associatedReflection.values.at(disjointHandles.attribute)) ==
              disjointValue,
          "associated regional reflection returned the wrong value");
  verifyTransportation(
      disjoint,
      associatedReflection.transportation,
      "associated regional reflection");
  for (int pass = 0; pass != 8; ++pass) {
    overlap.pump();
  }
  require(!overlap.recorder().reflection().present,
          "overlap receiver received an update after source-region reassociation");

  owner.rtiAmbassador().unassociateRegionsForUpdates(object, disjointSourcePair);
  overlap.rtiAmbassador().unsubscribeObjectClassAttributesWithRegions(
      overlapHandles.objectClass, overlapPair);
  disjoint.rtiAmbassador().unsubscribeObjectClassAttributesWithRegions(
      disjointHandles.objectClass, disjointPair);
  owner.rtiAmbassador().unpublishObjectClassAttributes(
      ownerHandles.objectClass, ownerAttributes);
  owner.rtiAmbassador().deleteRegion(sourceRegion);
  owner.rtiAmbassador().deleteRegion(disjointSourceRegion);
  overlap.rtiAmbassador().deleteRegion(overlapRegion);
  disjoint.rtiAmbassador().deleteRegion(disjointRegion);

  owner.resign(rti::DELETE_OBJECTS);
  overlap.resign(rti::NO_ACTION);
  disjoint.resign(rti::NO_ACTION);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  owner.disconnect();
  overlap.disconnect();
  disjoint.disconnect();
}

void scenarioRegionalObjectUpdateContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioRegionalObjectUpdate(options, model);
}

void scenarioRegionalAttributeValueUpdateResponseRecheck(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.ddmFom.empty(),
      "Regional attribute-value response recheck requires an adapter-supplied dimensional FOM");

  Session owner(options, model, "owner");
  Session requester(options, model, "member");
  auto const federation = federationName(
      options,
      "regional-attribute-value-update-response-recheck");
  connectAndJoin(owner, requester, options, federation, options.ddmFom);

  auto const ownerHandles = ddmHandles(owner, options);
  auto const requesterHandles = ddmHandles(requester, options);
  verifyDdmClassDimensions(
      owner,
      options,
      ownerHandles,
      "regional attribute-value response recheck");

  rti::AttributeHandleSet const ownerAttributes{ownerHandles.attribute};
  rti::AttributeHandleSet const requesterAttributes{requesterHandles.attribute};
  owner.rtiAmbassador().publishObjectClassAttributes(
      ownerHandles.objectClass,
      ownerAttributes);

  auto const ownerRegion = createDdmRegion(
      owner,
      ownerHandles,
      0UL,
      1UL,
      0UL,
      1UL);
  auto const requesterRegion = createDdmRegion(
      requester,
      requesterHandles,
      0UL,
      1UL,
      0UL,
      1UL);
  rti::AttributeHandleSetRegionHandleSetPairVector const ownerPair{{
      ownerAttributes,
      rti::RegionHandleSet{ownerRegion},
  }};
  rti::AttributeHandleSetRegionHandleSetPairVector const requesterPair{{
      requesterAttributes,
      rti::RegionHandleSet{requesterRegion},
  }};

  requester.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  requester.rtiAmbassador().subscribeObjectClassAttributesWithRegions(
      requesterHandles.objectClass,
      requesterPair,
      true,
      L"");
  auto const object = owner.rtiAmbassador().registerObjectInstanceWithRegions(
      ownerHandles.objectClass,
      ownerPair);
  require(
      object.isValid(),
      "regional attribute-value response registration returned an invalid object handle");
  waitFor(
      requester,
      [&] { return requester.recorder().hasDiscovery(object); },
      options,
      "regional attribute-value response discovery");

  std::vector<std::uint8_t> const requestTagBytes{0x52U, 0x45U, 0x51U};
  std::vector<std::uint8_t> const responseValueBytes{0x5AU, 0x25U, 0x07U};
  std::vector<std::uint8_t> const responseTagBytes{0x52U, 0x45U, 0x53U};
  rti::VariableLengthData const requestTag(
      requestTagBytes.data(),
      requestTagBytes.size());
  rti::VariableLengthData const responseTag(
      responseTagBytes.data(),
      responseTagBytes.size());
  rti::AttributeHandleValueMap responseValues;
  responseValues.emplace(
      ownerHandles.attribute,
      rti::VariableLengthData(
          responseValueBytes.data(),
          responseValueBytes.size()));

  owner.recorder().clearProvidedUpdates();
  requester.recorder().clearReflection();
  requester.rtiAmbassador().requestAttributeValueUpdateWithRegions(
      requesterHandles.objectClass,
      requesterPair,
      requestTag);
  waitFor(
      owner,
      [&] { return owner.recorder().providedUpdates().size() == 1U; },
      options,
      "regional attribute-value response provider callback");
  auto const requests = owner.recorder().providedUpdates();
  require(
      requests.front().object == object &&
          requests.front().attributes == ownerAttributes &&
          requests.front().tag == requestTagBytes,
      "regional attribute-value response provider callback returned the wrong metadata");

  // The response is sent after the requester moves its committed region out of
  // overlap. Reflection delivery must re-check the current DDM eligibility.
  requester.rtiAmbassador().setRangeBounds(
      requesterRegion,
      requesterHandles.firstDimension,
      rti::RangeBounds(2UL, 3UL));
  requester.rtiAmbassador().setRangeBounds(
      requesterRegion,
      requesterHandles.secondDimension,
      rti::RangeBounds(2UL, 3UL));
  requester.rtiAmbassador().commitRegionModifications(
      rti::RegionHandleSet{requesterRegion});
  owner.rtiAmbassador().updateAttributeValues(
      object,
      responseValues,
      responseTag);
  for (int pass = 0; pass != 8; ++pass) {
    requester.pump();
  }
  require(
      requester.recorder().reflectionCount() == 0U,
      "regional attribute-value response was reflected after overlap was removed");

  // Restore overlap and prove that a fresh request/response is delivered with
  // the ordinary value, tag, transport, and producer metadata intact.
  requester.rtiAmbassador().setRangeBounds(
      requesterRegion,
      requesterHandles.firstDimension,
      rti::RangeBounds(0UL, 1UL));
  requester.rtiAmbassador().setRangeBounds(
      requesterRegion,
      requesterHandles.secondDimension,
      rti::RangeBounds(0UL, 1UL));
  requester.rtiAmbassador().commitRegionModifications(
      rti::RegionHandleSet{requesterRegion});
  owner.recorder().clearProvidedUpdates();
  requester.recorder().clearReflection();
  requester.rtiAmbassador().requestAttributeValueUpdateWithRegions(
      requesterHandles.objectClass,
      requesterPair,
      requestTag);
  waitFor(
      owner,
      [&] { return owner.recorder().providedUpdates().size() == 1U; },
      options,
      "regional attribute-value response restoration callback");
  owner.rtiAmbassador().updateAttributeValues(
      object,
      responseValues,
      responseTag);
  waitFor(
      requester,
      [&] { return requester.recorder().reflection().present; },
      options,
      "regional attribute-value response restoration reflection");
  auto const reflection = requester.recorder().reflection();
  require(
      reflection.object == object &&
          reflection.values.size() == 1U &&
          reflection.values.count(requesterHandles.attribute) == 1U &&
          copyBytes(reflection.values.at(requesterHandles.attribute)) ==
              responseValueBytes &&
          reflection.tag == responseTagBytes,
      "regional attribute-value response restoration returned the wrong value or tag");
  require(
      reflection.transportation ==
              requester.rtiAmbassador().getTransportationTypeHandle(L"HLAreliable") &&
          reflection.producer == owner.federateHandle(),
      "regional attribute-value response restoration returned the wrong delivery metadata");

  requester.rtiAmbassador().unsubscribeObjectClassAttributesWithRegions(
      requesterHandles.objectClass,
      requesterPair);
  owner.rtiAmbassador().unassociateRegionsForUpdates(object, ownerPair);
  owner.rtiAmbassador().unpublishObjectClassAttributes(
      ownerHandles.objectClass,
      ownerAttributes);
  requester.rtiAmbassador().deleteRegion(requesterRegion);
  owner.rtiAmbassador().deleteRegion(ownerRegion);
  requester.resign(rti::NO_ACTION);
  owner.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  requester.disconnect();
  owner.disconnect();
}

void scenarioRegionalAttributeValueRequestFiltering(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.ddmFom.empty(),
      "Regional attribute-value request filtering requires an adapter-supplied dimensional FOM");

  Session owner(options, model, "owner");
  Session requester(options, model, "member");
  auto const federation = federationName(
      options,
      "regional-attribute-value-request-filtering");
  connectAndJoin(owner, requester, options, federation, options.ddmFom);

  auto const ownerHandles = ddmHandles(owner, options);
  auto const requesterHandles = ddmHandles(requester, options);
  verifyDdmClassDimensions(
      owner,
      options,
      ownerHandles,
      "regional attribute-value request filtering");

  rti::AttributeHandleSet const ownerAttributes{ownerHandles.attribute};
  rti::AttributeHandleSet const requesterAttributes{requesterHandles.attribute};
  owner.rtiAmbassador().publishObjectClassAttributes(
      ownerHandles.objectClass,
      ownerAttributes);

  auto const ownerRegion = createDdmRegion(
      owner,
      ownerHandles,
      0UL,
      1UL,
      0UL,
      1UL);
  auto const requestRegion = createDdmRegion(
      requester,
      requesterHandles,
      2UL,
      3UL,
      2UL,
      3UL);

  // A committed region with only one of the object's dimensions is valid as
  // a region, but is invalid as a request region for this object class.
  auto const wrongContextRegion = requester.rtiAmbassador().createRegion(
      rti::DimensionHandleSet{requesterHandles.firstDimension});
  require(
      wrongContextRegion.isValid(),
      "incompatible request region creation returned an invalid handle");
  requester.rtiAmbassador().setRangeBounds(
      wrongContextRegion,
      requesterHandles.firstDimension,
      rti::RangeBounds(0UL, 1UL));
  requester.rtiAmbassador().commitRegionModifications(
      rti::RegionHandleSet{wrongContextRegion});

  // Leave both required ranges unset so the service must reject the region
  // before attempting to solicit any provider callbacks.
  auto const uncommittedRegion = requester.rtiAmbassador().createRegion(
      rti::DimensionHandleSet{
          requesterHandles.firstDimension,
          requesterHandles.secondDimension});
  require(
      uncommittedRegion.isValid(),
      "uncommitted request region creation returned an invalid handle");

  rti::AttributeHandleSetRegionHandleSetPairVector const ownerPair{{
      ownerAttributes,
      rti::RegionHandleSet{ownerRegion},
  }};
  rti::AttributeHandleSetRegionHandleSetPairVector const disjointRequestPair{{
      requesterAttributes,
      rti::RegionHandleSet{requestRegion},
  }};
  rti::AttributeHandleSetRegionHandleSetPairVector const emptyRequestPair{{
      requesterAttributes,
      rti::RegionHandleSet{},
  }};
  rti::AttributeHandleSetRegionHandleSetPairVector const foreignRequestPair{{
      requesterAttributes,
      rti::RegionHandleSet{ownerRegion},
  }};
  rti::AttributeHandleSetRegionHandleSetPairVector const wrongContextRequestPair{{
      requesterAttributes,
      rti::RegionHandleSet{wrongContextRegion},
  }};
  rti::AttributeHandleSetRegionHandleSetPairVector const uncommittedRequestPair{{
      requesterAttributes,
      rti::RegionHandleSet{uncommittedRegion},
  }};

  auto const regionalObject = owner.rtiAmbassador().registerObjectInstanceWithRegions(
      ownerHandles.objectClass,
      ownerPair);
  auto const defaultObject = owner.rtiAmbassador().registerObjectInstance(
      ownerHandles.objectClass);
  require(
      regionalObject.isValid() && defaultObject.isValid(),
      "regional request filtering registration returned an invalid object handle");

  std::vector<std::uint8_t> const requestTagBytes{0x91U, 0x25U};
  rti::VariableLengthData const requestTag(
      requestTagBytes.data(),
      requestTagBytes.size());
  requireException(
      [&] {
        requester.rtiAmbassador().requestAttributeValueUpdateWithRegions(
            requesterHandles.objectClass,
            foreignRequestPair,
            requestTag);
      },
      L"RegionNotCreatedByThisFederate",
      "regional value request with a foreign region");
  requireException(
      [&] {
        requester.rtiAmbassador().requestAttributeValueUpdateWithRegions(
            requesterHandles.objectClass,
            wrongContextRequestPair,
            requestTag);
      },
      L"InvalidRegionContext",
      "regional value request with an incompatible region context");
  requireException(
      [&] {
        requester.rtiAmbassador().requestAttributeValueUpdateWithRegions(
            requesterHandles.objectClass,
            uncommittedRequestPair,
            requestTag);
      },
      L"InvalidRegion",
      "regional value request with an uncommitted region");

  owner.recorder().clearProvidedUpdates();
  requester.rtiAmbassador().requestAttributeValueUpdateWithRegions(
      requesterHandles.objectClass,
      emptyRequestPair,
      requestTag);
  for (int pass = 0; pass != 8; ++pass) {
    owner.pump();
  }
  require(
      owner.recorder().providedUpdates().empty(),
      "an empty regional request set generated a provider callback");

  // The explicit [0,1) association is disjoint from [2,3), but the ordinary
  // default-region object remains eligible for a regional request.
  requester.rtiAmbassador().requestAttributeValueUpdateWithRegions(
      requesterHandles.objectClass,
      disjointRequestPair,
      requestTag);
  waitFor(
      owner,
      [&] { return owner.recorder().providedUpdates().size() >= 1U; },
      options,
      "disjoint regional value request callback");
  auto const disjointRequests = owner.recorder().providedUpdates();
  require(
      disjointRequests.size() == 1U &&
          disjointRequests.front().object == defaultObject &&
          disjointRequests.front().attributes == ownerAttributes &&
          disjointRequests.front().tag == requestTagBytes,
      "disjoint regional value request did not retain the default-region object");

  // Recommitting the requester region into the source range makes both the
  // explicit and default-region objects eligible.
  requester.rtiAmbassador().setRangeBounds(
      requestRegion,
      requesterHandles.firstDimension,
      rti::RangeBounds(0UL, 1UL));
  requester.rtiAmbassador().setRangeBounds(
      requestRegion,
      requesterHandles.secondDimension,
      rti::RangeBounds(0UL, 1UL));
  requester.rtiAmbassador().commitRegionModifications(
      rti::RegionHandleSet{requestRegion});
  requester.rtiAmbassador().requestAttributeValueUpdateWithRegions(
      requesterHandles.objectClass,
      disjointRequestPair,
      requestTag);
  waitFor(
      owner,
      [&] { return owner.recorder().providedUpdates().size() >= 3U; },
      options,
      "overlapping regional value request callbacks");
  auto const overlappingRequests = owner.recorder().providedUpdates();
  require(
      overlappingRequests.size() == 3U,
      "overlapping regional value request returned an unexpected callback count");
  bool sawRegionalObject = false;
  bool sawDefaultObject = false;
  for (auto const& request : overlappingRequests) {
    require(
        request.attributes == ownerAttributes && request.tag == requestTagBytes,
        "regional value request callback did not preserve attributes or tag");
    sawRegionalObject = sawRegionalObject || request.object == regionalObject;
    sawDefaultObject = sawDefaultObject || request.object == defaultObject;
  }
  require(
      sawRegionalObject && sawDefaultObject,
      "overlapping regional value request omitted a source object");

  if (model == rti::HLA_EVOKED) {
    // An evoked provider must re-evaluate the request region when the
    // provideAttributeValueUpdate callback is actually delivered.
    requester.rtiAmbassador().requestAttributeValueUpdateWithRegions(
        requesterHandles.objectClass,
        disjointRequestPair,
        requestTag);
    requester.rtiAmbassador().setRangeBounds(
        requestRegion,
        requesterHandles.firstDimension,
        rti::RangeBounds(2UL, 3UL));
    requester.rtiAmbassador().setRangeBounds(
        requestRegion,
        requesterHandles.secondDimension,
        rti::RangeBounds(2UL, 3UL));
    requester.rtiAmbassador().commitRegionModifications(
        rti::RegionHandleSet{requestRegion});
    waitFor(
        owner,
        [&] { return owner.recorder().providedUpdates().size() >= 4U; },
        options,
        "evoked regional value request re-evaluation");
    auto const reevaluatedRequests = owner.recorder().providedUpdates();
    require(
        reevaluatedRequests.size() == 4U &&
            reevaluatedRequests.back().object == defaultObject,
        "evoked regional value request did not suppress the moved explicit source");
  } else {
    // Immediate delivery completes before the request region is moved, so a
    // later region commit must not replay the already-delivered callbacks.
    requester.rtiAmbassador().requestAttributeValueUpdateWithRegions(
        requesterHandles.objectClass,
        disjointRequestPair,
        requestTag);
    waitFor(
        owner,
        [&] { return owner.recorder().providedUpdates().size() >= 5U; },
        options,
        "immediate regional value request callbacks");
    requester.rtiAmbassador().setRangeBounds(
        requestRegion,
        requesterHandles.firstDimension,
        rti::RangeBounds(2UL, 3UL));
    requester.rtiAmbassador().setRangeBounds(
        requestRegion,
        requesterHandles.secondDimension,
        rti::RangeBounds(2UL, 3UL));
    requester.rtiAmbassador().commitRegionModifications(
        rti::RegionHandleSet{requestRegion});
    owner.pump();
    require(
        owner.recorder().providedUpdates().size() == 5U,
        "immediate regional value request was replayed after region movement");
  }

  owner.rtiAmbassador().unassociateRegionsForUpdates(regionalObject, ownerPair);
  owner.rtiAmbassador().unpublishObjectClassAttributes(
      ownerHandles.objectClass,
      ownerAttributes);
  owner.rtiAmbassador().deleteRegion(ownerRegion);
  requester.rtiAmbassador().deleteRegion(wrongContextRegion);
  requester.rtiAmbassador().deleteRegion(uncommittedRegion);
  requester.rtiAmbassador().deleteRegion(requestRegion);

  requester.resign(rti::NO_ACTION);
  owner.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  owner.disconnect();
  requester.disconnect();
}

void scenarioRegionalAttributeValueRequestFilteringContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioRegionalAttributeValueRequestFiltering(options, model);
}

void scenarioDefaultRegionObjectRouting(
    Options const& options,
    rti::CallbackModel model) {
  require(!options.ddmFom.empty(),
          "Default-region object routing requires an adapter-supplied dimensional FOM");

  Session publisher(options, model, "owner");
  Session regional(options, model, "member");
  Session mixed(options, model, "passive");
  auto const federation = federationName(options, "default-region-object-routing");
  connectAndJoin(publisher, regional, options, federation, options.ddmFom);
  mixed.connect();
  mixed.join(
      options.memberFederateName + L"-default-region-mixed",
      options.federateType,
      federation);

  auto const publisherHandles = ddmHandles(publisher, options);
  auto const regionalHandles = ddmHandles(regional, options);
  auto const mixedHandles = ddmHandles(mixed, options);
  verifyDdmClassDimensions(
      publisher,
      options,
      publisherHandles,
      "default-region object routing");

  rti::AttributeHandleSet const publisherAttributes{publisherHandles.attribute};
  rti::AttributeHandleSet const regionalAttributes{regionalHandles.attribute};
  rti::AttributeHandleSet const mixedAttributes{mixedHandles.attribute};
  publisher.rtiAmbassador().publishObjectClassAttributes(
      publisherHandles.objectClass,
      publisherAttributes);

  auto const sourceRegion = createDdmRegion(
      publisher,
      publisherHandles,
      1UL,
      5UL,
      1UL,
      5UL);
  auto const regionalRegion = createDdmRegion(
      regional,
      regionalHandles,
      2UL,
      6UL,
      2UL,
      6UL);
  auto const mixedRegion = createDdmRegion(
      mixed,
      mixedHandles,
      7UL,
      9UL,
      7UL,
      9UL);

  rti::AttributeHandleSetRegionHandleSetPairVector const sourcePair{{
      publisherAttributes,
      rti::RegionHandleSet{sourceRegion},
  }};
  rti::AttributeHandleSetRegionHandleSetPairVector const regionalPair{{
      regionalAttributes,
      rti::RegionHandleSet{regionalRegion},
  }};
  rti::AttributeHandleSetRegionHandleSetPairVector const mixedPair{{
      mixedAttributes,
      rti::RegionHandleSet{mixedRegion},
  }};

  regional.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  mixed.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  require(
      regional.rtiAmbassador().getConveyRegionDesignatorSetsSwitch() &&
          mixed.rtiAmbassador().getConveyRegionDesignatorSetsSwitch(),
      "default-region receivers did not enable region designator callbacks");
  regional.rtiAmbassador().subscribeObjectClassAttributesWithRegions(
      regionalHandles.objectClass,
      regionalPair,
      true,
      L"");
  mixed.rtiAmbassador().subscribeObjectClassAttributes(
      mixedHandles.objectClass,
      mixedAttributes,
      true);
  mixed.rtiAmbassador().subscribeObjectClassAttributesWithRegions(
      mixedHandles.objectClass,
      mixedPair,
      true,
      L"");

  auto const object = publisher.rtiAmbassador().registerObjectInstanceWithRegions(
      publisherHandles.objectClass,
      sourcePair);
  require(object.isValid(),
          "default-region object registration returned an invalid handle");
  waitFor(
      regional,
      [&] { return regional.recorder().hasDiscovery(object); },
      options,
      "default-region overlapping object discovery");
  for (int pass = 0; pass != 8; ++pass) {
    mixed.pump();
  }
  require(
      !mixed.recorder().hasDiscovery(object),
      "disjoint explicit subscription used the retained ordinary default region");

  // Removing the explicit declaration exposes the retained ordinary
  // declaration, which uses the derived default source region again.
  mixed.rtiAmbassador().unsubscribeObjectClassAttributesWithRegions(
      mixedHandles.objectClass,
      mixedPair);
  mixed.rtiAmbassador().subscribeObjectClassAttributes(
      mixedHandles.objectClass,
      mixedAttributes,
      true);
  waitFor(
      mixed,
      [&] { return mixed.recorder().hasDiscovery(object); },
      options,
      "default-region ordinary object discovery");
  require(
      mixed.recorder().discoveryCount() == 1U,
      "default-region ordinary discovery returned an unexpected callback count");

  // Restore the disjoint explicit declaration, then remove the publisher's
  // only explicit association. Both regional subscriptions should now match
  // the invisible default source region.
  mixed.rtiAmbassador().subscribeObjectClassAttributesWithRegions(
      mixedHandles.objectClass,
      mixedPair,
      true,
      L"");
  publisher.rtiAmbassador().unassociateRegionsForUpdates(object, sourcePair);
  regional.recorder().clearReflection();
  mixed.recorder().clearReflection();

  std::vector<std::uint8_t> defaultValue{0xD0U, 0x01U};
  std::vector<std::uint8_t> defaultTag{0x44U, 0x31U};
  rti::AttributeHandleValueMap defaultValues;
  defaultValues.emplace(
      publisherHandles.attribute,
      rti::VariableLengthData(defaultValue.data(), defaultValue.size()));
  rti::VariableLengthData defaultUserTag(defaultTag.data(), defaultTag.size());
  publisher.rtiAmbassador().updateAttributeValues(
      object,
      defaultValues,
      defaultUserTag);
  waitFor(
      regional,
      mixed,
      [&] {
        return regional.recorder().reflectionCount() >= 1U &&
            mixed.recorder().reflectionCount() >= 1U;
      },
      options,
      "default-region ordinary attribute reflection");

  auto const regionalDefault = regional.recorder().reflection();
  auto const mixedDefault = mixed.recorder().reflection();
  require(
      regionalDefault.object == object &&
          regionalDefault.values.size() == 1U &&
          regionalDefault.values.count(regionalHandles.attribute) == 1U &&
          copyBytes(regionalDefault.values.at(regionalHandles.attribute)) == defaultValue &&
          regionalDefault.tag == defaultTag &&
          regionalDefault.producer == publisher.federateHandle() &&
          regionalDefault.transportation.isValid() &&
          regionalDefault.regions.has_value() &&
          regionalDefault.regions->empty(),
      "regional default-source reflection did not preserve value metadata");
  require(
      mixedDefault.object == object &&
          mixedDefault.values.size() == 1U &&
          mixedDefault.values.count(mixedHandles.attribute) == 1U &&
          copyBytes(mixedDefault.values.at(mixedHandles.attribute)) == defaultValue &&
          mixedDefault.tag == defaultTag &&
          mixedDefault.producer == publisher.federateHandle() &&
          mixedDefault.transportation.isValid() &&
          mixedDefault.regions.has_value() &&
          mixedDefault.regions->empty(),
      "mixed default-source reflection did not preserve value metadata");

  // An explicit association replaces the default source for this attribute.
  // Only the overlapping regional subscriber should receive this update.
  publisher.rtiAmbassador().associateRegionsForUpdates(object, sourcePair);
  std::vector<std::uint8_t> explicitValue{0xE0U, 0x02U};
  std::vector<std::uint8_t> explicitTag{0x44U, 0x32U};
  rti::AttributeHandleValueMap explicitValues;
  explicitValues.emplace(
      publisherHandles.attribute,
      rti::VariableLengthData(explicitValue.data(), explicitValue.size()));
  rti::VariableLengthData explicitUserTag(explicitTag.data(), explicitTag.size());
  publisher.rtiAmbassador().updateAttributeValues(
      object,
      explicitValues,
      explicitUserTag);
  waitFor(
      regional,
      [&] { return regional.recorder().reflectionCount() >= 2U; },
      options,
      "explicit-source regional attribute reflection");
  for (int pass = 0; pass != 8; ++pass) {
    mixed.pump();
  }
  auto const regionalExplicit = regional.recorder().reflection();
  require(
      regionalExplicit.object == object &&
          regionalExplicit.values.size() == 1U &&
          regionalExplicit.values.count(regionalHandles.attribute) == 1U &&
          copyBytes(regionalExplicit.values.at(regionalHandles.attribute)) == explicitValue &&
          regionalExplicit.tag == explicitTag &&
          regionalExplicit.producer == publisher.federateHandle() &&
          regionalExplicit.transportation.isValid() &&
          regionalExplicit.regions.has_value() &&
          regionalExplicit.regions->size() == 1U &&
          regionalExplicit.regions->count(sourceRegion) == 1U,
      "explicit-source reflection did not preserve the source region designator");
  require(
      mixed.recorder().reflectionCount() == 1U,
      "disjoint explicit subscription received an explicit-source update");

  // Removing the association restores default-source fanout and the
  // supplied-empty callback projection.
  publisher.rtiAmbassador().unassociateRegionsForUpdates(object, sourcePair);
  std::vector<std::uint8_t> restoredValue{0xD0U, 0x03U};
  std::vector<std::uint8_t> restoredTag{0x44U, 0x33U};
  rti::AttributeHandleValueMap restoredValues;
  restoredValues.emplace(
      publisherHandles.attribute,
      rti::VariableLengthData(restoredValue.data(), restoredValue.size()));
  rti::VariableLengthData restoredUserTag(restoredTag.data(), restoredTag.size());
  publisher.rtiAmbassador().updateAttributeValues(
      object,
      restoredValues,
      restoredUserTag);
  waitFor(
      regional,
      mixed,
      [&] {
        return regional.recorder().reflectionCount() >= 3U &&
            mixed.recorder().reflectionCount() >= 2U;
      },
      options,
      "restored default-region attribute reflection");
  auto const regionalRestored = regional.recorder().reflection();
  auto const mixedRestored = mixed.recorder().reflection();
  require(
      regionalRestored.object == object &&
          copyBytes(regionalRestored.values.at(regionalHandles.attribute)) == restoredValue &&
          regionalRestored.tag == restoredTag &&
          regionalRestored.regions.has_value() &&
          regionalRestored.regions->empty(),
      "regional restored default-source reflection was not projected correctly");
  require(
      mixedRestored.object == object &&
          copyBytes(mixedRestored.values.at(mixedHandles.attribute)) == restoredValue &&
          mixedRestored.tag == restoredTag &&
          mixedRestored.regions.has_value() &&
          mixedRestored.regions->empty(),
      "mixed restored default-source reflection was not projected correctly");

  mixed.rtiAmbassador().unsubscribeObjectClassAttributesWithRegions(
      mixedHandles.objectClass,
      mixedPair);
  mixed.rtiAmbassador().unsubscribeObjectClassAttributes(
      mixedHandles.objectClass,
      mixedAttributes);
  regional.rtiAmbassador().unsubscribeObjectClassAttributesWithRegions(
      regionalHandles.objectClass,
      regionalPair);
  publisher.rtiAmbassador().unpublishObjectClassAttributes(
      publisherHandles.objectClass,
      publisherAttributes);
  publisher.rtiAmbassador().deleteRegion(sourceRegion);
  regional.rtiAmbassador().deleteRegion(regionalRegion);
  mixed.rtiAmbassador().deleteRegion(mixedRegion);

  publisher.resign(rti::DELETE_OBJECTS);
  regional.resign(rti::NO_ACTION);
  mixed.resign(rti::NO_ACTION);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  publisher.disconnect();
  regional.disconnect();
  mixed.disconnect();
}

void scenarioAutoProvide(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.autoProvideFom.empty(),
      "Auto Provide testing requires an adapter-supplied Auto Provide FOM");
  Session owner(options, model, "owner");
  Session requester(options, model, "requester");
  auto const federation = federationName(options, "auto-provide");
  connectAndJoin(owner, requester, options, federation, options.autoProvideFom);

  auto const ownerClass = owner.rtiAmbassador().getObjectClassHandle(
      options.autoProvideObjectClassName);
  auto const requesterClass = requester.rtiAmbassador().getObjectClassHandle(
      options.autoProvideObjectClassName);
  auto const ownerFirst = owner.rtiAmbassador().getAttributeHandle(
      ownerClass, options.autoProvideFirstAttributeName);
  auto const ownerSecond = owner.rtiAmbassador().getAttributeHandle(
      ownerClass, options.autoProvideSecondAttributeName);
  auto const requesterFirst = requester.rtiAmbassador().getAttributeHandle(
      requesterClass, options.autoProvideFirstAttributeName);
  auto const requesterSecond = requester.rtiAmbassador().getAttributeHandle(
      requesterClass, options.autoProvideSecondAttributeName);
  require(
      ownerClass.isValid() && requesterClass.isValid() && ownerFirst.isValid() &&
          ownerSecond.isValid() && requesterFirst.isValid() && requesterSecond.isValid(),
      "Auto Provide handle lookup returned an invalid handle");
  require(
      owner.rtiAmbassador().getAutoProvideSwitch() &&
          requester.rtiAmbassador().getAutoProvideSwitch(),
      "Auto Provide FOM did not enable the standard Auto Provide switch");

  rti::AttributeHandleSet ownerAttributes{ownerFirst, ownerSecond};
  rti::AttributeHandleSet requesterAttributes{requesterFirst, requesterSecond};
  owner.rtiAmbassador().publishObjectClassAttributes(ownerClass, ownerAttributes);
  requester.rtiAmbassador().subscribeObjectClassAttributes(
      requesterClass, requesterAttributes, true, L"");
  auto const object = owner.rtiAmbassador().registerObjectInstance(ownerClass);
  require(object.isValid(), "Auto Provide registration returned an invalid object handle");

  waitFor(
      owner,
      requester,
      [&] {
        return owner.recorder().providedUpdates().size() >= 1U &&
            requester.recorder().discovery().present;
      },
      options,
      "Auto Provide discovery and solicitation");
  auto const providedUpdates = owner.recorder().providedUpdates();
  require(
      providedUpdates.size() == 1U,
      "Auto Provide solicited more than one provider callback");
  auto const& provided = providedUpdates.front();
  require(
      provided.object == object && provided.attributes == ownerAttributes &&
          provided.tag.empty(),
      "Auto Provide callback returned the wrong object, attributes, or tag");
  auto const discovery = requester.recorder().discovery();
  require(
      discovery.object == object && discovery.objectClass == requesterClass,
      "Auto Provide discovery returned the wrong object or object class");

  requester.rtiAmbassador().unsubscribeObjectClassAttributes(
      requesterClass, requesterAttributes);
  requester.resign(rti::NO_ACTION);
  owner.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  requester.disconnect();
  owner.disconnect();
}

void scenarioPassiveRegionalSubscription(
    Options const& options,
    rti::CallbackModel model) {
  require(!options.ddmFom.empty(),
          "Passive regional subscription requires an adapter-supplied dimensional FOM");

  Session publisher(options, model, "owner");
  Session subscriber(options, model, "member");
  auto const federation = federationName(options, "passive-regional-subscription");
  connectAndJoin(publisher, subscriber, options, federation, options.ddmFom);

  auto const publisherHandles = ddmHandles(publisher, options);
  auto const subscriberHandles = ddmHandles(subscriber, options);
  verifyDdmClassDimensions(
      publisher,
      options,
      publisherHandles,
      "passive regional subscription");

  rti::AttributeHandleSet const publisherAttributes{publisherHandles.attribute};
  rti::AttributeHandleSet const subscriberAttributes{subscriberHandles.attribute};
  publisher.rtiAmbassador().publishObjectClassAttributes(
      publisherHandles.objectClass,
      publisherAttributes);

  auto const sourceRegion = createDdmRegion(
      publisher,
      publisherHandles,
      1UL,
      5UL,
      1UL,
      5UL);
  auto const subscriberRegion = createDdmRegion(
      subscriber,
      subscriberHandles,
      2UL,
      6UL,
      2UL,
      6UL);
  rti::AttributeHandleSetRegionHandleSetPairVector const sourcePair{{
      publisherAttributes,
      rti::RegionHandleSet{sourceRegion},
  }};
  rti::AttributeHandleSetRegionHandleSetPairVector const subscriberPair{{
      subscriberAttributes,
      rti::RegionHandleSet{subscriberRegion},
  }};

  subscriber.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  require(
      subscriber.rtiAmbassador().getConveyRegionDesignatorSetsSwitch(),
      "passive regional subscriber did not enable region designator callbacks");
  subscriber.rtiAmbassador().subscribeObjectClassAttributesWithRegions(
      subscriberHandles.objectClass,
      subscriberPair,
      false,
      L"");

  auto const object = publisher.rtiAmbassador().registerObjectInstanceWithRegions(
      publisherHandles.objectClass,
      sourcePair);
  require(object.isValid(),
          "passive regional registration returned an invalid object handle");
  for (int pass = 0; pass != 8; ++pass) {
    subscriber.pump();
  }
  require(
      !subscriber.recorder().hasDiscovery(object) &&
          subscriber.recorder().reflectionCount() == 0U,
      "passive regional subscription arranged discovery or reflection");
  requireException(
      [&] {
        static_cast<void>(
            subscriber.rtiAmbassador().getKnownObjectClassHandle(object));
      },
      L"ObjectInstanceNotKnown",
      "known-object lookup for a passively subscribed regional object");

  std::vector<std::uint8_t> passiveValue{0x50U, 0x60U};
  rti::AttributeHandleValueMap passiveValues;
  passiveValues.emplace(
      publisherHandles.attribute,
      rti::VariableLengthData(passiveValue.data(), passiveValue.size()));
  publisher.rtiAmbassador().updateAttributeValues(
      object,
      passiveValues,
      rti::VariableLengthData{});
  for (int pass = 0; pass != 8; ++pass) {
    subscriber.pump();
  }
  require(
      subscriber.recorder().reflectionCount() == 0U,
      "passive regional subscription received an attribute update");

  // Replacing the same regional declaration with an active one makes the
  // already-registered, in-scope object discoverable.
  subscriber.rtiAmbassador().subscribeObjectClassAttributesWithRegions(
      subscriberHandles.objectClass,
      subscriberPair,
      true,
      L"");
  waitFor(
      subscriber,
      [&] { return subscriber.recorder().hasDiscovery(object); },
      options,
      "active regional discovery after passive declaration");
  auto const discovery = subscriber.recorder().discovery();
  require(
      discovery.object == object &&
          discovery.objectClass == subscriberHandles.objectClass &&
          discovery.producer == publisher.federateHandle(),
      "active regional discovery returned the wrong object metadata");

  std::vector<std::uint8_t> activeValue{0x70U, 0x80U};
  std::vector<std::uint8_t> activeTag{0x50U, 0x52U};
  rti::AttributeHandleValueMap activeValues;
  activeValues.emplace(
      publisherHandles.attribute,
      rti::VariableLengthData(activeValue.data(), activeValue.size()));
  rti::VariableLengthData activeUserTag(activeTag.data(), activeTag.size());
  publisher.rtiAmbassador().updateAttributeValues(
      object,
      activeValues,
      activeUserTag);
  waitFor(
      subscriber,
      [&] { return subscriber.recorder().reflectionCount() >= 1U; },
      options,
      "active regional reflection after passive declaration");
  auto const reflection = subscriber.recorder().reflection();
  require(
      reflection.object == object &&
          reflection.values.size() == 1U &&
          reflection.values.count(subscriberHandles.attribute) == 1U &&
          copyBytes(reflection.values.at(subscriberHandles.attribute)) == activeValue &&
          reflection.tag == activeTag &&
          reflection.producer == publisher.federateHandle() &&
          reflection.transportation.isValid() &&
          reflection.regions.has_value() &&
          reflection.regions->size() == 1U &&
          reflection.regions->count(sourceRegion) == 1U,
      "active regional reflection did not preserve source-region metadata");

  subscriber.rtiAmbassador().unsubscribeObjectClassAttributesWithRegions(
      subscriberHandles.objectClass,
      subscriberPair);
  publisher.rtiAmbassador().unassociateRegionsForUpdates(object, sourcePair);
  publisher.rtiAmbassador().unpublishObjectClassAttributes(
      publisherHandles.objectClass,
      publisherAttributes);
  publisher.rtiAmbassador().deleteRegion(sourceRegion);
  subscriber.rtiAmbassador().deleteRegion(subscriberRegion);

  publisher.resign(rti::DELETE_OBJECTS);
  subscriber.resign(rti::NO_ACTION);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  publisher.disconnect();
  subscriber.disconnect();
}

void scenarioAttributeScopeAdvisories(
    Options const& options,
    rti::CallbackModel model) {
  Session owner(options, model, "owner");
  Session member(options, model, "member");
  auto const federation = federationName(options, "attribute-scope-advisories");
  connectAndJoin(owner, member, options, federation, options.ddmFom);

  auto const ownerHandles = ddmHandles(owner, options);
  auto const memberHandles = ddmHandles(member, options);
  verifyDdmClassDimensions(owner, options, ownerHandles, "attribute scope advisories");
  verifyDdmClassDimensions(member, options, memberHandles, "attribute scope advisories member");

  rti::AttributeHandleSet const ownerAttributes{ownerHandles.attribute};
  rti::AttributeHandleSet const memberAttributes{memberHandles.attribute};
  owner.rtiAmbassador().publishObjectClassAttributes(
      ownerHandles.objectClass, ownerAttributes);

  auto const sourceRegion = createDdmRegion(owner, ownerHandles, 1UL, 5UL, 1UL, 5UL);
  auto const alternateSourceRegion =
      createDdmRegion(owner, ownerHandles, 7UL, 9UL, 7UL, 9UL);
  auto const memberRegion = createDdmRegion(member, memberHandles, 2UL, 6UL, 2UL, 6UL);

  rti::AttributeHandleSetRegionHandleSetPairVector const sourcePair{{
      ownerAttributes,
      rti::RegionHandleSet{sourceRegion},
  }};
  rti::AttributeHandleSetRegionHandleSetPairVector const alternateSourcePair{{
      ownerAttributes,
      rti::RegionHandleSet{alternateSourceRegion},
  }};
  rti::AttributeHandleSetRegionHandleSetPairVector const memberPair{{
      memberAttributes,
      rti::RegionHandleSet{memberRegion},
  }};

  member.rtiAmbassador().setAttributeScopeAdvisorySwitch(false);
  require(!member.rtiAmbassador().getAttributeScopeAdvisorySwitch(),
          "attribute scope advisory switch did not turn off");
  member.rtiAmbassador().setAttributeScopeAdvisorySwitch(true);
  require(member.rtiAmbassador().getAttributeScopeAdvisorySwitch(),
          "attribute scope advisory switch did not turn on");
  member.rtiAmbassador().subscribeObjectClassAttributesWithRegions(
      memberHandles.objectClass, memberPair, true, L"");

  auto const object = owner.rtiAmbassador().registerObjectInstanceWithRegions(
      ownerHandles.objectClass, sourcePair);
  require(object.isValid(), "attribute scope advisory registration returned an invalid object");
  waitFor(member,
          [&] { return member.recorder().hasDiscovery(object); },
          options,
          "attribute scope advisory discovery");

  auto drainMember = [&] {
    if (model == rti::HLA_EVOKED) {
      while (member.evokeMultipleCallbacks(0.0, 0.0)) {
      }
    }
  };
  auto requireSingleScopeReport = [&](std::vector<ScopeAdvisoryRecord> const& reports,
                                      std::string const& description) {
    require(reports.size() == 1U, description + " returned an unexpected callback count");
    require(reports.front().object == object &&
                reports.front().attributes == memberAttributes,
            description + " returned the wrong object or attributes");
  };

  // Registration may establish the initial in-scope state. Drain and clear
  // that initial state so the transitions below each have one explicit cause.
  drainMember();
  member.recorder().clearScopeAdvisories();

  // Moving the registered object's source region out of overlap produces one
  // grouped Out Of Scope callback for the subscribed attribute.
  owner.rtiAmbassador().associateRegionsForUpdates(object, alternateSourcePair);
  owner.rtiAmbassador().unassociateRegionsForUpdates(object, sourcePair);
  waitFor(member,
          [&] { return !member.recorder().attributesOutOfScope().empty(); },
          options,
          "attribute out-of-scope advisory");
  requireSingleScopeReport(
      member.recorder().attributesOutOfScope(),
      "attribute out-of-scope advisory");
  require(member.recorder().attributesInScope().empty(),
          "source-region reassociation also produced an unexpected in-scope advisory");
  member.recorder().clearScopeAdvisories();

  // Restoring source-region overlap produces the inverse transition.
  owner.rtiAmbassador().associateRegionsForUpdates(object, sourcePair);
  owner.rtiAmbassador().unassociateRegionsForUpdates(object, alternateSourcePair);
  waitFor(member,
          [&] { return !member.recorder().attributesInScope().empty(); },
          options,
          "attribute in-scope advisory");
  requireSingleScopeReport(member.recorder().attributesInScope(),
                           "attribute in-scope advisory");
  require(member.recorder().attributesOutOfScope().empty(),
          "source-region reassociation also produced an unexpected out-of-scope advisory");
  member.recorder().clearScopeAdvisories();

  // Removing and restoring the regional subscription are independently
  // observable scope transitions for an already-known object.
  member.rtiAmbassador().unsubscribeObjectClassAttributesWithRegions(
      memberHandles.objectClass, memberPair);
  waitFor(member,
          [&] { return !member.recorder().attributesOutOfScope().empty(); },
          options,
          "regional subscription out-of-scope advisory");
  requireSingleScopeReport(member.recorder().attributesOutOfScope(),
                           "regional subscription out-of-scope advisory");
  member.recorder().clearScopeAdvisories();
  member.rtiAmbassador().subscribeObjectClassAttributesWithRegions(
      memberHandles.objectClass, memberPair, true, L"");
  waitFor(member,
          [&] { return !member.recorder().attributesInScope().empty(); },
          options,
          "regional subscription in-scope advisory");
  requireSingleScopeReport(member.recorder().attributesInScope(),
                           "regional subscription in-scope advisory");
  member.recorder().clearScopeAdvisories();
  member.rtiAmbassador().unsubscribeObjectClassAttributesWithRegions(
      memberHandles.objectClass, memberPair);
  waitFor(member,
          [&] { return !member.recorder().attributesOutOfScope().empty(); },
          options,
          "second regional subscription out-of-scope advisory");
  requireSingleScopeReport(member.recorder().attributesOutOfScope(),
                           "second regional subscription out-of-scope advisory");
  member.recorder().clearScopeAdvisories();

  // The per-federate switch suppresses both directions. Re-enabling it makes
  // a fresh subscription transition observable again.
  member.rtiAmbassador().setAttributeScopeAdvisorySwitch(false);
  require(!member.rtiAmbassador().getAttributeScopeAdvisorySwitch(),
          "attribute scope advisory switch did not remain disabled");
  member.rtiAmbassador().subscribeObjectClassAttributesWithRegions(
      memberHandles.objectClass, memberPair, true, L"");
  drainMember();
  require(member.recorder().attributesInScope().empty() &&
              member.recorder().attributesOutOfScope().empty(),
          "disabled attribute scope advisory switch did not suppress an in-scope transition");
  member.rtiAmbassador().unsubscribeObjectClassAttributesWithRegions(
      memberHandles.objectClass, memberPair);
  drainMember();
  require(member.recorder().attributesInScope().empty() &&
              member.recorder().attributesOutOfScope().empty(),
          "disabled attribute scope advisory switch did not suppress an out-of-scope transition");
  member.rtiAmbassador().setAttributeScopeAdvisorySwitch(true);
  require(member.rtiAmbassador().getAttributeScopeAdvisorySwitch(),
          "attribute scope advisory switch did not restore its enabled state");
  member.rtiAmbassador().subscribeObjectClassAttributesWithRegions(
      memberHandles.objectClass, memberPair, true, L"");

  // In evoked mode, make the queued In callback stale before servicing it.
  // The current committed region is then disjoint, so only the valid Out
  // transition may be delivered. Immediate mode observes both synchronously.
  if (model == rti::HLA_IMMEDIATE) {
    requireSingleScopeReport(member.recorder().attributesInScope(),
                             "re-enabled regional subscription in-scope advisory");
    member.recorder().clearScopeAdvisories();
  }
  member.rtiAmbassador().setRangeBounds(
      memberRegion,
      memberHandles.firstDimension,
      rti::RangeBounds(7UL, 9UL));
  member.rtiAmbassador().setRangeBounds(
      memberRegion,
      memberHandles.secondDimension,
      rti::RangeBounds(7UL, 9UL));
  member.rtiAmbassador().commitRegionModifications(rti::RegionHandleSet{memberRegion});
  waitFor(member,
          [&] { return !member.recorder().attributesOutOfScope().empty(); },
          options,
          "region-change out-of-scope advisory");
  requireSingleScopeReport(member.recorder().attributesOutOfScope(),
                           "region-change out-of-scope advisory");
  if (model == rti::HLA_EVOKED) {
    require(member.recorder().attributesInScope().empty(),
            "evoked delivery did not suppress the stale in-scope advisory");
  }

  member.rtiAmbassador().unsubscribeObjectClassAttributesWithRegions(
      memberHandles.objectClass, memberPair);
  owner.rtiAmbassador().unassociateRegionsForUpdates(object, sourcePair);
  owner.rtiAmbassador().unpublishObjectClassAttributes(
      ownerHandles.objectClass, ownerAttributes);
  owner.rtiAmbassador().deleteRegion(sourceRegion);
  owner.rtiAmbassador().deleteRegion(alternateSourceRegion);
  member.rtiAmbassador().deleteRegion(memberRegion);

  owner.resign(rti::DELETE_OBJECTS);
  member.resign(rti::NO_ACTION);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  owner.disconnect();
  member.disconnect();
}

void scenarioRegionalDeclarationRelevanceAdvisories(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.ddmFom.empty(),
      "Regional declaration-relevance testing requires an adapter-supplied DDM FOM");

  Session publisher(options, model, "regional-relevance-publisher");
  Session subscriber(options, model, "regional-relevance-subscriber");
  auto const federation = federationName(options, "regional-declaration-relevance");
  connectAndJoin(publisher, subscriber, options, federation, options.ddmFom);

  auto const publisherHandles = ddmHandles(publisher, options);
  auto const subscriberHandles = ddmHandles(subscriber, options);
  verifyDdmClassDimensions(
      publisher,
      options,
      publisherHandles,
      "regional declaration-relevance publisher");
  verifyDdmClassDimensions(
      subscriber,
      options,
      subscriberHandles,
      "regional declaration-relevance subscriber");

  publisher.rtiAmbassador().setObjectClassRelevanceAdvisorySwitch(true);
  publisher.rtiAmbassador().setInteractionRelevanceAdvisorySwitch(true);
  require(
      publisher.rtiAmbassador().getObjectClassRelevanceAdvisorySwitch() &&
          publisher.rtiAmbassador().getInteractionRelevanceAdvisorySwitch(),
      "regional declaration-relevance advisory switches did not enable");
  publisher.rtiAmbassador().publishObjectClassAttributes(
      publisherHandles.objectClass,
      rti::AttributeHandleSet{publisherHandles.attribute});
  publisher.rtiAmbassador().publishInteractionClass(
      publisherHandles.interactionClass);

  auto const objectRegion = createDdmRegion(
      subscriber,
      subscriberHandles,
      0UL,
      2UL,
      0UL,
      2UL);
  rti::AttributeHandleSetRegionHandleSetPairVector const objectSubscription{{
      rti::AttributeHandleSet{subscriberHandles.attribute},
      rti::RegionHandleSet{objectRegion},
  }};

  publisher.recorder().clearAdvisories();
  subscriber.rtiAmbassador().subscribeObjectClassAttributesWithRegions(
      subscriberHandles.objectClass,
      objectSubscription,
      false);
  require(
      publisher.recorder().registrationStarts().empty(),
      "passive regional object subscription changed registration relevance");

  subscriber.rtiAmbassador().subscribeObjectClassAttributesWithRegions(
      subscriberHandles.objectClass,
      objectSubscription,
      true);
  waitFor(
      publisher,
      [&] { return publisher.recorder().registrationStarts().size() >= 1U; },
      options,
      "regional object start-registration advisory");
  require(
      publisher.recorder().registrationStarts().size() == 1U &&
          publisher.recorder().registrationStarts().front() ==
              publisherHandles.objectClass,
      "active regional object subscription returned the wrong start-registration advisory");

  subscriber.rtiAmbassador().unsubscribeObjectClassAttributesWithRegions(
      subscriberHandles.objectClass,
      objectSubscription);
  waitFor(
      publisher,
      [&] { return publisher.recorder().registrationStops().size() >= 1U; },
      options,
      "regional object stop-registration advisory");
  require(
      publisher.recorder().registrationStops().size() == 1U &&
          publisher.recorder().registrationStops().front() ==
              publisherHandles.objectClass,
      "regional object unsubscription returned the wrong stop-registration advisory");

  publisher.recorder().clearAdvisories();
  auto const interactionRegion = createDdmRegion(
      subscriber,
      subscriberHandles,
      0UL,
      2UL,
      0UL,
      2UL);
  auto const interactionRegionSet = rti::RegionHandleSet{interactionRegion};
  subscriber.rtiAmbassador().subscribeInteractionClassWithRegions(
      subscriberHandles.interactionClass,
      interactionRegionSet,
      false);
  require(
      publisher.recorder().interactionsOn().empty(),
      "passive regional interaction subscription changed interaction relevance");

  subscriber.rtiAmbassador().subscribeInteractionClassWithRegions(
      subscriberHandles.interactionClass,
      interactionRegionSet,
      true);
  waitFor(
      publisher,
      [&] { return publisher.recorder().interactionsOn().size() >= 1U; },
      options,
      "regional interaction turn-on advisory");
  require(
      publisher.recorder().interactionsOn().size() == 1U &&
          publisher.recorder().interactionsOn().front() ==
              publisherHandles.interactionClass,
      "active regional interaction subscription returned the wrong turn-on advisory");

  subscriber.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      subscriberHandles.interactionClass,
      interactionRegionSet);
  waitFor(
      publisher,
      [&] { return publisher.recorder().interactionsOff().size() >= 1U; },
      options,
      "regional interaction turn-off advisory");
  require(
      publisher.recorder().interactionsOff().size() == 1U &&
          publisher.recorder().interactionsOff().front() ==
              publisherHandles.interactionClass,
      "regional interaction unsubscription returned the wrong turn-off advisory");

  subscriber.rtiAmbassador().deleteRegion(interactionRegion);
  subscriber.rtiAmbassador().deleteRegion(objectRegion);
  publisher.rtiAmbassador().unpublishInteractionClass(
      publisherHandles.interactionClass);
  publisher.rtiAmbassador().unpublishObjectClassAttributes(
      publisherHandles.objectClass,
      rti::AttributeHandleSet{publisherHandles.attribute});
  subscriber.resign(rti::NO_ACTION);
  publisher.resign(rti::NO_ACTION);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  publisher.disconnect();
  subscriber.disconnect();
}

void scenarioRegionalInteractionRouting(Options const& options, rti::CallbackModel model) {
  Session owner(options, model, "owner");
  Session overlap(options, model, "member");
  Session disjoint(options, model, "passive");
  auto const federation = federationName(options, "regional-interaction-routing");
  connectAndJoin(owner, overlap, options, federation, options.ddmFom);
  disjoint.connect();
  disjoint.join(
      options.memberFederateName + L"-regional-interaction-disjoint",
      options.federateType,
      federation);

  auto const ownerHandles = ddmHandles(owner, options);
  auto const overlapHandles = ddmHandles(overlap, options);
  auto const disjointHandles = ddmHandles(disjoint, options);
  verifyDdmClassDimensions(owner, options, ownerHandles, "regional interaction routing");

  owner.rtiAmbassador().publishInteractionClass(ownerHandles.interactionClass);
  auto const sourceRegion = createDdmRegion(owner, ownerHandles, 1UL, 5UL, 1UL, 5UL);
  auto const overlapRegion =
      createDdmRegion(overlap, overlapHandles, 2UL, 6UL, 2UL, 6UL);
  auto const disjointRegion =
      createDdmRegion(disjoint, disjointHandles, 7UL, 9UL, 7UL, 9UL);
  auto const sourceRegionSet = rti::RegionHandleSet{sourceRegion};
  auto const overlapRegionSet = rti::RegionHandleSet{overlapRegion};
  auto const disjointRegionSet = rti::RegionHandleSet{disjointRegion};

  auto verifyTransportation = [&](Session& receiver,
                                  rti::TransportationTypeHandle const& transportation,
                                  std::string const& description) {
    require(transportation.isValid(), description + " returned an invalid transportation handle");
    if (options.requireCustomTransportation) {
      require(
          receiver.rtiAmbassador().getTransportationTypeName(transportation) ==
              options.fomCustomTransportationName,
          description + " changed the adapter-declared custom transport");
    }
  };
  overlap.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  disjoint.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  overlap.rtiAmbassador().subscribeInteractionClassWithRegions(
      overlapHandles.interactionClass, overlapRegionSet, true);
  disjoint.rtiAmbassador().subscribeInteractionClassWithRegions(
      disjointHandles.interactionClass, disjointRegionSet, true);

  std::vector<std::uint8_t> firstValue{0x61U, 0x62U, 0x63U};
  std::vector<std::uint8_t> firstTag{0x49U, 0x31U};
  rti::ParameterHandleValueMap firstParameters;
  firstParameters.emplace(
      ownerHandles.parameter,
      rti::VariableLengthData(firstValue.data(), firstValue.size()));
  rti::VariableLengthData firstUserTag(firstTag.data(), firstTag.size());
  owner.rtiAmbassador().sendInteractionWithRegions(
      ownerHandles.interactionClass,
      firstParameters,
      sourceRegionSet,
      firstUserTag);
  waitFor(
      overlap,
      [&] { return overlap.recorder().interaction().present; },
      options,
      "regional ordinary interaction delivery");
  auto const firstInteraction = overlap.recorder().interaction();
  require(firstInteraction.interaction == overlapHandles.interactionClass &&
              firstInteraction.parameters.size() == 1U &&
              firstInteraction.parameters.count(overlapHandles.parameter) == 1U,
          "regional interaction returned the wrong class or parameter set");
  require(copyBytes(firstInteraction.parameters.at(overlapHandles.parameter)) == firstValue,
          "regional interaction returned the wrong parameter value");
  require(firstInteraction.tag == firstTag &&
              firstInteraction.producer == owner.federateHandle() &&
              firstInteraction.transportation.isValid(),
          "regional interaction did not preserve ordinary metadata");
  verifyTransportation(
      overlap,
      firstInteraction.transportation,
      "regional interaction");
  require(firstInteraction.regions.has_value() &&
              firstInteraction.regions->size() == 1U &&
              firstInteraction.regions->count(sourceRegion) == 1U,
          "regional interaction did not convey the source region designator set");
  for (int pass = 0; pass != 8; ++pass) {
    disjoint.pump();
  }
  require(!disjoint.recorder().interaction().present,
          "disjoint regional interaction subscription received the interaction");

  overlap.recorder().clearInteraction();
  overlap.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      overlapHandles.interactionClass, overlapRegionSet);
  owner.rtiAmbassador().sendInteractionWithRegions(
      ownerHandles.interactionClass,
      firstParameters,
      sourceRegionSet,
      firstUserTag);
  for (int pass = 0; pass != 8; ++pass) {
    overlap.pump();
  }
  require(!overlap.recorder().interaction().present,
          "unsubscribed regional interaction receiver received a message");

  overlap.rtiAmbassador().subscribeInteractionClassWithRegions(
      overlapHandles.interactionClass, overlapRegionSet, true);
  std::vector<std::uint8_t> secondValue{0x71U, 0x72U};
  std::vector<std::uint8_t> secondTag{0x49U, 0x32U};
  rti::ParameterHandleValueMap secondParameters;
  secondParameters.emplace(
      ownerHandles.parameter,
      rti::VariableLengthData(secondValue.data(), secondValue.size()));
  rti::VariableLengthData secondUserTag(secondTag.data(), secondTag.size());
  owner.rtiAmbassador().sendInteractionWithRegions(
      ownerHandles.interactionClass,
      secondParameters,
      sourceRegionSet,
      secondUserTag);
  waitFor(
      overlap,
      [&] { return overlap.recorder().interaction().present; },
      options,
      "regional interaction delivery after resubscription");
  auto const secondInteraction = overlap.recorder().interaction();
  require(copyBytes(secondInteraction.parameters.at(overlapHandles.parameter)) == secondValue &&
              secondInteraction.tag == secondTag,
          "regional interaction resubscription returned stale data");
  verifyTransportation(
      overlap,
      secondInteraction.transportation,
      "regional interaction resubscription");

  overlap.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      overlapHandles.interactionClass, overlapRegionSet);
  disjoint.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      disjointHandles.interactionClass, disjointRegionSet);
  owner.rtiAmbassador().unpublishInteractionClass(ownerHandles.interactionClass);
  owner.rtiAmbassador().deleteRegion(sourceRegion);
  overlap.rtiAmbassador().deleteRegion(overlapRegion);
  disjoint.rtiAmbassador().deleteRegion(disjointRegion);

  owner.resign(rti::NO_ACTION);
  overlap.resign(rti::NO_ACTION);
  disjoint.resign(rti::NO_ACTION);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  owner.disconnect();
  overlap.disconnect();
  disjoint.disconnect();
}

void scenarioRegionalInteractionSourceRegionSnapshot(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.ddmFom.empty(),
      "Regional interaction source-region snapshot requires an adapter-supplied dimensional FOM");

  Session publisher(options, model, "owner");
  Session subscriber(options, model, "member");
  auto const federation = federationName(
      options,
      "regional-interaction-source-region-snapshot");
  connectAndJoin(publisher, subscriber, options, federation, options.ddmFom);

  auto const publisherHandles = ddmHandles(publisher, options);
  auto const subscriberHandles = ddmHandles(subscriber, options);
  verifyDdmClassDimensions(
      publisher,
      options,
      publisherHandles,
      "regional interaction source-region snapshot");

  publisher.rtiAmbassador().publishInteractionClass(
      publisherHandles.interactionClass);
  auto const sourceRegion = createDdmRegion(
      publisher,
      publisherHandles,
      1UL,
      5UL,
      1UL,
      5UL);
  auto const subscriberRegion = createDdmRegion(
      subscriber,
      subscriberHandles,
      2UL,
      6UL,
      2UL,
      6UL);
  auto const sourceRegionSet = rti::RegionHandleSet{sourceRegion};
  auto const subscriberRegionSet = rti::RegionHandleSet{subscriberRegion};

  subscriber.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  subscriber.rtiAmbassador().subscribeInteractionClassWithRegions(
      subscriberHandles.interactionClass,
      subscriberRegionSet,
      true);

  std::vector<std::uint8_t> const valueBytes{0x2CU, 0x01U};
  std::vector<std::uint8_t> const tagBytes{0x53U, 0x4EU, 0x50U};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      publisherHandles.parameter,
      rti::VariableLengthData(valueBytes.data(), valueBytes.size()));
  rti::VariableLengthData const tag(tagBytes.data(), tagBytes.size());

  auto assertInteraction = [&](InteractionRecord const& record,
                               std::string const& description) {
    require(
        record.interaction == subscriberHandles.interactionClass &&
            record.parameters.size() == 1U &&
            record.parameters.count(subscriberHandles.parameter) == 1U &&
            copyBytes(record.parameters.at(subscriberHandles.parameter)) == valueBytes,
        description + " returned the wrong class, parameter, or value");
    require(
        record.tag == tagBytes &&
            record.producer == publisher.federateHandle() &&
            record.transportation.isValid(),
        description + " did not preserve ordinary metadata");
    require(
        record.regions.has_value() &&
            record.regions->size() == 1U &&
            record.regions->count(sourceRegion) == 1U,
        description + " did not preserve the send-time source region");
  };

  // Admission overlaps the subscriber's committed region. In evoked mode the
  // callback remains queued while the source region is changed; in immediate
  // mode delivery completes before the same mutation. Both paths must expose
  // the source-region realization captured at send time.
  publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      parameters,
      sourceRegionSet,
      tag);
  if (model == rti::HLA_EVOKED) {
    require(
        !subscriber.recorder().interaction().present,
        "evoked regional interaction was delivered before callback servicing");
  }
  if (model == rti::HLA_EVOKED) {
    publisher.rtiAmbassador().setRangeBounds(
        sourceRegion,
        publisherHandles.firstDimension,
        rti::RangeBounds(16UL, 20UL));
    publisher.rtiAmbassador().commitRegionModifications(
        rti::RegionHandleSet{sourceRegion});
  }
  waitFor(
      subscriber,
      [&] { return subscriber.recorder().interaction().present; },
      options,
      "regional interaction send-time source-region snapshot");
  assertInteraction(
      subscriber.recorder().interaction(),
      "regional interaction send-time source-region snapshot");

  subscriber.recorder().clearInteraction();
  if (model == rti::HLA_IMMEDIATE) {
    publisher.rtiAmbassador().setRangeBounds(
        sourceRegion,
        publisherHandles.firstDimension,
        rti::RangeBounds(16UL, 20UL));
    publisher.rtiAmbassador().commitRegionModifications(
        rti::RegionHandleSet{sourceRegion});
  }

  publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      parameters,
      sourceRegionSet,
      tag);
  for (int pass = 0; pass != 8; ++pass) {
    subscriber.pump();
  }
  require(
      !subscriber.recorder().interaction().present,
      "disjoint regional interaction source mutation did not suppress delivery");

  publisher.rtiAmbassador().setRangeBounds(
      sourceRegion,
      publisherHandles.firstDimension,
      rti::RangeBounds(0UL, 10UL));
  publisher.rtiAmbassador().commitRegionModifications(
      rti::RegionHandleSet{sourceRegion});
  publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      parameters,
      sourceRegionSet,
      tag);
  waitFor(
      subscriber,
      [&] { return subscriber.recorder().interaction().present; },
      options,
      "regional interaction delivery after source-region restoration");
  assertInteraction(
      subscriber.recorder().interaction(),
      "regional interaction delivery after source-region restoration");

  subscriber.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      subscriberHandles.interactionClass,
      subscriberRegionSet);
  publisher.rtiAmbassador().unpublishInteractionClass(
      publisherHandles.interactionClass);
  publisher.rtiAmbassador().deleteRegion(sourceRegion);
  subscriber.rtiAmbassador().deleteRegion(subscriberRegion);

  publisher.resign(rti::NO_ACTION);
  subscriber.resign(rti::NO_ACTION);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  publisher.disconnect();
  subscriber.disconnect();
}

void scenarioRegionalInteractionSubscriptionFiltering(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.ddmFom.empty(),
      "Regional interaction subscription filtering requires an adapter-supplied dimensional FOM");

  Session publisher(options, model, "owner");
  Session subscriber(options, model, "member");
  auto const federation = federationName(
      options,
      "regional-interaction-subscription-filtering");
  connectAndJoin(publisher, subscriber, options, federation, options.ddmFom);

  auto const publisherHandles = ddmHandles(publisher, options);
  auto const subscriberHandles = ddmHandles(subscriber, options);
  verifyDdmClassDimensions(
      publisher,
      options,
      publisherHandles,
      "regional interaction subscription filtering");

  publisher.rtiAmbassador().publishInteractionClass(
      publisherHandles.interactionClass);

  auto const sourceRegion = createDdmRegion(
      publisher,
      publisherHandles,
      1UL,
      5UL,
      1UL,
      5UL);
  auto const subscriberRegion = createDdmRegion(
      subscriber,
      subscriberHandles,
      2UL,
      6UL,
      2UL,
      6UL);

  std::vector<std::uint8_t> const parameterBytes{0x2CU, 0x01U};
  std::vector<std::uint8_t> const tagBytes{0x7AU, 0x19U};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      publisherHandles.parameter,
      rti::VariableLengthData(parameterBytes.data(), parameterBytes.size()));
  rti::VariableLengthData const tag(tagBytes.data(), tagBytes.size());

  auto assertInteraction = [&](InteractionRecord const& record, bool expectRegions) {
    require(
        record.interaction == subscriberHandles.interactionClass &&
            record.parameters.size() == 1U &&
            record.parameters.count(subscriberHandles.parameter) == 1U &&
            copyBytes(record.parameters.at(subscriberHandles.parameter)) == parameterBytes,
        "regional interaction filtering returned the wrong class or parameter");
    require(
        record.tag == tagBytes &&
            record.producer == publisher.federateHandle() &&
            record.transportation.isValid(),
        "regional interaction filtering did not preserve ordinary metadata");
    if (expectRegions) {
      require(
          record.regions.has_value() &&
              record.regions->size() == 1U &&
              record.regions->count(sourceRegion) == 1U,
          "regional interaction filtering did not convey the source region");
    } else {
      require(
          !record.regions.has_value(),
          "regional interaction filtering unexpectedly conveyed a source region");
    }
  };
  auto drainSubscriber = [&] {
    for (int pass = 0; pass != 8; ++pass) {
      subscriber.pump();
    }
  };

  // An ordinary declaration remains independent from an explicit regional
  // declaration, and an empty regional declaration does not create a default
  // subscription or turn an explicitly regional send into an ordinary send.
  subscriber.rtiAmbassador().subscribeInteractionClass(
      subscriberHandles.interactionClass);
  subscriber.rtiAmbassador().subscribeInteractionClassWithRegions(
      subscriberHandles.interactionClass,
      rti::RegionHandleSet{},
      true);
  subscriber.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      subscriberHandles.interactionClass,
      rti::RegionHandleSet{});
  subscriber.recorder().clearInteraction();
  publisher.rtiAmbassador().sendInteraction(
      publisherHandles.interactionClass,
      parameters,
      tag);
  waitFor(
      subscriber,
      [&] { return subscriber.recorder().interaction().present; },
      options,
      "ordinary interaction through the ordinary subscription");
  auto const ordinaryInteraction = subscriber.recorder().interaction();
  assertInteraction(ordinaryInteraction, false);

  subscriber.recorder().clearInteraction();
  publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      parameters,
      rti::RegionHandleSet{},
      tag);
  drainSubscriber();
  require(
      !subscriber.recorder().interaction().present,
      "an explicitly empty regional interaction send used the ordinary subscription");

  // Removing only the ordinary declaration makes the committed regional
  // declaration the complete routing filter.
  subscriber.rtiAmbassador().subscribeInteractionClassWithRegions(
      subscriberHandles.interactionClass,
      rti::RegionHandleSet{subscriberRegion},
      true);
  subscriber.rtiAmbassador().unsubscribeInteractionClass(
      subscriberHandles.interactionClass);
  subscriber.recorder().clearInteraction();
  publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      parameters,
      rti::RegionHandleSet{sourceRegion},
      tag);
  waitFor(
      subscriber,
      [&] { return subscriber.recorder().interaction().present; },
      options,
      "regional interaction through the explicit subscription");
  assertInteraction(subscriber.recorder().interaction(), false);

  subscriber.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  require(
      subscriber.rtiAmbassador().getConveyRegionDesignatorSetsSwitch(),
      "regional interaction receiver did not enable region designator callbacks");
  subscriber.recorder().clearInteraction();
  publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      parameters,
      rti::RegionHandleSet{sourceRegion},
      tag);
  waitFor(
      subscriber,
      [&] { return subscriber.recorder().interaction().present; },
      options,
      "regional interaction with conveyed source region");
  assertInteraction(subscriber.recorder().interaction(), true);

  // A queued regional interaction is rechecked against the committed
  // subscription region at callback entry. Immediate delivery completes
  // before the later region movement and therefore cannot be replayed.
  subscriber.recorder().clearInteraction();
  publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      parameters,
      rti::RegionHandleSet{sourceRegion},
      tag);
  if (model == rti::HLA_EVOKED) {
    subscriber.rtiAmbassador().setRangeBounds(
        subscriberRegion,
        subscriberHandles.firstDimension,
        rti::RangeBounds(7UL, 9UL));
    subscriber.rtiAmbassador().setRangeBounds(
        subscriberRegion,
        subscriberHandles.secondDimension,
        rti::RangeBounds(7UL, 9UL));
    subscriber.rtiAmbassador().commitRegionModifications(
        rti::RegionHandleSet{subscriberRegion});
    drainSubscriber();
    require(
        !subscriber.recorder().interaction().present,
        "evoked regional interaction ignored a moved subscription region");
  } else {
    waitFor(
        subscriber,
        [&] { return subscriber.recorder().interaction().present; },
        options,
        "immediate regional interaction delivery before region movement");
    assertInteraction(subscriber.recorder().interaction(), true);
    subscriber.recorder().clearInteraction();
    subscriber.rtiAmbassador().setRangeBounds(
        subscriberRegion,
        subscriberHandles.firstDimension,
        rti::RangeBounds(7UL, 9UL));
    subscriber.rtiAmbassador().setRangeBounds(
        subscriberRegion,
        subscriberHandles.secondDimension,
        rti::RangeBounds(7UL, 9UL));
    subscriber.rtiAmbassador().commitRegionModifications(
        rti::RegionHandleSet{subscriberRegion});
    drainSubscriber();
    require(
        !subscriber.recorder().interaction().present,
        "immediate regional interaction was replayed after region movement");
  }

  subscriber.rtiAmbassador().setRangeBounds(
      subscriberRegion,
      subscriberHandles.firstDimension,
      rti::RangeBounds(2UL, 6UL));
  subscriber.rtiAmbassador().setRangeBounds(
      subscriberRegion,
      subscriberHandles.secondDimension,
      rti::RangeBounds(2UL, 6UL));
  subscriber.rtiAmbassador().commitRegionModifications(
      rti::RegionHandleSet{subscriberRegion});
  subscriber.recorder().clearInteraction();
  publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      parameters,
      rti::RegionHandleSet{sourceRegion},
      tag);
  waitFor(
      subscriber,
      [&] { return subscriber.recorder().interaction().present; },
      options,
      "regional interaction after subscription-region restoration");
  assertInteraction(subscriber.recorder().interaction(), true);

  // Standard service-boundary failures for foreign, uncommitted, and
  // incompatible regions are distinct from ordinary no-send behavior.
  requireException(
      [&] {
        publisher.rtiAmbassador().sendInteractionWithRegions(
            publisherHandles.interactionClass,
            parameters,
            rti::RegionHandleSet{subscriberRegion},
            tag);
      },
      L"RegionNotCreatedByThisFederate",
      "regional interaction send with a foreign region");
  requireException(
      [&] {
        subscriber.rtiAmbassador().subscribeInteractionClassWithRegions(
            subscriberHandles.interactionClass,
            rti::RegionHandleSet{sourceRegion},
            true);
      },
      L"RegionNotCreatedByThisFederate",
      "regional interaction subscription with a foreign region");

  auto const uncommittedRegion = subscriber.rtiAmbassador().createRegion(
      rti::DimensionHandleSet{
          subscriberHandles.firstDimension,
          subscriberHandles.secondDimension});
  requireException(
      [&] {
        subscriber.rtiAmbassador().subscribeInteractionClassWithRegions(
            subscriberHandles.interactionClass,
            rti::RegionHandleSet{uncommittedRegion},
            true);
      },
      L"InvalidRegion",
      "regional interaction subscription with an uncommitted region");

  auto const wrongContextRegion = subscriber.rtiAmbassador().createRegion(
      rti::DimensionHandleSet{subscriberHandles.firstDimension});
  subscriber.rtiAmbassador().setRangeBounds(
      wrongContextRegion,
      subscriberHandles.firstDimension,
      rti::RangeBounds(0UL, 1UL));
  subscriber.rtiAmbassador().commitRegionModifications(
      rti::RegionHandleSet{wrongContextRegion});
  requireException(
      [&] {
        subscriber.rtiAmbassador().subscribeInteractionClassWithRegions(
            subscriberHandles.interactionClass,
            rti::RegionHandleSet{wrongContextRegion},
            true);
      },
      L"InvalidRegionContext",
      "regional interaction subscription with an incompatible region context");

  auto const publisherWrongContextRegion = publisher.rtiAmbassador().createRegion(
      rti::DimensionHandleSet{publisherHandles.firstDimension});
  publisher.rtiAmbassador().setRangeBounds(
      publisherWrongContextRegion,
      publisherHandles.firstDimension,
      rti::RangeBounds(0UL, 1UL));
  publisher.rtiAmbassador().commitRegionModifications(
      rti::RegionHandleSet{publisherWrongContextRegion});
  requireException(
      [&] {
        publisher.rtiAmbassador().sendInteractionWithRegions(
            publisherHandles.interactionClass,
            parameters,
            rti::RegionHandleSet{publisherWrongContextRegion},
            tag);
      },
      L"InvalidRegionContext",
      "regional interaction send with an incompatible region context");

  subscriber.recorder().clearInteraction();
  publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      parameters,
      rti::RegionHandleSet{},
      tag);
  drainSubscriber();
  require(
      !subscriber.recorder().interaction().present,
      "empty regional interaction send produced a callback after filtering");

  requireException(
      [&] { subscriber.rtiAmbassador().deleteRegion(subscriberRegion); },
      L"RegionInUseForUpdateOrSubscription",
      "deletion of a region used by a regional interaction subscription");
  subscriber.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      subscriberHandles.interactionClass,
      rti::RegionHandleSet{subscriberRegion});
  publisher.rtiAmbassador().unpublishInteractionClass(
      publisherHandles.interactionClass);
  subscriber.rtiAmbassador().deleteRegion(subscriberRegion);
  subscriber.rtiAmbassador().deleteRegion(uncommittedRegion);
  subscriber.rtiAmbassador().deleteRegion(wrongContextRegion);
  publisher.rtiAmbassador().deleteRegion(sourceRegion);
  publisher.rtiAmbassador().deleteRegion(publisherWrongContextRegion);

  subscriber.resign(rti::NO_ACTION);
  publisher.resign(rti::NO_ACTION);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  publisher.disconnect();
  subscriber.disconnect();
}

void scenarioAllowRelaxedDdm(Options const& options, rti::CallbackModel model) {
  require(!options.ddmFom.empty(),
          "Allow Relaxed DDM requires an adapter-supplied dimensional FOM");
  require(!options.switchesFom.empty(),
          "Allow Relaxed DDM requires an adapter-supplied switch-declaration FOM");

  auto modulesFor = [&](bool enabled) {
    std::vector<std::wstring> modules{options.ddmFom.wstring()};
    if (enabled) {
      modules.push_back(options.switchesFom.wstring());
    }
    return modules;
  };

  auto runObject = [&](bool enabled) {
    Session publisher(options, model, enabled ? "relaxed-object-enabled" : "relaxed-object-strict");
    Session subscriber(options, model, enabled ? "relaxed-object-member-enabled" : "relaxed-object-member-strict");
    auto const federation = federationName(
        options,
        enabled ? "allow-relaxed-ddm-object-enabled" : "allow-relaxed-ddm-object-strict");
    publisher.connect();
    subscriber.connect();
    publisher.rtiAmbassador().createFederationExecution(
        federation,
        modulesFor(enabled),
        options.logicalTimeImplementationName);
    publisher.join(
        options.ownerFederateName,
        options.federateType,
        federation);
    subscriber.join(
        options.memberFederateName,
        options.federateType,
        federation);

    require(
        publisher.rtiAmbassador().getAllowRelaxedDDMSwitch() == enabled &&
            subscriber.rtiAmbassador().getAllowRelaxedDDMSwitch() == enabled,
        "Allow Relaxed DDM object composition did not match the adapter switch FOM");
    auto const publisherHandles = ddmHandles(publisher, options);
    auto const subscriberHandles = ddmHandles(subscriber, options);
    verifyDdmClassDimensions(
        publisher,
        options,
        publisherHandles,
        "Allow Relaxed DDM object publisher");
    publisher.rtiAmbassador().publishObjectClassAttributes(
        publisherHandles.objectClass,
        rti::AttributeHandleSet{publisherHandles.attribute});

    auto const sourceRegion = createDdmRegion(
        publisher,
        publisherHandles,
        0UL,
        2UL,
        0UL,
        2UL);
    auto const subscriptionRegion = createDdmRegion(
        subscriber,
        subscriberHandles,
        2UL,
        3UL,
        2UL,
        3UL);
    rti::AttributeHandleSetRegionHandleSetPairVector const sourcePair{{
        rti::AttributeHandleSet{publisherHandles.attribute},
        rti::RegionHandleSet{sourceRegion},
    }};
    rti::AttributeHandleSetRegionHandleSetPairVector const subscriptionPair{{
        rti::AttributeHandleSet{subscriberHandles.attribute},
        rti::RegionHandleSet{subscriptionRegion},
    }};
    subscriber.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
    subscriber.rtiAmbassador().subscribeObjectClassAttributesWithRegions(
        subscriberHandles.objectClass,
        subscriptionPair,
        true,
        L"");

    auto const object = publisher.rtiAmbassador().registerObjectInstanceWithRegions(
        publisherHandles.objectClass,
        sourcePair);
    require(object.isValid(), "Allow Relaxed DDM object registration returned an invalid handle");
    if (enabled) {
      waitFor(
          subscriber,
          [&] { return subscriber.recorder().hasDiscovery(object); },
          options,
          "Allow Relaxed DDM touching object discovery");
      auto const discovery = subscriber.recorder().discovery();
      require(
          discovery.object == object && discovery.objectClass == subscriberHandles.objectClass,
          "Allow Relaxed DDM object discovery returned the wrong identity");
    } else {
      for (int pass = 0; pass != 8; ++pass) {
        subscriber.pump();
      }
      require(
          !subscriber.recorder().discovery().present,
          "strict DDM unexpectedly discovered a touching object");
    }

    std::vector<std::uint8_t> valueBytes{0x41U, 0x52U, 0x44U};
    std::vector<std::uint8_t> tagBytes{0x4FU, 0x42U};
    rti::AttributeHandleValueMap values;
    values.emplace(
        publisherHandles.attribute,
        rti::VariableLengthData(valueBytes.data(), valueBytes.size()));
    rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());
    publisher.rtiAmbassador().updateAttributeValues(object, values, tag);
    if (enabled) {
      waitFor(
          subscriber,
          [&] { return subscriber.recorder().reflection().present; },
          options,
          "Allow Relaxed DDM touching object reflection");
      auto const reflection = subscriber.recorder().reflection();
      require(
          reflection.object == object && reflection.tag == tagBytes &&
              reflection.values.size() == 1U &&
              reflection.values.count(subscriberHandles.attribute) == 1U &&
              copyBytes(reflection.values.at(subscriberHandles.attribute)) == valueBytes,
          "Allow Relaxed DDM object reflection changed the delivered data");
      require(
          reflection.regions.has_value() &&
              reflection.regions->count(sourceRegion) == 1U,
          "Allow Relaxed DDM object reflection omitted the source region");
    } else {
      for (int pass = 0; pass != 8; ++pass) {
        subscriber.pump();
      }
      require(
          !subscriber.recorder().reflection().present,
          "strict DDM unexpectedly reflected a touching object update");
    }

    subscriber.rtiAmbassador().unsubscribeObjectClassAttributesWithRegions(
        subscriberHandles.objectClass,
        subscriptionPair);
    publisher.rtiAmbassador().unassociateRegionsForUpdates(object, sourcePair);
    subscriber.rtiAmbassador().deleteRegion(subscriptionRegion);
    publisher.rtiAmbassador().deleteRegion(sourceRegion);
    subscriber.resign(rti::NO_ACTION);
    publisher.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
    publisher.rtiAmbassador().destroyFederationExecution(federation);
    subscriber.disconnect();
    publisher.disconnect();
  };

  auto runInteraction = [&](bool enabled) {
    Session publisher(options, model, enabled ? "relaxed-interaction-enabled" : "relaxed-interaction-strict");
    Session subscriber(options, model, enabled ? "relaxed-interaction-member-enabled" : "relaxed-interaction-member-strict");
    auto const federation = federationName(
        options,
        enabled ? "allow-relaxed-ddm-interaction-enabled" : "allow-relaxed-ddm-interaction-strict");
    publisher.connect();
    subscriber.connect();
    publisher.rtiAmbassador().createFederationExecution(
        federation,
        modulesFor(enabled),
        options.logicalTimeImplementationName);
    publisher.join(
        options.ownerFederateName,
        options.federateType,
        federation);
    subscriber.join(
        options.memberFederateName,
        options.federateType,
        federation);

    require(
        publisher.rtiAmbassador().getAllowRelaxedDDMSwitch() == enabled &&
            subscriber.rtiAmbassador().getAllowRelaxedDDMSwitch() == enabled,
        "Allow Relaxed DDM interaction composition did not match the adapter switch FOM");
    auto const publisherHandles = ddmHandles(publisher, options);
    auto const subscriberHandles = ddmHandles(subscriber, options);
    verifyDdmClassDimensions(
        publisher,
        options,
        publisherHandles,
        "Allow Relaxed DDM interaction publisher");
    publisher.rtiAmbassador().publishInteractionClass(publisherHandles.interactionClass);

    auto const sourceRegion = createDdmRegion(
        publisher,
        publisherHandles,
        0UL,
        2UL,
        0UL,
        2UL);
    auto const subscriptionRegion = createDdmRegion(
        subscriber,
        subscriberHandles,
        2UL,
        3UL,
        2UL,
        3UL);
    auto const sourceRegions = rti::RegionHandleSet{sourceRegion};
    auto const subscriptionRegions = rti::RegionHandleSet{subscriptionRegion};
    subscriber.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
    subscriber.rtiAmbassador().subscribeInteractionClassWithRegions(
        subscriberHandles.interactionClass,
        subscriptionRegions,
        true);

    std::vector<std::uint8_t> parameterBytes{0x49U, 0x4EU, 0x54U};
    std::vector<std::uint8_t> tagBytes{0x52U, 0x58U};
    rti::ParameterHandleValueMap parameters;
    parameters.emplace(
        publisherHandles.parameter,
        rti::VariableLengthData(parameterBytes.data(), parameterBytes.size()));
    rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());
    publisher.rtiAmbassador().sendInteractionWithRegions(
        publisherHandles.interactionClass,
        parameters,
        sourceRegions,
        tag);
    if (enabled) {
      waitFor(
          subscriber,
          [&] { return subscriber.recorder().interaction().present; },
          options,
          "Allow Relaxed DDM touching interaction delivery");
      auto const interaction = subscriber.recorder().interaction();
      require(
          interaction.interaction == subscriberHandles.interactionClass &&
              interaction.tag == tagBytes && interaction.producer == publisher.federateHandle() &&
              interaction.parameters.size() == 1U &&
              interaction.parameters.count(subscriberHandles.parameter) == 1U &&
              copyBytes(interaction.parameters.at(subscriberHandles.parameter)) == parameterBytes,
          "Allow Relaxed DDM interaction changed the delivered data");
      require(
          interaction.regions.has_value() &&
              interaction.regions->count(sourceRegion) == 1U,
          "Allow Relaxed DDM interaction omitted the source region");
    } else {
      for (int pass = 0; pass != 8; ++pass) {
        subscriber.pump();
      }
      require(
          !subscriber.recorder().interaction().present,
          "strict DDM unexpectedly delivered a touching interaction");
    }

    subscriber.rtiAmbassador().unsubscribeInteractionClassWithRegions(
        subscriberHandles.interactionClass,
        subscriptionRegions);
    publisher.rtiAmbassador().unpublishInteractionClass(publisherHandles.interactionClass);
    subscriber.rtiAmbassador().deleteRegion(subscriptionRegion);
    publisher.rtiAmbassador().deleteRegion(sourceRegion);
    subscriber.resign(rti::NO_ACTION);
    publisher.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
    publisher.rtiAmbassador().destroyFederationExecution(federation);
    subscriber.disconnect();
    publisher.disconnect();
  };

  runObject(false);
  runObject(true);
  runInteraction(false);
  runInteraction(true);
}

void scenarioRegionalMultiAttributeUpdate(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.multiAttributeFom.empty(),
      "Multi-attribute regional testing requires an adapter-supplied FOM");

  Session publisher(options, model, "multi-attribute-publisher");
  Session flavor(options, model, "multi-attribute-flavor");
  Session organic(options, model, "multi-attribute-organic");
  auto const federation = federationName(
      options,
      "regional-multi-attribute-update");
  publisher.connect();
  flavor.connect();
  organic.connect();
  publisher.rtiAmbassador().createFederationExecution(
      federation,
      options.multiAttributeFom.wstring(),
      options.logicalTimeImplementationName);
  publisher.join(
      options.ownerFederateName + L"-multi-attribute-publisher",
      options.federateType,
      federation);
  flavor.join(
      options.memberFederateName + L"-multi-attribute-flavor",
      options.federateType,
      federation);
  organic.join(
      options.memberFederateName + L"-multi-attribute-organic",
      options.federateType,
      federation);

  auto const publisherHandles = multiAttributeDdmHandles(publisher, options);
  auto const flavorHandles = multiAttributeDdmHandles(flavor, options);
  auto const organicHandles = multiAttributeDdmHandles(organic, options);
  verifyDdmObjectClassDimensions(
      publisher,
      options,
      publisherHandles.objectClass,
      publisherHandles.firstDimension,
      publisherHandles.secondDimension,
      "multi-attribute regional publisher");

  publisher.rtiAmbassador().publishObjectClassAttributes(
      publisherHandles.objectClass,
      rti::AttributeHandleSet{
          publisherHandles.firstAttribute,
          publisherHandles.secondAttribute});

  auto const sourceFlavor = createDdmRegionForDimensions(
      publisher,
      publisherHandles.firstDimension,
      publisherHandles.secondDimension,
      0UL,
      2UL,
      0UL,
      2UL);
  auto const sourceOrganic = createDdmRegionForDimensions(
      publisher,
      publisherHandles.firstDimension,
      publisherHandles.secondDimension,
      5UL,
      7UL,
      5UL,
      7UL);
  auto const flavorRegion = createDdmRegionForDimensions(
      flavor,
      flavorHandles.firstDimension,
      flavorHandles.secondDimension,
      0UL,
      2UL,
      0UL,
      2UL);
  auto const organicRegion = createDdmRegionForDimensions(
      organic,
      organicHandles.firstDimension,
      organicHandles.secondDimension,
      5UL,
      7UL,
      5UL,
      7UL);

  flavor.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  organic.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  rti::AttributeHandleSetRegionHandleSetPairVector const sourcePairs{
      {rti::AttributeHandleSet{publisherHandles.firstAttribute},
       rti::RegionHandleSet{sourceFlavor}},
      {rti::AttributeHandleSet{publisherHandles.secondAttribute},
       rti::RegionHandleSet{sourceOrganic}}};
  rti::AttributeHandleSetRegionHandleSetPairVector const flavorPairs{
      {rti::AttributeHandleSet{flavorHandles.firstAttribute},
       rti::RegionHandleSet{flavorRegion}}};
  rti::AttributeHandleSetRegionHandleSetPairVector const organicPairs{
      {rti::AttributeHandleSet{organicHandles.secondAttribute},
       rti::RegionHandleSet{organicRegion}}};
  flavor.rtiAmbassador().subscribeObjectClassAttributesWithRegions(
      flavorHandles.objectClass,
      flavorPairs);
  organic.rtiAmbassador().subscribeObjectClassAttributesWithRegions(
      organicHandles.objectClass,
      organicPairs);

  auto const object = publisher.rtiAmbassador().registerObjectInstanceWithRegions(
      publisherHandles.objectClass,
      sourcePairs);
  require(
      object.isValid(),
      "multi-attribute regional registration returned an invalid handle");
  waitFor(
      flavor,
      organic,
      [&] {
        return flavor.recorder().hasDiscovery(object) &&
            organic.recorder().hasDiscovery(object);
      },
      options,
      "multi-attribute regional object discovery");
  require(
      flavor.recorder().discovery().objectClass == flavorHandles.objectClass &&
          organic.recorder().discovery().objectClass == organicHandles.objectClass,
      "multi-attribute regional discovery returned the wrong class");

  auto sendValues = [&](std::vector<std::uint8_t> firstValue,
                        std::vector<std::uint8_t> secondValue,
                        std::vector<std::uint8_t> tag) {
    rti::AttributeHandleValueMap values;
    values.emplace(
        publisherHandles.firstAttribute,
        rti::VariableLengthData(firstValue.data(), firstValue.size()));
    values.emplace(
        publisherHandles.secondAttribute,
        rti::VariableLengthData(secondValue.data(), secondValue.size()));
    publisher.rtiAmbassador().updateAttributeValues(
        object,
        values,
        rti::VariableLengthData(tag.data(), tag.size()));
  };

  sendValues(
      {0x46U, 0x31U},
      {0x4FU, 0x31U},
      {0x49U, 0x31U});
  waitFor(
      flavor,
      organic,
      [&] {
        return flavor.recorder().reflectionCount() >= 1U &&
            organic.recorder().reflectionCount() >= 1U;
      },
      options,
      "multi-attribute regional initial reflection");
  auto assertReflection = [&](Session& subscriber,
                              rti::AttributeHandle const& expectedAttribute,
                              rti::RegionHandle const& expectedRegion,
                              std::vector<std::uint8_t> const& expectedValue,
                              std::vector<std::uint8_t> const& expectedTag,
                              std::string const& description) {
    auto const reflection = subscriber.recorder().reflection();
    require(
        reflection.object == object &&
            reflection.values.size() == 1U &&
            reflection.values.count(expectedAttribute) == 1U &&
            copyBytes(reflection.values.at(expectedAttribute)) == expectedValue,
        description + " returned the wrong projected attribute value");
    require(
        reflection.tag == expectedTag &&
            reflection.producer == publisher.federateHandle() &&
            reflection.transportation.isValid(),
        description + " returned the wrong metadata");
    require(
        reflection.regions.has_value() &&
            reflection.regions->size() == 1U &&
            reflection.regions->count(expectedRegion) == 1U,
        description + " omitted the source region designator");
  };
  assertReflection(
      flavor,
      flavorHandles.firstAttribute,
      sourceFlavor,
      {0x46U, 0x31U},
      {0x49U, 0x31U},
      "multi-attribute regional Flavor reflection");
  assertReflection(
      organic,
      organicHandles.secondAttribute,
      sourceOrganic,
      {0x4FU, 0x31U},
      {0x49U, 0x31U},
      "multi-attribute regional Organic reflection");

  auto const flavorReflections = flavor.recorder().reflectionCount();
  auto const organicReflections = organic.recorder().reflectionCount();
  publisher.rtiAmbassador().setRangeBounds(
      sourceFlavor,
      publisherHandles.firstDimension,
      rti::RangeBounds(8UL, 9UL));
  publisher.rtiAmbassador().commitRegionModifications(
      rti::RegionHandleSet{sourceFlavor});
  sendValues(
      {0x46U, 0x58U},
      {0x4FU, 0x58U},
      {0x58U, 0x31U});
  waitFor(
      organic,
      [&] { return organic.recorder().reflectionCount() > organicReflections; },
      options,
      "multi-attribute regional surviving Organic reflection");
  require(
      flavor.recorder().reflectionCount() == flavorReflections,
      "multi-attribute regional X-only source mutation leaked Flavor delivery");
  assertReflection(
      organic,
      organicHandles.secondAttribute,
      sourceOrganic,
      {0x4FU, 0x58U},
      {0x58U, 0x31U},
      "multi-attribute regional X-only Organic reflection");

  publisher.rtiAmbassador().setRangeBounds(
      sourceOrganic,
      publisherHandles.secondDimension,
      rti::RangeBounds(8UL, 9UL));
  publisher.rtiAmbassador().commitRegionModifications(
      rti::RegionHandleSet{sourceOrganic});
  auto const flavorBeforeDisjoint = flavor.recorder().reflectionCount();
  auto const organicBeforeDisjoint = organic.recorder().reflectionCount();
  sendValues(
      {0x46U, 0x4EU},
      {0x4FU, 0x4EU},
      {0x4EU, 0x31U});
  for (int pass = 0; pass != 16; ++pass) {
    flavor.pump();
    organic.pump();
  }
  require(
      flavor.recorder().reflectionCount() == flavorBeforeDisjoint &&
          organic.recorder().reflectionCount() == organicBeforeDisjoint,
      "multi-attribute regional disjoint source mutation was delivered");

  publisher.rtiAmbassador().setRangeBounds(
      sourceFlavor,
      publisherHandles.firstDimension,
      rti::RangeBounds(0UL, 2UL));
  publisher.rtiAmbassador().setRangeBounds(
      sourceOrganic,
      publisherHandles.secondDimension,
      rti::RangeBounds(5UL, 7UL));
  publisher.rtiAmbassador().commitRegionModifications(
      rti::RegionHandleSet{sourceFlavor, sourceOrganic});
  auto const flavorBeforeRestore = flavor.recorder().reflectionCount();
  auto const organicBeforeRestore = organic.recorder().reflectionCount();
  sendValues(
      {0x46U, 0x52U},
      {0x4FU, 0x52U},
      {0x52U, 0x31U});
  waitFor(
      flavor,
      organic,
      [&] {
        return flavor.recorder().reflectionCount() > flavorBeforeRestore &&
            organic.recorder().reflectionCount() > organicBeforeRestore;
      },
      options,
      "multi-attribute regional restored reflections");
  assertReflection(
      flavor,
      flavorHandles.firstAttribute,
      sourceFlavor,
      {0x46U, 0x52U},
      {0x52U, 0x31U},
      "multi-attribute regional restored Flavor reflection");
  assertReflection(
      organic,
      organicHandles.secondAttribute,
      sourceOrganic,
      {0x4FU, 0x52U},
      {0x52U, 0x31U},
      "multi-attribute regional restored Organic reflection");

  flavor.rtiAmbassador().unsubscribeObjectClassAttributesWithRegions(
      flavorHandles.objectClass,
      flavorPairs);
  organic.rtiAmbassador().unsubscribeObjectClassAttributesWithRegions(
      organicHandles.objectClass,
      organicPairs);
  publisher.rtiAmbassador().unassociateRegionsForUpdates(object, sourcePairs);
  publisher.rtiAmbassador().unpublishObjectClassAttributes(
      publisherHandles.objectClass,
      rti::AttributeHandleSet{
          publisherHandles.firstAttribute,
          publisherHandles.secondAttribute});
  flavor.rtiAmbassador().deleteRegion(flavorRegion);
  organic.rtiAmbassador().deleteRegion(organicRegion);
  publisher.rtiAmbassador().deleteRegion(sourceFlavor);
  publisher.rtiAmbassador().deleteRegion(sourceOrganic);
  flavor.resign(rti::NO_ACTION);
  organic.resign(rti::NO_ACTION);
  publisher.resign(rti::DELETE_OBJECTS);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  flavor.disconnect();
  organic.disconnect();
  publisher.disconnect();
}

void scenarioRegionalThreeDimensionalOverlap(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.threeDimensionalFom.empty(),
      "Three-dimensional regional testing requires an adapter-supplied FOM");

  Session publisher(options, model, "three-dimensional-publisher");
  Session subscriber(options, model, "three-dimensional-subscriber");
  auto const federation = federationName(
      options,
      "regional-three-dimensional-overlap");
  publisher.connect();
  subscriber.connect();
  publisher.rtiAmbassador().createFederationExecution(
      federation,
      options.threeDimensionalFom.wstring(),
      options.logicalTimeImplementationName);
  publisher.join(
      options.ownerFederateName + L"-three-dimensional-publisher",
      options.federateType,
      federation);
  subscriber.join(
      options.memberFederateName + L"-three-dimensional-subscriber",
      options.federateType,
      federation);

  auto const publisherHandles = threeDimensionalDdmHandles(publisher, options);
  auto const subscriberHandles = threeDimensionalDdmHandles(subscriber, options);
  verifyThreeDimensionalObjectClassDimensions(
      publisher,
      options,
      publisherHandles,
      "three-dimensional regional publisher");

  publisher.rtiAmbassador().publishObjectClassAttributes(
      publisherHandles.objectClass,
      rti::AttributeHandleSet{publisherHandles.attribute});

  auto const sourceRegion = createDdmRegionForDimensions(
      publisher,
      publisherHandles.dimensions.at(0),
      publisherHandles.dimensions.at(1),
      publisherHandles.dimensions.at(2),
      0UL,
      5UL,
      0UL,
      2UL,
      0UL,
      1UL);
  auto const subscriberRegion = createDdmRegionForDimensions(
      subscriber,
      subscriberHandles.dimensions.at(0),
      subscriberHandles.dimensions.at(1),
      subscriberHandles.dimensions.at(2),
      0UL,
      5UL,
      0UL,
      2UL,
      0UL,
      1UL);
  subscriber.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  rti::AttributeHandleSetRegionHandleSetPairVector const sourcePair{{
      rti::AttributeHandleSet{publisherHandles.attribute},
      rti::RegionHandleSet{sourceRegion},
  }};
  rti::AttributeHandleSetRegionHandleSetPairVector const subscriberPair{{
      rti::AttributeHandleSet{subscriberHandles.attribute},
      rti::RegionHandleSet{subscriberRegion},
  }};
  subscriber.rtiAmbassador().subscribeObjectClassAttributesWithRegions(
      subscriberHandles.objectClass,
      subscriberPair);
  auto const object = publisher.rtiAmbassador().registerObjectInstanceWithRegions(
      publisherHandles.objectClass,
      sourcePair);
  require(
      object.isValid(),
      "three-dimensional regional registration returned an invalid handle");
  waitFor(
      subscriber,
      [&] { return subscriber.recorder().hasDiscovery(object); },
      options,
      "three-dimensional regional object discovery");
  require(
      subscriber.recorder().discovery().objectClass ==
          subscriberHandles.objectClass,
      "three-dimensional regional discovery returned the wrong class");

  auto update = [&](std::vector<std::uint8_t> value,
                    std::vector<std::uint8_t> tag) {
    rti::AttributeHandleValueMap values;
    values.emplace(
        publisherHandles.attribute,
        rti::VariableLengthData(value.data(), value.size()));
    publisher.rtiAmbassador().updateAttributeValues(
        object,
        values,
        rti::VariableLengthData(tag.data(), tag.size()));
  };
  auto assertReflection = [&](std::vector<std::uint8_t> const& expectedValue,
                              std::vector<std::uint8_t> const& expectedTag,
                              std::string const& description) {
    auto const reflection = subscriber.recorder().reflection();
    require(
        reflection.object == object &&
            reflection.values.size() == 1U &&
            reflection.values.count(subscriberHandles.attribute) == 1U &&
            copyBytes(reflection.values.at(subscriberHandles.attribute)) ==
                expectedValue,
        description + " returned the wrong attribute value");
    require(
        reflection.tag == expectedTag &&
            reflection.producer == publisher.federateHandle() &&
            reflection.transportation.isValid(),
        description + " returned the wrong metadata");
    require(
        reflection.regions.has_value() &&
            reflection.regions->size() == 1U &&
            reflection.regions->count(sourceRegion) == 1U,
        description + " omitted the source region designator");
  };

  update({0x10U}, {0x49U, 0x31U});
  waitFor(
      subscriber,
      [&] { return subscriber.recorder().reflectionCount() >= 1U; },
      options,
      "three-dimensional regional initial reflection");
  assertReflection(
      {0x10U},
      {0x49U, 0x31U},
      "three-dimensional regional initial reflection");
  auto const reflectedCount = subscriber.recorder().reflectionCount();

  auto expectSuppressed = [&](rti::DimensionHandle const& dimension,
                              rti::RangeBounds const& disjoint,
                              rti::RangeBounds const& restored,
                              std::string const& dimensionDescription) {
    publisher.rtiAmbassador().setRangeBounds(sourceRegion, dimension, disjoint);
    publisher.rtiAmbassador().commitRegionModifications(
        rti::RegionHandleSet{sourceRegion});
    update({0x20U}, {0x53U, 0x50U});
    for (int pass = 0; pass != 16; ++pass) {
      subscriber.pump();
    }
    require(
        subscriber.recorder().reflectionCount() == reflectedCount,
        "three-dimensional regional " + dimensionDescription +
            " disjoint source mutation was delivered");
    publisher.rtiAmbassador().setRangeBounds(sourceRegion, dimension, restored);
    publisher.rtiAmbassador().commitRegionModifications(
        rti::RegionHandleSet{sourceRegion});
  };
  expectSuppressed(
      publisherHandles.dimensions.at(0),
      rti::RangeBounds(6UL, 8UL),
      rti::RangeBounds(0UL, 5UL),
      "first-dimension");
  expectSuppressed(
      publisherHandles.dimensions.at(1),
      rti::RangeBounds(3UL, 4UL),
      rti::RangeBounds(0UL, 2UL),
      "second-dimension");
  expectSuppressed(
      publisherHandles.dimensions.at(2),
      rti::RangeBounds(2UL, 3UL),
      rti::RangeBounds(0UL, 1UL),
      "third-dimension");

  update({0x30U}, {0x52U, 0x31U});
  waitFor(
      subscriber,
      [&] { return subscriber.recorder().reflectionCount() > reflectedCount; },
      options,
      "three-dimensional regional restored reflection");
  assertReflection(
      {0x30U},
      {0x52U, 0x31U},
      "three-dimensional regional restored reflection");

  subscriber.rtiAmbassador().unsubscribeObjectClassAttributesWithRegions(
      subscriberHandles.objectClass,
      subscriberPair);
  publisher.rtiAmbassador().unassociateRegionsForUpdates(object, sourcePair);
  publisher.rtiAmbassador().unpublishObjectClassAttributes(
      publisherHandles.objectClass,
      rti::AttributeHandleSet{publisherHandles.attribute});
  subscriber.rtiAmbassador().deleteRegion(subscriberRegion);
  publisher.rtiAmbassador().deleteRegion(sourceRegion);
  subscriber.resign(rti::NO_ACTION);
  publisher.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  subscriber.disconnect();
  publisher.disconnect();
}

void scenarioTimestampedRegionalInteraction(
    Options const& options,
    rti::CallbackModel model) {
  Session owner(options, model, "owner");
  Session immediate(options, model, "member");
  Session constrained(options, model, "constrained");
  Session disjoint(options, model, "passive");
  auto const federation = federationName(options, "timestamped-regional-interaction");
  connectAndJoin(owner, immediate, options, federation, options.ddmFom);
  constrained.connect();
  constrained.join(
      options.memberFederateName + L"-regional-constrained",
      options.federateType,
      federation);
  disjoint.connect();
  disjoint.join(
      options.memberFederateName + L"-regional-timestamped-disjoint",
      options.federateType,
      federation);

  auto const ownerHandles = ddmHandles(owner, options);
  auto const immediateHandles = ddmHandles(immediate, options);
  auto const constrainedHandles = ddmHandles(constrained, options);
  auto const disjointHandles = ddmHandles(disjoint, options);
  verifyDdmClassDimensions(
      owner,
      options,
      ownerHandles,
      "timestamped regional interaction");

  owner.rtiAmbassador().publishInteractionClass(ownerHandles.interactionClass);
  owner.rtiAmbassador().changeInteractionOrderType(
      ownerHandles.interactionClass, rti::TIMESTAMP);
  auto const sourceRegion = createDdmRegion(owner, ownerHandles, 1UL, 5UL, 1UL, 5UL);
  auto const immediateRegion =
      createDdmRegion(immediate, immediateHandles, 2UL, 6UL, 2UL, 6UL);
  auto const constrainedRegion =
      createDdmRegion(constrained, constrainedHandles, 2UL, 6UL, 2UL, 6UL);
  auto const disjointRegion =
      createDdmRegion(disjoint, disjointHandles, 7UL, 9UL, 7UL, 9UL);
  auto const sourceRegionSet = rti::RegionHandleSet{sourceRegion};
  auto const immediateRegionSet = rti::RegionHandleSet{immediateRegion};
  auto const constrainedRegionSet = rti::RegionHandleSet{constrainedRegion};
  auto const disjointRegionSet = rti::RegionHandleSet{disjointRegion};
  immediate.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  constrained.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  disjoint.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  immediate.rtiAmbassador().subscribeInteractionClassWithRegions(
      immediateHandles.interactionClass, immediateRegionSet, true);
  constrained.rtiAmbassador().subscribeInteractionClassWithRegions(
      constrainedHandles.interactionClass, constrainedRegionSet, true);
  disjoint.rtiAmbassador().subscribeInteractionClassWithRegions(
      disjointHandles.interactionClass, disjointRegionSet, true);

  auto ownerTime = makeTimeContext(owner);
  auto constrainedTime = makeTimeContext(constrained);
  require(
      ownerTime.factory->getName() == constrainedTime.factory->getName(),
      "timestamped regional interaction members selected different logical-time factories");
  enableTimestampedRoles(
      owner,
      constrained,
      ownerTime,
      constrainedTime,
      options,
      "timestamped regional interaction");

  auto assertInteraction = [&](TimedInteractionRecord const& record,
                               rti::InteractionClassHandle const& expectedInteraction,
                               rti::ParameterHandle const& expectedParameter,
                               std::vector<std::uint8_t> const& expectedValue,
                               std::vector<std::uint8_t> const& expectedTag,
                               std::vector<std::uint8_t> const& expectedTime,
                               rti::OrderType expectedReceivedOrder,
                               Session& inspector) {
    require(record.interaction == expectedInteraction,
            "timestamped regional interaction returned the wrong class handle");
    require(record.parameters.size() == 1U &&
                record.parameters.count(expectedParameter) == 1U,
            "timestamped regional interaction returned the wrong parameter set");
    require(copyBytes(record.parameters.at(expectedParameter)) == expectedValue,
            "timestamped regional interaction returned the wrong parameter value");
    require(record.tag == expectedTag && record.time == expectedTime,
            "timestamped regional interaction did not preserve user data");
    require(record.producer == owner.federateHandle() && record.timeText.size() != 0U,
            "timestamped regional interaction returned the wrong producer or time text");
    require(record.transportation.isValid() &&
                !inspector.rtiAmbassador().getTransportationTypeName(
                    record.transportation).empty(),
            "timestamped regional interaction returned an unresolvable transport");
    require(record.sentOrder == rti::TIMESTAMP &&
                record.receivedOrder == expectedReceivedOrder,
            "timestamped regional interaction returned the wrong order metadata");
    require(record.regions.has_value() && record.regions->size() == 1U &&
                record.regions->count(sourceRegion) == 1U,
            "timestamped regional interaction omitted the source region designator set");
  };

  auto firstTime = timeAfter(
      *ownerTime.factory,
      *ownerTime.initial,
      *ownerTime.epsilon,
      3U);
  auto firstConstrainedTime = timeAfter(
      *constrainedTime.factory,
      *constrainedTime.initial,
      *constrainedTime.epsilon,
      3U);
  std::vector<std::uint8_t> firstValue{0x01U, 0x02U, 0x03U};
  std::vector<std::uint8_t> firstTag{0x51U, 0x31U};
  rti::ParameterHandleValueMap firstParameters;
  firstParameters.emplace(
      ownerHandles.parameter,
      rti::VariableLengthData(firstValue.data(), firstValue.size()));
  rti::VariableLengthData firstUserTag(firstTag.data(), firstTag.size());
  auto const firstRetraction = owner.rtiAmbassador().sendInteractionWithRegions(
      ownerHandles.interactionClass,
      firstParameters,
      sourceRegionSet,
      firstUserTag,
      *firstTime);
  require(firstRetraction.isValid(),
          "timestamped regional interaction returned an invalid retraction handle");
  waitFor(
      immediate,
      [&] { return immediate.recorder().timedInteractions().size() >= 1U; },
      options,
      "immediate timestamped regional interaction delivery");
  auto const firstImmediate = immediate.recorder().timedInteractions();
  require(firstImmediate.size() == 1U,
          "immediate regional receiver received duplicate timestamped interactions");
  assertInteraction(
      firstImmediate.front(),
      immediateHandles.interactionClass,
      immediateHandles.parameter,
      firstValue,
      firstTag,
      encodeTime(*firstTime),
      rti::RECEIVE,
      immediate);
  require(firstImmediate.front().retractionPresent &&
              firstImmediate.front().retraction == copyBytes(firstRetraction.encode()),
          "immediate regional interaction omitted its retraction handle");
  require(constrained.recorder().timedInteractions().empty(),
          "constrained regional receiver delivered before its time grant");
  for (int pass = 0; pass != 8; ++pass) {
    disjoint.pump();
  }
  require(disjoint.recorder().timedInteractions().empty(),
          "disjoint regional receiver received a timestamped interaction");

  owner.rtiAmbassador().retract(firstRetraction);
  waitFor(
      immediate,
      [&] { return immediate.recorder().retractions().size() >= 1U; },
      options,
      "timestamped regional interaction retraction callback");
  auto const immediateRetractions = immediate.recorder().retractions();
  require(immediateRetractions.size() == 1U && immediateRetractions.front().valid &&
              immediateRetractions.front().encoded == copyBytes(firstRetraction.encode()),
          "timestamped regional interaction retraction returned the wrong handle");
  require(constrained.recorder().retractions().empty(),
          "pending constrained regional interaction produced a retraction callback");

  constrained.rtiAmbassador().timeAdvanceRequest(*firstConstrainedTime);
  owner.rtiAmbassador().timeAdvanceRequest(*firstTime);
  waitFor(
      owner,
      constrained,
      [&] {
        return owner.recorder().timeAdvanceGrants().size() >= 1U &&
            constrained.recorder().timeAdvanceGrants().size() >= 1U;
      },
      options,
      "first timestamped regional interaction grants");
  for (int pass = 0; pass != 8; ++pass) {
    constrained.pump();
  }
  require(constrained.recorder().timedInteractions().empty(),
          "retracted constrained regional interaction was delivered at its grant");

  auto secondTime = timeAfter(
      *ownerTime.factory,
      *firstTime,
      *ownerTime.epsilon,
      3U);
  auto secondConstrainedTime = timeAfter(
      *constrainedTime.factory,
      *firstConstrainedTime,
      *constrainedTime.epsilon,
      3U);
  std::vector<std::uint8_t> secondValue{0x21U, 0x22U};
  std::vector<std::uint8_t> secondTag{0x51U, 0x32U};
  rti::ParameterHandleValueMap secondParameters;
  secondParameters.emplace(
      ownerHandles.parameter,
      rti::VariableLengthData(secondValue.data(), secondValue.size()));
  rti::VariableLengthData secondUserTag(secondTag.data(), secondTag.size());
  auto const secondRetraction = owner.rtiAmbassador().sendInteractionWithRegions(
      ownerHandles.interactionClass,
      secondParameters,
      sourceRegionSet,
      secondUserTag,
      *secondTime);
  require(secondRetraction.isValid(),
          "second timestamped regional interaction returned an invalid retraction handle");
  waitFor(
      immediate,
      [&] { return immediate.recorder().timedInteractions().size() >= 2U; },
      options,
      "second immediate timestamped regional interaction delivery");
  auto const secondImmediate = immediate.recorder().timedInteractions();
  require(secondImmediate.size() == 2U,
          "immediate regional receiver received duplicate second interactions");
  assertInteraction(
      secondImmediate.at(1),
      immediateHandles.interactionClass,
      immediateHandles.parameter,
      secondValue,
      secondTag,
      encodeTime(*secondTime),
      rti::RECEIVE,
      immediate);
  require(secondImmediate.at(1).retractionPresent &&
              secondImmediate.at(1).retraction == copyBytes(secondRetraction.encode()),
          "second immediate regional interaction omitted its retraction handle");

  constrained.rtiAmbassador().timeAdvanceRequest(*secondConstrainedTime);
  owner.rtiAmbassador().timeAdvanceRequest(*secondTime);
  waitFor(
      owner,
      constrained,
      [&] {
        return owner.recorder().timeAdvanceGrants().size() >= 2U &&
            constrained.recorder().timeAdvanceGrants().size() >= 2U &&
            constrained.recorder().timedInteractions().size() >= 1U;
      },
      options,
      "second timestamped regional interaction delivery and grants");
  auto const constrainedInteractions = constrained.recorder().timedInteractions();
  require(constrainedInteractions.size() == 1U,
          "constrained regional receiver received the wrong interaction count");
  assertInteraction(
      constrainedInteractions.front(),
      constrainedHandles.interactionClass,
      constrainedHandles.parameter,
      secondValue,
      secondTag,
      encodeTime(*secondTime),
      rti::TIMESTAMP,
      constrained);
  require(constrainedInteractions.front().retractionPresent &&
              constrainedInteractions.front().retraction ==
                  copyBytes(secondRetraction.encode()),
          "constrained regional interaction omitted its retraction handle");
  requireException(
      [&] { owner.rtiAmbassador().retract(secondRetraction); },
      L"MessageCanNoLongerBeRetracted",
      "retraction after constrained regional interaction delivery");

  constrained.rtiAmbassador().disableTimeConstrained();
  owner.rtiAmbassador().disableTimeRegulation();
  immediate.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      immediateHandles.interactionClass, immediateRegionSet);
  constrained.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      constrainedHandles.interactionClass, constrainedRegionSet);
  disjoint.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      disjointHandles.interactionClass, disjointRegionSet);
  owner.rtiAmbassador().unpublishInteractionClass(ownerHandles.interactionClass);
  owner.rtiAmbassador().deleteRegion(sourceRegion);
  immediate.rtiAmbassador().deleteRegion(immediateRegion);
  constrained.rtiAmbassador().deleteRegion(constrainedRegion);
  disjoint.rtiAmbassador().deleteRegion(disjointRegion);

  owner.resign(rti::NO_ACTION);
  immediate.resign(rti::NO_ACTION);
  constrained.resign(rti::NO_ACTION);
  disjoint.resign(rti::NO_ACTION);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  owner.disconnect();
  immediate.disconnect();
  constrained.disconnect();
  disjoint.disconnect();
}

void scenarioTimestampedRegionalInteractionRegulationReenable(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.logicalTimeImplementationName.empty(),
      "Timestamped regional interaction regulation re-enable requires an adapter-supplied logical-time implementation");
  require(
      !options.ddmFom.empty(),
      "Timestamped regional interaction regulation re-enable requires an adapter-supplied dimensional FOM");

  Session publisher(options, model, "owner");
  Session receiver(options, model, "constrained");
  auto const federation = federationName(
      options,
      "timestamped-regional-interaction-regulation-reenable");
  connectAndJoin(publisher, receiver, options, federation, options.ddmFom);

  auto const publisherHandles = ddmHandles(publisher, options);
  auto const receiverHandles = ddmHandles(receiver, options);
  verifyDdmClassDimensions(
      publisher,
      options,
      publisherHandles,
      "timestamped regional interaction regulation re-enable");

  publisher.rtiAmbassador().publishInteractionClass(
      publisherHandles.interactionClass);
  publisher.rtiAmbassador().changeInteractionOrderType(
      publisherHandles.interactionClass,
      rti::TIMESTAMP);
  auto const sourceRegion = createDdmRegion(
      publisher,
      publisherHandles,
      1UL,
      5UL,
      1UL,
      5UL);
  auto const receiverRegion = createDdmRegion(
      receiver,
      receiverHandles,
      2UL,
      6UL,
      2UL,
      6UL);
  auto const sourceRegionSet = rti::RegionHandleSet{sourceRegion};
  auto const receiverRegionSet = rti::RegionHandleSet{receiverRegion};
  receiver.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  receiver.rtiAmbassador().subscribeInteractionClassWithRegions(
      receiverHandles.interactionClass,
      receiverRegionSet,
      true);

  auto publisherTime = makeTimeContext(publisher);
  auto receiverTime = makeTimeContext(receiver);
  enableTimestampedRoles(
      publisher,
      receiver,
      publisherTime,
      receiverTime,
      options,
      "timestamped regional interaction regulation re-enable");

  auto const interactionTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      5U);
  auto const publisherTarget = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      2U);
  auto const changedLookaheadTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      3U);
  auto changedLookahead = publisherTime.factory->makeZero();
  require(
      changedLookahead != nullptr,
      "timestamped regional interaction regulation re-enable could not allocate the changed lookahead");
  changedLookahead->setToDifference(
      *changedLookaheadTime,
      *publisherTime.initial);

  std::vector<std::uint8_t> parameterBytes{0xC7U, 0x19U};
  std::vector<std::uint8_t> tagBytes{0x52U, 0x47U, 0x43U, 0x48U};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      publisherHandles.parameter,
      rti::VariableLengthData(parameterBytes.data(), parameterBytes.size()));
  rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());
  auto const retraction = publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      parameters,
      sourceRegionSet,
      tag,
      *interactionTime);
  require(
      retraction.isValid(),
      "timestamped regional interaction regulation re-enable send returned an invalid retraction handle");
  require(
      receiver.recorder().timedInteractions().empty(),
      "timestamped regional interaction regulation re-enable delivered before its grant");

  // Move the live source out of overlap after admission. The queued passel
  // must retain its invocation-time source-region snapshot.
  publisher.rtiAmbassador().setRangeBounds(
      sourceRegion,
      publisherHandles.firstDimension,
      rti::RangeBounds(7UL, 9UL));
  publisher.rtiAmbassador().setRangeBounds(
      sourceRegion,
      publisherHandles.secondDimension,
      rti::RangeBounds(7UL, 9UL));
  publisher.rtiAmbassador().commitRegionModifications(
      rti::RegionHandleSet{sourceRegion});

  publisher.rtiAmbassador().disableTimeRegulation();
  publisher.rtiAmbassador().enableTimeRegulation(*changedLookahead);
  waitFor(
      publisher,
      [&] { return publisher.recorder().timeRegulationEnabled().size() >= 2U; },
      options,
      "timestamped regional interaction regulation re-enable callback");
  auto queriedLookahead = publisherTime.factory->makeZero();
  require(
      queriedLookahead != nullptr,
      "timestamped regional interaction regulation re-enable could not allocate a lookahead query");
  publisher.rtiAmbassador().queryLookahead(*queriedLookahead);
  require(
      *queriedLookahead == *changedLookahead,
      "timestamped regional interaction regulation re-enable did not expose the changed lookahead");

  receiver.recorder().clearCallbackOrder();
  publisher.recorder().clearCallbackOrder();
  receiver.rtiAmbassador().timeAdvanceRequest(*interactionTime);
  require(
      receiver.recorder().timedInteractions().empty(),
      "timestamped regional interaction regulation re-enable delivered while the producer boundary was pending");
  publisher.rtiAmbassador().timeAdvanceRequest(*publisherTarget);
  waitFor(
      publisher,
      receiver,
      [&] {
        return publisher.recorder().timeAdvanceGrants().size() >= 1U &&
            receiver.recorder().timeAdvanceGrants().size() >= 1U &&
            receiver.recorder().timedInteractions().size() >= 1U;
      },
      options,
      "timestamped regional interaction regulation re-enable delivery");

  auto const interactions = receiver.recorder().timedInteractions();
  require(
      interactions.size() == 1U &&
          publisher.recorder().timeRegulationEnabled().size() == 2U,
      "timestamped regional interaction regulation re-enable returned the wrong callback counts");
  require(
      receiver.recorder().callbackOrder() ==
          std::vector<std::string>{"interaction", "grant"},
      "timestamped regional interaction regulation re-enable delivered after its grant");
  auto const& interaction = interactions.front();
  require(
      interaction.interaction == receiverHandles.interactionClass &&
          interaction.parameters.size() == 1U &&
          interaction.parameters.count(receiverHandles.parameter) == 1U &&
          copyBytes(interaction.parameters.at(receiverHandles.parameter)) == parameterBytes,
      "timestamped regional interaction regulation re-enable returned the wrong class or parameter");
  require(
      interaction.tag == tagBytes &&
          interaction.time == encodeTime(*interactionTime) &&
          !interaction.timeText.empty(),
      "timestamped regional interaction regulation re-enable did not preserve value metadata");
  require(
      interaction.producer == publisher.federateHandle() &&
          interaction.sentOrder == rti::TIMESTAMP &&
          interaction.receivedOrder == rti::TIMESTAMP,
      "timestamped regional interaction regulation re-enable returned the wrong producer or order");
  require(
      interaction.transportation.isValid() &&
          !receiver.rtiAmbassador().getTransportationTypeName(
              interaction.transportation).empty(),
      "timestamped regional interaction regulation re-enable returned an unresolvable transport");
  require(
      interaction.regions.has_value() &&
          interaction.regions->size() == 1U &&
          interaction.regions->count(sourceRegion) == 1U,
      "timestamped regional interaction regulation re-enable did not preserve the source region snapshot");
  require(
      interaction.retractionPresent &&
          interaction.retraction == copyBytes(retraction.encode()),
      "timestamped regional interaction regulation re-enable omitted the retraction handle");
  require(
      publisher.recorder().timeAdvanceGrants().front().encoded ==
          encodeTime(*publisherTarget),
      "timestamped regional interaction regulation re-enable returned the wrong producer grant");
  require(
      receiver.recorder().timeAdvanceGrants().front().encoded ==
          encodeTime(*interactionTime),
      "timestamped regional interaction regulation re-enable returned the wrong receiver grant");
  requireException(
      [&] { publisher.rtiAmbassador().retract(retraction); },
      L"MessageCanNoLongerBeRetracted",
      "timestamped regional interaction regulation re-enable retraction after delivery");

  receiver.rtiAmbassador().disableTimeConstrained();
  publisher.rtiAmbassador().disableTimeRegulation();
  receiver.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      receiverHandles.interactionClass,
      receiverRegionSet);
  receiver.rtiAmbassador().deleteRegion(receiverRegion);
  publisher.rtiAmbassador().deleteRegion(sourceRegion);
  publisher.rtiAmbassador().unpublishInteractionClass(
      publisherHandles.interactionClass);
  receiver.resign(rti::NO_ACTION);
  publisher.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  receiver.disconnect();
  publisher.disconnect();
}

void scenarioTimestampedRegionalInteractionAlternateAdvances(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.ddmFom.empty(),
      "Timestamped regional interaction alternate advances require an adapter-supplied dimensional FOM");
  require(
      !options.logicalTimeImplementationName.empty(),
      "Timestamped regional interaction alternate advances require an adapter-supplied logical-time implementation");

  Session publisher(options, model, "owner");
  Session flushQueue(options, model, "member");
  Session timeAdvanceAvailable(options, model, "member");
  Session nextMessageAvailable(options, model, "member");
  auto const federation = federationName(
      options,
      "timestamped-regional-interaction-alternate-advances");
  connectAndJoin(publisher, flushQueue, options, federation, options.ddmFom);
  timeAdvanceAvailable.connect();
  timeAdvanceAvailable.join(
      options.memberFederateName + L"-regional-interaction-tara",
      options.federateType,
      federation);
  nextMessageAvailable.connect();
  nextMessageAvailable.join(
      options.memberFederateName + L"-regional-interaction-nmra",
      options.federateType,
      federation);

  auto const publisherHandles = ddmHandles(publisher, options);
  auto const flushQueueHandles = ddmHandles(flushQueue, options);
  auto const timeAdvanceAvailableHandles = ddmHandles(timeAdvanceAvailable, options);
  auto const nextMessageAvailableHandles = ddmHandles(nextMessageAvailable, options);
  verifyDdmClassDimensions(
      publisher,
      options,
      publisherHandles,
      "timestamped regional interaction alternate advances");

  publisher.rtiAmbassador().publishInteractionClass(
      publisherHandles.interactionClass);
  publisher.rtiAmbassador().changeInteractionOrderType(
      publisherHandles.interactionClass,
      rti::TIMESTAMP);

  auto const sourceRegion = createDdmRegion(
      publisher,
      publisherHandles,
      1UL,
      5UL,
      1UL,
      5UL);
  auto const flushQueueRegion = createDdmRegion(
      flushQueue,
      flushQueueHandles,
      2UL,
      6UL,
      2UL,
      6UL);
  auto const timeAdvanceAvailableRegion = createDdmRegion(
      timeAdvanceAvailable,
      timeAdvanceAvailableHandles,
      2UL,
      6UL,
      2UL,
      6UL);
  auto const nextMessageAvailableRegion = createDdmRegion(
      nextMessageAvailable,
      nextMessageAvailableHandles,
      2UL,
      6UL,
      2UL,
      6UL);
  auto const sourceRegionSet = rti::RegionHandleSet{sourceRegion};
  auto const flushQueueRegionSet = rti::RegionHandleSet{flushQueueRegion};
  auto const timeAdvanceAvailableRegionSet =
      rti::RegionHandleSet{timeAdvanceAvailableRegion};
  auto const nextMessageAvailableRegionSet =
      rti::RegionHandleSet{nextMessageAvailableRegion};
  flushQueue.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  timeAdvanceAvailable.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  nextMessageAvailable.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  require(
      flushQueue.rtiAmbassador().getConveyRegionDesignatorSetsSwitch() &&
          timeAdvanceAvailable.rtiAmbassador().getConveyRegionDesignatorSetsSwitch() &&
          nextMessageAvailable.rtiAmbassador().getConveyRegionDesignatorSetsSwitch(),
      "timestamped regional interaction alternate recipients did not enable region designator callbacks");
  flushQueue.rtiAmbassador().subscribeInteractionClassWithRegions(
      flushQueueHandles.interactionClass,
      flushQueueRegionSet,
      true);
  timeAdvanceAvailable.rtiAmbassador().subscribeInteractionClassWithRegions(
      timeAdvanceAvailableHandles.interactionClass,
      timeAdvanceAvailableRegionSet,
      true);
  nextMessageAvailable.rtiAmbassador().subscribeInteractionClassWithRegions(
      nextMessageAvailableHandles.interactionClass,
      nextMessageAvailableRegionSet,
      true);

  auto publisherTime = makeTimeContext(publisher);
  auto flushQueueTime = makeTimeContext(flushQueue);
  auto timeAdvanceAvailableTime = makeTimeContext(timeAdvanceAvailable);
  auto nextMessageAvailableTime = makeTimeContext(nextMessageAvailable);
  require(
      publisherTime.factory->getName() == flushQueueTime.factory->getName() &&
          publisherTime.factory->getName() == timeAdvanceAvailableTime.factory->getName() &&
          publisherTime.factory->getName() == nextMessageAvailableTime.factory->getName(),
      "timestamped regional interaction alternate members selected different logical-time factories");
  for (auto* member :
       std::vector<Session*>{&flushQueue, &timeAdvanceAvailable, &nextMessageAvailable}) {
    member->rtiAmbassador().enableTimeConstrained();
    waitFor(
        *member,
        [&] { return member->recorder().timeConstrainedEnabled().size() >= 1U; },
        options,
        "timestamped regional interaction alternate time-constrained callback");
  }
  publisher.rtiAmbassador().enableTimeRegulation(*publisherTime.epsilon);
  waitFor(
      publisher,
      [&] { return publisher.recorder().timeRegulationEnabled().size() >= 1U; },
      options,
      "timestamped regional interaction alternate time-regulation callback");

  auto const messageTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      3U);
  auto const publisherTarget = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      2U);
  auto const requestBoundary = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      5U);
  std::vector<std::uint8_t> parameterBytes{0x61U, 0x62U, 0x63U};
  std::vector<std::uint8_t> tagBytes{0x52U, 0x49U, 0x41U};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      publisherHandles.parameter,
      rti::VariableLengthData(parameterBytes.data(), parameterBytes.size()));
  rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());
  auto const retraction = publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      parameters,
      sourceRegionSet,
      tag,
      *messageTime);
  require(
      retraction.isValid(),
      "timestamped regional interaction alternate send returned an invalid retraction handle");
  require(
      flushQueue.recorder().timedInteractions().empty() &&
          timeAdvanceAvailable.recorder().timedInteractions().empty() &&
          nextMessageAvailable.recorder().timedInteractions().empty(),
      "timestamped regional interaction alternate recipient received an interaction before its request");
  flushQueue.recorder().clearCallbackOrder();
  timeAdvanceAvailable.recorder().clearCallbackOrder();
  nextMessageAvailable.recorder().clearCallbackOrder();
  publisher.recorder().clearCallbackOrder();

  flushQueue.rtiAmbassador().flushQueueRequest(*requestBoundary);
  timeAdvanceAvailable.rtiAmbassador().timeAdvanceRequestAvailable(*messageTime);
  nextMessageAvailable.rtiAmbassador().nextMessageRequestAvailable(*requestBoundary);
  publisher.rtiAmbassador().timeAdvanceRequest(*publisherTarget);

  waitForSessions(
      {&publisher, &flushQueue, &timeAdvanceAvailable, &nextMessageAvailable},
      [&] {
        return publisher.recorder().timeAdvanceGrants().size() >= 1U &&
            flushQueue.recorder().timedInteractions().size() >= 1U &&
            flushQueue.recorder().flushQueueGrants().size() >= 1U &&
            timeAdvanceAvailable.recorder().timedInteractions().size() >= 1U &&
            timeAdvanceAvailable.recorder().timeAdvanceGrants().size() >= 1U &&
            nextMessageAvailable.recorder().timedInteractions().size() >= 1U &&
            nextMessageAvailable.recorder().timeAdvanceGrants().size() >= 1U;
      },
      options,
      "timestamped regional interaction alternate delivery and grants");

  require(
      publisher.recorder().timeAdvanceGrants().size() == 1U,
      "timestamped regional interaction alternate publisher received the wrong grant count");
  require(
      flushQueue.recorder().timedInteractions().size() == 1U &&
          flushQueue.recorder().flushQueueGrants().size() == 1U &&
          flushQueue.recorder().timeAdvanceGrants().empty(),
      "timestamped regional interaction Flush Queue Request returned the wrong callback pair");
  require(
      timeAdvanceAvailable.recorder().timedInteractions().size() == 1U &&
          timeAdvanceAvailable.recorder().timeAdvanceGrants().size() == 1U &&
          timeAdvanceAvailable.recorder().flushQueueGrants().empty(),
      "timestamped regional interaction Time Advance Request Available returned the wrong callback pair");
  require(
      nextMessageAvailable.recorder().timedInteractions().size() == 1U &&
          nextMessageAvailable.recorder().timeAdvanceGrants().size() == 1U &&
          nextMessageAvailable.recorder().flushQueueGrants().empty(),
      "timestamped regional interaction Next Message Request Available returned the wrong callback pair");
  require(
      flushQueue.recorder().callbackOrder() ==
          std::vector<std::string>{"interaction", "flush-grant"},
      "timestamped regional interaction Flush Queue Request granted before delivery");
  require(
      timeAdvanceAvailable.recorder().callbackOrder() ==
          std::vector<std::string>{"interaction", "grant"},
      "timestamped regional interaction Time Advance Request Available granted before delivery");
  require(
      nextMessageAvailable.recorder().callbackOrder() ==
          std::vector<std::string>{"interaction", "grant"},
      "timestamped regional interaction Next Message Request Available granted before delivery");

  auto assertInteraction = [&](TimedInteractionRecord const& record,
                               rti::InteractionClassHandle const& expectedInteraction,
                               rti::ParameterHandle const& expectedParameter,
                               Session& inspector) {
    require(
        record.interaction == expectedInteraction &&
            record.parameters.size() == 1U &&
            record.parameters.count(expectedParameter) == 1U,
        "timestamped regional interaction alternate callback returned the wrong class or parameters");
    require(
        copyBytes(record.parameters.at(expectedParameter)) == parameterBytes &&
            record.tag == tagBytes,
        "timestamped regional interaction alternate callback did not preserve parameter or tag data");
    require(
        record.producer == publisher.federateHandle() &&
            record.time == encodeTime(*messageTime) &&
            !record.timeText.empty(),
        "timestamped regional interaction alternate callback returned the wrong producer or time");
    require(
        record.transportation.isValid() &&
            !inspector.rtiAmbassador().getTransportationTypeName(record.transportation).empty(),
        "timestamped regional interaction alternate callback returned an unresolvable transport");
    require(
        record.sentOrder == rti::TIMESTAMP && record.receivedOrder == rti::TIMESTAMP,
        "timestamped regional interaction alternate callback returned the wrong order metadata");
    require(
        record.regions.has_value() && record.regions->size() == 1U &&
            record.regions->count(sourceRegion) == 1U,
        "timestamped regional interaction alternate callback omitted the source region designator");
    require(
        record.retractionPresent && record.retraction == copyBytes(retraction.encode()),
        "timestamped regional interaction alternate callback omitted the retraction handle");
  };
  assertInteraction(
      flushQueue.recorder().timedInteractions().front(),
      flushQueueHandles.interactionClass,
      flushQueueHandles.parameter,
      flushQueue);
  assertInteraction(
      timeAdvanceAvailable.recorder().timedInteractions().front(),
      timeAdvanceAvailableHandles.interactionClass,
      timeAdvanceAvailableHandles.parameter,
      timeAdvanceAvailable);
  assertInteraction(
      nextMessageAvailable.recorder().timedInteractions().front(),
      nextMessageAvailableHandles.interactionClass,
      nextMessageAvailableHandles.parameter,
      nextMessageAvailable);

  require(
      publisher.recorder().timeAdvanceGrants().front().encoded ==
          encodeTime(*publisherTarget),
      "timestamped regional interaction alternate publisher received the wrong grant time");
  auto const flushGrants = flushQueue.recorder().flushQueueGrants();
  require(
      flushGrants.front().optimisticTime == encodeTime(*messageTime),
      "timestamped regional interaction Flush Queue Grant returned the wrong optimistic time");
  require(
      !flushGrants.front().time.empty() && !flushGrants.front().timeText.empty() &&
          !flushGrants.front().optimisticTimeText.empty(),
      "timestamped regional interaction Flush Queue Grant returned incomplete time metadata");
  auto actualFlushTime = decodeTime(*flushQueueTime.factory, flushGrants.front().time);
  auto optimisticFlushTime =
      decodeTime(*flushQueueTime.factory, flushGrants.front().optimisticTime);
  require(
      actualFlushTime != nullptr && optimisticFlushTime != nullptr &&
          !(*actualFlushTime < *flushQueueTime.initial) &&
          !(*requestBoundary < *actualFlushTime) &&
          !(*optimisticFlushTime < *actualFlushTime),
      "timestamped regional interaction Flush Queue Grant returned time outside standard bounds");
  require(
      timeAdvanceAvailable.recorder().timeAdvanceGrants().front().encoded ==
          encodeTime(*messageTime) &&
          nextMessageAvailable.recorder().timeAdvanceGrants().front().encoded ==
              encodeTime(*messageTime),
      "timestamped regional interaction alternate grants returned the wrong logical time");

  auto queriedFlushQueue = flushQueueTime.factory->makeInitial();
  flushQueue.rtiAmbassador().queryLogicalTime(*queriedFlushQueue);
  require(
      encodeTime(*queriedFlushQueue) == flushGrants.front().time,
      "timestamped regional interaction Flush Queue Request query did not match its grant");
  auto queriedTimeAdvanceAvailable = timeAdvanceAvailableTime.factory->makeInitial();
  timeAdvanceAvailable.rtiAmbassador().queryLogicalTime(*queriedTimeAdvanceAvailable);
  requireTimeEquals(
      *queriedTimeAdvanceAvailable,
      *messageTime,
      "timestamped regional interaction Time Advance Request Available logical-time query");
  auto queriedNextMessageAvailable = nextMessageAvailableTime.factory->makeInitial();
  nextMessageAvailable.rtiAmbassador().queryLogicalTime(*queriedNextMessageAvailable);
  requireTimeEquals(
      *queriedNextMessageAvailable,
      *messageTime,
      "timestamped regional interaction Next Message Request Available logical-time query");

  auto const pastFlushQueueTime = timeAfter(
      *flushQueueTime.factory,
      *flushQueueTime.initial,
      *flushQueueTime.epsilon,
      1U);
  auto const pastTimeAdvanceAvailableTime = timeAfter(
      *timeAdvanceAvailableTime.factory,
      *timeAdvanceAvailableTime.initial,
      *timeAdvanceAvailableTime.epsilon,
      1U);
  auto const pastNextMessageAvailableTime = timeAfter(
      *nextMessageAvailableTime.factory,
      *nextMessageAvailableTime.initial,
      *nextMessageAvailableTime.epsilon,
      1U);
  requireException(
      [&] { flushQueue.rtiAmbassador().flushQueueRequest(*pastFlushQueueTime); },
      L"LogicalTimeAlreadyPassed",
      "timestamped regional interaction Flush Queue Request before current time");
  requireException(
      [&] {
        timeAdvanceAvailable.rtiAmbassador().timeAdvanceRequestAvailable(
            *pastTimeAdvanceAvailableTime);
      },
      L"LogicalTimeAlreadyPassed",
      "timestamped regional interaction Time Advance Request Available before current time");
  requireException(
      [&] {
        nextMessageAvailable.rtiAmbassador().nextMessageRequestAvailable(
            *pastNextMessageAvailableTime);
      },
      L"LogicalTimeAlreadyPassed",
      "timestamped regional interaction Next Message Request Available before current time");
  requireException(
      [&] { publisher.rtiAmbassador().retract(retraction); },
      L"MessageCanNoLongerBeRetracted",
      "timestamped regional interaction alternate retraction after delivery");

  flushQueue.rtiAmbassador().disableTimeConstrained();
  timeAdvanceAvailable.rtiAmbassador().disableTimeConstrained();
  nextMessageAvailable.rtiAmbassador().disableTimeConstrained();
  publisher.rtiAmbassador().disableTimeRegulation();
  flushQueue.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      flushQueueHandles.interactionClass,
      flushQueueRegionSet);
  timeAdvanceAvailable.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      timeAdvanceAvailableHandles.interactionClass,
      timeAdvanceAvailableRegionSet);
  nextMessageAvailable.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      nextMessageAvailableHandles.interactionClass,
      nextMessageAvailableRegionSet);
  publisher.rtiAmbassador().unpublishInteractionClass(
      publisherHandles.interactionClass);
  flushQueue.rtiAmbassador().deleteRegion(flushQueueRegion);
  timeAdvanceAvailable.rtiAmbassador().deleteRegion(timeAdvanceAvailableRegion);
  nextMessageAvailable.rtiAmbassador().deleteRegion(nextMessageAvailableRegion);
  publisher.rtiAmbassador().deleteRegion(sourceRegion);
  nextMessageAvailable.resign(rti::NO_ACTION);
  timeAdvanceAvailable.resign(rti::NO_ACTION);
  flushQueue.resign(rti::NO_ACTION);
  publisher.resign(rti::NO_ACTION);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  nextMessageAvailable.disconnect();
  timeAdvanceAvailable.disconnect();
  flushQueue.disconnect();
  publisher.disconnect();
}

void scenarioTimestampedRegionalInteractionNoOverlap(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.ddmFom.empty(),
      "Timestamped regional interaction no-overlap requires an adapter-supplied dimensional FOM");
  require(
      !options.logicalTimeImplementationName.empty(),
      "Timestamped regional interaction no-overlap requires an adapter-supplied logical-time implementation");

  Session publisher(options, model, "owner");
  Session receiver(options, model, "passive");
  auto const federation = federationName(
      options,
      "timestamped-regional-interaction-no-overlap");
  connectAndJoin(publisher, receiver, options, federation, options.ddmFom);

  auto const publisherHandles = ddmHandles(publisher, options);
  auto const receiverHandles = ddmHandles(receiver, options);
  verifyDdmClassDimensions(
      publisher,
      options,
      publisherHandles,
      "timestamped regional interaction no-overlap");
  publisher.rtiAmbassador().publishInteractionClass(
      publisherHandles.interactionClass);
  publisher.rtiAmbassador().changeInteractionOrderType(
      publisherHandles.interactionClass,
      rti::TIMESTAMP);

  auto const publisherRegion = createDdmRegion(
      publisher,
      publisherHandles,
      1UL,
      5UL,
      1UL,
      5UL);
  auto const receiverRegion = createDdmRegion(
      receiver,
      receiverHandles,
      7UL,
      9UL,
      7UL,
      9UL);
  auto const publisherRegionSet = rti::RegionHandleSet{publisherRegion};
  auto const receiverRegionSet = rti::RegionHandleSet{receiverRegion};
  receiver.rtiAmbassador().subscribeInteractionClassWithRegions(
      receiverHandles.interactionClass,
      receiverRegionSet,
      true);

  auto publisherTime = makeTimeContext(publisher);
  auto receiverTime = makeTimeContext(receiver);
  require(
      publisherTime.factory->getName() == receiverTime.factory->getName(),
      "timestamped regional interaction no-overlap members selected different logical-time factories");
  receiver.rtiAmbassador().enableTimeConstrained();
  waitFor(
      receiver,
      [&] { return receiver.recorder().timeConstrainedEnabled().size() >= 1U; },
      options,
      "timestamped regional interaction no-overlap time-constrained callback");
  publisher.rtiAmbassador().enableTimeRegulation(*publisherTime.epsilon);
  waitFor(
      publisher,
      [&] { return publisher.recorder().timeRegulationEnabled().size() >= 1U; },
      options,
      "timestamped regional interaction no-overlap time-regulation callback");

  auto const messageTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      6U);
  auto const publisherAdvance = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      1U);
  std::vector<std::uint8_t> parameterBytes{0x4EU, 0x4FU};
  std::vector<std::uint8_t> tagBytes{0x4FU, 0x56U, 0x45U, 0x52U};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      publisherHandles.parameter,
      rti::VariableLengthData(parameterBytes.data(), parameterBytes.size()));
  rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());

  auto const retractable = publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      parameters,
      publisherRegionSet,
      tag,
      *messageTime);
  require(
      retractable.isValid(),
      "timestamped regional interaction no-overlap send returned an invalid retraction handle");
  require(
      receiver.recorder().timedInteractions().empty(),
      "timestamped regional interaction no-overlap receiver received a filtered interaction");
  publisher.rtiAmbassador().retract(retractable);
  requireException(
      [&] { publisher.rtiAmbassador().retract(retractable); },
      L"MessageCanNoLongerBeRetracted",
      "timestamped regional interaction no-overlap second retraction");

  auto const expired = publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      parameters,
      publisherRegionSet,
      tag,
      *messageTime);
  require(
      expired.isValid(),
      "timestamped regional interaction no-overlap second send returned an invalid retraction handle");
  publisher.rtiAmbassador().timeAdvanceRequest(*publisherAdvance);
  waitFor(
      publisher,
      [&] { return publisher.recorder().timeAdvanceGrants().size() >= 1U; },
      options,
      "timestamped regional interaction no-overlap producer advance");
  requireException(
      [&] { publisher.rtiAmbassador().retract(expired); },
      L"MessageCanNoLongerBeRetracted",
      "timestamped regional interaction no-overlap expired retraction");
  for (int pass = 0; pass != 8; ++pass) {
    receiver.pump();
  }
  require(
      receiver.recorder().timedInteractions().empty(),
      "timestamped regional interaction no-overlap receiver received a later filtered interaction");

  receiver.rtiAmbassador().disableTimeConstrained();
  publisher.rtiAmbassador().disableTimeRegulation();
  receiver.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      receiverHandles.interactionClass,
      receiverRegionSet);
  receiver.rtiAmbassador().deleteRegion(receiverRegion);
  publisher.rtiAmbassador().deleteRegion(publisherRegion);
  publisher.rtiAmbassador().unpublishInteractionClass(
      publisherHandles.interactionClass);
  receiver.resign(rti::NO_ACTION);
  publisher.resign(rti::NO_ACTION);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  receiver.disconnect();
  publisher.disconnect();
}

void scenarioTimestampedRegionalInteractionSubscriptionReplacement(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.ddmFom.empty(),
      "Timestamped regional interaction subscription replacement requires an adapter-supplied dimensional FOM");
  require(
      !options.logicalTimeImplementationName.empty(),
      "Timestamped regional interaction subscription replacement requires an adapter-supplied logical-time implementation");

  Session publisher(options, model, "owner");
  Session receiver(options, model, "constrained");
  auto const federation = federationName(
      options,
      "timestamped-regional-interaction-subscription-replacement");
  connectAndJoin(publisher, receiver, options, federation, options.ddmFom);

  auto const publisherHandles = ddmHandles(publisher, options);
  auto const receiverHandles = ddmHandles(receiver, options);
  verifyDdmClassDimensions(
      publisher,
      options,
      publisherHandles,
      "timestamped regional interaction subscription replacement");
  publisher.rtiAmbassador().publishInteractionClass(
      publisherHandles.interactionClass);
  publisher.rtiAmbassador().changeInteractionOrderType(
      publisherHandles.interactionClass,
      rti::TIMESTAMP);

  auto const sourceRegionA = createDdmRegion(
      publisher,
      publisherHandles,
      0UL,
      1UL,
      0UL,
      1UL);
  auto const sourceRegionB = createDdmRegion(
      publisher,
      publisherHandles,
      2UL,
      3UL,
      2UL,
      3UL);
  auto const receiverRegionA = createDdmRegion(
      receiver,
      receiverHandles,
      0UL,
      1UL,
      0UL,
      1UL);
  auto const receiverRegionB = createDdmRegion(
      receiver,
      receiverHandles,
      2UL,
      3UL,
      2UL,
      3UL);
  auto const sourceRegionSetA = rti::RegionHandleSet{sourceRegionA};
  auto const sourceRegionSetB = rti::RegionHandleSet{sourceRegionB};
  auto const receiverRegionSetA = rti::RegionHandleSet{receiverRegionA};
  auto const receiverRegionSetB = rti::RegionHandleSet{receiverRegionB};
  receiver.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  require(
      receiver.rtiAmbassador().getConveyRegionDesignatorSetsSwitch(),
      "timestamped regional interaction subscription replacement did not enable region designator callbacks");
  receiver.rtiAmbassador().subscribeInteractionClassWithRegions(
      receiverHandles.interactionClass,
      receiverRegionSetA,
      true);

  auto publisherTime = makeTimeContext(publisher);
  auto receiverTime = makeTimeContext(receiver);
  require(
      publisherTime.factory->getName() == receiverTime.factory->getName(),
      "timestamped regional interaction subscription replacement members selected different logical-time factories");
  receiver.rtiAmbassador().enableTimeConstrained();
  waitFor(
      receiver,
      [&] { return receiver.recorder().timeConstrainedEnabled().size() >= 1U; },
      options,
      "timestamped regional interaction subscription replacement time-constrained callback");
  publisher.rtiAmbassador().enableTimeRegulation(*publisherTime.epsilon);
  waitFor(
      publisher,
      [&] { return publisher.recorder().timeRegulationEnabled().size() >= 1U; },
      options,
      "timestamped regional interaction subscription replacement time-regulation callback");
  receiver.recorder().clearCallbackOrder();
  publisher.recorder().clearCallbackOrder();

  auto const firstTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      6U);
  auto const firstPublisherTarget = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      2U);
  std::vector<std::uint8_t> firstParameterBytes{0x49U, 0x52U, 0x31U};
  std::vector<std::uint8_t> secondParameterBytes{0x49U, 0x52U, 0x32U};
  std::vector<std::uint8_t> firstTagBytes{0x53U, 0x55U, 0x42U, 0x31U};
  std::vector<std::uint8_t> secondTagBytes{0x53U, 0x55U, 0x42U, 0x32U};
  rti::ParameterHandleValueMap firstParameters;
  firstParameters.emplace(
      publisherHandles.parameter,
      rti::VariableLengthData(
          firstParameterBytes.data(),
          firstParameterBytes.size()));
  rti::ParameterHandleValueMap secondParameters;
  secondParameters.emplace(
      publisherHandles.parameter,
      rti::VariableLengthData(
          secondParameterBytes.data(),
          secondParameterBytes.size()));
  rti::VariableLengthData firstTag(firstTagBytes.data(), firstTagBytes.size());
  rti::VariableLengthData secondTag(secondTagBytes.data(), secondTagBytes.size());

  auto const firstRetraction = publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      firstParameters,
      sourceRegionSetA,
      firstTag,
      *firstTime);
  require(
      firstRetraction.isValid(),
      "timestamped regional interaction subscription replacement first send returned an invalid retraction handle");
  require(
      receiver.recorder().timedInteractions().empty(),
      "timestamped regional interaction subscription replacement delivered before its grant");

  receiver.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      receiverHandles.interactionClass,
      receiverRegionSetA);
  receiver.rtiAmbassador().subscribeInteractionClassWithRegions(
      receiverHandles.interactionClass,
      receiverRegionSetB,
      true);
  receiver.rtiAmbassador().timeAdvanceRequest(*firstTime);
  publisher.rtiAmbassador().timeAdvanceRequest(*firstPublisherTarget);
  waitForSessions(
      {&publisher, &receiver},
      [&] {
        return publisher.recorder().timeAdvanceGrants().size() >= 1U &&
            receiver.recorder().timeAdvanceGrants().size() >= 1U;
      },
      options,
      "timestamped regional interaction subscription replacement first grant");
  require(
      receiver.recorder().timeAdvanceGrants().size() == 1U &&
          receiver.recorder().timedInteractions().empty() &&
          receiver.recorder().retractions().empty(),
      "timestamped regional interaction subscription replacement retargeted the first passel");
  require(
      receiver.recorder().callbackOrder() == std::vector<std::string>{"grant"},
      "timestamped regional interaction subscription replacement returned an unexpected first callback order");
  receiver.recorder().clearCallbackOrder();
  publisher.recorder().clearCallbackOrder();

  auto const secondTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      7U);
  auto const secondPublisherTarget = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      3U);
  auto const secondRetraction = publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      secondParameters,
      sourceRegionSetB,
      secondTag,
      *secondTime);
  require(
      secondRetraction.isValid(),
      "timestamped regional interaction subscription replacement second send returned an invalid retraction handle");
  receiver.rtiAmbassador().timeAdvanceRequest(*secondTime);
  publisher.rtiAmbassador().timeAdvanceRequest(*secondPublisherTarget);
  waitForSessions(
      {&publisher, &receiver},
      [&] {
        return publisher.recorder().timeAdvanceGrants().size() >= 2U &&
            receiver.recorder().timeAdvanceGrants().size() >= 2U &&
            receiver.recorder().timedInteractions().size() >= 1U;
      },
      options,
      "timestamped regional interaction subscription replacement second delivery");

  auto const interactions = receiver.recorder().timedInteractions();
  require(
      interactions.size() == 1U && receiver.recorder().retractions().empty(),
      "timestamped regional interaction subscription replacement returned the wrong delivery count");
  auto const& interaction = interactions.front();
  require(
      interaction.interaction == receiverHandles.interactionClass &&
          interaction.parameters.size() == 1U &&
          interaction.parameters.count(receiverHandles.parameter) == 1U &&
          copyBytes(interaction.parameters.at(receiverHandles.parameter)) ==
              secondParameterBytes,
      "timestamped regional interaction subscription replacement returned the wrong class or parameter");
  require(
      interaction.tag == secondTagBytes &&
          interaction.time == encodeTime(*secondTime) &&
          !interaction.timeText.empty(),
      "timestamped regional interaction subscription replacement did not preserve second metadata");
  require(
      interaction.producer == publisher.federateHandle() &&
          interaction.sentOrder == rti::TIMESTAMP &&
          interaction.receivedOrder == rti::TIMESTAMP,
      "timestamped regional interaction subscription replacement returned the wrong producer or order");
  require(
      interaction.transportation.isValid() &&
          !receiver.rtiAmbassador().getTransportationTypeName(
              interaction.transportation).empty(),
      "timestamped regional interaction subscription replacement returned an unresolvable transport");
  require(
      interaction.regions.has_value() && interaction.regions->size() == 1U &&
          interaction.regions->count(sourceRegionB) == 1U,
      "timestamped regional interaction subscription replacement did not carry the replacement source region");
  require(
      interaction.retractionPresent &&
          interaction.retraction == copyBytes(secondRetraction.encode()),
      "timestamped regional interaction subscription replacement omitted the second retraction handle");
  require(
      receiver.recorder().callbackOrder() ==
          std::vector<std::string>{"interaction", "grant"},
      "timestamped regional interaction subscription replacement delivered after its grant");

  receiver.rtiAmbassador().disableTimeConstrained();
  publisher.rtiAmbassador().disableTimeRegulation();
  receiver.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      receiverHandles.interactionClass,
      receiverRegionSetB);
  publisher.rtiAmbassador().unpublishInteractionClass(
      publisherHandles.interactionClass);
  receiver.rtiAmbassador().deleteRegion(receiverRegionB);
  receiver.rtiAmbassador().deleteRegion(receiverRegionA);
  publisher.rtiAmbassador().deleteRegion(sourceRegionB);
  publisher.rtiAmbassador().deleteRegion(sourceRegionA);
  receiver.resign(rti::NO_ACTION);
  publisher.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  receiver.disconnect();
  publisher.disconnect();
}

void scenarioTimestampedRegionalInteractionSourceResignation(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.ddmFom.empty(),
      "Timestamped regional interaction source resignation requires an adapter-supplied dimensional FOM");
  require(
      !options.logicalTimeImplementationName.empty(),
      "Timestamped regional interaction source resignation requires an adapter-supplied logical-time implementation");

  Session publisher(options, model, "owner");
  Session receiver(options, model, "member");
  Session clock(options, model, "source-resignation-clock");
  auto const federation = federationName(
      options,
      "timestamped-regional-interaction-source-resignation");
  connectAndJoin(publisher, receiver, options, federation, options.ddmFom);
  clock.connect();
  clock.join(
      options.memberFederateName + L"-timestamped-regional-resignation-clock",
      options.federateType,
      federation);

  auto const publisherHandles = ddmHandles(publisher, options);
  auto const receiverHandles = ddmHandles(receiver, options);
  verifyDdmClassDimensions(
      publisher,
      options,
      publisherHandles,
      "timestamped regional interaction source resignation");
  publisher.rtiAmbassador().publishInteractionClass(
      publisherHandles.interactionClass);
  publisher.rtiAmbassador().changeInteractionOrderType(
      publisherHandles.interactionClass,
      rti::TIMESTAMP);

  auto const sourceRegion = createDdmRegion(
      publisher,
      publisherHandles,
      1UL,
      5UL,
      1UL,
      5UL);
  auto const receiverRegion = createDdmRegion(
      receiver,
      receiverHandles,
      2UL,
      6UL,
      2UL,
      6UL);
  auto const sourceRegionSet = rti::RegionHandleSet{sourceRegion};
  auto const receiverRegionSet = rti::RegionHandleSet{receiverRegion};
  receiver.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  receiver.rtiAmbassador().subscribeInteractionClassWithRegions(
      receiverHandles.interactionClass,
      receiverRegionSet,
      true);

  auto publisherTime = makeTimeContext(publisher);
  auto receiverTime = makeTimeContext(receiver);
  auto clockTime = makeTimeContext(clock);
  require(
      publisherTime.factory->getName() == receiverTime.factory->getName() &&
          publisherTime.factory->getName() == clockTime.factory->getName(),
      "timestamped regional interaction source resignation members selected different logical-time factories");

  auto makeLookahead = [](TimeContext const& time, std::size_t steps) {
    auto target = timeAfter(*time.factory, *time.initial, *time.epsilon, steps);
    auto result = time.factory->makeZero();
    require(
        result != nullptr,
        "timestamped regional interaction source resignation could not allocate a lookahead interval");
    result->setToDifference(*target, *time.initial);
    return result;
  };
  auto publisherLookahead = makeLookahead(publisherTime, 5U);
  auto clockLookahead = makeLookahead(clockTime, 5U);

  receiver.rtiAmbassador().enableTimeConstrained();
  waitFor(
      receiver,
      [&] { return receiver.recorder().timeConstrainedEnabled().size() >= 1U; },
      options,
      "timestamped regional interaction source resignation time-constrained callback");
  publisher.rtiAmbassador().enableTimeRegulation(*publisherLookahead);
  waitFor(
      publisher,
      [&] { return publisher.recorder().timeRegulationEnabled().size() >= 1U; },
      options,
      "timestamped regional interaction source resignation publisher time-regulation callback");
  clock.rtiAmbassador().enableTimeRegulation(*clockLookahead);
  waitFor(
      clock,
      [&] { return clock.recorder().timeRegulationEnabled().size() >= 1U; },
      options,
      "timestamped regional interaction source resignation clock time-regulation callback");

  auto const messageTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      6U);
  auto const receiverTarget = timeAfter(
      *receiverTime.factory,
      *receiverTime.initial,
      *receiverTime.epsilon,
      6U);
  auto const clockTarget = timeAfter(
      *clockTime.factory,
      *clockTime.initial,
      *clockTime.epsilon,
      2U);
  std::vector<std::uint8_t> parameterBytes{0x52U, 0x45U, 0x47U, 0x53U};
  std::vector<std::uint8_t> tagBytes{0x52U, 0x45U, 0x53U, 0x49U, 0x47U};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      publisherHandles.parameter,
      rti::VariableLengthData(parameterBytes.data(), parameterBytes.size()));
  rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());

  auto const retraction = publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      parameters,
      sourceRegionSet,
      tag,
      *messageTime);
  require(
      retraction.isValid(),
      "timestamped regional interaction source resignation send returned an invalid retraction handle");
  require(
      receiver.recorder().timedInteractions().empty() &&
          receiver.recorder().retractions().empty(),
      "timestamped regional interaction source resignation delivered before the recipient frontier");

  receiver.rtiAmbassador().timeAdvanceRequest(*receiverTarget);
  require(
      receiver.recorder().timeAdvanceGrants().empty(),
      "timestamped regional interaction source resignation granted before an independent frontier");
  publisher.resign(rti::NO_ACTION);
  require(
      receiver.recorder().timedInteractions().empty() &&
          receiver.recorder().timeAdvanceGrants().empty(),
      "timestamped regional interaction source resignation released the queued passel too early");

  clock.rtiAmbassador().timeAdvanceRequest(*clockTarget);
  waitFor(
      clock,
      [&] { return clock.recorder().timeAdvanceGrants().size() >= 1U; },
      options,
      "timestamped regional interaction source resignation clock frontier");
  waitFor(
      receiver,
      [&] {
        return receiver.recorder().timedInteractions().size() >= 1U &&
            receiver.recorder().timeAdvanceGrants().size() >= 1U;
      },
      options,
      "timestamped regional interaction source resignation delivery and grant");

  auto const interactions = receiver.recorder().timedInteractions();
  require(
      interactions.size() == 1U,
      "timestamped regional interaction source resignation delivered a duplicate passel");
  auto const& interaction = interactions.front();
  require(
      interaction.interaction == receiverHandles.interactionClass &&
          interaction.parameters.size() == 1U &&
          interaction.parameters.count(receiverHandles.parameter) == 1U,
      "timestamped regional interaction source resignation returned the wrong class or parameter set");
  require(
      copyBytes(interaction.parameters.at(receiverHandles.parameter)) == parameterBytes &&
          interaction.tag == tagBytes && interaction.time == encodeTime(*messageTime),
      "timestamped regional interaction source resignation did not preserve payload or time");
  require(
      interaction.producer == publisher.federateHandle() &&
          interaction.sentOrder == rti::TIMESTAMP &&
          interaction.receivedOrder == rti::TIMESTAMP &&
          !interaction.timeText.empty(),
      "timestamped regional interaction source resignation returned the wrong producer or order metadata");
  require(
      interaction.transportation.isValid() &&
          !receiver.rtiAmbassador().getTransportationTypeName(
              interaction.transportation).empty(),
      "timestamped regional interaction source resignation returned an unresolvable transport");
  require(
      interaction.regions.has_value() && interaction.regions->size() == 1U &&
          interaction.regions->count(sourceRegion) == 1U,
      "timestamped regional interaction source resignation omitted the source region snapshot");
  require(
      interaction.retractionPresent &&
          interaction.retraction == copyBytes(retraction.encode()),
      "timestamped regional interaction source resignation omitted its retraction handle");
  auto const grants = receiver.recorder().timeAdvanceGrants();
  require(
      grants.size() == 1U && grants.front().encoded == encodeTime(*receiverTarget),
      "timestamped regional interaction source resignation returned the wrong recipient grant");
  require(
      receiver.recorder().callbackOrder() ==
          std::vector<std::string>{"interaction", "grant"},
      "timestamped regional interaction source resignation delivered after its grant");
  requireException(
      [&] { publisher.rtiAmbassador().retract(retraction); },
      L"FederateNotExecutionMember",
      "timestamped regional interaction source resignation post-resignation retraction");

  receiver.rtiAmbassador().disableTimeConstrained();
  clock.rtiAmbassador().disableTimeRegulation();
  receiver.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      receiverHandles.interactionClass,
      receiverRegionSet);
  receiver.rtiAmbassador().deleteRegion(receiverRegion);
  receiver.resign(rti::NO_ACTION);
  clock.resign(rti::NO_ACTION);
  receiver.rtiAmbassador().destroyFederationExecution(federation);
  publisher.disconnect();
  receiver.disconnect();
  clock.disconnect();
}

void scenarioTimestampedRegionalInteractionTarNmr(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.ddmFom.empty(),
      "Timestamped regional interaction TAR/NMR requires an adapter-supplied dimensional FOM");
  require(
      !options.logicalTimeImplementationName.empty(),
      "Timestamped regional interaction TAR/NMR requires an adapter-supplied logical-time implementation");

  Session publisher(options, model, "owner");
  Session tar(options, model, "member");
  Session nmr(options, model, "next-message-member");
  auto const federation = federationName(
      options,
      "timestamped-regional-interaction-tar-nmr");
  connectAndJoin(publisher, tar, options, federation, options.ddmFom);
  nmr.connect();
  nmr.join(
      options.memberFederateName + L"-timestamped-regional-nmr",
      options.federateType,
      federation);

  auto const publisherHandles = ddmHandles(publisher, options);
  auto const tarHandles = ddmHandles(tar, options);
  auto const nmrHandles = ddmHandles(nmr, options);
  verifyDdmClassDimensions(
      publisher,
      options,
      publisherHandles,
      "timestamped regional interaction TAR/NMR");
  publisher.rtiAmbassador().publishInteractionClass(
      publisherHandles.interactionClass);
  publisher.rtiAmbassador().changeInteractionOrderType(
      publisherHandles.interactionClass,
      rti::TIMESTAMP);

  auto const sourceRegion = createDdmRegion(
      publisher,
      publisherHandles,
      1UL,
      5UL,
      1UL,
      5UL);
  auto const tarRegion = createDdmRegion(
      tar,
      tarHandles,
      2UL,
      6UL,
      2UL,
      6UL);
  auto const nmrRegion = createDdmRegion(
      nmr,
      nmrHandles,
      2UL,
      6UL,
      2UL,
      6UL);
  auto const sourceRegionSet = rti::RegionHandleSet{sourceRegion};
  auto const tarRegionSet = rti::RegionHandleSet{tarRegion};
  auto const nmrRegionSet = rti::RegionHandleSet{nmrRegion};
  tar.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  nmr.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  tar.rtiAmbassador().subscribeInteractionClassWithRegions(
      tarHandles.interactionClass,
      tarRegionSet,
      true);
  nmr.rtiAmbassador().subscribeInteractionClassWithRegions(
      nmrHandles.interactionClass,
      nmrRegionSet,
      true);

  auto publisherTime = makeTimeContext(publisher);
  auto tarTime = makeTimeContext(tar);
  auto nmrTime = makeTimeContext(nmr);
  require(
      publisherTime.factory->getName() == tarTime.factory->getName() &&
          publisherTime.factory->getName() == nmrTime.factory->getName(),
      "timestamped regional interaction TAR/NMR members selected different logical-time factories");

  auto makeLookahead = [](TimeContext const& time, std::size_t steps) {
    auto target = timeAfter(*time.factory, *time.initial, *time.epsilon, steps);
    auto result = time.factory->makeZero();
    require(
        result != nullptr,
        "timestamped regional interaction TAR/NMR could not allocate a lookahead interval");
    result->setToDifference(*target, *time.initial);
    return result;
  };
  auto publisherLookahead = makeLookahead(publisherTime, 5U);

  tar.rtiAmbassador().enableTimeConstrained();
  waitFor(
      tar,
      [&] { return tar.recorder().timeConstrainedEnabled().size() >= 1U; },
      options,
      "timestamped regional interaction TAR/NMR TAR time-constrained callback");
  nmr.rtiAmbassador().enableTimeConstrained();
  waitFor(
      nmr,
      [&] { return nmr.recorder().timeConstrainedEnabled().size() >= 1U; },
      options,
      "timestamped regional interaction TAR/NMR NMR time-constrained callback");
  publisher.rtiAmbassador().enableTimeRegulation(*publisherLookahead);
  waitFor(
      publisher,
      [&] { return publisher.recorder().timeRegulationEnabled().size() >= 1U; },
      options,
      "timestamped regional interaction TAR/NMR publisher time-regulation callback");

  auto const messageTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      7U);
  auto const tarTarget = timeAfter(
      *tarTime.factory,
      *tarTime.initial,
      *tarTime.epsilon,
      7U);
  auto const nmrTarget = timeAfter(
      *nmrTime.factory,
      *nmrTime.initial,
      *nmrTime.epsilon,
      10U);
  std::vector<std::uint8_t> parameterBytes{0x54U, 0x41U, 0x52U, 0x2DU, 0x4EU};
  std::vector<std::uint8_t> tagBytes{0x54U, 0x41U, 0x52U, 0x2DU, 0x4DU};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      publisherHandles.parameter,
      rti::VariableLengthData(parameterBytes.data(), parameterBytes.size()));
  rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());

  auto const retraction = publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      parameters,
      sourceRegionSet,
      tag,
      *messageTime);
  require(
      retraction.isValid(),
      "timestamped regional interaction TAR/NMR send returned an invalid retraction handle");
  require(
      tar.recorder().timedInteractions().empty() &&
          nmr.recorder().timedInteractions().empty(),
      "timestamped regional interaction TAR/NMR delivered before either request");

  tar.rtiAmbassador().timeAdvanceRequest(*tarTarget);
  nmr.rtiAmbassador().nextMessageRequest(*nmrTarget);
  require(
      tar.recorder().timeAdvanceGrants().empty() &&
          nmr.recorder().timeAdvanceGrants().empty(),
      "timestamped regional interaction TAR/NMR granted before the publisher frontier");
  publisher.rtiAmbassador().timeAdvanceRequest(
      *timeAfter(
          *publisherTime.factory,
          *publisherTime.initial,
          *publisherTime.epsilon,
          2U));
  waitForSessions(
      {&publisher, &tar, &nmr},
      [&] {
        return publisher.recorder().timeAdvanceGrants().size() >= 1U &&
            tar.recorder().timedInteractions().size() >= 1U &&
            tar.recorder().timeAdvanceGrants().size() >= 1U &&
            nmr.recorder().timedInteractions().size() >= 1U &&
            nmr.recorder().timeAdvanceGrants().size() >= 1U;
      },
      options,
      "timestamped regional interaction TAR/NMR deliveries and grants");

  auto assertRegionalInteraction = [&](Session& receiver,
                                       DdmHandles const& receiverHandles,
                                       TimedInteractionRecord const& record) {
    require(
        record.interaction == receiverHandles.interactionClass &&
            record.parameters.size() == 1U &&
            record.parameters.count(receiverHandles.parameter) == 1U,
        "timestamped regional interaction TAR/NMR returned the wrong class or parameter set");
    require(
        copyBytes(record.parameters.at(receiverHandles.parameter)) == parameterBytes &&
            record.tag == tagBytes && record.time == encodeTime(*messageTime),
        "timestamped regional interaction TAR/NMR did not preserve payload or time");
    require(
        record.producer == publisher.federateHandle() &&
            record.sentOrder == rti::TIMESTAMP &&
            record.receivedOrder == rti::TIMESTAMP &&
            !record.timeText.empty(),
        "timestamped regional interaction TAR/NMR returned the wrong producer or order metadata");
    require(
        record.transportation.isValid() &&
            !receiver.rtiAmbassador().getTransportationTypeName(
                record.transportation).empty(),
        "timestamped regional interaction TAR/NMR returned an unresolvable transport");
    require(
        record.regions.has_value() && record.regions->size() == 1U &&
            record.regions->count(sourceRegion) == 1U,
        "timestamped regional interaction TAR/NMR omitted the source region designator");
    require(
        record.retractionPresent &&
            record.retraction == copyBytes(retraction.encode()),
        "timestamped regional interaction TAR/NMR omitted its retraction handle");
  };

  auto const tarInteractions = tar.recorder().timedInteractions();
  auto const nmrInteractions = nmr.recorder().timedInteractions();
  require(tarInteractions.size() == 1U && nmrInteractions.size() == 1U,
          "timestamped regional interaction TAR/NMR delivered duplicate callbacks");
  assertRegionalInteraction(tar, tarHandles, tarInteractions.front());
  assertRegionalInteraction(nmr, nmrHandles, nmrInteractions.front());
  require(
      tar.recorder().timeAdvanceGrants().size() == 1U &&
          tar.recorder().timeAdvanceGrants().front().encoded == encodeTime(*tarTarget),
      "timestamped regional interaction TAR/NMR returned the wrong TAR grant");
  require(
      nmr.recorder().timeAdvanceGrants().size() == 1U &&
          nmr.recorder().timeAdvanceGrants().front().encoded == encodeTime(*messageTime),
      "timestamped regional interaction TAR/NMR returned the wrong NMR grant");
  require(
      tar.recorder().callbackOrder() ==
          std::vector<std::string>{"interaction", "grant"} &&
          nmr.recorder().callbackOrder() ==
              std::vector<std::string>{"interaction", "grant"},
      "timestamped regional interaction TAR/NMR delivered after its grant");

  auto tarLogicalTime = tarTime.factory->makeInitial();
  auto nmrLogicalTime = nmrTime.factory->makeInitial();
  require(
      tarLogicalTime != nullptr && nmrLogicalTime != nullptr,
      "timestamped regional interaction TAR/NMR could not allocate query times");
  tar.rtiAmbassador().queryLogicalTime(*tarLogicalTime);
  nmr.rtiAmbassador().queryLogicalTime(*nmrLogicalTime);
  require(
      *tarLogicalTime == *tarTarget && *nmrLogicalTime == *messageTime,
      "timestamped regional interaction TAR/NMR query returned the wrong logical time");

  tar.rtiAmbassador().disableTimeConstrained();
  nmr.rtiAmbassador().disableTimeConstrained();
  publisher.rtiAmbassador().disableTimeRegulation();
  tar.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      tarHandles.interactionClass,
      tarRegionSet);
  nmr.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      nmrHandles.interactionClass,
      nmrRegionSet);
  publisher.rtiAmbassador().unpublishInteractionClass(
      publisherHandles.interactionClass);
  tar.rtiAmbassador().deleteRegion(tarRegion);
  nmr.rtiAmbassador().deleteRegion(nmrRegion);
  publisher.rtiAmbassador().deleteRegion(sourceRegion);
  nmr.resign(rti::NO_ACTION);
  tar.resign(rti::NO_ACTION);
  publisher.resign(rti::NO_ACTION);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  nmr.disconnect();
  tar.disconnect();
  publisher.disconnect();
}

void scenarioRegionalBoundaries(Options const& options, rti::CallbackModel model) {
  Session owner(options, model, "owner");
  Session foreign(options, model, "member");
  auto const federation = federationName(options, "regional-boundaries");
  connectAndJoin(owner, foreign, options, federation, options.ddmFom);

  auto const ownerHandles = ddmHandles(owner, options);
  auto const foreignHandles = ddmHandles(foreign, options);
  verifyDdmClassDimensions(owner, options, ownerHandles, "regional boundaries");

  auto const emptyRegion = owner.rtiAmbassador().createRegion(rti::DimensionHandleSet{});
  require(emptyRegion.isValid(), "zero-dimensional region creation returned an invalid handle");
  require(owner.rtiAmbassador().getDimensionHandleSet(emptyRegion).empty(),
          "zero-dimensional region reported unexpected dimensions");
  owner.rtiAmbassador().commitRegionModifications(rti::RegionHandleSet{emptyRegion});
  owner.rtiAmbassador().deleteRegion(emptyRegion);

  auto const uncommittedRegion = owner.rtiAmbassador().createRegion(
      rti::DimensionHandleSet{
          ownerHandles.firstDimension,
          ownerHandles.secondDimension});
  requireException(
      [&] {
        static_cast<void>(owner.rtiAmbassador().getRangeBounds(
            uncommittedRegion, ownerHandles.firstDimension));
      },
      L"InvalidRegion",
      "range lookup for an uncommitted region");
  requireException(
      [&] {
        owner.rtiAmbassador().commitRegionModifications(
            rti::RegionHandleSet{uncommittedRegion});
      },
      L"InvalidRegion",
      "commit of a region with missing range bounds");
  owner.rtiAmbassador().setRangeBounds(
      uncommittedRegion,
      ownerHandles.firstDimension,
      rti::RangeBounds(1UL, 5UL));
  owner.rtiAmbassador().setRangeBounds(
      uncommittedRegion,
      ownerHandles.secondDimension,
      rti::RangeBounds(1UL, 5UL));
  owner.rtiAmbassador().commitRegionModifications(
      rti::RegionHandleSet{uncommittedRegion});

  auto const wrongContextRegion = owner.rtiAmbassador().createRegion(
      rti::DimensionHandleSet{ownerHandles.firstDimension});
  owner.rtiAmbassador().setRangeBounds(
      wrongContextRegion,
      ownerHandles.firstDimension,
      rti::RangeBounds(1UL, 5UL));
  owner.rtiAmbassador().commitRegionModifications(
      rti::RegionHandleSet{wrongContextRegion});

  rti::AttributeHandleSet const ownerAttributes{ownerHandles.attribute};
  owner.rtiAmbassador().publishObjectClassAttributes(
      ownerHandles.objectClass, ownerAttributes);
  rti::AttributeHandleSetRegionHandleSetPairVector const wrongObjectPair{{
      ownerAttributes,
      rti::RegionHandleSet{wrongContextRegion},
  }};
  requireException(
      [&] {
        static_cast<void>(owner.rtiAmbassador().registerObjectInstanceWithRegions(
            ownerHandles.objectClass, wrongObjectPair));
      },
      L"InvalidRegionContext",
      "object registration with an incompatible region context");

  owner.rtiAmbassador().publishInteractionClass(ownerHandles.interactionClass);
  std::vector<std::uint8_t> interactionValue{0x42U};
  std::vector<std::uint8_t> interactionTag{0x42U, 0x44U};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      ownerHandles.parameter,
      rti::VariableLengthData(interactionValue.data(), interactionValue.size()));
  rti::VariableLengthData userSuppliedTag(interactionTag.data(), interactionTag.size());
  requireException(
      [&] {
        owner.rtiAmbassador().sendInteractionWithRegions(
            ownerHandles.interactionClass,
            parameters,
            rti::RegionHandleSet{wrongContextRegion},
            userSuppliedTag);
      },
      L"InvalidRegionContext",
      "interaction send with an incompatible region context");

  auto const foreignRegion = createDdmRegion(
      foreign,
      foreignHandles,
      1UL,
      5UL,
      1UL,
      5UL);
  requireException(
      [&] { owner.rtiAmbassador().deleteRegion(foreignRegion); },
      L"RegionNotCreatedByThisFederate",
      "deletion of a region created by another federate");
  requireException(
      [&] {
        owner.rtiAmbassador().commitRegionModifications(
            rti::RegionHandleSet{foreignRegion});
      },
      L"RegionNotCreatedByThisFederate",
      "commit of a region created by another federate");

  auto const subscriptionRegion = createDdmRegion(
      owner,
      ownerHandles,
      2UL,
      6UL,
      2UL,
      6UL);
  auto const subscriptionRegionSet = rti::RegionHandleSet{subscriptionRegion};
  owner.rtiAmbassador().subscribeInteractionClassWithRegions(
      ownerHandles.interactionClass,
      subscriptionRegionSet,
      false);
  requireException(
      [&] { owner.rtiAmbassador().deleteRegion(subscriptionRegion); },
      L"RegionInUseForUpdateOrSubscription",
      "deletion of a region used by a passive subscription");
  owner.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      ownerHandles.interactionClass,
      subscriptionRegionSet);
  owner.rtiAmbassador().deleteRegion(subscriptionRegion);

  auto const objectRegion = createDdmRegion(
      owner,
      ownerHandles,
      2UL,
      6UL,
      2UL,
      6UL);
  rti::AttributeHandleSetRegionHandleSetPairVector const objectPair{{
      ownerAttributes,
      rti::RegionHandleSet{objectRegion},
  }};
  auto const object = owner.rtiAmbassador().registerObjectInstanceWithRegions(
      ownerHandles.objectClass, objectPair);
  require(object.isValid(), "boundary object registration returned an invalid handle");
  requireException(
      [&] { owner.rtiAmbassador().deleteRegion(objectRegion); },
      L"RegionInUseForUpdateOrSubscription",
      "deletion of a region used by an object update association");
  owner.rtiAmbassador().deleteObjectInstance(object, rti::VariableLengthData{});
  owner.rtiAmbassador().deleteRegion(objectRegion);
  owner.rtiAmbassador().unpublishObjectClassAttributes(
      ownerHandles.objectClass, ownerAttributes);
  owner.rtiAmbassador().unpublishInteractionClass(ownerHandles.interactionClass);

  owner.rtiAmbassador().deleteRegion(wrongContextRegion);
  owner.rtiAmbassador().deleteRegion(uncommittedRegion);
  foreign.rtiAmbassador().deleteRegion(foreignRegion);

  owner.resign(rti::NO_ACTION);
  foreign.resign(rti::NO_ACTION);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  owner.disconnect();
  foreign.disconnect();
}

void scenarioSynchronizationPoints(Options const& options, rti::CallbackModel model) {
  Session lifecycle(options, model, "synchronization-lifecycle");
  rti::VariableLengthData const emptyTag;
  rti::FederateHandleSet const emptySynchronizationSet;
  requireException(
      [&] {
        lifecycle.rtiAmbassador().registerFederationSynchronizationPoint(
            L"tck-lifecycle-global-before-connect",
            emptyTag);
      },
      L"NotConnected",
      "global synchronization-point registration before connect");
  requireException(
      [&] {
        lifecycle.rtiAmbassador().registerFederationSynchronizationPoint(
            L"tck-lifecycle-explicit-before-connect",
            emptyTag,
            emptySynchronizationSet);
      },
      L"NotConnected",
      "explicit synchronization-point registration before connect");
  requireException(
      [&] {
        lifecycle.rtiAmbassador().synchronizationPointAchieved(
            L"tck-lifecycle-achieved-before-connect");
      },
      L"NotConnected",
      "synchronization-point achievement before connect");
  lifecycle.connect();
  requireException(
      [&] {
        lifecycle.rtiAmbassador().registerFederationSynchronizationPoint(
            L"tck-lifecycle-global-before-join",
            emptyTag);
      },
      L"FederateNotExecutionMember",
      "global synchronization-point registration before joining an execution");
  requireException(
      [&] {
        lifecycle.rtiAmbassador().registerFederationSynchronizationPoint(
            L"tck-lifecycle-explicit-before-join",
            emptyTag,
            emptySynchronizationSet);
      },
      L"FederateNotExecutionMember",
      "explicit synchronization-point registration before joining an execution");
  requireException(
      [&] {
        lifecycle.rtiAmbassador().synchronizationPointAchieved(
            L"tck-lifecycle-achieved-before-join");
      },
      L"FederateNotExecutionMember",
      "synchronization-point achievement before joining an execution");
  lifecycle.disconnect();

  Session first(options, model, "owner");
  Session second(options, model, "member");
  Session third(options, model, "late");
  auto const federation = federationName(options, "synchronization-points");

  first.connect();
  second.connect();
  third.connect();
  first.rtiAmbassador().createFederationExecution(
      federation,
      options.fom.wstring(),
      options.logicalTimeImplementationName);
  first.join(options.ownerFederateName, options.federateType, federation);
  second.join(options.memberFederateName, options.federateType, federation);

  std::vector<std::uint8_t> tagBytes{0x53U, 0x59U, 0x4EU, 0x43U};
  rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());
  std::wstring const globalLabel = L"tck-global-synchronization";
  first.rtiAmbassador().registerFederationSynchronizationPoint(globalLabel, tag);
  waitForSessions(
      {&first, &second},
      [&] {
        return first.synchronizationPointRegistrations().size() >= 1U &&
            first.synchronizationPointAnnouncements().size() >= 1U &&
            second.synchronizationPointAnnouncements().size() >= 1U;
      },
      options,
      "global synchronization-point registration and announcement");

  auto const registration = first.synchronizationPointRegistrations().front();
  require(registration.succeeded && registration.label == globalLabel,
          "synchronization-point registration did not succeed for the requested label");
  for (auto* session : {&first, &second}) {
    auto const announcements = session->synchronizationPointAnnouncements();
    require(announcements.front().label == globalLabel,
            "synchronization-point announcement returned the wrong label");
    require(announcements.front().tag == tagBytes,
            "synchronization-point announcement returned the wrong tag");
  }

  // A default synchronization set includes a member that joins after the
  // point is registered, so the late member receives the pending
  // announcement and participates in the completion barrier.
  third.join(L"tck-third", options.federateType, federation);
  waitFor(
      third,
      [&] { return third.synchronizationPointAnnouncements().size() >= 1U; },
      options,
      "late synchronization-point announcement");
  require(
      third.synchronizationPointRegistrations().empty(),
      "late synchronization member received a registration-success callback");
  auto const lateAnnouncements = third.synchronizationPointAnnouncements();
  require(lateAnnouncements.front().label == globalLabel &&
              lateAnnouncements.front().tag == tagBytes,
          "late synchronization-point announcement returned the wrong label or tag");

  // Registration is one-shot by label.  A duplicate is reported to the
  // requesting federate and does not replace the already announced point.
  second.rtiAmbassador().registerFederationSynchronizationPoint(globalLabel, tag);
  waitFor(
      second,
      [&] { return second.synchronizationPointRegistrations().size() >= 1U; },
      options,
      "duplicate synchronization-point registration result");
  auto const duplicate = second.synchronizationPointRegistrations().back();
  require(!duplicate.succeeded && duplicate.label == globalLabel &&
              duplicate.failureReason.has_value() &&
              duplicate.failureReason.value() ==
                  rti::SYNCHRONIZATION_POINT_LABEL_NOT_UNIQUE,
          "duplicate synchronization-point registration returned the wrong result");

  first.rtiAmbassador().synchronizationPointAchieved(globalLabel, true);
  second.rtiAmbassador().synchronizationPointAchieved(globalLabel, false);
  third.rtiAmbassador().synchronizationPointAchieved(globalLabel, true);
  waitForSessions(
      {&first, &second, &third},
      [&] {
        return first.federationSynchronized().size() >= 1U &&
            second.federationSynchronized().size() >= 1U &&
            third.federationSynchronized().size() >= 1U;
      },
      options,
      "synchronization-point completion");
  for (auto* session : {&first, &second, &third}) {
    auto const completions = session->federationSynchronized();
    require(completions.front().label == globalLabel,
            "federation synchronized callback returned the wrong label");
    require(completions.front().failedToSyncSet.count(second.federateHandle()) == 1U,
            "federation synchronized callback omitted the unsuccessful federate");
  }
  requireException(
      [&] { first.rtiAmbassador().synchronizationPointAchieved(globalLabel); },
      L"SynchronizationPointLabelNotAnnounced",
      "re-achieving a completed synchronization point");

  // An explicit synchronization set excludes the third member, which gives
  // the portable test a second registration form without relying on provider
  // membership reports or private synchronization state.
  std::wstring const explicitLabel = L"tck-explicit-synchronization";
  rti::FederateHandleSet invalidExplicitSet{rti::FederateHandle{}};
  requireException(
      [&] {
        first.rtiAmbassador().registerFederationSynchronizationPoint(
            L"tck-invalid-explicit-synchronization",
            tag,
            invalidExplicitSet);
      },
      L"InvalidFederateHandle",
      "explicit synchronization set with an invalid federate handle");
  rti::FederateHandleSet explicitSet{
      first.federateHandle(),
      second.federateHandle()};
  first.rtiAmbassador().registerFederationSynchronizationPoint(
      explicitLabel,
      tag,
      explicitSet);
  waitForSessions(
      {&first, &second},
      [&] {
        return first.synchronizationPointRegistrations().size() >= 2U &&
            first.synchronizationPointAnnouncements().size() >= 2U &&
            second.synchronizationPointAnnouncements().size() >= 2U;
      },
      options,
      "explicit synchronization-set registration and announcement");
  for (int pass = 0; pass != 8; ++pass) {
    third.pump();
  }
  require(third.synchronizationPointAnnouncements().size() == 1U,
          "explicit synchronization set announced to an excluded federate");

  first.rtiAmbassador().synchronizationPointAchieved(explicitLabel);
  second.rtiAmbassador().synchronizationPointAchieved(explicitLabel);
  waitForSessions(
      {&first, &second},
      [&] {
        return first.federationSynchronized().size() >= 2U &&
            second.federationSynchronized().size() >= 2U;
      },
      options,
      "explicit synchronization-set completion");
  require(third.federationSynchronized().size() == 1U,
          "excluded federate received explicit synchronization completion");
  for (auto* session : {&first, &second}) {
    auto const completions = session->federationSynchronized();
    require(completions.back().label == explicitLabel &&
                completions.back().failedToSyncSet.empty(),
            "explicit synchronization completion returned an unexpected failure set");
  }

  third.resign(rti::NO_ACTION);
  second.resign(rti::NO_ACTION);
  first.resign(rti::NO_ACTION);
  first.rtiAmbassador().destroyFederationExecution(federation);
  third.disconnect();
  second.disconnect();
  first.disconnect();
}

void scenarioCallbackControls(Options const& options, rti::CallbackModel model) {
  Session publisher(options, model, "owner");
  Session receiver(options, model, "member");
  auto const federation = federationName(options, "callback-controls");
  connectAndJoin(publisher, receiver, options, federation, options.fom);

  rti::ObjectClassHandle publisherObjectClass;
  rti::AttributeHandle publisherAttribute;
  rti::InteractionClassHandle publisherInteraction;
  rti::ParameterHandle publisherParameter;
  handles(
      publisher,
      options,
      publisherObjectClass,
      publisherAttribute,
      publisherInteraction,
      publisherParameter);
  rti::ObjectClassHandle receiverObjectClass;
  rti::AttributeHandle receiverAttribute;
  rti::InteractionClassHandle receiverInteraction;
  rti::ParameterHandle receiverParameter;
  handles(
      receiver,
      options,
      receiverObjectClass,
      receiverAttribute,
      receiverInteraction,
      receiverParameter);
  require(publisherInteraction == receiverInteraction &&
              publisherParameter == receiverParameter,
          "callback-control handles did not retain identity across members");

  publisher.rtiAmbassador().publishInteractionClass(publisherInteraction);
  receiver.rtiAmbassador().subscribeInteractionClass(receiverInteraction);

  std::vector<std::uint8_t> valueBytes{0xC0U, 0xDEU};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      publisherParameter,
      rti::VariableLengthData(valueBytes.data(), valueBytes.size()));
  std::vector<std::uint8_t> firstTagBytes{0x43U, 0x42U, 0x31U};
  rti::VariableLengthData firstTag(firstTagBytes.data(), firstTagBytes.size());
  publisher.rtiAmbassador().sendInteraction(
      publisherInteraction,
      parameters,
      firstTag);
  waitFor(
      receiver,
      [&] { return receiver.recorder().interaction().present; },
      options,
      "baseline callback-control interaction");
  require(receiver.recorder().interaction().tag == firstTagBytes,
          "baseline callback-control interaction lost its tag");

  receiver.recorder().clearInteraction();
  receiver.rtiAmbassador().disableCallbacks();
  std::vector<std::uint8_t> secondTagBytes{0x43U, 0x42U, 0x32U};
  rti::VariableLengthData secondTag(secondTagBytes.data(), secondTagBytes.size());
  publisher.rtiAmbassador().sendInteraction(
      publisherInteraction,
      parameters,
      secondTag);

  if (model == rti::HLA_EVOKED) {
    require(
        receiver.evokeMultipleCallbacks(0.0, 1.0),
        "evoked callback control did not admit the pending process event");
  } else {
    static_cast<void>(receiver.rtiAmbassador().getObjectClassHandle(
        options.objectClassName));
  }
  require(!receiver.recorder().interaction().present,
          "disabled callbacks exposed an interaction callback");

  receiver.rtiAmbassador().enableCallbacks();
  if (model == rti::HLA_EVOKED) {
    static_cast<void>(receiver.evokeMultipleCallbacks(0.0, 1.0));
  } else {
    static_cast<void>(receiver.rtiAmbassador().getObjectClassHandle(
        options.objectClassName));
  }
  waitFor(
      receiver,
      [&] { return receiver.recorder().interaction().present; },
      options,
      "re-enabled callback-control interaction");
  require(receiver.recorder().interaction().tag == secondTagBytes,
          "re-enabled callback-control interaction lost its tag");

  receiver.rtiAmbassador().unsubscribeInteractionClass(receiverInteraction);
  publisher.rtiAmbassador().unpublishInteractionClass(publisherInteraction);
  receiver.resign(rti::NO_ACTION);
  publisher.resign(rti::NO_ACTION);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  receiver.disconnect();
  publisher.disconnect();
}

void scenarioCallbackControlsContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioCallbackControls(options, model);
}

void scenarioAsynchronousDelivery(Options const& options, rti::CallbackModel model) {
  Session publisher(options, model, "owner");
  Session receiver(options, model, "member");
  auto const federation = federationName(options, "asynchronous-delivery");
  connectAndJoin(publisher, receiver, options, federation, options.fom);

  rti::ObjectClassHandle publisherObjectClass;
  rti::AttributeHandle publisherAttribute;
  rti::InteractionClassHandle publisherInteraction;
  rti::ParameterHandle publisherParameter;
  handles(
      publisher,
      options,
      publisherObjectClass,
      publisherAttribute,
      publisherInteraction,
      publisherParameter);
  rti::ObjectClassHandle receiverObjectClass;
  rti::AttributeHandle receiverAttribute;
  rti::InteractionClassHandle receiverInteraction;
  rti::ParameterHandle receiverParameter;
  handles(
      receiver,
      options,
      receiverObjectClass,
      receiverAttribute,
      receiverInteraction,
      receiverParameter);
  require(publisherParameter == receiverParameter,
          "asynchronous-delivery parameter handles did not retain identity");

  publisher.rtiAmbassador().publishInteractionClass(publisherInteraction);
  receiver.rtiAmbassador().subscribeInteractionClass(receiverInteraction);
  auto const receiverTime = makeTimeContext(receiver);
  receiver.rtiAmbassador().enableTimeConstrained();
  waitFor(
      receiver,
      [&] { return receiver.recorder().timeConstrainedEnabled().size() >= 1U; },
      options,
      "asynchronous-delivery time-constrained callback");

  std::vector<std::uint8_t> valueBytes{0xA5U, 0x51U};
  std::vector<std::uint8_t> firstTagBytes{0x41U, 0x53U, 0x59U, 0x31U};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      publisherParameter,
      rti::VariableLengthData(valueBytes.data(), valueBytes.size()));
  rti::VariableLengthData firstTag(firstTagBytes.data(), firstTagBytes.size());

  // Receive-order callbacks are held for a time-constrained federate while
  // asynchronous delivery is disabled.  The assertion is intentionally made
  // before callback servicing in evoked mode and after a bounded drain in both
  // models, so it checks retention rather than timing luck.
  publisher.rtiAmbassador().sendInteraction(
      publisherInteraction,
      parameters,
      firstTag);
  if (model == rti::HLA_EVOKED) {
    require(!receiver.recorder().interaction().present,
            "evoked receive-order callback arrived before callback servicing");
  }
  for (int pass = 0; pass != 8; ++pass) {
    receiver.pump();
  }
  require(!receiver.recorder().interaction().present,
          "receive-order callback bypassed disabled asynchronous delivery");

  receiver.rtiAmbassador().enableAsynchronousDelivery();
  requireException(
      [&] { receiver.rtiAmbassador().enableAsynchronousDelivery(); },
      L"AsynchronousDeliveryAlreadyEnabled",
      "enabling asynchronous delivery twice");
  if (model == rti::HLA_EVOKED) {
    static_cast<void>(receiver.evokeMultipleCallbacks(0.0, 0.0));
  }
  waitFor(
      receiver,
      [&] { return receiver.recorder().interaction().present; },
      options,
      "asynchronous receive-order callback release");
  auto const firstReceived = receiver.recorder().interaction();
  require(firstReceived.interaction == receiverInteraction &&
              firstReceived.parameters.size() == 1U &&
              firstReceived.parameters.find(receiverParameter) !=
                  firstReceived.parameters.end() &&
              firstReceived.tag == firstTagBytes,
          "released asynchronous interaction did not preserve application data");

  receiver.recorder().clearInteraction();
  receiver.rtiAmbassador().disableAsynchronousDelivery();
  requireException(
      [&] { receiver.rtiAmbassador().disableAsynchronousDelivery(); },
      L"AsynchronousDeliveryAlreadyDisabled",
      "disabling asynchronous delivery twice");
  std::vector<std::uint8_t> secondTagBytes{0x41U, 0x53U, 0x59U, 0x32U};
  rti::VariableLengthData secondTag(secondTagBytes.data(), secondTagBytes.size());
  publisher.rtiAmbassador().sendInteraction(
      publisherInteraction,
      parameters,
      secondTag);
  for (int pass = 0; pass != 8; ++pass) {
    receiver.pump();
  }
  require(!receiver.recorder().interaction().present,
          "disabled asynchronous delivery did not retain the second interaction");

  auto const nextTime = timeAfter(
      *receiverTime.factory,
      *receiverTime.initial,
      *receiverTime.epsilon,
      1U);
  receiver.rtiAmbassador().timeAdvanceRequest(*nextTime);
  waitFor(
      receiver,
      [&] { return receiver.recorder().interaction().present; },
      options,
      "time-advance release of a retained receive-order callback");
  auto const secondReceived = receiver.recorder().interaction();
  require(secondReceived.tag == secondTagBytes,
          "time-advance release delivered the wrong retained interaction");
  requireException(
      [&] { receiver.rtiAmbassador().disableAsynchronousDelivery(); },
      L"AsynchronousDeliveryAlreadyDisabled",
      "disabling asynchronous delivery after time-advance release");

  receiver.rtiAmbassador().disableTimeConstrained();
  receiver.rtiAmbassador().unsubscribeInteractionClass(receiverInteraction);
  publisher.rtiAmbassador().unpublishInteractionClass(publisherInteraction);
  receiver.resign(rti::NO_ACTION);
  publisher.resign(rti::NO_ACTION);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  receiver.disconnect();
  publisher.disconnect();
}

void scenarioFederationMomSaveConditionals(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.mimFom.empty(),
      "Federation MOM save-conditionals testing requires an adapter-supplied standard MIM");
  require(
      !options.logicalTimeImplementationName.empty(),
      "Federation MOM save-conditionals testing requires an adapter-supplied logical-time implementation");

  Session owner(options, model, "mom-save-owner");
  Session observer(options, model, "mom-save-observer");
  Session constrained(options, model, "mom-save-constrained");
  auto const federation = federationName(options, "federation-mom-save-conditionals");
  owner.connect();
  observer.connect();
  constrained.connect();
  owner.rtiAmbassador().createFederationExecutionWithMIM(
      federation,
      std::vector<std::wstring>{options.fom.wstring()},
      options.mimFom.wstring(),
      options.logicalTimeImplementationName);
  owner.join(
      options.ownerFederateName + L"-mom-save-owner",
      options.federateType,
      federation);
  observer.join(
      options.memberFederateName + L"-mom-save-observer",
      options.federateType,
      federation);
  constrained.join(
      options.memberFederateName + L"-mom-save-constrained",
      options.federateType,
      federation);

  auto const ownerFederationClass = owner.rtiAmbassador().getObjectClassHandle(
      L"HLAobjectRoot.HLAmanager.HLAfederation");
  auto const observerFederationClass = observer.rtiAmbassador().getObjectClassHandle(
      L"HLAobjectRoot.HLAmanager.HLAfederation");
  require(
      ownerFederationClass.isValid() && observerFederationClass.isValid() &&
          ownerFederationClass == observerFederationClass &&
          observer.rtiAmbassador().getObjectClassName(observerFederationClass) ==
              L"HLAobjectRoot.HLAmanager.HLAfederation",
      "Federation MOM save-conditionals class lookup did not round-trip the standard class");

  auto const ownerNextSaveName = owner.rtiAmbassador().getAttributeHandle(
      ownerFederationClass, L"HLAnextSaveName");
  auto const ownerNextSaveTime = owner.rtiAmbassador().getAttributeHandle(
      ownerFederationClass, L"HLAnextSaveTime");
  auto const ownerLastSaveName = owner.rtiAmbassador().getAttributeHandle(
      ownerFederationClass, L"HLAlastSaveName");
  auto const ownerLastSaveTime = owner.rtiAmbassador().getAttributeHandle(
      ownerFederationClass, L"HLAlastSaveTime");
  auto const observerNextSaveName = observer.rtiAmbassador().getAttributeHandle(
      observerFederationClass, L"HLAnextSaveName");
  auto const observerNextSaveTime = observer.rtiAmbassador().getAttributeHandle(
      observerFederationClass, L"HLAnextSaveTime");
  auto const observerLastSaveName = observer.rtiAmbassador().getAttributeHandle(
      observerFederationClass, L"HLAlastSaveName");
  auto const observerLastSaveTime = observer.rtiAmbassador().getAttributeHandle(
      observerFederationClass, L"HLAlastSaveTime");
  require(
      ownerNextSaveName.isValid() && ownerNextSaveTime.isValid() &&
          ownerLastSaveName.isValid() && ownerLastSaveTime.isValid() &&
          observerNextSaveName.isValid() && observerNextSaveTime.isValid() &&
          observerLastSaveName.isValid() && observerLastSaveTime.isValid() &&
          ownerNextSaveName == observerNextSaveName &&
          ownerNextSaveTime == observerNextSaveTime &&
          ownerLastSaveName == observerLastSaveName &&
          ownerLastSaveTime == observerLastSaveTime,
      "Federation MOM save-conditionals lookup returned inconsistent standard attribute handles");
  require(
      observer.rtiAmbassador().getAttributeName(
          observerFederationClass, observerNextSaveName) == L"HLAnextSaveName" &&
          observer.rtiAmbassador().getAttributeName(
              observerFederationClass, observerNextSaveTime) == L"HLAnextSaveTime" &&
          observer.rtiAmbassador().getAttributeName(
              observerFederationClass, observerLastSaveName) == L"HLAlastSaveName" &&
          observer.rtiAmbassador().getAttributeName(
              observerFederationClass, observerLastSaveTime) == L"HLAlastSaveTime",
      "Federation MOM save-conditionals attribute names did not round-trip");

  auto const reliable = observer.rtiAmbassador().getTransportationTypeHandle(L"HLAreliable");
  require(
      reliable.isValid() &&
          observer.rtiAmbassador().getTransportationTypeName(reliable) == L"HLAreliable",
      "Federation MOM save-conditionals could not resolve HLAreliable");
  rti::AttributeHandleSet const conditionalAttributes{
      observerNextSaveName,
      observerNextSaveTime,
      observerLastSaveName,
      observerLastSaveTime};
  observer.rtiAmbassador().subscribeObjectClassAttributes(
      observerFederationClass,
      conditionalAttributes,
      true,
      L"");
  waitFor(
      observer,
      [&] { return observer.recorder().discoveryCount() >= 1U; },
      options,
      "Federation MOM save-conditionals object discovery");
  auto const discovered = observer.recorder().discovery();
  require(
      discovered.objectClass == observerFederationClass &&
          discovered.name == L"HLAfederation" && discovered.object.isValid(),
      "Federation MOM save-conditionals discovered the wrong standard object");
  auto const federationObject = discovered.object;
  auto const observerTime = makeTimeContext(observer);

  auto decodeLogicalTimeValue = [&](rti::VariableLengthData const& encoded,
                                    std::string const& description) {
    if (encoded.size() == 0U) {
      return std::vector<std::uint8_t>{};
    }
    auto raw = copyBytes(encoded);
    if (!raw.empty()) {
      auto decoded = decodeTime(*observerTime.factory, raw);
      require(decoded != nullptr, description + " returned an undecodable logical time");
    }
    return raw;
  };

  struct SaveConditionals final {
    std::wstring nextName;
    std::vector<std::uint8_t> nextTime;
    std::wstring lastName;
    std::vector<std::uint8_t> lastTime;
  };

  auto decodeConditionals = [&](ReflectionRecord const& reflection,
                                std::string const& description) {
    require(
        reflection.present && reflection.object == federationObject &&
            reflection.transportation == reliable && reflection.tag.empty() &&
            !reflection.producer.isValid() && !reflection.regions.has_value(),
        description + " returned non-standard MOM reflection metadata");
    SaveConditionals result;
    auto decodePair = [&](rti::AttributeHandle const& nameHandle,
                          rti::AttributeHandle const& timeHandle,
                          std::wstring& name,
                          std::vector<std::uint8_t>& time,
                          std::string const& pairDescription) {
      bool const hasName = reflection.values.count(nameHandle) == 1U;
      bool const hasTime = reflection.values.count(timeHandle) == 1U;
      require(
          hasName == hasTime,
          pairDescription + " did not reflect its name/time pair together");
      if (hasName) {
        rti::HLAunicodeString decodedName;
        decodedName.decode(reflection.values.at(nameHandle));
        name = decodedName.get();
        time = decodeLogicalTimeValue(
            reflection.values.at(timeHandle), pairDescription + " time");
      }
    };
    decodePair(
        observerNextSaveName,
        observerNextSaveTime,
        result.nextName,
        result.nextTime,
        description + " next-save");
    decodePair(
        observerLastSaveName,
        observerLastSaveTime,
        result.lastName,
        result.lastTime,
        description + " last-save");
    return result;
  };

  auto collectConditionals = [&](std::size_t before,
                                 std::vector<rti::AttributeHandle> const& required,
                                 std::string const& description) {
    auto mergeReflections = [&](std::vector<ReflectionRecord> const& reflections) {
      ReflectionRecord merged;
      for (std::size_t index = before; index < reflections.size(); ++index) {
        auto const& candidate = reflections[index];
        if (!candidate.present || candidate.object != federationObject) {
          continue;
        }
        require(
            candidate.transportation == reliable && candidate.tag.empty() &&
                !candidate.producer.isValid() && !candidate.regions.has_value(),
            description + " returned non-standard MOM reflection metadata");
        if (!merged.present) {
          merged = candidate;
        }
        for (auto const& value : candidate.values) {
          merged.values[value.first] = value.second;
        }
      }
      return merged;
    };
    waitFor(
        observer,
        [&] {
          auto const reflections = observer.recorder().reflections();
          if (reflections.size() <= before) {
            return false;
          }
          auto const merged = mergeReflections(reflections);
          return merged.present && std::all_of(
              required.begin(),
              required.end(),
              [&](auto const& handle) { return merged.values.count(handle) == 1U; });
        },
        options,
        description);
    auto const merged = mergeReflections(observer.recorder().reflections());
    require(merged.present, description + " produced no reflection");
    return merged;
  };

  auto requestConditionals = [&] {
    observer.recorder().clearReflection();
    auto const before = observer.recorder().reflections().size();
    observer.rtiAmbassador().requestAttributeValueUpdate(
        federationObject,
        conditionalAttributes,
        rti::VariableLengthData{});
    waitFor(
        observer,
        [&] { return observer.recorder().reflectionCount() >= 1U; },
        options,
        "Federation MOM save-conditionals direct value request");
    auto const reflection = collectConditionals(
        before,
        {observerNextSaveName, observerNextSaveTime, observerLastSaveName, observerLastSaveTime},
        "Federation MOM save-conditionals direct value request");
    require(
        reflection.values.size() == 4U,
        "Federation MOM save-conditionals direct value request omitted a conditional");
    return decodeConditionals(reflection, "Federation MOM save-conditionals direct value request");
  };

  auto const initial = requestConditionals();
  require(
      initial.nextName.empty() && initial.nextTime.empty() && initial.lastName.empty() &&
          initial.lastTime.empty(),
      "Federation MOM save-conditionals initial values were not empty");

  auto regulatorTime = makeTimeContext(owner);
  auto constrainedTime = makeTimeContext(constrained);
  enableTimestampedRoles(
      owner,
      constrained,
      regulatorTime,
      constrainedTime,
      options,
      "Federation MOM save-conditionals");

  std::wstring const saveLabel = L"tck-federation-mom-save-conditionals";
  auto const saveTime = timeAfter(
      *regulatorTime.factory,
      *regulatorTime.initial,
      *regulatorTime.epsilon,
      7U);
  owner.rtiAmbassador().requestFederationSave(saveLabel, *saveTime);
  auto const pending = requestConditionals();
  require(
      pending.nextName == saveLabel && pending.nextTime == encodeTime(*saveTime) &&
          pending.lastName.empty() && pending.lastTime.empty(),
      "Federation MOM save-conditionals pending values did not expose the requested save");

  auto const admittedReflectionBefore = observer.recorder().reflections().size();
  constrained.rtiAmbassador().timeAdvanceRequest(*saveTime);
  owner.rtiAmbassador().timeAdvanceRequest(*saveTime);
  waitForSessions(
      {&owner, &constrained, &observer},
      [&] {
        return owner.federateSaveInitiations().size() >= 1U &&
            constrained.federateSaveInitiations().size() >= 1U &&
            observer.federateSaveInitiations().size() >= 1U;
      },
      options,
      "Federation MOM save-conditionals admission callbacks");
  auto const admittedReflection = collectConditionals(
      admittedReflectionBefore,
      {observerNextSaveName, observerNextSaveTime},
      "Federation MOM save-conditionals admission reflection");
  auto const admitted = decodeConditionals(
      admittedReflection,
      "Federation MOM save-conditionals admission reflection");
  require(
      admitted.nextName.empty() && admitted.nextTime.empty() && admitted.lastName.empty() &&
          admitted.lastTime.empty(),
      "Federation MOM save-conditionals admission did not clear the pending values");
  require(
      owner.federateSaveInitiations().front() == saveLabel &&
          constrained.federateSaveInitiations().front() == saveLabel &&
          observer.federateSaveInitiations().front() == saveLabel,
      "Federation MOM save-conditionals admission returned the wrong save label");
  require(
      owner.federateSaveTimes().front().encoded == encodeTime(*saveTime) &&
          constrained.federateSaveTimes().front().encoded == encodeTime(*saveTime),
      "Federation MOM save-conditionals admission returned the wrong save timestamp");

  owner.rtiAmbassador().federateSaveBegun();
  constrained.rtiAmbassador().federateSaveBegun();
  observer.rtiAmbassador().federateSaveBegun();
  auto const completedReflectionBefore = observer.recorder().reflections().size();
  owner.rtiAmbassador().federateSaveComplete();
  constrained.rtiAmbassador().federateSaveComplete();
  observer.rtiAmbassador().federateSaveComplete();
  waitForSessions(
      {&owner, &constrained, &observer},
      [&] {
        return owner.federationSavedCount() >= 1U &&
            constrained.federationSavedCount() >= 1U &&
            observer.federationSavedCount() >= 1U;
      },
      options,
      "Federation MOM save-conditionals completion callbacks");
  auto const completedReflection = collectConditionals(
      completedReflectionBefore,
      {observerLastSaveName, observerLastSaveTime},
      "Federation MOM save-conditionals completion reflection");
  auto const completed = decodeConditionals(
      completedReflection,
      "Federation MOM save-conditionals completion reflection");
  require(
      completed.nextName.empty() && completed.nextTime.empty() &&
          completed.lastName == saveLabel && completed.lastTime == encodeTime(*saveTime),
      "Federation MOM save-conditionals completion did not update the last values");
  require(
      owner.federationNotSavedReasons().empty() &&
          constrained.federationNotSavedReasons().empty() &&
          observer.federationNotSavedReasons().empty(),
      "Federation MOM save-conditionals reported a failed save");

  observer.rtiAmbassador().unsubscribeObjectClassAttributes(
      observerFederationClass,
      conditionalAttributes);
  constrained.rtiAmbassador().disableTimeConstrained();
  owner.rtiAmbassador().disableTimeRegulation();
  constrained.resign(rti::NO_ACTION);
  observer.resign(rti::NO_ACTION);
  owner.resign(rti::NO_ACTION);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  constrained.disconnect();
  observer.disconnect();
  owner.disconnect();
}

void scenarioJoinedFederateMomFederateStateSaveRestore(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.mimFom.empty(),
      "Joined-federate MOM HLAfederateState testing requires an adapter-supplied standard MIM");
  require(
      !options.logicalTimeImplementationName.empty(),
      "Joined-federate MOM HLAfederateState testing requires an adapter-supplied logical-time implementation");

  Session subject(options, model, "mom-state-subject");
  Session observer(options, model, "mom-state-observer");
  auto const federation = federationName(
      options,
      "joined-federate-mom-federate-state-save-restore");
  auto const subjectName = options.ownerFederateName + L"-mom-state-subject";
  auto const observerName = options.memberFederateName + L"-mom-state-observer";
  subject.connect();
  observer.connect();
  subject.rtiAmbassador().createFederationExecutionWithMIM(
      federation,
      std::vector<std::wstring>{options.fom.wstring()},
      options.mimFom.wstring(),
      options.logicalTimeImplementationName);
  observer.join(observerName, options.federateType, federation);

  auto const observerMomClass = observer.rtiAmbassador().getObjectClassHandle(
      L"HLAobjectRoot.HLAmanager.HLAfederate");
  auto const observerFederateHandleAttribute = observer.rtiAmbassador().getAttributeHandle(
      observerMomClass,
      L"HLAfederateHandle");
  auto const observerFederateStateAttribute = observer.rtiAmbassador().getAttributeHandle(
      observerMomClass,
      L"HLAfederateState");
  auto const reliable = observer.rtiAmbassador().getTransportationTypeHandle(L"HLAreliable");
  require(
      observerMomClass.isValid() &&
          observer.rtiAmbassador().getObjectClassName(observerMomClass) ==
              L"HLAobjectRoot.HLAmanager.HLAfederate" &&
          observerFederateHandleAttribute.isValid() &&
          observerFederateStateAttribute.isValid() && reliable.isValid() &&
          observer.rtiAmbassador().getAttributeName(
              observerMomClass,
              observerFederateHandleAttribute) == L"HLAfederateHandle" &&
          observer.rtiAmbassador().getAttributeName(
              observerMomClass,
              observerFederateStateAttribute) == L"HLAfederateState" &&
          observer.rtiAmbassador().getTransportationTypeName(reliable) == L"HLAreliable",
      "Joined-federate MOM HLAfederateState lookup did not resolve the standard surface");
  observer.rtiAmbassador().subscribeObjectClassAttributes(
      observerMomClass,
      rti::AttributeHandleSet{
          observerFederateHandleAttribute,
          observerFederateStateAttribute},
      true,
      L"");

  subject.join(subjectName, options.federateType, federation);
  auto const subjectMomClass = subject.rtiAmbassador().getObjectClassHandle(
      L"HLAobjectRoot.HLAmanager.HLAfederate");
  auto const subjectFederateHandleAttribute = subject.rtiAmbassador().getAttributeHandle(
      subjectMomClass,
      L"HLAfederateHandle");
  auto const subjectFederateStateAttribute = subject.rtiAmbassador().getAttributeHandle(
      subjectMomClass,
      L"HLAfederateState");
  require(
      subjectMomClass == observerMomClass &&
          subjectFederateHandleAttribute == observerFederateHandleAttribute &&
          subjectFederateStateAttribute == observerFederateStateAttribute,
      "Joined-federate MOM HLAfederateState members did not agree on standard handles");
  subject.rtiAmbassador().subscribeObjectClassAttributes(
      subjectMomClass,
      rti::AttributeHandleSet{
          subjectFederateHandleAttribute,
          subjectFederateStateAttribute},
      true,
      L"");

  auto const expectedSubjectFederateHandle = copyBytes(subject.federateHandle().encode());
  auto findMomReflection = [&](Session& session,
                               rti::AttributeHandle const& handleAttribute)
      -> std::optional<ReflectionRecord> {
    auto const reflections = session.recorder().reflections();
    auto const iterator = std::find_if(
        reflections.begin(),
        reflections.end(),
        [&](ReflectionRecord const& reflection) {
          auto const value = reflection.values.find(handleAttribute);
          return reflection.present && value != reflection.values.end() &&
              copyBytes(value->second) == expectedSubjectFederateHandle;
        });
    if (iterator == reflections.end()) {
      return std::nullopt;
    }
    return *iterator;
  };
  waitForSessions(
      {&subject, &observer},
      [&] {
        return findMomReflection(observer, observerFederateHandleAttribute).has_value() &&
            findMomReflection(subject, subjectFederateHandleAttribute).has_value();
      },
      options,
      "joined-federate MOM HLAfederateState object discovery");
  auto const observerInitial =
      findMomReflection(observer, observerFederateHandleAttribute);
  auto const subjectInitial =
      findMomReflection(subject, subjectFederateHandleAttribute);
  require(
      observerInitial.has_value() && observerInitial->object.isValid() &&
          observer.rtiAmbassador().getKnownObjectClassHandle(observerInitial->object) ==
              observerMomClass &&
          subjectInitial.has_value() && subjectInitial->object.isValid() &&
          subject.rtiAmbassador().getKnownObjectClassHandle(subjectInitial->object) ==
              subjectMomClass,
      "Joined-federate MOM HLAfederateState discovery returned the wrong standard object");
  require(
      observerInitial->values.count(observerFederateStateAttribute) == 0U &&
          subjectInitial->values.count(subjectFederateStateAttribute) == 0U,
      "Joined-federate MOM HLAfederateState initial reflection was not conditional");
  auto const observerMomObject = observerInitial->object;
  auto const subjectMomObject = subjectInitial->object;

  auto findStateReflection = [&](Session& session,
                                 rti::ObjectInstanceHandle const& object,
                                 rti::AttributeHandle const& stateAttribute,
                                 std::size_t before)
      -> std::optional<ReflectionRecord> {
    auto const reflections = session.recorder().reflections();
    if (before > reflections.size()) {
      return std::nullopt;
    }
    auto const iterator = std::find_if(
        reflections.begin() + static_cast<std::ptrdiff_t>(before),
        reflections.end(),
        [&](ReflectionRecord const& reflection) {
          return reflection.present && reflection.object == object &&
              reflection.values.count(stateAttribute) == 1U;
        });
    if (iterator == reflections.end()) {
      return std::nullopt;
    }
    return *iterator;
  };
  auto findExpectedStateReflection = [&](Session& session,
                                          rti::ObjectInstanceHandle const& object,
                                          rti::AttributeHandle const& stateAttribute,
                                          std::size_t before,
                                          std::int32_t expected)
      -> std::optional<ReflectionRecord> {
    auto const reflections = session.recorder().reflections();
    if (before > reflections.size()) {
      return std::nullopt;
    }
    for (auto iterator = reflections.begin() + static_cast<std::ptrdiff_t>(before);
         iterator != reflections.end();
         ++iterator) {
      if (!iterator->present || iterator->object != object ||
          iterator->values.count(stateAttribute) != 1U) {
        continue;
      }
      rti::HLAinteger32BE state;
      state.decode(iterator->values.at(stateAttribute));
      if (state.get() == expected) {
        return *iterator;
      }
    }
    return std::nullopt;
  };
  auto requireStateReflection = [&](Session& session,
                                    rti::ObjectInstanceHandle const& object,
                                    rti::AttributeHandle const& stateAttribute,
                                    std::size_t before,
                                    std::int32_t expected,
                                    std::string const& description) {
    waitForSessions(
        {&subject, &observer},
        [&] {
          return findExpectedStateReflection(
                     session,
                     object,
                     stateAttribute,
                     before,
                     expected)
              .has_value();
        },
        options,
        description);
    auto const reflection = findExpectedStateReflection(
        session,
        object,
        stateAttribute,
        before,
        expected);
    require(
        reflection.has_value() && reflection->values.size() == 1U &&
            reflection->transportation == reliable && reflection->tag.empty() &&
            !reflection->producer.isValid() && !reflection->regions.has_value(),
        description + " returned non-standard MOM reflection metadata");
    rti::HLAinteger32BE state;
    state.decode(reflection->values.at(stateAttribute));
    require(
        state.get() == expected,
        description + " returned the wrong HLAfederateState value");
  };

  auto const beforeInitialObserver = observer.recorder().reflections().size();
  auto const beforeInitialSubject = subject.recorder().reflections().size();
  observer.rtiAmbassador().requestAttributeValueUpdate(
      observerMomObject,
      rti::AttributeHandleSet{observerFederateStateAttribute},
      rti::VariableLengthData{});
  subject.rtiAmbassador().requestAttributeValueUpdate(
      subjectMomObject,
      rti::AttributeHandleSet{subjectFederateStateAttribute},
      rti::VariableLengthData{});
  requireStateReflection(
      observer,
      observerMomObject,
      observerFederateStateAttribute,
      beforeInitialObserver,
      1,
      "joined-federate MOM HLAfederateState initial observer request");
  requireStateReflection(
      subject,
      subjectMomObject,
      subjectFederateStateAttribute,
      beforeInitialSubject,
      1,
      "joined-federate MOM HLAfederateState initial self request");

  std::wstring const saveLabel = L"mom-state-save";
  auto const beforeSaveObserver = observer.recorder().reflections().size();
  auto const beforeSaveSubject = subject.recorder().reflections().size();
  subject.rtiAmbassador().requestFederationSave(saveLabel);
  waitForSessions(
      {&subject, &observer},
      [&] {
        return subject.federateSaveInitiations().size() >= 1U &&
            observer.federateSaveInitiations().size() >= 1U &&
            findStateReflection(
                observer,
                observerMomObject,
                observerFederateStateAttribute,
                beforeSaveObserver)
                .has_value();
      },
      options,
      "joined-federate MOM HLAfederateState save initiation");
  require(
      subject.federateSaveInitiations().front() == saveLabel &&
          observer.federateSaveInitiations().front() == saveLabel,
      "Joined-federate MOM HLAfederateState save initiation returned the wrong label");
  requireStateReflection(
      observer,
      observerMomObject,
      observerFederateStateAttribute,
      beforeSaveObserver,
      3,
      "joined-federate MOM HLAfederateState save initiation reflection");
  for (int pass = 0; pass != 8; ++pass) {
    subject.pump();
    observer.pump();
  }
  auto const subjectSaveReflections = subject.recorder().reflections();
  auto const subjectSaveStateReflection = std::find_if(
      subjectSaveReflections.begin() + static_cast<std::ptrdiff_t>(beforeSaveSubject),
      subjectSaveReflections.end(),
      [&](ReflectionRecord const& reflection) {
        return reflection.object == subjectMomObject &&
            reflection.values.count(subjectFederateStateAttribute) == 1U;
      });
  require(
      subjectSaveStateReflection == subjectSaveReflections.end(),
      "Joined-federate MOM HLAfederateState exposed the saving federate's own state transition");

  subject.rtiAmbassador().federateSaveBegun();
  observer.rtiAmbassador().federateSaveBegun();
  subject.rtiAmbassador().federateSaveComplete();
  auto const beforeSaveCompletion = observer.recorder().reflections().size();
  observer.rtiAmbassador().federateSaveComplete();
  waitForSessions(
      {&subject, &observer},
      [&] {
        return subject.federationSavedCount() >= 1U &&
            observer.federationSavedCount() >= 1U &&
            findStateReflection(
                observer,
                observerMomObject,
                observerFederateStateAttribute,
                beforeSaveCompletion)
                .has_value();
      },
      options,
      "joined-federate MOM HLAfederateState save completion");
  requireStateReflection(
      observer,
      observerMomObject,
      observerFederateStateAttribute,
      beforeSaveCompletion,
      1,
      "joined-federate MOM HLAfederateState save completion reflection");
  require(
      subject.federationNotSavedReasons().empty() &&
          observer.federationNotSavedReasons().empty(),
      "Joined-federate MOM HLAfederateState save reported a failure");

  auto const beforeRestore = observer.recorder().reflections().size();
  subject.rtiAmbassador().requestFederationRestore(saveLabel);
  waitForSessions(
      {&subject, &observer},
      [&] {
        return subject.federationRestoreRequestsSucceeded().size() >= 1U &&
            subject.federationRestoreBegunCount() >= 1U &&
            observer.federationRestoreBegunCount() >= 1U &&
            subject.federateRestoreInitiations().size() >= 1U &&
            observer.federateRestoreInitiations().size() >= 1U &&
            findStateReflection(
                observer,
                observerMomObject,
                observerFederateStateAttribute,
                beforeRestore)
                .has_value();
      },
      options,
      "joined-federate MOM HLAfederateState restore initiation");
  require(
      subject.federationRestoreRequestsSucceeded().back() == saveLabel &&
          subject.federationRestoreRequestsFailed().empty() &&
          observer.federationRestoreRequestsFailed().empty(),
      "Joined-federate MOM HLAfederateState restore request returned an unexpected result");
  auto const subjectRestore = subject.federateRestoreInitiations().back();
  auto const observerRestore = observer.federateRestoreInitiations().back();
  require(
      subjectRestore.label == saveLabel && observerRestore.label == saveLabel &&
          subjectRestore.federateName == subjectName &&
          observerRestore.federateName == observerName &&
          subjectRestore.postRestoreFederateHandle.isValid() &&
          observerRestore.postRestoreFederateHandle.isValid(),
      "Joined-federate MOM HLAfederateState restore initiation returned incorrect identity data");
  requireStateReflection(
      observer,
      observerMomObject,
      observerFederateStateAttribute,
      beforeRestore,
      5,
      "joined-federate MOM HLAfederateState restore initiation reflection");

  subject.rtiAmbassador().federateRestoreComplete();
  auto const beforeRestoreCompletion = observer.recorder().reflections().size();
  observer.rtiAmbassador().federateRestoreComplete();
  waitForSessions(
      {&subject, &observer},
      [&] {
        return subject.federationRestoredCount() >= 1U &&
            observer.federationRestoredCount() >= 1U &&
            findExpectedStateReflection(
                observer,
                observerMomObject,
                observerFederateStateAttribute,
                beforeRestoreCompletion,
                1)
                .has_value();
      },
      options,
      "joined-federate MOM HLAfederateState restore completion");
  requireStateReflection(
      observer,
      observerMomObject,
      observerFederateStateAttribute,
      beforeRestoreCompletion,
      1,
      "joined-federate MOM HLAfederateState restore completion reflection");
  require(
      subject.federationNotRestoredReasons().empty() &&
          observer.federationNotRestoredReasons().empty(),
      "Joined-federate MOM HLAfederateState restore reported a failure");

  subject.resign(rti::NO_ACTION);
  observer.resign(rti::NO_ACTION);
  subject.rtiAmbassador().destroyFederationExecution(federation);
  observer.disconnect();
  subject.disconnect();
}

void scenarioJoinedFederateMomGaltLitsPeriodic(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.fom.empty(),
      "Joined-federate MOM GALT/LITS testing requires an adapter-supplied FOM");
  require(
      !options.mimFom.empty(),
      "Joined-federate MOM GALT/LITS testing requires an adapter-supplied standard MIM");
  require(
      !options.logicalTimeImplementationName.empty(),
      "Joined-federate MOM GALT/LITS testing requires an adapter-supplied logical-time implementation");

  Session subject(options, model, "mom-galt-lits-subject");
  Session regulator(options, model, "mom-galt-lits-regulator");
  Session observer(options, model, "mom-galt-lits-observer");
  auto const federation = federationName(options, "joined-federate-mom-galt-lits-periodic");
  subject.connect();
  regulator.connect();
  observer.connect();
  subject.rtiAmbassador().createFederationExecutionWithMIM(
      federation,
      std::vector<std::wstring>{options.fom.wstring()},
      options.mimFom.wstring(),
      options.logicalTimeImplementationName);
  observer.join(
      options.memberFederateName + L"-mom-galt-lits-observer",
      options.federateType,
      federation);

  auto const observerFederateClass = observer.rtiAmbassador().getObjectClassHandle(
      L"HLAobjectRoot.HLAmanager.HLAfederate");
  require(
      observerFederateClass.isValid() &&
          observer.rtiAmbassador().getObjectClassName(observerFederateClass) ==
              L"HLAobjectRoot.HLAmanager.HLAfederate",
      "Joined-federate MOM GALT/LITS lookup did not round-trip the standard class");
  auto const federateHandleAttribute = observer.rtiAmbassador().getAttributeHandle(
      observerFederateClass,
      L"HLAfederateHandle");
  auto const galtAttribute = observer.rtiAmbassador().getAttributeHandle(
      observerFederateClass,
      L"HLAGALT");
  auto const litsAttribute = observer.rtiAmbassador().getAttributeHandle(
      observerFederateClass,
      L"HLALITS");
  auto const reliable = observer.rtiAmbassador().getTransportationTypeHandle(
      L"HLAreliable");
  require(
      federateHandleAttribute.isValid() && galtAttribute.isValid() &&
          litsAttribute.isValid() && reliable.isValid() &&
          observer.rtiAmbassador().getAttributeName(
              observerFederateClass,
              galtAttribute) == L"HLAGALT" &&
          observer.rtiAmbassador().getAttributeName(
              observerFederateClass,
              litsAttribute) == L"HLALITS" &&
          observer.rtiAmbassador().getTransportationTypeName(reliable) ==
              L"HLAreliable",
      "Joined-federate MOM GALT/LITS lookup returned inconsistent standard handles");
  rti::AttributeHandleSet const requestedAttributes{
      galtAttribute,
      litsAttribute};
  rti::AttributeHandleSet const subscribedAttributes{
      federateHandleAttribute,
      galtAttribute,
      litsAttribute};
  observer.rtiAmbassador().subscribeObjectClassAttributes(
      observerFederateClass,
      subscribedAttributes,
      true,
      L"");

  regulator.join(
      options.ownerFederateName + L"-mom-galt-lits-regulator",
      options.federateType,
      federation);
  auto regulatorTime = makeTimeContext(regulator);
  auto observerTime = makeTimeContext(observer);
  require(
      regulatorTime.factory->getName() == observerTime.factory->getName(),
      "Joined-federate MOM GALT/LITS members selected different logical-time factories");
  auto regulatorLookaheadTime = timeAfter(
      *regulatorTime.factory,
      *regulatorTime.initial,
      *regulatorTime.epsilon,
      2U);
  auto regulatorLookahead = regulatorTime.factory->makeZero();
  require(
      regulatorLookahead != nullptr,
      "Joined-federate MOM GALT/LITS could not allocate a lookahead interval");
  regulatorLookahead->setToDifference(
      *regulatorLookaheadTime,
      *regulatorTime.initial);
  regulator.rtiAmbassador().enableTimeRegulation(*regulatorLookahead);
  waitFor(
      regulator,
      [&] { return regulator.recorder().timeRegulationEnabled().size() >= 1U; },
      options,
      "joined-federate MOM GALT/LITS time-regulation callback");

  subject.join(
      options.ownerFederateName + L"-mom-galt-lits-subject",
      options.federateType,
      federation);
  auto const expectedSubjectFederateHandle = copyBytes(subject.federateHandle().encode());
  auto findSubjectMomReflection = [&]() -> std::optional<ReflectionRecord> {
    auto const reflections = observer.recorder().reflections();
    auto const iterator = std::find_if(
        reflections.begin(),
        reflections.end(),
        [&](ReflectionRecord const& reflection) {
          auto const value = reflection.values.find(federateHandleAttribute);
          return reflection.present && value != reflection.values.end() &&
              copyBytes(value->second) == expectedSubjectFederateHandle;
        });
    if (iterator == reflections.end()) {
      return std::nullopt;
    }
    return *iterator;
  };
  waitFor(
      observer,
      [&] { return findSubjectMomReflection().has_value(); },
      options,
      "joined-federate MOM GALT/LITS subject discovery");
  auto const subjectMomReflection = findSubjectMomReflection();
  require(
      subjectMomReflection.has_value() && subjectMomReflection->object.isValid() &&
          observer.rtiAmbassador().getKnownObjectClassHandle(
              subjectMomReflection->object) == observerFederateClass,
      "Joined-federate MOM GALT/LITS discovery returned the wrong standard object");
  auto const subjectMomObject = subjectMomReflection->object;

  auto findBoundsReflection = [&](std::size_t before,
                                  bool undefined) -> std::optional<ReflectionRecord> {
    auto const reflections = observer.recorder().reflections();
    auto const begin = reflections.begin() + static_cast<std::ptrdiff_t>(before);
    auto const iterator = std::find_if(
        begin,
        reflections.end(),
        [&](ReflectionRecord const& reflection) {
          if (!reflection.present || reflection.object != subjectMomObject ||
              reflection.values.count(galtAttribute) != 1U ||
              reflection.values.count(litsAttribute) != 1U) {
            return false;
          }
          auto const galt = copyBytes(reflection.values.at(galtAttribute));
          auto const lits = copyBytes(reflection.values.at(litsAttribute));
          return undefined ? galt.empty() && lits.empty()
                           : !galt.empty() && !lits.empty();
        });
    if (iterator == reflections.end()) {
      return std::nullopt;
    }
    return *iterator;
  };
  auto verifyBoundsReflection = [&](ReflectionRecord const& reflection,
                                    bool undefined,
                                    std::string const& description) {
    require(
        reflection.values.size() == 2U && reflection.transportation == reliable &&
            reflection.tag.empty() && !reflection.producer.isValid() &&
            !reflection.regions.has_value(),
        description + " returned non-standard MOM reflection metadata");
    if (undefined) {
      require(
          reflection.values.at(galtAttribute).size() == 0U &&
              reflection.values.at(litsAttribute).size() == 0U,
          description + " did not use empty encodings for undefined bounds");
      return;
    }
    auto const galt = decodeTime(
        *observerTime.factory,
        copyBytes(reflection.values.at(galtAttribute)));
    auto const lits = decodeTime(
        *observerTime.factory,
        copyBytes(reflection.values.at(litsAttribute)));
    auto const expected = timeAfter(
        *observerTime.factory,
        *observerTime.initial,
        *observerTime.epsilon,
        2U);
    requireTimeEquals(*galt, *expected, description + " HLAGALT");
    requireTimeEquals(*lits, *expected, description + " HLALITS");
  };
  auto requestBounds = [&](bool undefined, std::string const& description) {
    auto const before = observer.recorder().reflections().size();
    observer.rtiAmbassador().requestAttributeValueUpdate(
        subjectMomObject,
        requestedAttributes,
        rti::VariableLengthData{});
    waitFor(
        observer,
        [&] { return findBoundsReflection(before, undefined).has_value(); },
        options,
        description);
    auto const reflection = findBoundsReflection(before, undefined);
    require(reflection.has_value(), description + " produced no MOM reflection");
    verifyBoundsReflection(*reflection, undefined, description);
  };

  auto galt = observerTime.factory->makeInitial();
  auto lits = observerTime.factory->makeInitial();
  require(galt != nullptr && lits != nullptr, "Joined-federate MOM GALT/LITS could not allocate query values");
  require(observer.rtiAmbassador().queryGALT(*galt),
          "Joined-federate MOM queryGALT remained undefined while a regulator was active");
  require(observer.rtiAmbassador().queryLITS(*lits),
          "Joined-federate MOM queryLITS remained undefined while a regulator was active");
  auto const expected = timeAfter(
      *observerTime.factory,
      *observerTime.initial,
      *observerTime.epsilon,
      2U);
  requireTimeEquals(*galt, *expected, "Joined-federate MOM queryGALT");
  requireTimeEquals(*lits, *expected, "Joined-federate MOM queryLITS");
  requestBounds(false, "joined-federate MOM GALT/LITS direct value request");

  auto const setTiming = observer.rtiAmbassador().getInteractionClassHandle(
      L"HLAinteractionRoot.HLAmanager.HLAfederate.HLAadjust.HLAsetTiming");
  auto const timingFederate = observer.rtiAmbassador().getParameterHandle(
      setTiming,
      L"HLAfederate");
  auto const reportPeriod = observer.rtiAmbassador().getParameterHandle(
      setTiming,
      L"HLAreportPeriod");
  require(
      setTiming.isValid() && timingFederate.isValid() && reportPeriod.isValid(),
      "Joined-federate MOM GALT/LITS HLAsetTiming lookup returned an invalid handle");
  auto const beforePeriodic = observer.recorder().reflections().size();
  observer.rtiAmbassador().sendInteraction(
      setTiming,
      rti::ParameterHandleValueMap{
          {timingFederate, subject.federateHandle().encode()},
          {reportPeriod, rti::HLAinteger32BE{1}.encode()}},
      rti::VariableLengthData{});
  waitFor(
      observer,
      [&] { return findBoundsReflection(beforePeriodic, false).has_value(); },
      options,
      "joined-federate MOM GALT/LITS periodic reflection");
  auto const periodicReflection = findBoundsReflection(beforePeriodic, false);
  require(periodicReflection.has_value(),
          "Joined-federate MOM GALT/LITS periodic report was missing");
  verifyBoundsReflection(*periodicReflection, false,
                         "joined-federate MOM GALT/LITS periodic report");

  observer.rtiAmbassador().sendInteraction(
      setTiming,
      rti::ParameterHandleValueMap{
          {timingFederate, subject.federateHandle().encode()},
          {reportPeriod, rti::HLAinteger32BE{0}.encode()}},
      rti::VariableLengthData{});
  regulator.rtiAmbassador().disableTimeRegulation();
  require(!observer.rtiAmbassador().queryGALT(*galt),
          "Joined-federate MOM queryGALT remained defined after regulation was disabled");
  require(!observer.rtiAmbassador().queryLITS(*lits),
          "Joined-federate MOM queryLITS remained defined after regulation was disabled");
  requestBounds(true, "joined-federate MOM GALT/LITS undefined value request");

  observer.rtiAmbassador().unsubscribeObjectClassAttributes(
      observerFederateClass,
      subscribedAttributes);
  subject.resign(rti::NO_ACTION);
  observer.resign(rti::NO_ACTION);
  regulator.resign(rti::NO_ACTION);
  subject.rtiAmbassador().destroyFederationExecution(federation);
  subject.disconnect();
  regulator.disconnect();
  observer.disconnect();
}

void scenarioJoinedFederateMomTsoLengthPeriodic(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.fom.empty(),
      "Joined-federate MOM TSO-length testing requires an adapter-supplied FOM");
  require(
      !options.mimFom.empty(),
      "Joined-federate MOM TSO-length testing requires an adapter-supplied standard MIM");
  require(
      !options.logicalTimeImplementationName.empty(),
      "Joined-federate MOM TSO-length testing requires an adapter-supplied logical-time implementation");

  Session target(options, model, "mom-tso-length-target");
  Session publisher(options, model, "mom-tso-length-publisher");
  Session observer(options, model, "mom-tso-length-observer");
  auto const federation = federationName(options, "joined-federate-mom-tso-length-periodic");
  target.connect();
  publisher.connect();
  observer.connect();
  target.rtiAmbassador().createFederationExecutionWithMIM(
      federation,
      std::vector<std::wstring>{options.fom.wstring()},
      options.mimFom.wstring(),
      options.logicalTimeImplementationName);
  observer.join(
      options.memberFederateName + L"-mom-tso-length-observer",
      options.federateType,
      federation);

  auto const observerFederateClass = observer.rtiAmbassador().getObjectClassHandle(
      L"HLAobjectRoot.HLAmanager.HLAfederate");
  auto const federateHandleAttribute = observer.rtiAmbassador().getAttributeHandle(
      observerFederateClass,
      L"HLAfederateHandle");
  auto const tsoLengthAttribute = observer.rtiAmbassador().getAttributeHandle(
      observerFederateClass,
      L"HLATSOlength");
  auto const reliable = observer.rtiAmbassador().getTransportationTypeHandle(
      L"HLAreliable");
  require(
      observerFederateClass.isValid() && federateHandleAttribute.isValid() &&
          tsoLengthAttribute.isValid() && reliable.isValid() &&
          observer.rtiAmbassador().getObjectClassName(observerFederateClass) ==
              L"HLAobjectRoot.HLAmanager.HLAfederate" &&
          observer.rtiAmbassador().getAttributeName(
              observerFederateClass,
              tsoLengthAttribute) == L"HLATSOlength",
      "Joined-federate MOM TSO-length lookup returned inconsistent standard handles");
  rti::AttributeHandleSet const momAttributes{
      federateHandleAttribute,
      tsoLengthAttribute};
  observer.rtiAmbassador().subscribeObjectClassAttributes(
      observerFederateClass,
      momAttributes,
      true,
      L"");

  target.join(
      options.ownerFederateName + L"-mom-tso-length-target",
      options.federateType,
      federation);
  publisher.join(
      options.ownerFederateName + L"-mom-tso-length-publisher",
      options.federateType,
      federation);
  auto const expectedTargetFederateHandle = copyBytes(target.federateHandle().encode());
  auto findTargetMomReflection = [&]() -> std::optional<ReflectionRecord> {
    auto const reflections = observer.recorder().reflections();
    auto const iterator = std::find_if(
        reflections.begin(),
        reflections.end(),
        [&](ReflectionRecord const& reflection) {
          auto const value = reflection.values.find(federateHandleAttribute);
          return reflection.present && value != reflection.values.end() &&
              copyBytes(value->second) == expectedTargetFederateHandle;
        });
    if (iterator == reflections.end()) {
      return std::nullopt;
    }
    return *iterator;
  };
  waitFor(
      observer,
      [&] { return findTargetMomReflection().has_value(); },
      options,
      "joined-federate MOM TSO-length target discovery");
  auto const targetMomReflection = findTargetMomReflection();
  require(
      targetMomReflection.has_value() && targetMomReflection->object.isValid() &&
          observer.rtiAmbassador().getKnownObjectClassHandle(
              targetMomReflection->object) == observerFederateClass,
      "Joined-federate MOM TSO-length discovery returned the wrong standard object");
  auto const targetMomObject = targetMomReflection->object;

  auto findTsoLengthReflection = [&](std::size_t before)
      -> std::optional<ReflectionRecord> {
    auto const reflections = observer.recorder().reflections();
    auto const begin = reflections.begin() + static_cast<std::ptrdiff_t>(before);
    auto const iterator = std::find_if(
        begin,
        reflections.end(),
        [&](ReflectionRecord const& reflection) {
          return reflection.present && reflection.object == targetMomObject &&
              reflection.values.count(tsoLengthAttribute) == 1U;
        });
    if (iterator == reflections.end()) {
      return std::nullopt;
    }
    return *iterator;
  };
  auto verifyTsoLengthReflection = [&](ReflectionRecord const& reflection,
                                       std::int32_t expected,
                                       std::string const& description) {
    require(
        reflection.values.size() == 1U && reflection.transportation == reliable &&
            reflection.tag.empty() && !reflection.producer.isValid() &&
            !reflection.regions.has_value(),
        description + " returned non-standard MOM reflection metadata");
    rti::HLAinteger32BE decoded;
    decoded.decode(reflection.values.at(tsoLengthAttribute));
    require(decoded.get() == expected, description + " returned the wrong HLATSOlength value");
  };
  auto requestTsoLength = [&](std::int32_t expected, std::string const& description) {
    auto const before = observer.recorder().reflections().size();
    observer.rtiAmbassador().requestAttributeValueUpdate(
        targetMomObject,
        rti::AttributeHandleSet{tsoLengthAttribute},
        rti::VariableLengthData{});
    waitFor(
        observer,
        [&] { return findTsoLengthReflection(before).has_value(); },
        options,
        description);
    auto const reflection = findTsoLengthReflection(before);
    require(reflection.has_value(), description + " produced no MOM reflection");
    verifyTsoLengthReflection(*reflection, expected, description);
  };

  auto const publisherInteraction = publisher.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const targetInteraction = target.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const publisherParameter = publisher.rtiAmbassador().getParameterHandle(
      publisherInteraction,
      options.parameterName);
  auto const targetParameter = target.rtiAmbassador().getParameterHandle(
      targetInteraction,
      options.parameterName);
  require(
      publisherInteraction.isValid() && targetInteraction.isValid() &&
          publisherParameter.isValid() && targetParameter.isValid(),
      "Joined-federate MOM TSO-length application lookup returned an invalid adapter-supplied handle");
  publisher.rtiAmbassador().publishInteractionClass(publisherInteraction);
  publisher.rtiAmbassador().changeInteractionOrderType(
      publisherInteraction,
      rti::TIMESTAMP);
  target.rtiAmbassador().subscribeInteractionClass(targetInteraction);

  auto targetTime = makeTimeContext(target);
  auto publisherTime = makeTimeContext(publisher);
  require(
      targetTime.factory->getName() == publisherTime.factory->getName(),
      "Joined-federate MOM TSO-length members selected different logical-time factories");
  target.rtiAmbassador().enableTimeConstrained();
  waitFor(
      target,
      [&] { return target.recorder().timeConstrainedEnabled().size() >= 1U; },
      options,
      "joined-federate MOM TSO-length time-constrained callback");
  auto publisherLookaheadTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      1U);
  auto publisherLookahead = publisherTime.factory->makeZero();
  require(
      publisherLookahead != nullptr,
      "Joined-federate MOM TSO-length could not allocate a lookahead interval");
  publisherLookahead->setToDifference(
      *publisherLookaheadTime,
      *publisherTime.initial);
  publisher.rtiAmbassador().enableTimeRegulation(*publisherLookahead);
  waitFor(
      publisher,
      [&] { return publisher.recorder().timeRegulationEnabled().size() >= 1U; },
      options,
      "joined-federate MOM TSO-length time-regulation callback");

  auto const messageTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      2U);
  std::vector<std::uint8_t> const parameterBytes{0x54U, 0x53U};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      publisherParameter,
      rti::VariableLengthData(parameterBytes.data(), parameterBytes.size()));
  auto const retraction = publisher.rtiAmbassador().sendInteraction(
      publisherInteraction,
      parameters,
      rti::VariableLengthData{},
      *messageTime);
  require(
      retraction.isValid(),
      "Joined-federate MOM TSO-length send returned an invalid retraction handle");
  require(
      target.recorder().timedInteractions().empty(),
      "Joined-federate MOM TSO-length delivered the queued interaction before its grant");
  requestTsoLength(1, "joined-federate MOM TSO-length direct value request");

  auto const setTiming = observer.rtiAmbassador().getInteractionClassHandle(
      L"HLAinteractionRoot.HLAmanager.HLAfederate.HLAadjust.HLAsetTiming");
  auto const timingFederate = observer.rtiAmbassador().getParameterHandle(
      setTiming,
      L"HLAfederate");
  auto const reportPeriod = observer.rtiAmbassador().getParameterHandle(
      setTiming,
      L"HLAreportPeriod");
  require(
      setTiming.isValid() && timingFederate.isValid() && reportPeriod.isValid(),
      "Joined-federate MOM TSO-length HLAsetTiming lookup returned an invalid handle");
  auto const beforePeriodic = observer.recorder().reflections().size();
  observer.rtiAmbassador().sendInteraction(
      setTiming,
      rti::ParameterHandleValueMap{
          {timingFederate, target.federateHandle().encode()},
          {reportPeriod, rti::HLAinteger32BE{1}.encode()}},
      rti::VariableLengthData{});
  waitFor(
      observer,
      [&] { return findTsoLengthReflection(beforePeriodic).has_value(); },
      options,
      "joined-federate MOM TSO-length periodic reflection");
  auto const periodicReflection = findTsoLengthReflection(beforePeriodic);
  require(periodicReflection.has_value(),
          "Joined-federate MOM TSO-length periodic report was missing");
  verifyTsoLengthReflection(*periodicReflection, 1,
                            "joined-federate MOM TSO-length periodic report");

  observer.rtiAmbassador().sendInteraction(
      setTiming,
      rti::ParameterHandleValueMap{
          {timingFederate, target.federateHandle().encode()},
          {reportPeriod, rti::HLAinteger32BE{0}.encode()}},
      rti::VariableLengthData{});
  auto const targetMessageTime = timeAfter(
      *targetTime.factory,
      *targetTime.initial,
      *targetTime.epsilon,
      2U);
  target.rtiAmbassador().timeAdvanceRequest(*targetMessageTime);
  publisher.rtiAmbassador().timeAdvanceRequest(*messageTime);
  waitForSessions(
      {&target, &publisher},
      [&] {
        return target.recorder().timeAdvanceGrants().size() >= 1U &&
            publisher.recorder().timeAdvanceGrants().size() >= 1U &&
            target.recorder().timedInteractions().size() >= 1U;
      },
      options,
      "joined-federate MOM TSO-length delivery and grants");
  auto const timedInteractions = target.recorder().timedInteractions();
  require(
      timedInteractions.size() == 1U,
      "Joined-federate MOM TSO-length returned the wrong timestamped interaction count");
  auto const& timedInteraction = timedInteractions.front();
  require(
      timedInteraction.interaction == targetInteraction &&
          timedInteraction.parameters.size() == 1U &&
          timedInteraction.parameters.count(targetParameter) == 1U &&
          copyBytes(timedInteraction.parameters.at(targetParameter)) == parameterBytes &&
          timedInteraction.time == encodeTime(*targetMessageTime) &&
          timedInteraction.sentOrder == rti::TIMESTAMP &&
          timedInteraction.receivedOrder == rti::TIMESTAMP &&
          timedInteraction.retractionPresent,
      "Joined-federate MOM TSO-length returned the wrong timestamped interaction metadata");
  requestTsoLength(0, "joined-federate MOM TSO-length post-grant value request");

  observer.rtiAmbassador().unsubscribeObjectClassAttributes(
      observerFederateClass,
      momAttributes);
  target.rtiAmbassador().unsubscribeInteractionClass(targetInteraction);
  publisher.rtiAmbassador().unpublishInteractionClass(publisherInteraction);
  target.rtiAmbassador().disableTimeConstrained();
  publisher.rtiAmbassador().disableTimeRegulation();
  target.resign(rti::NO_ACTION);
  publisher.resign(rti::NO_ACTION);
  observer.resign(rti::NO_ACTION);
  target.rtiAmbassador().destroyFederationExecution(federation);
  target.disconnect();
  publisher.disconnect();
  observer.disconnect();
}

void scenarioJoinedFederateMomRemovedObjectCount(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.mimFom.empty(),
      "Joined-federate MOM removed-object testing requires an adapter-supplied standard MIM");
  require(
      !options.logicalTimeImplementationName.empty(),
      "Joined-federate MOM removed-object testing requires an adapter-supplied logical-time implementation");

  Session publisher(options, model, "mom-removed-publisher");
  Session observer(options, model, "mom-removed-observer");
  auto const federation = federationName(options, "joined-federate-mom-removed-object-count");
  publisher.connect();
  observer.connect();
  publisher.rtiAmbassador().createFederationExecutionWithMIM(
      federation,
      std::vector<std::wstring>{options.fom.wstring()},
      options.mimFom.wstring(),
      options.logicalTimeImplementationName);
  publisher.join(
      options.ownerFederateName + L"-mom-removed-publisher",
      options.federateType,
      federation);
  observer.join(
      options.memberFederateName + L"-mom-removed-observer",
      options.federateType,
      federation);

  auto const publisherFederateClass = publisher.rtiAmbassador().getObjectClassHandle(
      L"HLAobjectRoot.HLAmanager.HLAfederate");
  auto const observerFederateClass = observer.rtiAmbassador().getObjectClassHandle(
      L"HLAobjectRoot.HLAmanager.HLAfederate");
  require(
      publisherFederateClass.isValid() && observerFederateClass.isValid() &&
          publisherFederateClass == observerFederateClass &&
          observer.rtiAmbassador().getObjectClassName(observerFederateClass) ==
              L"HLAobjectRoot.HLAmanager.HLAfederate",
      "Joined-federate MOM removed-object lookup did not round-trip the standard class");

  auto const observerFederateHandleAttribute = observer.rtiAmbassador().getAttributeHandle(
      observerFederateClass,
      L"HLAfederateHandle");
  auto const observerRemovedCountAttribute = observer.rtiAmbassador().getAttributeHandle(
      observerFederateClass,
      L"HLAobjectInstancesRemoved");
  auto const publisherFederateHandleAttribute = publisher.rtiAmbassador().getAttributeHandle(
      publisherFederateClass,
      L"HLAfederateHandle");
  auto const publisherRemovedCountAttribute = publisher.rtiAmbassador().getAttributeHandle(
      publisherFederateClass,
      L"HLAobjectInstancesRemoved");
  require(
      observerFederateHandleAttribute.isValid() && observerRemovedCountAttribute.isValid() &&
          publisherFederateHandleAttribute == observerFederateHandleAttribute &&
          publisherRemovedCountAttribute == observerRemovedCountAttribute &&
          observer.rtiAmbassador().getAttributeName(
              observerFederateClass,
              observerRemovedCountAttribute) == L"HLAobjectInstancesRemoved",
      "Joined-federate MOM removed-object lookup returned inconsistent standard attributes");

  auto const reliable = observer.rtiAmbassador().getTransportationTypeHandle(L"HLAreliable");
  require(
      reliable.isValid() &&
          observer.rtiAmbassador().getTransportationTypeName(reliable) == L"HLAreliable",
      "Joined-federate MOM removed-object lookup could not resolve HLAreliable");
  auto const reportClass = observer.rtiAmbassador().getInteractionClassHandle(
      L"HLAinteractionRoot.HLAmanager.HLAfederate.HLAreport.HLAreportServiceInvocation");
  require(
      reportClass.isValid(),
      "Joined-federate MOM removed-object service-report lookup returned an invalid HLAreportServiceInvocation handle");
  std::vector<rti::ParameterHandle> reportParameters;
  for (auto const& name : {
           L"HLAservice",
           L"HLAserviceType",
           L"HLAsuccessIndicator",
           L"HLAsuppliedArguments",
           L"HLAreturnedArgument",
           L"HLAexception",
           L"HLAserialNumber"}) {
    auto const parameter = observer.rtiAmbassador().getParameterHandle(reportClass, name);
    require(
        parameter.isValid(),
        "Joined-federate MOM removed-object service-report parameter lookup returned an invalid handle");
    reportParameters.push_back(parameter);
  }
  auto const publisherReportClass = publisher.rtiAmbassador().getInteractionClassHandle(
      L"HLAinteractionRoot.HLAmanager.HLAfederate.HLAreport.HLAreportServiceInvocation");
  require(
      publisherReportClass.isValid() && publisherReportClass == reportClass,
      "Joined-federate MOM removed-object publisher report lookup did not match the standard HLAreportServiceInvocation handle");
  observer.rtiAmbassador().setServiceReportingSwitch(false);
  observer.rtiAmbassador().setSendServiceReportsToFileSwitch(false);
  publisher.rtiAmbassador().subscribeInteractionClass(publisherReportClass);
  rti::AttributeHandleSet const momAttributes{
      observerFederateHandleAttribute,
      observerRemovedCountAttribute};
  observer.rtiAmbassador().subscribeObjectClassAttributes(
      observerFederateClass,
      momAttributes,
      true,
      L"");

  auto findObserverMomReflection = [&]() -> std::optional<ReflectionRecord> {
    auto const reflections = observer.recorder().reflections();
    auto const expectedFederateHandle = copyBytes(observer.federateHandle().encode());
    auto const iterator = std::find_if(
        reflections.begin(),
        reflections.end(),
        [&](ReflectionRecord const& reflection) {
          auto const value = reflection.values.find(observerFederateHandleAttribute);
          return reflection.present && value != reflection.values.end() &&
              copyBytes(value->second) == expectedFederateHandle;
        });
    if (iterator == reflections.end()) {
      return std::nullopt;
    }
    return *iterator;
  };
  waitFor(
      observer,
      [&] { return findObserverMomReflection().has_value(); },
      options,
      "joined-federate MOM removed-object observer object discovery");
  auto const observerMomReflection = findObserverMomReflection();
  require(
      observerMomReflection.has_value() &&
          observer.rtiAmbassador().getKnownObjectClassHandle(
              observerMomReflection->object) == observerFederateClass,
      "Joined-federate MOM removed-object discovery returned the wrong standard object");
  auto const observerMomObject = observerMomReflection->object;

  // A joined-federate MOM object is RTI-owned. Query one of its standard
  // attributes to exercise the distinct IEEE callback rather than treating
  // RTI ownership as an unowned or synthetic-federate result.
  observer.recorder().clearOwnershipRecords();
  observer.rtiAmbassador().queryAttributeOwnership(
      observerMomObject,
      rti::AttributeHandleSet{observerFederateHandleAttribute});
  waitFor(
      observer,
      [&] { return observer.recorder().ownershipOwnedByRti().has_value(); },
      options,
      "joined-federate MOM RTI-owned attribute query");
  auto const rtiOwned = observer.recorder().ownershipOwnedByRti();
  require(
      rtiOwned->object == observerMomObject &&
          rtiOwned->attributes ==
              rti::AttributeHandleSet{observerFederateHandleAttribute},
      "Joined-federate MOM ownership query did not report RTI ownership");

  auto requestRemovedCount = [&](std::int32_t expected, std::string const& description) {
    auto const before = observer.recorder().reflections().size();
    observer.rtiAmbassador().requestAttributeValueUpdate(
        observerMomObject,
        rti::AttributeHandleSet{observerRemovedCountAttribute},
        rti::VariableLengthData{});
    waitFor(
        observer,
        [&] {
          auto const reflections = observer.recorder().reflections();
          return reflections.size() > before &&
              std::any_of(
                  reflections.begin() + static_cast<std::ptrdiff_t>(before),
                  reflections.end(),
                  [&](ReflectionRecord const& reflection) {
                    return reflection.object == observerMomObject &&
                        reflection.values.count(observerRemovedCountAttribute) == 1U;
                  });
        },
        options,
        description);
    auto const reflections = observer.recorder().reflections();
    auto const iterator = std::find_if(
        reflections.begin() + static_cast<std::ptrdiff_t>(before),
        reflections.end(),
        [&](ReflectionRecord const& reflection) {
          return reflection.object == observerMomObject &&
              reflection.values.count(observerRemovedCountAttribute) == 1U;
        });
    require(iterator != reflections.end(), description + " produced no removed-object value");
    auto const& reflection = *iterator;
    require(
        reflection.values.size() == 1U && reflection.transportation == reliable &&
            reflection.tag.empty() && !reflection.producer.isValid() &&
            !reflection.regions.has_value(),
        description + " returned non-standard MOM reflection metadata");
    rti::HLAinteger32BE decoded;
    decoded.decode(reflection.values.at(observerRemovedCountAttribute));
    require(decoded.get() == expected, description + " returned the wrong removed-object count");
  };

  requestRemovedCount(0, "joined-federate MOM removed-object initial value request");

  auto const publisherObjectClass = publisher.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const observerObjectClass = observer.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const publisherAttribute = publisher.rtiAmbassador().getAttributeHandle(
      publisherObjectClass,
      options.attributeName);
  auto const observerAttribute = observer.rtiAmbassador().getAttributeHandle(
      observerObjectClass,
      options.attributeName);
  require(
      publisherObjectClass.isValid() && observerObjectClass.isValid() &&
          publisherAttribute.isValid() && observerAttribute.isValid(),
      "Joined-federate MOM removed-object application lookup returned an invalid handle");
  rti::AttributeHandleSet const publisherAttributes{publisherAttribute};
  rti::AttributeHandleSet const observerAttributes{observerAttribute};
  publisher.rtiAmbassador().publishObjectClassAttributes(
      publisherObjectClass,
      publisherAttributes);
  observer.rtiAmbassador().subscribeObjectClassAttributes(
      observerObjectClass,
      observerAttributes,
      true,
      L"");
  auto const object = publisher.rtiAmbassador().registerObjectInstance(publisherObjectClass);
  require(object.isValid(), "Joined-federate MOM removed-object registration returned an invalid handle");
  waitFor(
      observer,
      [&] { return observer.recorder().hasDiscovery(object); },
      options,
      "joined-federate MOM removed-object application discovery");
  auto const objectName = publisher.rtiAmbassador().getObjectInstanceName(object);
  observer.recorder().clearRemovals();
  std::vector<std::uint8_t> const deletionTagBytes{0x4DU, 0x4FU, 0x4DU};
  rti::VariableLengthData const deletionTag(
      deletionTagBytes.data(),
      deletionTagBytes.size());
  publisher.rtiAmbassador().deleteObjectInstance(object, deletionTag);
  waitFor(
      observer,
      [&] {
        return observer.recorder().hasRemoval(
            object,
            deletionTagBytes,
            publisher.federateHandle());
      },
      options,
      "joined-federate MOM removed-object application removal");
  auto const removals = observer.recorder().removals();
  require(
      removals.size() == 1U && removals.front().object == object &&
          removals.front().tag == deletionTagBytes &&
          removals.front().producer == publisher.federateHandle(),
      "Joined-federate MOM removed-object callback returned the wrong removal metadata");
  requestRemovedCount(1, "joined-federate MOM removed-object post-removal value request");
  requireException(
      [&] { static_cast<void>(observer.rtiAmbassador().getObjectInstanceHandle(objectName)); },
      L"ObjectInstanceNotKnown",
      "looking up an application object after the MOM-counted removal");

  // The RTI-owned MOM object is also a standard Request Attribute Value Update
  // target. Exercise its public service-report route after the ordinary MOM
  // reflection path so the report and the callback remain independently
  // observable under both callback models.
  publisher.recorder().clearInteraction();
  observer.rtiAmbassador().setServiceReportingSwitch(true);
  requestRemovedCount(
      1,
      "joined-federate MOM removed-object service-reported value request");
  waitFor(
      publisher,
      [&] { return publisher.recorder().interaction().present; },
      options,
      "joined-federate MOM RequestAttributeValueUpdate service report");
  auto const momReport = publisher.recorder().interaction();
  require(
      momReport.interaction == reportClass &&
          momReport.parameters.size() == reportParameters.size() &&
          !momReport.producer.isValid(),
      "Joined-federate MOM RequestAttributeValueUpdate report returned the wrong identity or producer metadata");
  require(
      momReport.tag.empty() && !momReport.regions.has_value() &&
          momReport.transportation == reliable,
      "Joined-federate MOM RequestAttributeValueUpdate report returned non-standard metadata");
  for (auto const parameterHandle : reportParameters) {
    require(
        momReport.parameters.count(parameterHandle) == 1U,
        "Joined-federate MOM RequestAttributeValueUpdate report omitted a standard parameter");
  }
  rti::HLAunicodeString momService;
  momService.decode(momReport.parameters.at(reportParameters[0]));
  require(
      momService.get() == L"RequestAttributeValueUpdate",
      "Joined-federate MOM service report returned the wrong service name");
  rti::HLAinteger16BE momServiceType;
  momServiceType.decode(momReport.parameters.at(reportParameters[1]));
  require(
      momServiceType.get() == 2,
      "Joined-federate MOM service report returned the wrong service type");
  rti::HLAboolean momSuccess;
  momSuccess.decode(momReport.parameters.at(reportParameters[2]));
  require(momSuccess.get(), "Joined-federate MOM service report did not report success");
  rti::HLAunicodeString momException;
  momException.decode(momReport.parameters.at(reportParameters[5]));
  require(
      momException.get().empty(),
      "Successful joined-federate MOM service report carried an exception");
  rti::HLAinteger32BE momSerial;
  momSerial.decode(momReport.parameters.at(reportParameters[6]));
  require(
      momSerial.get() == 0,
      "First joined-federate MOM service report did not use serial number zero");
  observer.rtiAmbassador().setServiceReportingSwitch(false);

  observer.rtiAmbassador().unsubscribeObjectClassAttributes(
      observerFederateClass,
      momAttributes);
  publisher.rtiAmbassador().unsubscribeInteractionClass(publisherReportClass);
  observer.rtiAmbassador().unsubscribeObjectClassAttributes(
      observerObjectClass,
      observerAttributes);
  publisher.rtiAmbassador().unpublishObjectClassAttributes(
      publisherObjectClass,
      publisherAttributes);
  observer.resign(rti::NO_ACTION);
  publisher.resign(rti::NO_ACTION);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  observer.disconnect();
  publisher.disconnect();
}

void scenarioJoinedFederateMomUpdatesSentCounts(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.fom.empty(),
      "Joined-federate MOM updates-sent testing requires an adapter-supplied FOM");
  require(
      !options.mimFom.empty(),
      "Joined-federate MOM updates-sent testing requires an adapter-supplied standard MIM");

  Session target(options, model, "owner");
  Session requester(options, model, "member");
  auto const federation = federationName(options, "joined-federate-mom-updates-sent-counts");
  target.connect();
  requester.connect();
  if (options.logicalTimeImplementationName.empty()) {
    target.rtiAmbassador().createFederationExecutionWithMIM(
        federation,
        std::vector<std::wstring>{options.fom.wstring()},
        options.mimFom.wstring());
  } else {
    target.rtiAmbassador().createFederationExecutionWithMIM(
        federation,
        std::vector<std::wstring>{options.fom.wstring()},
        options.mimFom.wstring(),
        options.logicalTimeImplementationName);
  }
  target.join(
      options.ownerFederateName + L"-mom-updates-sent-target",
      options.federateType,
      federation);
  requester.join(
      options.memberFederateName + L"-mom-updates-sent-requester",
      options.federateType,
      federation);

  auto const targetClass = target.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const targetReliable = target.rtiAmbassador().getAttributeHandle(
      targetClass,
      options.attributeName);
  require(
      targetClass.isValid() &&
          target.rtiAmbassador().getObjectClassName(targetClass) ==
              options.objectClassName,
      "Joined-federate MOM updates-sent object-class lookup did not round-trip");
  require(
      targetReliable.isValid() &&
          target.rtiAmbassador().getAttributeName(targetClass, targetReliable) ==
              options.attributeName,
      "Joined-federate MOM updates-sent attribute lookup did not round-trip");

  auto const reliable = target.rtiAmbassador().getTransportationTypeHandle(L"HLAreliable");
  auto const bestEffort = target.rtiAmbassador().getTransportationTypeHandle(L"HLAbestEffort");
  require(
      reliable.isValid() && bestEffort.isValid() &&
          target.rtiAmbassador().getTransportationTypeName(reliable) == L"HLAreliable" &&
          target.rtiAmbassador().getTransportationTypeName(bestEffort) == L"HLAbestEffort",
      "Joined-federate MOM updates-sent lookup could not resolve standard transports");
  target.rtiAmbassador().publishObjectClassAttributes(
      targetClass,
      rti::AttributeHandleSet{targetReliable});

  auto const object = target.rtiAmbassador().registerObjectInstance(targetClass);
  require(
      object.isValid(),
      "Joined-federate MOM updates-sent registration returned an invalid object handle");
  auto sendValue = [&](rti::AttributeHandle const& attribute, std::uint8_t value) {
    std::vector<std::uint8_t> bytes{value};
    rti::AttributeHandleValueMap values;
    values.emplace(
        attribute,
        rti::VariableLengthData(bytes.data(), bytes.size()));
    target.rtiAmbassador().updateAttributeValues(
        object,
        values,
        rti::VariableLengthData{});
  };
  sendValue(targetReliable, 0x51U);
  target.rtiAmbassador().requestAttributeTransportationTypeChange(
      object,
      rti::AttributeHandleSet{targetReliable},
      bestEffort);
  waitFor(
      target,
      [&] {
        auto const confirmations = target.recorder().attributeTransportationConfirmations();
        return !confirmations.empty();
      },
      options,
      "joined-federate MOM updates-sent transportation change");
  auto const transportationConfirmations =
      target.recorder().attributeTransportationConfirmations();
  require(
      transportationConfirmations.back().object == object &&
          transportationConfirmations.back().attributes.count(targetReliable) == 1U &&
          transportationConfirmations.back().transportation == bestEffort,
      "joined-federate MOM updates-sent transportation change did not commit best effort");
  sendValue(targetReliable, 0x52U);
  sendValue(targetReliable, 0x53U);

  auto const reportClass = requester.rtiAmbassador().getInteractionClassHandle(
      L"HLAinteractionRoot.HLAmanager.HLAfederate.HLAreport.HLAreportUpdatesSent");
  auto const requestClass = requester.rtiAmbassador().getInteractionClassHandle(
      L"HLAinteractionRoot.HLAmanager.HLAfederate.HLArequest.HLArequestUpdatesSent");
  auto const requestFederate = requester.rtiAmbassador().getParameterHandle(
      requestClass,
      L"HLAfederate");
  auto const reportTransportation = requester.rtiAmbassador().getParameterHandle(
      reportClass,
      L"HLAtransportation");
  auto const reportCounts = requester.rtiAmbassador().getParameterHandle(
      reportClass,
      L"HLAupdateCounts");
  require(
      reportClass.isValid() && requestClass.isValid() && requestFederate.isValid() &&
          reportTransportation.isValid() && reportCounts.isValid() &&
          requester.rtiAmbassador().getInteractionClassName(reportClass) ==
              L"HLAinteractionRoot.HLAmanager.HLAfederate.HLAreport.HLAreportUpdatesSent" &&
          requester.rtiAmbassador().getInteractionClassName(requestClass) ==
              L"HLAinteractionRoot.HLAmanager.HLAfederate.HLArequest.HLArequestUpdatesSent" &&
          requester.rtiAmbassador().getParameterName(requestClass, requestFederate) ==
              L"HLAfederate" &&
          requester.rtiAmbassador().getParameterName(reportClass, reportTransportation) ==
              L"HLAtransportation" &&
          requester.rtiAmbassador().getParameterName(reportClass, reportCounts) ==
              L"HLAupdateCounts",
      "Joined-federate MOM updates-sent lookup did not round-trip the standard report surface");
  requester.rtiAmbassador().subscribeInteractionClass(reportClass, true);

  auto const expectedClassEncoding = copyBytes(targetClass.encode());
  auto formatBytes = [](std::vector<std::uint8_t> const& bytes) {
    std::ostringstream stream;
    stream << std::hex;
    for (auto const byte : bytes) {
      if (byte < 0x10U) {
        stream << '0';
      }
      stream << static_cast<unsigned int>(byte);
    }
    return stream.str();
  };
  auto decodePositiveCount = [&](rti::VariableLengthData const& encoded,
                                 std::string const& description) {
    rti::HLAfixedRecord countPrototype;
    countPrototype.appendElement(rti::HLAvariableArray{rti::HLAbyte{}})
        .appendElement(rti::HLAinteger32BE{});
    rti::HLAvariableArray counts{countPrototype};
    counts.decode(encoded);
    require(
        counts.size() == 1U,
        description + " returned the wrong number of positive class counts");
    auto const& count = dynamic_cast<rti::HLAfixedRecord const&>(counts.get(0U));
    auto const& encodedClass = dynamic_cast<rti::HLAvariableArray const&>(count.get(0U));
    auto const countValue = dynamic_cast<rti::HLAinteger32BE const&>(count.get(1U)).get();
    auto const actualClassEncoding = copyBytes(encodedClass.encode());
    require(
        actualClassEncoding == expectedClassEncoding,
        description + " returned the wrong registered object class (expected " +
            formatBytes(expectedClassEncoding) + ", got " +
            formatBytes(actualClassEncoding) + ")");
    require(
        countValue > 0,
        description + " returned a non-positive class count");
    return countValue;
  };
  auto verifyEmptyCount = [&](rti::VariableLengthData const& encoded,
                              std::string const& description) {
    if (encoded.size() == 0U) {
      return;
    }
    rti::HLAfixedRecord countPrototype;
    countPrototype.appendElement(rti::HLAvariableArray{rti::HLAbyte{}})
        .appendElement(rti::HLAinteger32BE{});
    rti::HLAvariableArray counts{countPrototype};
    counts.decode(encoded);
    require(
        counts.size() == 0U,
        description + " encoded a non-empty class count list for a NULL response");
  };

  auto verifyReports = [&](std::vector<InteractionRecord> const& reports,
                           std::string const& description,
                           bool expectUpdates) {
    require(
        reports.size() == 2U,
        description + " did not return exactly one report for each standard transport");
    bool sawReliable = false;
    bool sawBestEffort = false;
    for (auto const& report : reports) {
      require(
          report.present && report.interaction == reportClass && report.parameters.size() == 2U &&
              report.parameters.count(reportTransportation) == 1U &&
              report.parameters.count(reportCounts) == 1U && report.tag.empty() &&
              report.transportation == reliable && !report.producer.isValid() &&
              !report.regions.has_value(),
          description + " returned non-standard report metadata");
      auto const transportBytes = copyBytes(report.parameters.at(reportTransportation));
      if (transportBytes == copyBytes(reliable.encode())) {
        require(!sawReliable, description + " returned duplicate reliable reports");
        sawReliable = true;
        if (expectUpdates) {
          require(
              decodePositiveCount(
                  report.parameters.at(reportCounts),
                  description + " reliable count") == 1,
              description + " returned the wrong reliable update count");
        } else {
          verifyEmptyCount(
              report.parameters.at(reportCounts),
              description + " reliable NULL count");
        }
      } else if (transportBytes == copyBytes(bestEffort.encode())) {
        require(!sawBestEffort, description + " returned duplicate best-effort reports");
        sawBestEffort = true;
        if (expectUpdates) {
          require(
              decodePositiveCount(
                  report.parameters.at(reportCounts),
                  description + " best-effort count") == 2,
              description + " returned the wrong best-effort update count");
        } else {
          verifyEmptyCount(
              report.parameters.at(reportCounts),
              description + " best-effort NULL count");
        }
      } else {
        require(false, description + " returned an unknown transportation value");
      }
    }
    require(
        sawReliable && sawBestEffort,
        description + " omitted a standard transportation bucket");
  };

  auto requestReports = [&](rti::FederateHandle const& subject,
                            std::string const& description) {
    requester.recorder().clearInteraction();
    requester.rtiAmbassador().sendInteraction(
        requestClass,
        rti::ParameterHandleValueMap{{requestFederate, subject.encode()}},
        rti::VariableLengthData{});
    waitFor(
        requester,
        [&] { return requester.recorder().interactions().size() >= 2U; },
        options,
        description);
    return requester.recorder().interactions();
  };

  auto const targetReports = requestReports(
      target.federateHandle(),
      "joined-federate MOM updates-sent target reports");
  verifyReports(targetReports, "joined-federate MOM updates-sent target", true);
  auto const requesterReports = requestReports(
      requester.federateHandle(),
      "joined-federate MOM updates-sent empty reports");
  verifyReports(requesterReports, "joined-federate MOM updates-sent empty", false);

  requester.rtiAmbassador().unsubscribeInteractionClass(reportClass);
  target.rtiAmbassador().unpublishObjectClassAttributes(
      targetClass,
      rti::AttributeHandleSet{targetReliable});
  requester.resign(rti::NO_ACTION);
  target.resign(rti::NO_ACTION);
  target.rtiAmbassador().destroyFederationExecution(federation);
  requester.disconnect();
  target.disconnect();
}

void scenarioJoinedFederateMomInteractionsReceivedCounts(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.fom.empty(),
      "Joined-federate MOM interactions-received testing requires an adapter-supplied FOM");
  require(
      !options.mimFom.empty(),
      "Joined-federate MOM interactions-received testing requires an adapter-supplied standard MIM");

  Session receiver(options, model, "owner");
  Session sender(options, model, "member");
  Session requester(options, model, "member");
  auto const federation =
      federationName(options, "joined-federate-mom-interactions-received-counts");
  receiver.connect();
  sender.connect();
  requester.connect();
  if (options.logicalTimeImplementationName.empty()) {
    receiver.rtiAmbassador().createFederationExecutionWithMIM(
        federation,
        std::vector<std::wstring>{options.fom.wstring()},
        options.mimFom.wstring());
  } else {
    receiver.rtiAmbassador().createFederationExecutionWithMIM(
        federation,
        std::vector<std::wstring>{options.fom.wstring()},
        options.mimFom.wstring(),
        options.logicalTimeImplementationName);
  }
  receiver.join(
      options.ownerFederateName + L"-mom-interactions-received-receiver",
      options.federateType,
      federation);
  sender.join(
      options.memberFederateName + L"-mom-interactions-received-sender",
      options.federateType,
      federation);
  requester.join(
      options.memberFederateName + L"-mom-interactions-received-requester",
      options.federateType,
      federation);

  auto const receiverInteraction = receiver.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const receiverParameter = receiver.rtiAmbassador().getParameterHandle(
      receiverInteraction,
      options.parameterName);
  require(
      receiverInteraction.isValid() &&
          receiver.rtiAmbassador().getInteractionClassName(receiverInteraction) ==
              options.interactionClassName,
      "Joined-federate MOM interactions-received interaction lookup did not round-trip");
  require(
      receiverParameter.isValid() &&
          receiver.rtiAmbassador().getParameterName(
              receiverInteraction,
              receiverParameter) == options.parameterName,
      "Joined-federate MOM interactions-received parameter lookup did not round-trip");

  auto const senderInteraction = sender.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const senderParameter = sender.rtiAmbassador().getParameterHandle(
      senderInteraction,
      options.parameterName);
  require(
      senderInteraction.isValid() && senderParameter.isValid(),
      "Joined-federate MOM interactions-received sender lookup returned invalid handles");
  auto const reliable = sender.rtiAmbassador().getTransportationTypeHandle(L"HLAreliable");
  auto const bestEffort = sender.rtiAmbassador().getTransportationTypeHandle(L"HLAbestEffort");
  require(
      reliable.isValid() && bestEffort.isValid() &&
          sender.rtiAmbassador().getTransportationTypeName(reliable) == L"HLAreliable" &&
          sender.rtiAmbassador().getTransportationTypeName(bestEffort) == L"HLAbestEffort",
      "Joined-federate MOM interactions-received lookup could not resolve standard transports");

  sender.rtiAmbassador().publishInteractionClass(senderInteraction);
  receiver.rtiAmbassador().subscribeInteractionClass(receiverInteraction, true);

  auto sendInteraction = [&](std::uint8_t value) {
    std::vector<std::uint8_t> bytes{value};
    sender.rtiAmbassador().sendInteraction(
        senderInteraction,
        rti::ParameterHandleValueMap{{
            senderParameter,
            rti::VariableLengthData(bytes.data(), bytes.size())}},
        rti::VariableLengthData{});
  };
  sendInteraction(0x61U);
  waitFor(
      receiver,
      [&] { return receiver.recorder().interactions().size() >= 1U; },
      options,
      "joined-federate MOM interactions-received reliable delivery");
  auto const confirmationBefore =
      sender.recorder().interactionTransportationConfirmations().size();
  sender.rtiAmbassador().requestInteractionTransportationTypeChange(
      senderInteraction,
      bestEffort);
  waitFor(
      sender,
      [&] {
        return sender.recorder().interactionTransportationConfirmations().size() >
            confirmationBefore;
      },
      options,
      "joined-federate MOM interactions-received transportation change");
  auto const transportationConfirmations =
      sender.recorder().interactionTransportationConfirmations();
  require(
      transportationConfirmations.back().interaction == senderInteraction &&
          transportationConfirmations.back().transportation == bestEffort,
      "Joined-federate MOM interactions-received transportation change did not commit best effort");
  sendInteraction(0x62U);
  sendInteraction(0x63U);
  waitFor(
      receiver,
      [&] { return receiver.recorder().interactions().size() >= 3U; },
      options,
      "joined-federate MOM interactions-received best-effort delivery");

  auto const received = receiver.recorder().interactions();
  require(
      received.size() == 3U,
      "Joined-federate MOM interactions-received receiver observed the wrong delivery count");
  std::size_t reliableReceived = 0U;
  std::size_t bestEffortReceived = 0U;
  for (auto const& interaction : received) {
    require(
        interaction.present && interaction.interaction == receiverInteraction &&
            interaction.parameters.size() == 1U &&
            interaction.parameters.count(receiverParameter) == 1U &&
            interaction.tag.empty() && interaction.producer == sender.federateHandle() &&
            !interaction.regions.has_value(),
        "Joined-federate MOM interactions-received delivery returned non-standard metadata");
    auto const value = copyBytes(interaction.parameters.at(receiverParameter));
    require(
        value.size() == 1U &&
            (value.front() == 0x61U || value.front() == 0x62U || value.front() == 0x63U),
        "Joined-federate MOM interactions-received delivery returned the wrong payload");
    if (interaction.transportation == reliable) {
      ++reliableReceived;
    } else if (interaction.transportation == bestEffort) {
      ++bestEffortReceived;
    } else {
      require(
          false,
          "Joined-federate MOM interactions-received delivery returned an unknown transport");
    }
  }
  require(
      reliableReceived == 1U && bestEffortReceived == 2U,
      "Joined-federate MOM interactions-received delivery returned wrong transport counts");

  auto const reportClass = requester.rtiAmbassador().getInteractionClassHandle(
      L"HLAinteractionRoot.HLAmanager.HLAfederate.HLAreport.HLAreportInteractionsReceived");
  auto const requestClass = requester.rtiAmbassador().getInteractionClassHandle(
      L"HLAinteractionRoot.HLAmanager.HLAfederate.HLArequest.HLArequestInteractionsReceived");
  auto const requestFederate = requester.rtiAmbassador().getParameterHandle(
      requestClass,
      L"HLAfederate");
  auto const reportTransportation = requester.rtiAmbassador().getParameterHandle(
      reportClass,
      L"HLAtransportation");
  auto const reportCounts = requester.rtiAmbassador().getParameterHandle(
      reportClass,
      L"HLAinteractionCounts");
  require(
      reportClass.isValid() && requestClass.isValid() && requestFederate.isValid() &&
          reportTransportation.isValid() && reportCounts.isValid() &&
          requester.rtiAmbassador().getInteractionClassName(reportClass) ==
              L"HLAinteractionRoot.HLAmanager.HLAfederate.HLAreport.HLAreportInteractionsReceived" &&
          requester.rtiAmbassador().getInteractionClassName(requestClass) ==
              L"HLAinteractionRoot.HLAmanager.HLAfederate.HLArequest.HLArequestInteractionsReceived" &&
          requester.rtiAmbassador().getParameterName(requestClass, requestFederate) ==
              L"HLAfederate" &&
          requester.rtiAmbassador().getParameterName(reportClass, reportTransportation) ==
              L"HLAtransportation" &&
          requester.rtiAmbassador().getParameterName(reportClass, reportCounts) ==
              L"HLAinteractionCounts",
      "Joined-federate MOM interactions-received lookup did not round-trip the standard report surface");
  requester.rtiAmbassador().subscribeInteractionClass(reportClass, true);

  auto const expectedInteractionEncoding = copyBytes(receiverInteraction.encode());
  auto formatBytes = [](std::vector<std::uint8_t> const& bytes) {
    std::ostringstream stream;
    stream << std::hex;
    for (auto const byte : bytes) {
      if (byte < 0x10U) {
        stream << '0';
      }
      stream << static_cast<unsigned int>(byte);
    }
    return stream.str();
  };
  auto decodePositiveCount = [&](rti::VariableLengthData const& encoded,
                                 std::int32_t expectedCount,
                                 std::string const& description) {
    rti::HLAfixedRecord countPrototype;
    countPrototype.appendElement(rti::HLAvariableArray{rti::HLAbyte{}})
        .appendElement(rti::HLAinteger32BE{});
    rti::HLAvariableArray counts{countPrototype};
    counts.decode(encoded);
    require(
        counts.size() == 1U,
        description + " returned the wrong number of positive interaction counts");
    auto const& count = dynamic_cast<rti::HLAfixedRecord const&>(counts.get(0U));
    auto const& encodedInteraction =
        dynamic_cast<rti::HLAvariableArray const&>(count.get(0U));
    auto const actualInteractionEncoding = copyBytes(encodedInteraction.encode());
    require(
        actualInteractionEncoding == expectedInteractionEncoding,
        description + " returned the wrong interaction class (expected " +
            formatBytes(expectedInteractionEncoding) + ", got " +
            formatBytes(actualInteractionEncoding) + ")");
    auto const countValue = dynamic_cast<rti::HLAinteger32BE const&>(count.get(1U)).get();
    require(
        countValue == expectedCount,
        description + " returned the wrong interaction count");
  };
  auto verifyEmptyCount = [&](rti::VariableLengthData const& encoded,
                              std::string const& description) {
    if (encoded.size() == 0U) {
      return;
    }
    rti::HLAfixedRecord countPrototype;
    countPrototype.appendElement(rti::HLAvariableArray{rti::HLAbyte{}})
        .appendElement(rti::HLAinteger32BE{});
    rti::HLAvariableArray counts{countPrototype};
    counts.decode(encoded);
    require(
        counts.size() == 0U,
        description + " encoded a non-empty interaction count list for a NULL response");
  };

  auto verifyReports = [&](std::vector<InteractionRecord> const& reports,
                           std::string const& description,
                           bool expectInteractions) {
    require(
        reports.size() == 2U,
        description + " did not return exactly one report for each standard transport");
    bool sawReliable = false;
    bool sawBestEffort = false;
    for (auto const& report : reports) {
      require(
          report.present && report.interaction == reportClass && report.parameters.size() == 2U &&
              report.parameters.count(reportTransportation) == 1U &&
              report.parameters.count(reportCounts) == 1U && report.tag.empty() &&
              report.transportation == reliable && !report.producer.isValid() &&
              !report.regions.has_value(),
          description + " returned non-standard report metadata");
      auto const transportBytes = copyBytes(report.parameters.at(reportTransportation));
      if (transportBytes == copyBytes(reliable.encode())) {
        require(!sawReliable, description + " returned duplicate reliable reports");
        sawReliable = true;
        if (expectInteractions) {
          decodePositiveCount(
              report.parameters.at(reportCounts),
              1,
              description + " reliable count");
        } else {
          verifyEmptyCount(
              report.parameters.at(reportCounts),
              description + " reliable NULL count");
        }
      } else if (transportBytes == copyBytes(bestEffort.encode())) {
        require(!sawBestEffort, description + " returned duplicate best-effort reports");
        sawBestEffort = true;
        if (expectInteractions) {
          decodePositiveCount(
              report.parameters.at(reportCounts),
              2,
              description + " best-effort count");
        } else {
          verifyEmptyCount(
              report.parameters.at(reportCounts),
              description + " best-effort NULL count");
        }
      } else {
        require(false, description + " returned an unknown transportation value");
      }
    }
    require(
        sawReliable && sawBestEffort,
        description + " omitted a standard transportation bucket");
  };

  auto requestReports = [&](rti::FederateHandle const& subject,
                            std::string const& description) {
    requester.recorder().clearInteraction();
    requester.rtiAmbassador().sendInteraction(
        requestClass,
        rti::ParameterHandleValueMap{{requestFederate, subject.encode()}},
        rti::VariableLengthData{});
    waitFor(
        requester,
        [&] { return requester.recorder().interactions().size() >= 2U; },
        options,
        description);
    return requester.recorder().interactions();
  };

  auto const receiverReports = requestReports(
      receiver.federateHandle(),
      "joined-federate MOM interactions-received receiver reports");
  verifyReports(receiverReports, "joined-federate MOM interactions-received receiver", true);
  auto const requesterReports = requestReports(
      requester.federateHandle(),
      "joined-federate MOM interactions-received empty reports");
  verifyReports(requesterReports, "joined-federate MOM interactions-received empty", false);

  requester.rtiAmbassador().unsubscribeInteractionClass(reportClass);
  receiver.rtiAmbassador().unsubscribeInteractionClass(receiverInteraction);
  sender.rtiAmbassador().unpublishInteractionClass(senderInteraction);
  requester.resign(rti::NO_ACTION);
  sender.resign(rti::NO_ACTION);
  receiver.resign(rti::NO_ACTION);
  receiver.rtiAmbassador().destroyFederationExecution(federation);
  requester.disconnect();
  sender.disconnect();
  receiver.disconnect();
}

void scenarioJoinedFederateMomDirectedInteractionsReceivedCounts(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.fom.empty(),
      "Joined-federate MOM directed-interactions-received testing requires an adapter-supplied FOM");
  require(
      !options.mimFom.empty(),
      "Joined-federate MOM directed-interactions-received testing requires an adapter-supplied standard MIM");

  Session receiver(options, model, "owner");
  Session sender(options, model, "member");
  Session requester(options, model, "member");
  auto const federation =
      federationName(options, "joined-federate-mom-directed-interactions-received-counts");
  receiver.connect();
  sender.connect();
  requester.connect();
  if (options.logicalTimeImplementationName.empty()) {
    receiver.rtiAmbassador().createFederationExecutionWithMIM(
        federation,
        std::vector<std::wstring>{options.fom.wstring()},
        options.mimFom.wstring());
  } else {
    receiver.rtiAmbassador().createFederationExecutionWithMIM(
        federation,
        std::vector<std::wstring>{options.fom.wstring()},
        options.mimFom.wstring(),
        options.logicalTimeImplementationName);
  }
  receiver.join(
      options.ownerFederateName + L"-mom-directed-interactions-received-receiver",
      options.federateType,
      federation);
  sender.join(
      options.memberFederateName + L"-mom-directed-interactions-received-sender",
      options.federateType,
      federation);
  requester.join(
      options.memberFederateName + L"-mom-directed-interactions-received-requester",
      options.federateType,
      federation);

  auto const receiverObjectClass = receiver.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const receiverAttribute = receiver.rtiAmbassador().getAttributeHandle(
      receiverObjectClass,
      options.attributeName);
  auto const senderObjectClass = sender.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const senderAttribute = sender.rtiAmbassador().getAttributeHandle(
      senderObjectClass,
      options.attributeName);
  auto const receiverInteraction = receiver.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const receiverParameter = receiver.rtiAmbassador().getParameterHandle(
      receiverInteraction,
      options.parameterName);
  auto const senderInteraction = sender.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const senderParameter = sender.rtiAmbassador().getParameterHandle(
      senderInteraction,
      options.parameterName);
  require(
      receiverObjectClass.isValid() && receiverAttribute.isValid() &&
          receiverInteraction.isValid() && receiverParameter.isValid() &&
          receiver.rtiAmbassador().getObjectClassName(receiverObjectClass) ==
              options.objectClassName &&
          receiver.rtiAmbassador().getAttributeName(
              receiverObjectClass,
              receiverAttribute) == options.attributeName &&
          receiver.rtiAmbassador().getInteractionClassName(receiverInteraction) ==
              options.interactionClassName &&
          receiver.rtiAmbassador().getParameterName(
              receiverInteraction,
              receiverParameter) == options.parameterName,
      "Joined-federate MOM directed-interactions-received receiver lookups did not round-trip");
  require(
      senderObjectClass.isValid() && senderAttribute.isValid() &&
          senderInteraction.isValid() && senderParameter.isValid(),
      "Joined-federate MOM directed-interactions-received sender lookup returned invalid handles");

  auto const reliable = sender.rtiAmbassador().getTransportationTypeHandle(L"HLAreliable");
  auto const bestEffort = sender.rtiAmbassador().getTransportationTypeHandle(L"HLAbestEffort");
  require(
      reliable.isValid() && bestEffort.isValid() &&
          sender.rtiAmbassador().getTransportationTypeName(reliable) == L"HLAreliable" &&
          sender.rtiAmbassador().getTransportationTypeName(bestEffort) == L"HLAbestEffort",
      "Joined-federate MOM directed-interactions-received lookup could not resolve standard transports");

  receiver.rtiAmbassador().publishObjectClassAttributes(
      receiverObjectClass,
      rti::AttributeHandleSet{receiverAttribute});
  sender.rtiAmbassador().subscribeObjectClassAttributes(
      senderObjectClass,
      rti::AttributeHandleSet{senderAttribute},
      true,
      L"");
  sender.rtiAmbassador().publishInteractionClass(senderInteraction);
  receiver.rtiAmbassador().subscribeInteractionClass(receiverInteraction, true);
  rti::InteractionClassHandleSet const senderDirectedInteractions{senderInteraction};
  rti::InteractionClassHandleSet const receiverDirectedInteractions{receiverInteraction};
  sender.rtiAmbassador().publishObjectClassDirectedInteractions(
      senderObjectClass,
      senderDirectedInteractions);
  receiver.rtiAmbassador().subscribeObjectClassDirectedInteractions(
      receiverObjectClass,
      receiverDirectedInteractions,
      true);

  auto const target = receiver.rtiAmbassador().registerObjectInstance(receiverObjectClass);
  require(target.isValid(), "Joined-federate MOM directed-interactions-received registration returned an invalid target");
  waitFor(
      sender,
      [&] { return sender.recorder().hasDiscovery(target); },
      options,
      "joined-federate MOM directed-interactions-received target discovery");

  std::vector<std::uint8_t> const parameterBytes{0x61U};
  rti::ParameterHandleValueMap const parameters{{
      senderParameter,
      rti::VariableLengthData(parameterBytes.data(), parameterBytes.size())}};
  sender.rtiAmbassador().sendInteraction(
      senderInteraction,
      parameters,
      rti::VariableLengthData{});
  waitFor(
      receiver,
      [&] { return receiver.recorder().interactions().size() >= 1U; },
      options,
      "joined-federate MOM directed-interactions-received ordinary delivery");
  auto const ordinaryReceives = receiver.recorder().interactions();
  require(
      ordinaryReceives.size() == 1U &&
          ordinaryReceives.front().interaction == receiverInteraction &&
          ordinaryReceives.front().parameters.size() == 1U &&
          ordinaryReceives.front().parameters.count(receiverParameter) == 1U &&
          copyBytes(ordinaryReceives.front().parameters.at(receiverParameter)) ==
              parameterBytes &&
          ordinaryReceives.front().tag.empty() &&
          ordinaryReceives.front().transportation == reliable &&
          ordinaryReceives.front().producer == sender.federateHandle() &&
          !ordinaryReceives.front().regions.has_value(),
      "Joined-federate MOM directed-interactions-received ordinary delivery returned non-standard metadata");

  sender.rtiAmbassador().sendDirectedInteraction(
      senderInteraction,
      target,
      parameters,
      rti::VariableLengthData{});
  waitFor(
      receiver,
      [&] { return receiver.recorder().directedInteractions().size() >= 1U; },
      options,
      "joined-federate MOM directed-interactions-received directed delivery");
  auto const directedReceives = receiver.recorder().directedInteractions();
  require(
      directedReceives.size() == 1U &&
          directedReceives.front().interaction == receiverInteraction &&
          directedReceives.front().object == target &&
          directedReceives.front().parameters.size() == 1U &&
          directedReceives.front().parameters.count(receiverParameter) == 1U &&
          copyBytes(directedReceives.front().parameters.at(receiverParameter)) ==
              parameterBytes &&
          directedReceives.front().tag.empty() &&
          directedReceives.front().transportation == reliable &&
          directedReceives.front().producer == sender.federateHandle(),
      "Joined-federate MOM directed-interactions-received directed delivery returned non-standard metadata");

  auto const confirmationBefore =
      sender.recorder().interactionTransportationConfirmations().size();
  sender.rtiAmbassador().requestInteractionTransportationTypeChange(
      senderInteraction,
      bestEffort);
  waitFor(
      sender,
      [&] {
        return sender.recorder().interactionTransportationConfirmations().size() >
            confirmationBefore;
      },
      options,
      "joined-federate MOM directed-interactions-received transportation change");
  auto const transportationConfirmations =
      sender.recorder().interactionTransportationConfirmations();
  require(
      transportationConfirmations.back().interaction == senderInteraction &&
          transportationConfirmations.back().transportation == bestEffort,
      "Joined-federate MOM directed-interactions-received transportation change did not commit best effort");

  auto const reportClass = requester.rtiAmbassador().getInteractionClassHandle(
      L"HLAinteractionRoot.HLAmanager.HLAfederate.HLAreport.HLAreportDirectedInteractionsReceived");
  auto const requestClass = requester.rtiAmbassador().getInteractionClassHandle(
      L"HLAinteractionRoot.HLAmanager.HLAfederate.HLArequest.HLArequestDirectedInteractionsReceived");
  auto const requestFederate = requester.rtiAmbassador().getParameterHandle(
      requestClass,
      L"HLAfederate");
  auto const reportTransportation = requester.rtiAmbassador().getParameterHandle(
      reportClass,
      L"HLAtransportation");
  auto const reportCounts = requester.rtiAmbassador().getParameterHandle(
      reportClass,
      L"HLAinteractionCounts");
  require(
      reportClass.isValid() && requestClass.isValid() && requestFederate.isValid() &&
          reportTransportation.isValid() && reportCounts.isValid() &&
          requester.rtiAmbassador().getInteractionClassName(reportClass) ==
              L"HLAinteractionRoot.HLAmanager.HLAfederate.HLAreport.HLAreportDirectedInteractionsReceived" &&
          requester.rtiAmbassador().getInteractionClassName(requestClass) ==
              L"HLAinteractionRoot.HLAmanager.HLAfederate.HLArequest.HLArequestDirectedInteractionsReceived" &&
          requester.rtiAmbassador().getParameterName(requestClass, requestFederate) ==
              L"HLAfederate" &&
          requester.rtiAmbassador().getParameterName(reportClass, reportTransportation) ==
              L"HLAtransportation" &&
          requester.rtiAmbassador().getParameterName(reportClass, reportCounts) ==
              L"HLAinteractionCounts",
      "Joined-federate MOM directed-interactions-received lookup did not round-trip the standard report surface");
  requester.rtiAmbassador().subscribeInteractionClass(reportClass, true);

  auto const expectedInteractionEncoding = copyBytes(receiverInteraction.encode());
  auto const reliableEncoding = copyBytes(reliable.encode());
  auto const bestEffortEncoding = copyBytes(bestEffort.encode());
  auto decodePositiveCount = [&](rti::VariableLengthData const& encoded,
                                 std::int32_t expectedCount,
                                 std::string const& description) {
    rti::HLAfixedRecord countPrototype;
    countPrototype.appendElement(rti::HLAvariableArray{rti::HLAbyte{}})
        .appendElement(rti::HLAinteger32BE{});
    rti::HLAvariableArray counts{countPrototype};
    counts.decode(encoded);
    require(counts.size() == 1U, description + " returned the wrong count-list size");
    auto const& count = dynamic_cast<rti::HLAfixedRecord const&>(counts.get(0U));
    auto const& encodedInteraction =
        dynamic_cast<rti::HLAvariableArray const&>(count.get(0U));
    require(
        copyBytes(encodedInteraction.encode()) == expectedInteractionEncoding,
        description + " returned the wrong interaction class");
    require(
        dynamic_cast<rti::HLAinteger32BE const&>(count.get(1U)).get() == expectedCount,
        description + " returned the wrong interaction count");
  };
  auto verifyEmptyCount = [&](rti::VariableLengthData const& encoded,
                              std::string const& description) {
    if (encoded.size() == 0U) {
      return;
    }
    rti::HLAfixedRecord countPrototype;
    countPrototype.appendElement(rti::HLAvariableArray{rti::HLAbyte{}})
        .appendElement(rti::HLAinteger32BE{});
    rti::HLAvariableArray counts{countPrototype};
    counts.decode(encoded);
    require(counts.size() == 0U, description + " returned a non-empty NULL count list");
  };
  auto verifyReports = [&](std::vector<InteractionRecord> const& reports,
                           std::string const& description,
                           bool expectDirected) {
    require(
        reports.size() == 2U,
        description + " did not return one report for each standard transport");
    bool sawReliable = false;
    bool sawBestEffort = false;
    for (auto const& report : reports) {
      require(
          report.present && report.interaction == reportClass &&
              report.parameters.size() == 2U &&
              report.parameters.count(reportTransportation) == 1U &&
              report.parameters.count(reportCounts) == 1U && report.tag.empty() &&
              report.transportation == reliable && !report.producer.isValid() &&
              !report.regions.has_value(),
          description + " returned non-standard report metadata");
      auto const encodedTransportation =
          copyBytes(report.parameters.at(reportTransportation));
      if (encodedTransportation == reliableEncoding) {
        require(!sawReliable, description + " returned duplicate reliable reports");
        sawReliable = true;
        if (expectDirected) {
          decodePositiveCount(
              report.parameters.at(reportCounts),
              1,
              description + " reliable count");
        } else {
          verifyEmptyCount(
              report.parameters.at(reportCounts),
              description + " reliable NULL count");
        }
      } else if (encodedTransportation == bestEffortEncoding) {
        require(!sawBestEffort, description + " returned duplicate best-effort reports");
        sawBestEffort = true;
        verifyEmptyCount(
            report.parameters.at(reportCounts),
            description + " best-effort count");
      } else {
        require(false, description + " returned an unknown transportation value");
      }
    }
    require(
        sawReliable && sawBestEffort,
        description + " omitted a standard transportation bucket");
  };
  auto requestReports = [&](rti::FederateHandle const& subject,
                            std::string const& description) {
    requester.recorder().clearInteraction();
    requester.rtiAmbassador().sendInteraction(
        requestClass,
        rti::ParameterHandleValueMap{{requestFederate, subject.encode()}},
        rti::VariableLengthData{});
    waitFor(
        requester,
        [&] { return requester.recorder().interactions().size() >= 2U; },
        options,
        description);
    return requester.recorder().interactions();
  };

  auto const receiverReports = requestReports(
      receiver.federateHandle(),
      "joined-federate MOM directed-interactions-received receiver reports");
  verifyReports(
      receiverReports,
      "joined-federate MOM directed-interactions-received receiver",
      true);
  auto const requesterReports = requestReports(
      requester.federateHandle(),
      "joined-federate MOM directed-interactions-received empty reports");
  verifyReports(
      requesterReports,
      "joined-federate MOM directed-interactions-received empty",
      false);

  requester.rtiAmbassador().unsubscribeInteractionClass(reportClass);
  receiver.rtiAmbassador().unsubscribeObjectClassDirectedInteractions(
      receiverObjectClass,
      receiverDirectedInteractions);
  sender.rtiAmbassador().unpublishObjectClassDirectedInteractions(
      senderObjectClass,
      senderDirectedInteractions);
  receiver.rtiAmbassador().unsubscribeInteractionClass(receiverInteraction);
  sender.rtiAmbassador().unpublishInteractionClass(senderInteraction);
  sender.rtiAmbassador().unsubscribeObjectClassAttributes(
      senderObjectClass,
      rti::AttributeHandleSet{senderAttribute});
  receiver.rtiAmbassador().unpublishObjectClassAttributes(
      receiverObjectClass,
      rti::AttributeHandleSet{receiverAttribute});
  requester.resign(rti::NO_ACTION);
  sender.resign(rti::NO_ACTION);
  receiver.resign(rti::DELETE_OBJECTS);
  receiver.rtiAmbassador().destroyFederationExecution(federation);
  requester.disconnect();
  sender.disconnect();
  receiver.disconnect();
}

void scenarioJoinedFederateMomReflectionsReceivedCounts(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.fom.empty(),
      "Joined-federate MOM reflections-received testing requires an adapter-supplied FOM");
  require(
      !options.mimFom.empty(),
      "Joined-federate MOM reflections-received testing requires an adapter-supplied standard MIM");

  Session receiver(options, model, "owner");
  Session sender(options, model, "member");
  Session requester(options, model, "member");
  auto const federation =
      federationName(options, "joined-federate-mom-reflections-received-counts");
  receiver.connect();
  sender.connect();
  requester.connect();
  if (options.logicalTimeImplementationName.empty()) {
    receiver.rtiAmbassador().createFederationExecutionWithMIM(
        federation,
        std::vector<std::wstring>{options.fom.wstring()},
        options.mimFom.wstring());
  } else {
    receiver.rtiAmbassador().createFederationExecutionWithMIM(
        federation,
        std::vector<std::wstring>{options.fom.wstring()},
        options.mimFom.wstring(),
        options.logicalTimeImplementationName);
  }
  receiver.join(
      options.ownerFederateName + L"-mom-reflections-received-receiver",
      options.federateType,
      federation);
  sender.join(
      options.memberFederateName + L"-mom-reflections-received-sender",
      options.federateType,
      federation);
  requester.join(
      options.memberFederateName + L"-mom-reflections-received-requester",
      options.federateType,
      federation);

  auto const senderObjectClass = sender.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const senderAttribute = sender.rtiAmbassador().getAttributeHandle(
      senderObjectClass,
      options.attributeName);
  auto const receiverObjectClass = receiver.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const receiverAttribute = receiver.rtiAmbassador().getAttributeHandle(
      receiverObjectClass,
      options.attributeName);
  require(
      senderObjectClass.isValid() &&
          sender.rtiAmbassador().getObjectClassName(senderObjectClass) ==
              options.objectClassName &&
          senderAttribute.isValid() &&
          sender.rtiAmbassador().getAttributeName(
              senderObjectClass,
              senderAttribute) == options.attributeName,
      "Joined-federate MOM reflections-received sender lookup did not round-trip");
  require(
      receiverObjectClass.isValid() &&
          receiver.rtiAmbassador().getObjectClassName(receiverObjectClass) ==
              options.objectClassName &&
          receiverAttribute.isValid() &&
          receiver.rtiAmbassador().getAttributeName(
              receiverObjectClass,
              receiverAttribute) == options.attributeName,
      "Joined-federate MOM reflections-received receiver lookup did not round-trip");

  auto const reliable = sender.rtiAmbassador().getTransportationTypeHandle(L"HLAreliable");
  auto const bestEffort =
      sender.rtiAmbassador().getTransportationTypeHandle(L"HLAbestEffort");
  require(
      reliable.isValid() && bestEffort.isValid() &&
          sender.rtiAmbassador().getTransportationTypeName(reliable) == L"HLAreliable" &&
          sender.rtiAmbassador().getTransportationTypeName(bestEffort) == L"HLAbestEffort",
      "Joined-federate MOM reflections-received lookup could not resolve standard transports");

  sender.rtiAmbassador().publishObjectClassAttributes(
      senderObjectClass,
      rti::AttributeHandleSet{senderAttribute});
  receiver.rtiAmbassador().subscribeObjectClassAttributes(
      receiverObjectClass,
      rti::AttributeHandleSet{receiverAttribute},
      true,
      L"");
  auto const object = sender.rtiAmbassador().registerObjectInstance(senderObjectClass);
  require(
      object.isValid(),
      "Joined-federate MOM reflections-received registration returned an invalid handle");
  waitFor(
      receiver,
      [&] { return receiver.recorder().hasDiscovery(object); },
      options,
      "joined-federate MOM reflections-received object discovery");
  receiver.recorder().clearReflection();

  auto updateAttribute = [&](std::uint8_t value) {
    std::vector<std::uint8_t> bytes{value};
    sender.rtiAmbassador().updateAttributeValues(
        object,
        rti::AttributeHandleValueMap{{
            senderAttribute,
            rti::VariableLengthData(bytes.data(), bytes.size())}},
        rti::VariableLengthData{});
  };
  // The first update uses the standard reliable default. The per-instance
  // request after that first callback makes the next two updates best effort.
  updateAttribute(0x71U);
  waitFor(
      receiver,
      [&] { return receiver.recorder().reflectionCount() >= 1U; },
      options,
      "joined-federate MOM reflections-received reliable delivery");

  auto const confirmationBefore =
      sender.recorder().attributeTransportationConfirmations().size();
  sender.rtiAmbassador().requestAttributeTransportationTypeChange(
      object,
      rti::AttributeHandleSet{senderAttribute},
      bestEffort);
  waitFor(
      sender,
      [&] {
        return sender.recorder().attributeTransportationConfirmations().size() >
            confirmationBefore;
      },
      options,
      "joined-federate MOM reflections-received transportation change");
  auto const transportationConfirmations =
      sender.recorder().attributeTransportationConfirmations();
  require(
      transportationConfirmations.back().object == object &&
          transportationConfirmations.back().attributes ==
              rti::AttributeHandleSet{senderAttribute} &&
          transportationConfirmations.back().transportation == bestEffort,
      "Joined-federate MOM reflections-received transportation change did not commit best effort");

  updateAttribute(0x72U);
  waitFor(
      receiver,
      [&] { return receiver.recorder().reflectionCount() >= 2U; },
      options,
      "joined-federate MOM reflections-received first best-effort delivery");
  updateAttribute(0x73U);
  waitFor(
      receiver,
      [&] { return receiver.recorder().reflectionCount() >= 3U; },
      options,
      "joined-federate MOM reflections-received second best-effort delivery");

  auto const reflections = receiver.recorder().reflections();
  require(
      reflections.size() == 3U,
      "Joined-federate MOM reflections-received receiver observed the wrong delivery count");
  std::size_t reliableReflections = 0U;
  std::size_t bestEffortReflections = 0U;
  for (auto const& reflection : reflections) {
    require(
        reflection.present && reflection.object == object &&
            reflection.values.size() == 1U &&
            reflection.values.count(receiverAttribute) == 1U &&
            reflection.tag.empty() && reflection.producer == sender.federateHandle() &&
            !reflection.regions.has_value(),
        "Joined-federate MOM reflections-received delivery returned non-standard metadata");
    auto const value = copyBytes(reflection.values.at(receiverAttribute));
    require(
        value.size() == 1U &&
            (value.front() == 0x71U || value.front() == 0x72U || value.front() == 0x73U),
        "Joined-federate MOM reflections-received delivery returned the wrong payload");
    if (reflection.transportation == reliable) {
      ++reliableReflections;
    } else if (reflection.transportation == bestEffort) {
      ++bestEffortReflections;
    } else {
      require(
          false,
          "Joined-federate MOM reflections-received delivery returned an unknown transport");
    }
  }
  require(
      reliableReflections == 1U && bestEffortReflections == 2U,
      "Joined-federate MOM reflections-received delivery returned wrong transport counts");

  auto const reportClass = requester.rtiAmbassador().getInteractionClassHandle(
      L"HLAinteractionRoot.HLAmanager.HLAfederate.HLAreport.HLAreportReflectionsReceived");
  auto const requestClass = requester.rtiAmbassador().getInteractionClassHandle(
      L"HLAinteractionRoot.HLAmanager.HLAfederate.HLArequest.HLArequestReflectionsReceived");
  auto const requestFederate = requester.rtiAmbassador().getParameterHandle(
      requestClass,
      L"HLAfederate");
  auto const reportTransportation = requester.rtiAmbassador().getParameterHandle(
      reportClass,
      L"HLAtransportation");
  auto const reportCounts = requester.rtiAmbassador().getParameterHandle(
      reportClass,
      L"HLAreflectCounts");
  require(
      reportClass.isValid() && requestClass.isValid() && requestFederate.isValid() &&
          reportTransportation.isValid() && reportCounts.isValid() &&
          requester.rtiAmbassador().getInteractionClassName(reportClass) ==
              L"HLAinteractionRoot.HLAmanager.HLAfederate.HLAreport.HLAreportReflectionsReceived" &&
          requester.rtiAmbassador().getInteractionClassName(requestClass) ==
              L"HLAinteractionRoot.HLAmanager.HLAfederate.HLArequest.HLArequestReflectionsReceived" &&
          requester.rtiAmbassador().getParameterName(requestClass, requestFederate) ==
              L"HLAfederate" &&
          requester.rtiAmbassador().getParameterName(reportClass, reportTransportation) ==
              L"HLAtransportation" &&
          requester.rtiAmbassador().getParameterName(reportClass, reportCounts) ==
              L"HLAreflectCounts",
      "Joined-federate MOM reflections-received lookup did not round-trip the standard report surface");
  requester.rtiAmbassador().subscribeInteractionClass(reportClass, true);

  auto const expectedClassEncoding = copyBytes(receiverObjectClass.encode());
  auto formatBytes = [](std::vector<std::uint8_t> const& bytes) {
    std::ostringstream stream;
    stream << std::hex;
    for (auto const byte : bytes) {
      if (byte < 0x10U) {
        stream << '0';
      }
      stream << static_cast<unsigned int>(byte);
    }
    return stream.str();
  };
  auto decodePositiveCount = [&](rti::VariableLengthData const& encoded,
                                 std::int32_t expectedCount,
                                 std::string const& description) {
    rti::HLAfixedRecord countPrototype;
    countPrototype.appendElement(rti::HLAvariableArray{rti::HLAbyte{}})
        .appendElement(rti::HLAinteger32BE{});
    rti::HLAvariableArray counts{countPrototype};
    counts.decode(encoded);
    require(
        counts.size() == 1U,
        description + " returned the wrong number of positive object-class counts");
    auto const& count = dynamic_cast<rti::HLAfixedRecord const&>(counts.get(0U));
    auto const& encodedClass = dynamic_cast<rti::HLAvariableArray const&>(count.get(0U));
    auto const actualClassEncoding = copyBytes(encodedClass.encode());
    require(
        actualClassEncoding == expectedClassEncoding,
        description + " returned the wrong object class (expected " +
            formatBytes(expectedClassEncoding) + ", got " +
            formatBytes(actualClassEncoding) + ")");
    auto const countValue = dynamic_cast<rti::HLAinteger32BE const&>(count.get(1U)).get();
    require(
        countValue == expectedCount,
        description + " returned the wrong reflection count");
  };
  auto verifyEmptyCount = [&](rti::VariableLengthData const& encoded,
                              std::string const& description) {
    if (encoded.size() == 0U) {
      return;
    }
    rti::HLAfixedRecord countPrototype;
    countPrototype.appendElement(rti::HLAvariableArray{rti::HLAbyte{}})
        .appendElement(rti::HLAinteger32BE{});
    rti::HLAvariableArray counts{countPrototype};
    counts.decode(encoded);
    require(
        counts.size() == 0U,
        description + " encoded a non-empty reflection count list for a NULL response");
  };

  auto verifyReports = [&](std::vector<InteractionRecord> const& reports,
                           std::string const& description,
                           bool expectReflections) {
    require(
        reports.size() == 2U,
        description + " did not return exactly one report for each standard transport");
    bool sawReliable = false;
    bool sawBestEffort = false;
    for (auto const& report : reports) {
      require(
          report.present && report.interaction == reportClass && report.parameters.size() == 2U &&
              report.parameters.count(reportTransportation) == 1U &&
              report.parameters.count(reportCounts) == 1U && report.tag.empty() &&
              report.transportation == reliable && !report.producer.isValid() &&
              !report.regions.has_value(),
          description + " returned non-standard report metadata");
      auto const transportBytes = copyBytes(report.parameters.at(reportTransportation));
      if (transportBytes == copyBytes(reliable.encode())) {
        require(!sawReliable, description + " returned duplicate reliable reports");
        sawReliable = true;
        if (expectReflections) {
          decodePositiveCount(
              report.parameters.at(reportCounts),
              1,
              description + " reliable count");
        } else {
          verifyEmptyCount(
              report.parameters.at(reportCounts),
              description + " reliable NULL count");
        }
      } else if (transportBytes == copyBytes(bestEffort.encode())) {
        require(!sawBestEffort, description + " returned duplicate best-effort reports");
        sawBestEffort = true;
        if (expectReflections) {
          decodePositiveCount(
              report.parameters.at(reportCounts),
              2,
              description + " best-effort count");
        } else {
          verifyEmptyCount(
              report.parameters.at(reportCounts),
              description + " best-effort NULL count");
        }
      } else {
        require(false, description + " returned an unknown transportation value");
      }
    }
    require(
        sawReliable && sawBestEffort,
        description + " omitted a standard transportation bucket");
  };

  auto requestReports = [&](rti::FederateHandle const& subject,
                            std::string const& description) {
    requester.recorder().clearInteraction();
    requester.rtiAmbassador().sendInteraction(
        requestClass,
        rti::ParameterHandleValueMap{{requestFederate, subject.encode()}},
        rti::VariableLengthData{});
    waitFor(
        requester,
        [&] { return requester.recorder().interactions().size() >= 2U; },
        options,
        description);
    return requester.recorder().interactions();
  };

  auto const receiverReports = requestReports(
      receiver.federateHandle(),
      "joined-federate MOM reflections-received receiver reports");
  verifyReports(receiverReports, "joined-federate MOM reflections-received receiver", true);
  auto const requesterReports = requestReports(
      requester.federateHandle(),
      "joined-federate MOM reflections-received empty reports");
  verifyReports(requesterReports, "joined-federate MOM reflections-received empty", false);

  requester.rtiAmbassador().unsubscribeInteractionClass(reportClass);
  receiver.rtiAmbassador().unsubscribeObjectClassAttributes(
      receiverObjectClass,
      rti::AttributeHandleSet{receiverAttribute});
  sender.rtiAmbassador().unpublishObjectClassAttributes(
      senderObjectClass,
      rti::AttributeHandleSet{senderAttribute});
  requester.resign(rti::NO_ACTION);
  sender.resign(rti::DELETE_OBJECTS);
  receiver.resign(rti::NO_ACTION);
  receiver.rtiAmbassador().destroyFederationExecution(federation);
  requester.disconnect();
  sender.disconnect();
  receiver.disconnect();
}

void scenarioJoinedFederateMomInteractionsSentCounts(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.fom.empty(),
      "Joined-federate MOM interactions-sent testing requires an adapter-supplied FOM");
  require(
      !options.mimFom.empty(),
      "Joined-federate MOM interactions-sent testing requires an adapter-supplied standard MIM");

  Session sender(options, model, "owner");
  Session requester(options, model, "member");
  Session idle(options, model, "member");
  auto const federation =
      federationName(options, "joined-federate-mom-interactions-sent-counts");
  sender.connect();
  requester.connect();
  idle.connect();
  if (options.logicalTimeImplementationName.empty()) {
    sender.rtiAmbassador().createFederationExecutionWithMIM(
        federation,
        std::vector<std::wstring>{options.fom.wstring()},
        options.mimFom.wstring());
  } else {
    sender.rtiAmbassador().createFederationExecutionWithMIM(
        federation,
        std::vector<std::wstring>{options.fom.wstring()},
        options.mimFom.wstring(),
        options.logicalTimeImplementationName);
  }
  sender.join(
      options.ownerFederateName + L"-mom-interactions-sent-sender",
      options.federateType,
      federation);
  requester.join(
      options.memberFederateName + L"-mom-interactions-sent-requester",
      options.federateType,
      federation);
  idle.join(
      options.memberFederateName + L"-mom-interactions-sent-idle",
      options.federateType,
      federation);

  auto const senderInteraction = sender.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const senderParameter = sender.rtiAmbassador().getParameterHandle(
      senderInteraction,
      options.parameterName);
  require(
      senderInteraction.isValid() &&
          sender.rtiAmbassador().getInteractionClassName(senderInteraction) ==
              options.interactionClassName,
      "Joined-federate MOM interactions-sent interaction lookup did not round-trip");
  require(
      senderParameter.isValid() &&
          sender.rtiAmbassador().getParameterName(
              senderInteraction,
              senderParameter) == options.parameterName,
      "Joined-federate MOM interactions-sent parameter lookup did not round-trip");

  auto const reliable = sender.rtiAmbassador().getTransportationTypeHandle(L"HLAreliable");
  auto const bestEffort = sender.rtiAmbassador().getTransportationTypeHandle(L"HLAbestEffort");
  require(
      reliable.isValid() && bestEffort.isValid() &&
          sender.rtiAmbassador().getTransportationTypeName(reliable) == L"HLAreliable" &&
          sender.rtiAmbassador().getTransportationTypeName(bestEffort) == L"HLAbestEffort",
      "Joined-federate MOM interactions-sent lookup could not resolve standard transports");
  sender.rtiAmbassador().publishInteractionClass(senderInteraction);

  auto sendInteraction = [&](std::uint8_t value) {
    std::vector<std::uint8_t> bytes{value};
    sender.rtiAmbassador().sendInteraction(
        senderInteraction,
        rti::ParameterHandleValueMap{{
            senderParameter,
            rti::VariableLengthData(bytes.data(), bytes.size())}},
        rti::VariableLengthData{});
  };
  sendInteraction(0x81U);
  sender.rtiAmbassador().requestInteractionTransportationTypeChange(
      senderInteraction,
      bestEffort);
  waitFor(
      sender,
      [&] {
        return !sender.recorder().interactionTransportationConfirmations().empty();
      },
      options,
      "joined-federate MOM interactions-sent transportation change");
  auto const transportationConfirmations =
      sender.recorder().interactionTransportationConfirmations();
  require(
      transportationConfirmations.back().interaction == senderInteraction &&
          transportationConfirmations.back().transportation == bestEffort,
      "Joined-federate MOM interactions-sent transportation change did not commit best effort");
  sendInteraction(0x82U);
  sendInteraction(0x83U);

  auto const reportClass = requester.rtiAmbassador().getInteractionClassHandle(
      L"HLAinteractionRoot.HLAmanager.HLAfederate.HLAreport.HLAreportInteractionsSent");
  auto const requestClass = requester.rtiAmbassador().getInteractionClassHandle(
      L"HLAinteractionRoot.HLAmanager.HLAfederate.HLArequest.HLArequestInteractionsSent");
  auto const requestFederate = requester.rtiAmbassador().getParameterHandle(
      requestClass,
      L"HLAfederate");
  auto const reportTransportation = requester.rtiAmbassador().getParameterHandle(
      reportClass,
      L"HLAtransportation");
  auto const reportCounts = requester.rtiAmbassador().getParameterHandle(
      reportClass,
      L"HLAinteractionCounts");
  require(
      reportClass.isValid() && requestClass.isValid() && requestFederate.isValid() &&
          reportTransportation.isValid() && reportCounts.isValid() &&
          requester.rtiAmbassador().getInteractionClassName(reportClass) ==
              L"HLAinteractionRoot.HLAmanager.HLAfederate.HLAreport.HLAreportInteractionsSent" &&
          requester.rtiAmbassador().getInteractionClassName(requestClass) ==
              L"HLAinteractionRoot.HLAmanager.HLAfederate.HLArequest.HLArequestInteractionsSent" &&
          requester.rtiAmbassador().getParameterName(requestClass, requestFederate) ==
              L"HLAfederate" &&
          requester.rtiAmbassador().getParameterName(reportClass, reportTransportation) ==
              L"HLAtransportation" &&
          requester.rtiAmbassador().getParameterName(reportClass, reportCounts) ==
              L"HLAinteractionCounts",
      "Joined-federate MOM interactions-sent lookup did not round-trip the standard report surface");
  requester.rtiAmbassador().subscribeInteractionClass(reportClass, true);

  auto const expectedInteractionEncoding = copyBytes(senderInteraction.encode());
  auto decodePositiveCount = [&](rti::VariableLengthData const& encoded,
                                 std::int32_t expectedCount,
                                 std::string const& description) {
    rti::HLAfixedRecord countPrototype;
    countPrototype.appendElement(rti::HLAvariableArray{rti::HLAbyte{}})
        .appendElement(rti::HLAinteger32BE{});
    rti::HLAvariableArray counts{countPrototype};
    counts.decode(encoded);
    require(
        counts.size() == 1U,
        description + " returned the wrong number of positive interaction counts");
    auto const& count = dynamic_cast<rti::HLAfixedRecord const&>(counts.get(0U));
    auto const& encodedInteraction =
        dynamic_cast<rti::HLAvariableArray const&>(count.get(0U));
    require(
        copyBytes(encodedInteraction.encode()) == expectedInteractionEncoding,
        description + " returned the wrong interaction class");
    require(
        dynamic_cast<rti::HLAinteger32BE const&>(count.get(1U)).get() == expectedCount,
        description + " returned the wrong interaction count");
  };
  auto verifyEmptyCount = [&](rti::VariableLengthData const& encoded,
                              std::string const& description) {
    if (encoded.size() == 0U) {
      return;
    }
    rti::HLAfixedRecord countPrototype;
    countPrototype.appendElement(rti::HLAvariableArray{rti::HLAbyte{}})
        .appendElement(rti::HLAinteger32BE{});
    rti::HLAvariableArray counts{countPrototype};
    counts.decode(encoded);
    require(
        counts.size() == 0U,
        description + " encoded a non-empty interaction count list for a NULL response");
  };

  auto verifyReports = [&](std::vector<InteractionRecord> const& reports,
                           std::string const& description,
                           bool expectInteractions) {
    require(
        reports.size() == 2U,
        description + " did not return exactly one report for each standard transport");
    bool sawReliable = false;
    bool sawBestEffort = false;
    for (auto const& report : reports) {
      require(
          report.present && report.interaction == reportClass &&
              report.parameters.size() == 2U &&
              report.parameters.count(reportTransportation) == 1U &&
              report.parameters.count(reportCounts) == 1U && report.tag.empty() &&
              report.transportation == reliable && !report.producer.isValid() &&
              !report.regions.has_value(),
          description + " returned non-standard report metadata");
      auto const transportBytes = copyBytes(report.parameters.at(reportTransportation));
      if (transportBytes == copyBytes(reliable.encode())) {
        require(!sawReliable, description + " returned duplicate reliable reports");
        sawReliable = true;
        if (expectInteractions) {
          decodePositiveCount(
              report.parameters.at(reportCounts),
              1,
              description + " reliable count");
        } else {
          verifyEmptyCount(
              report.parameters.at(reportCounts),
              description + " reliable NULL count");
        }
      } else if (transportBytes == copyBytes(bestEffort.encode())) {
        require(!sawBestEffort, description + " returned duplicate best-effort reports");
        sawBestEffort = true;
        if (expectInteractions) {
          decodePositiveCount(
              report.parameters.at(reportCounts),
              2,
              description + " best-effort count");
        } else {
          verifyEmptyCount(
              report.parameters.at(reportCounts),
              description + " best-effort NULL count");
        }
      } else {
        require(false, description + " returned an unknown transportation value");
      }
    }
    require(
        sawReliable && sawBestEffort,
        description + " omitted a standard transportation bucket");
  };

  auto requestReports = [&](rti::FederateHandle const& subject,
                            std::string const& description) {
    requester.recorder().clearInteraction();
    requester.rtiAmbassador().sendInteraction(
        requestClass,
        rti::ParameterHandleValueMap{{requestFederate, subject.encode()}},
        rti::VariableLengthData{});
    waitFor(
        requester,
        [&] { return requester.recorder().interactions().size() >= 2U; },
        options,
        description);
    return requester.recorder().interactions();
  };

  auto const senderReports = requestReports(
      sender.federateHandle(),
      "joined-federate MOM interactions-sent sender reports");
  verifyReports(senderReports, "joined-federate MOM interactions-sent sender", true);
  auto const idleReports = requestReports(
      idle.federateHandle(),
      "joined-federate MOM interactions-sent empty reports");
  verifyReports(idleReports, "joined-federate MOM interactions-sent empty", false);

  requester.rtiAmbassador().unsubscribeInteractionClass(reportClass);
  sender.rtiAmbassador().unpublishInteractionClass(senderInteraction);
  requester.resign(rti::NO_ACTION);
  idle.resign(rti::NO_ACTION);
  sender.resign(rti::NO_ACTION);
  sender.rtiAmbassador().destroyFederationExecution(federation);
  requester.disconnect();
  idle.disconnect();
  sender.disconnect();
}

void scenarioJoinedFederateMomDirectedInteractionsSentCounts(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.fom.empty(),
      "Joined-federate MOM directed-interactions-sent testing requires an adapter-supplied FOM");
  require(
      !options.mimFom.empty(),
      "Joined-federate MOM directed-interactions-sent testing requires an adapter-supplied standard MIM");

  Session sender(options, model, "owner");
  Session requester(options, model, "member");
  Session idle(options, model, "member");
  auto const federation =
      federationName(options, "joined-federate-mom-directed-interactions-sent-counts");
  sender.connect();
  requester.connect();
  idle.connect();
  if (options.logicalTimeImplementationName.empty()) {
    sender.rtiAmbassador().createFederationExecutionWithMIM(
        federation,
        std::vector<std::wstring>{options.fom.wstring()},
        options.mimFom.wstring());
  } else {
    sender.rtiAmbassador().createFederationExecutionWithMIM(
        federation,
        std::vector<std::wstring>{options.fom.wstring()},
        options.mimFom.wstring(),
        options.logicalTimeImplementationName);
  }
  sender.join(
      options.ownerFederateName + L"-mom-directed-interactions-sent-sender",
      options.federateType,
      federation);
  requester.join(
      options.memberFederateName + L"-mom-directed-interactions-sent-requester",
      options.federateType,
      federation);
  idle.join(
      options.memberFederateName + L"-mom-directed-interactions-sent-idle",
      options.federateType,
      federation);

  auto const senderObjectClass = sender.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const senderAttribute = sender.rtiAmbassador().getAttributeHandle(
      senderObjectClass,
      options.attributeName);
  auto const requesterObjectClass = requester.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const requesterAttribute = requester.rtiAmbassador().getAttributeHandle(
      requesterObjectClass,
      options.attributeName);
  auto const senderInteraction = sender.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const senderParameter = sender.rtiAmbassador().getParameterHandle(
      senderInteraction,
      options.parameterName);
  require(
      senderObjectClass.isValid() && senderAttribute.isValid() &&
          sender.rtiAmbassador().getObjectClassName(senderObjectClass) ==
              options.objectClassName &&
          sender.rtiAmbassador().getAttributeName(
              senderObjectClass,
              senderAttribute) == options.attributeName &&
          senderInteraction.isValid() &&
          sender.rtiAmbassador().getInteractionClassName(senderInteraction) ==
              options.interactionClassName &&
          senderParameter.isValid() &&
          sender.rtiAmbassador().getParameterName(
              senderInteraction,
              senderParameter) == options.parameterName,
      "Joined-federate MOM directed-interactions-sent sender lookup did not round-trip");
  require(
      requesterObjectClass.isValid() && requesterAttribute.isValid() &&
          requester.rtiAmbassador().getObjectClassName(requesterObjectClass) ==
              options.objectClassName &&
          requester.rtiAmbassador().getAttributeName(
              requesterObjectClass,
              requesterAttribute) == options.attributeName,
      "Joined-federate MOM directed-interactions-sent target lookup did not round-trip");

  auto const reliable = sender.rtiAmbassador().getTransportationTypeHandle(L"HLAreliable");
  auto const bestEffort = sender.rtiAmbassador().getTransportationTypeHandle(L"HLAbestEffort");
  require(
      reliable.isValid() && bestEffort.isValid() &&
          sender.rtiAmbassador().getTransportationTypeName(reliable) == L"HLAreliable" &&
          sender.rtiAmbassador().getTransportationTypeName(bestEffort) == L"HLAbestEffort",
      "Joined-federate MOM directed-interactions-sent lookup could not resolve standard transports");

  requester.rtiAmbassador().publishObjectClassAttributes(
      requesterObjectClass,
      rti::AttributeHandleSet{requesterAttribute});
  sender.rtiAmbassador().subscribeObjectClassAttributes(
      senderObjectClass,
      rti::AttributeHandleSet{senderAttribute},
      true,
      L"");
  sender.rtiAmbassador().publishInteractionClass(senderInteraction);
  rti::InteractionClassHandleSet const directedInteractions{senderInteraction};
  sender.rtiAmbassador().publishObjectClassDirectedInteractions(
      senderObjectClass,
      directedInteractions);

  auto const target = requester.rtiAmbassador().registerObjectInstance(requesterObjectClass);
  require(
      target.isValid(),
      "Joined-federate MOM directed-interactions-sent registration returned an invalid target");
  waitFor(
      sender,
      [&] { return sender.recorder().hasDiscovery(target); },
      options,
      "joined-federate MOM directed-interactions-sent target discovery");

  auto sendInteraction = [&](std::uint8_t value) {
    std::vector<std::uint8_t> bytes{value};
    sender.rtiAmbassador().sendInteraction(
        senderInteraction,
        rti::ParameterHandleValueMap{{
            senderParameter,
            rti::VariableLengthData(bytes.data(), bytes.size())}},
        rti::VariableLengthData{});
  };
  auto sendDirectedInteraction = [&](std::uint8_t value) {
    std::vector<std::uint8_t> bytes{value};
    sender.rtiAmbassador().sendDirectedInteraction(
        senderInteraction,
        target,
        rti::ParameterHandleValueMap{{
            senderParameter,
            rti::VariableLengthData(bytes.data(), bytes.size())}},
        rti::VariableLengthData{});
  };

  // Keep an ordinary send in the same reliable class ledger; the directed
  // report must count only the two target-qualified sends below.
  sendInteraction(0x81U);
  sendDirectedInteraction(0x82U);
  sendDirectedInteraction(0x83U);
  auto const confirmationBefore =
      sender.recorder().interactionTransportationConfirmations().size();
  sender.rtiAmbassador().requestInteractionTransportationTypeChange(
      senderInteraction,
      bestEffort);
  waitFor(
      sender,
      [&] {
        return sender.recorder().interactionTransportationConfirmations().size() >
            confirmationBefore;
      },
      options,
      "joined-federate MOM directed-interactions-sent transportation change");
  auto const transportationConfirmations =
      sender.recorder().interactionTransportationConfirmations();
  require(
      transportationConfirmations.back().interaction == senderInteraction &&
          transportationConfirmations.back().transportation == bestEffort,
      "Joined-federate MOM directed-interactions-sent transportation change did not commit best effort");
  sendInteraction(0x84U);

  auto const reportClass = sender.rtiAmbassador().getInteractionClassHandle(
      L"HLAinteractionRoot.HLAmanager.HLAfederate.HLAreport.HLAreportDirectedInteractionsSent");
  auto const requestClass = sender.rtiAmbassador().getInteractionClassHandle(
      L"HLAinteractionRoot.HLAmanager.HLAfederate.HLArequest.HLArequestDirectedInteractionsSent");
  auto const requestFederate = sender.rtiAmbassador().getParameterHandle(
      requestClass,
      L"HLAfederate");
  auto const reportTransportation = sender.rtiAmbassador().getParameterHandle(
      reportClass,
      L"HLAtransportation");
  auto const reportCounts = sender.rtiAmbassador().getParameterHandle(
      reportClass,
      L"HLAinteractionCounts");
  require(
      reportClass.isValid() && requestClass.isValid() && requestFederate.isValid() &&
          reportTransportation.isValid() && reportCounts.isValid() &&
          sender.rtiAmbassador().getInteractionClassName(reportClass) ==
              L"HLAinteractionRoot.HLAmanager.HLAfederate.HLAreport.HLAreportDirectedInteractionsSent" &&
          sender.rtiAmbassador().getInteractionClassName(requestClass) ==
              L"HLAinteractionRoot.HLAmanager.HLAfederate.HLArequest.HLArequestDirectedInteractionsSent" &&
          sender.rtiAmbassador().getParameterName(requestClass, requestFederate) ==
              L"HLAfederate" &&
          sender.rtiAmbassador().getParameterName(reportClass, reportTransportation) ==
              L"HLAtransportation" &&
          sender.rtiAmbassador().getParameterName(reportClass, reportCounts) ==
              L"HLAinteractionCounts",
      "Joined-federate MOM directed-interactions-sent lookup did not round-trip the standard report surface");
  requester.rtiAmbassador().subscribeInteractionClass(reportClass, true);

  auto const expectedInteractionEncoding = copyBytes(senderInteraction.encode());
  auto const reliableEncoding = copyBytes(reliable.encode());
  auto const bestEffortEncoding = copyBytes(bestEffort.encode());
  auto decodePositiveCount = [&](rti::VariableLengthData const& encoded,
                                 std::int32_t expectedCount,
                                 std::string const& description) {
    rti::HLAfixedRecord countPrototype;
    countPrototype.appendElement(rti::HLAvariableArray{rti::HLAbyte{}})
        .appendElement(rti::HLAinteger32BE{});
    rti::HLAvariableArray counts{countPrototype};
    counts.decode(encoded);
    require(counts.size() == 1U, description + " returned the wrong count-list size");
    auto const& count = dynamic_cast<rti::HLAfixedRecord const&>(counts.get(0U));
    auto const& encodedInteraction =
        dynamic_cast<rti::HLAvariableArray const&>(count.get(0U));
    require(
        copyBytes(encodedInteraction.encode()) == expectedInteractionEncoding,
        description + " returned the wrong interaction class");
    require(
        dynamic_cast<rti::HLAinteger32BE const&>(count.get(1U)).get() == expectedCount,
        description + " returned the wrong interaction count");
  };
  auto verifyEmptyCount = [&](rti::VariableLengthData const& encoded,
                              std::string const& description) {
    if (encoded.size() == 0U) {
      return;
    }
    rti::HLAfixedRecord countPrototype;
    countPrototype.appendElement(rti::HLAvariableArray{rti::HLAbyte{}})
        .appendElement(rti::HLAinteger32BE{});
    rti::HLAvariableArray counts{countPrototype};
    counts.decode(encoded);
    require(counts.size() == 0U, description + " returned a non-empty NULL count list");
  };
  auto verifyReports = [&](std::vector<InteractionRecord> const& reports,
                           std::string const& description,
                           bool expectDirected) {
    require(
        reports.size() == 2U,
        description + " did not return one report for each standard transport");
    bool sawReliable = false;
    bool sawBestEffort = false;
    for (auto const& report : reports) {
      require(
          report.present && report.interaction == reportClass &&
              report.parameters.size() == 2U &&
              report.parameters.count(reportTransportation) == 1U &&
              report.parameters.count(reportCounts) == 1U && report.tag.empty() &&
              report.transportation == reliable && !report.producer.isValid() &&
              !report.regions.has_value(),
          description + " returned non-standard report metadata");
      auto const encodedTransportation =
          copyBytes(report.parameters.at(reportTransportation));
      if (encodedTransportation == reliableEncoding) {
        require(!sawReliable, description + " returned duplicate reliable reports");
        sawReliable = true;
        if (expectDirected) {
          decodePositiveCount(
              report.parameters.at(reportCounts),
              2,
              description + " reliable count");
        } else {
          verifyEmptyCount(
              report.parameters.at(reportCounts),
              description + " reliable NULL count");
        }
      } else if (encodedTransportation == bestEffortEncoding) {
        require(!sawBestEffort, description + " returned duplicate best-effort reports");
        sawBestEffort = true;
        verifyEmptyCount(
            report.parameters.at(reportCounts),
            description + " best-effort NULL count");
      } else {
        require(false, description + " returned an unknown transportation value");
      }
    }
    require(
        sawReliable && sawBestEffort,
        description + " omitted a standard transportation bucket");
  };
  auto requestReports = [&](rti::FederateHandle const& subject,
                            std::string const& description) {
    requester.recorder().clearInteraction();
    requester.rtiAmbassador().sendInteraction(
        requestClass,
        rti::ParameterHandleValueMap{{requestFederate, subject.encode()}},
        rti::VariableLengthData{});
    waitFor(
        requester,
        [&] { return requester.recorder().interactions().size() >= 2U; },
        options,
        description);
    return requester.recorder().interactions();
  };

  auto const senderReports = requestReports(
      sender.federateHandle(),
      "joined-federate MOM directed-interactions-sent sender reports");
  verifyReports(
      senderReports,
      "joined-federate MOM directed-interactions-sent sender",
      true);
  auto const idleReports = requestReports(
      idle.federateHandle(),
      "joined-federate MOM directed-interactions-sent empty reports");
  verifyReports(
      idleReports,
      "joined-federate MOM directed-interactions-sent empty",
      false);

  requester.rtiAmbassador().unsubscribeInteractionClass(reportClass);
  sender.rtiAmbassador().unsubscribeObjectClassAttributes(
      senderObjectClass,
      rti::AttributeHandleSet{senderAttribute});
  requester.rtiAmbassador().unpublishObjectClassAttributes(
      requesterObjectClass,
      rti::AttributeHandleSet{requesterAttribute});
  sender.rtiAmbassador().unpublishObjectClassDirectedInteractions(
      senderObjectClass,
      directedInteractions);
  sender.rtiAmbassador().unpublishInteractionClass(senderInteraction);
  requester.resign(rti::DELETE_OBJECTS);
  idle.resign(rti::NO_ACTION);
  sender.resign(rti::NO_ACTION);
  sender.rtiAmbassador().destroyFederationExecution(federation);
  requester.disconnect();
  idle.disconnect();
  sender.disconnect();
}

void scenarioMomTransportationTypeChangeRequest(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.fom.empty(),
      "MOM transportation-type request testing requires an adapter-supplied FOM");
  require(
      !options.mimFom.empty(),
      "MOM transportation-type request testing requires an adapter-supplied standard MIM");

  Session subject(options, model, "mom-transportation-subject");
  Session observer(options, model, "mom-transportation-observer");
  auto const federation = federationName(
      options,
      "mom-transportation-type-change-request");
  subject.connect();
  observer.connect();
  subject.rtiAmbassador().createFederationExecutionWithMIM(
      federation,
      std::vector<std::wstring>{options.fom.wstring()},
      options.mimFom.wstring(),
      options.logicalTimeImplementationName);
  subject.join(
      options.ownerFederateName + L"-mom-transportation-subject",
      options.federateType,
      federation);
  observer.join(
      options.memberFederateName + L"-mom-transportation-observer",
      options.federateType,
      federation);

  subject.rtiAmbassador().setServiceReportingSwitch(false);
  subject.rtiAmbassador().setSendServiceReportsToFileSwitch(false);
  observer.rtiAmbassador().setServiceReportingSwitch(false);
  observer.rtiAmbassador().setSendServiceReportsToFileSwitch(false);

  rti::ObjectClassHandle subjectObjectClass;
  rti::AttributeHandle subjectAttribute;
  rti::InteractionClassHandle subjectInteraction;
  rti::ParameterHandle subjectParameter;
  handles(
      subject,
      options,
      subjectObjectClass,
      subjectAttribute,
      subjectInteraction,
      subjectParameter);
  rti::ObjectClassHandle observerObjectClass;
  rti::AttributeHandle observerAttribute;
  rti::InteractionClassHandle observerInteraction;
  rti::ParameterHandle observerParameter;
  handles(
      observer,
      options,
      observerObjectClass,
      observerAttribute,
      observerInteraction,
      observerParameter);
  require(
      subjectObjectClass == observerObjectClass &&
          subjectAttribute == observerAttribute &&
          subjectInteraction == observerInteraction &&
          subjectParameter == observerParameter &&
          observer.rtiAmbassador().getObjectClassName(observerObjectClass) ==
              options.objectClassName &&
          observer.rtiAmbassador().getAttributeName(
              observerObjectClass,
              observerAttribute) == options.attributeName &&
          observer.rtiAmbassador().getInteractionClassName(observerInteraction) ==
              options.interactionClassName &&
          observer.rtiAmbassador().getParameterName(
              observerInteraction,
              observerParameter) == options.parameterName,
      "MOM transportation-type request adapter declarations did not round-trip");

  auto const reliable = subject.rtiAmbassador().getTransportationTypeHandle(
      L"HLAreliable");
  auto const bestEffort = subject.rtiAmbassador().getTransportationTypeHandle(
      L"HLAbestEffort");
  require(
      reliable.isValid() && bestEffort.isValid() &&
          subject.rtiAmbassador().getTransportationTypeName(reliable) ==
              L"HLAreliable" &&
          subject.rtiAmbassador().getTransportationTypeName(bestEffort) ==
              L"HLAbestEffort",
      "MOM transportation-type request could not resolve the standard transport pair");

  rti::AttributeHandleSet const subjectAttributes{subjectAttribute};
  rti::AttributeHandleSet const observerAttributes{observerAttribute};
  subject.rtiAmbassador().publishObjectClassAttributes(
      subjectObjectClass,
      subjectAttributes);
  observer.rtiAmbassador().subscribeObjectClassAttributes(
      observerObjectClass,
      observerAttributes,
      true,
      L"");
  subject.rtiAmbassador().publishInteractionClass(subjectInteraction);
  subject.rtiAmbassador().subscribeInteractionClass(subjectInteraction, true);
  observer.rtiAmbassador().publishInteractionClass(observerInteraction);
  observer.rtiAmbassador().subscribeInteractionClass(observerInteraction, true);

  auto const object = subject.rtiAmbassador().registerObjectInstance(
      subjectObjectClass);
  require(
      object.isValid(),
      "MOM transportation-type request object registration returned an invalid handle");
  waitFor(
      observer,
      [&] { return observer.recorder().hasDiscovery(object); },
      options,
      "MOM transportation-type request object discovery");

  std::vector<std::uint8_t> const baselineValueBytes{0x42U, 0x41U};
  std::vector<std::uint8_t> const baselineTagBytes{0x42U};
  rti::ParameterHandleValueMap baselineParameters;
  baselineParameters.emplace(
      observerParameter,
      rti::VariableLengthData(
          baselineValueBytes.data(),
          baselineValueBytes.size()));
  rti::VariableLengthData const baselineTag(
      baselineTagBytes.data(),
      baselineTagBytes.size());
  subject.recorder().clearInteraction();
  observer.rtiAmbassador().sendInteraction(
      observerInteraction,
      baselineParameters,
      baselineTag);
  waitFor(
      subject,
      [&] { return subject.recorder().interaction().present; },
      options,
      "MOM transportation-type request baseline interaction");
  auto const baselineInteraction = subject.recorder().interaction();
  require(
      baselineInteraction.interaction == subjectInteraction &&
          baselineInteraction.parameters.size() == 1U &&
          copyBytes(baselineInteraction.parameters.at(subjectParameter)) ==
              baselineValueBytes &&
          baselineInteraction.tag == baselineTagBytes &&
          baselineInteraction.transportation == reliable &&
          baselineInteraction.producer == observer.federateHandle() &&
          !baselineInteraction.regions.has_value(),
      "MOM transportation-type request baseline interaction metadata was not reliable");

  auto encodeAttributeHandleList = [](rti::AttributeHandle const& attribute) {
    auto const encodedAttribute = copyBytes(attribute.encode());
    std::vector<std::uint8_t> bytes{0x00U, 0x00U, 0x00U, 0x01U};
    bytes.insert(bytes.end(), encodedAttribute.begin(), encodedAttribute.end());
    return rti::VariableLengthData(bytes.data(), bytes.size());
  };

  auto const requestAttributeClass = subject.rtiAmbassador().getInteractionClassHandle(
      L"HLAinteractionRoot.HLAmanager.HLAfederate.HLAservice.HLArequestAttributeTransportationTypeChange");
  auto const requestAttributeObject = subject.rtiAmbassador().getParameterHandle(
      requestAttributeClass,
      L"HLAobjectInstance");
  auto const requestAttributeList = subject.rtiAmbassador().getParameterHandle(
      requestAttributeClass,
      L"HLAattributeList");
  auto const requestAttributeTransportation = subject.rtiAmbassador().getParameterHandle(
      requestAttributeClass,
      L"HLAtransportation");
  require(
      requestAttributeClass.isValid() && requestAttributeObject.isValid() &&
          requestAttributeList.isValid() && requestAttributeTransportation.isValid(),
      "MOM transportation-type request attribute interaction lookup failed");

  subject.recorder().clearTransportationRecords();
  subject.rtiAmbassador().sendInteraction(
      requestAttributeClass,
      rti::ParameterHandleValueMap{
          {requestAttributeObject, object.encode()},
          {requestAttributeList, encodeAttributeHandleList(subjectAttribute)},
          {requestAttributeTransportation, bestEffort.encode()}},
      rti::VariableLengthData{});
  waitFor(
      subject,
      [&] {
        return subject.recorder().attributeTransportationConfirmations().size() >= 1U;
      },
      options,
      "MOM transportation-type request attribute confirmation");
  auto const attributeConfirmations =
      subject.recorder().attributeTransportationConfirmations();
  require(
      attributeConfirmations.size() == 1U &&
          attributeConfirmations.front().object == object &&
          attributeConfirmations.front().attributes == subjectAttributes &&
          attributeConfirmations.front().transportation == bestEffort,
      "MOM transportation-type request attribute confirmation did not commit best effort");

  std::vector<std::uint8_t> const valueBytes{0xA1U};
  rti::AttributeHandleValueMap values;
  values.emplace(
      subjectAttribute,
      rti::VariableLengthData(valueBytes.data(), valueBytes.size()));
  observer.recorder().clearReflection();
  subject.rtiAmbassador().updateAttributeValues(
      object,
      values,
      rti::VariableLengthData{});
  waitFor(
      observer,
      [&] { return observer.recorder().reflection().present; },
      options,
      "MOM transportation-type request attribute delivery");
  auto const reflection = observer.recorder().reflection();
  require(
      reflection.object == object && reflection.values.size() == 1U &&
          copyBytes(reflection.values.at(observerAttribute)) == valueBytes &&
          reflection.transportation == bestEffort &&
          reflection.producer == subject.federateHandle() &&
          reflection.tag.empty() && !reflection.regions.has_value(),
      "MOM transportation-type request did not route the attribute as best effort");

  auto const requestInteractionClass = subject.rtiAmbassador().getInteractionClassHandle(
      L"HLAinteractionRoot.HLAmanager.HLAfederate.HLAservice.HLArequestInteractionTransportationTypeChange");
  auto const requestInteractionTarget = subject.rtiAmbassador().getParameterHandle(
      requestInteractionClass,
      L"HLAinteractionClass");
  auto const requestInteractionTransportation = subject.rtiAmbassador().getParameterHandle(
      requestInteractionClass,
      L"HLAtransportation");
  require(
      requestInteractionClass.isValid() && requestInteractionTarget.isValid() &&
          requestInteractionTransportation.isValid(),
      "MOM transportation-type request interaction lookup failed");

  subject.recorder().clearInteraction();
  observer.rtiAmbassador().sendInteraction(
      observerInteraction,
      rti::ParameterHandleValueMap{},
      rti::VariableLengthData{});
  waitFor(
      subject,
      [&] { return subject.recorder().interaction().present; },
      options,
      "MOM transportation-type request independent publisher baseline");
  require(
      subject.recorder().interaction().transportation == reliable,
      "MOM transportation-type request changed the independent publisher");

  subject.recorder().clearTransportationRecords();
  subject.rtiAmbassador().sendInteraction(
      requestInteractionClass,
      rti::ParameterHandleValueMap{
          {requestInteractionTarget, subjectInteraction.encode()},
          {requestInteractionTransportation, bestEffort.encode()}},
      rti::VariableLengthData{});
  waitFor(
      subject,
      [&] {
        return subject.recorder().interactionTransportationConfirmations().size() >= 1U;
      },
      options,
      "MOM transportation-type request interaction confirmation");
  auto const interactionConfirmations =
      subject.recorder().interactionTransportationConfirmations();
  require(
      interactionConfirmations.size() == 1U &&
          interactionConfirmations.front().interaction == subjectInteraction &&
          interactionConfirmations.front().transportation == bestEffort,
      "MOM transportation-type request interaction confirmation did not commit best effort");

  std::vector<std::uint8_t> const changedTagBytes{0x54U};
  rti::VariableLengthData const changedTag(
      changedTagBytes.data(),
      changedTagBytes.size());
  observer.recorder().clearInteraction();
  subject.rtiAmbassador().sendInteraction(
      subjectInteraction,
      rti::ParameterHandleValueMap{},
      changedTag);
  waitFor(
      observer,
      [&] { return observer.recorder().interaction().present; },
      options,
      "MOM transportation-type request changed interaction delivery");
  auto const changedInteraction = observer.recorder().interaction();
  require(
      changedInteraction.interaction == observerInteraction &&
          changedInteraction.transportation == bestEffort &&
          changedInteraction.tag == changedTagBytes &&
          changedInteraction.producer == subject.federateHandle() &&
          !changedInteraction.regions.has_value(),
      "MOM transportation-type request did not route the interaction as best effort");

  subject.recorder().clearInteraction();
  observer.rtiAmbassador().sendInteraction(
      observerInteraction,
      rti::ParameterHandleValueMap{},
      rti::VariableLengthData{});
  waitFor(
      subject,
      [&] { return subject.recorder().interaction().present; },
      options,
      "MOM transportation-type request independent publisher post-change delivery");
  require(
      subject.recorder().interaction().transportation == reliable,
      "MOM transportation-type request changed the independent publisher after interaction change");

  auto const reportClass = observer.rtiAmbassador().getInteractionClassHandle(
      L"HLAinteractionRoot.HLAmanager.HLAfederate.HLAreport.HLAreportServiceInvocation");
  auto const reportService = observer.rtiAmbassador().getParameterHandle(
      reportClass,
      L"HLAservice");
  require(
      reportClass.isValid() && reportService.isValid(),
      "MOM transportation-type request service-report lookup failed");
  observer.rtiAmbassador().subscribeInteractionClass(reportClass, true);
  subject.rtiAmbassador().setServiceReportingSwitch(true);
  observer.recorder().clearInteraction();
  subject.rtiAmbassador().sendInteraction(
      requestInteractionClass,
      rti::ParameterHandleValueMap{
          {requestInteractionTarget, subjectInteraction.encode()},
          {requestInteractionTransportation, reliable.encode()}},
      rti::VariableLengthData{});
  waitFor(
      observer,
      [&] { return observer.recorder().interaction().present; },
      options,
      "MOM transportation-type request service report");
  auto const serviceReport = observer.recorder().interaction();
  require(
      serviceReport.interaction == reportClass &&
          serviceReport.parameters.count(reportService) == 1U &&
          serviceReport.transportation == reliable &&
          !serviceReport.producer.isValid() && serviceReport.tag.empty() &&
          !serviceReport.regions.has_value(),
      "MOM transportation-type request service report metadata was not standard");
  rti::HLAunicodeString service;
  service.decode(serviceReport.parameters.at(reportService));
  require(
      service.get() == L"SendInteraction",
      "MOM transportation-type request service report named the wrong service");
  subject.rtiAmbassador().setServiceReportingSwitch(false);

  observer.rtiAmbassador().unsubscribeInteractionClass(reportClass);
  observer.rtiAmbassador().unsubscribeInteractionClass(observerInteraction);
  subject.rtiAmbassador().unsubscribeInteractionClass(subjectInteraction);
  observer.rtiAmbassador().unsubscribeObjectClassAttributes(
      observerObjectClass,
      observerAttributes);
  observer.rtiAmbassador().unpublishInteractionClass(observerInteraction);
  subject.rtiAmbassador().unpublishInteractionClass(subjectInteraction);
  subject.rtiAmbassador().unpublishObjectClassAttributes(
      subjectObjectClass,
      subjectAttributes);
  observer.resign(rti::NO_ACTION);
  subject.resign(rti::DELETE_OBJECTS);
  subject.rtiAmbassador().destroyFederationExecution(federation);
  observer.disconnect();
  subject.disconnect();
}

void scenarioJoinedFederateMomReflectionCounts(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.fom.empty(),
      "Joined-federate MOM reflection-count testing requires an adapter-supplied FOM");
  require(
      !options.mimFom.empty(),
      "Joined-federate MOM reflection-count testing requires an adapter-supplied standard MIM");
  require(
      !options.logicalTimeImplementationName.empty(),
      "Joined-federate MOM reflection-count testing requires an adapter-supplied logical-time implementation");

  Session publisher(options, model, "owner");
  Session receiver(options, model, "member");
  auto const federation =
      federationName(options, "joined-federate-mom-reflection-counts");
  publisher.connect();
  receiver.connect();
  publisher.rtiAmbassador().createFederationExecutionWithMIM(
      federation,
      std::vector<std::wstring>{options.fom.wstring()},
      options.mimFom.wstring(),
      options.logicalTimeImplementationName);
  receiver.join(
      options.memberFederateName + L"-mom-reflection-count-receiver",
      options.federateType,
      federation);
  auto const receiverFederate = receiver.federateHandle();

  auto const momClass = receiver.rtiAmbassador().getObjectClassHandle(
      L"HLAobjectRoot.HLAmanager.HLAfederate");
  auto const federateHandleAttribute = receiver.rtiAmbassador().getAttributeHandle(
      momClass,
      L"HLAfederateHandle");
  auto const reflectedObjectsAttribute = receiver.rtiAmbassador().getAttributeHandle(
      momClass,
      L"HLAobjectInstancesReflected");
  auto const reflectionsReceivedAttribute = receiver.rtiAmbassador().getAttributeHandle(
      momClass,
      L"HLAreflectionsReceived");
  auto const reliable = receiver.rtiAmbassador().getTransportationTypeHandle(
      L"HLAreliable");
  require(
      momClass.isValid() &&
          receiver.rtiAmbassador().getObjectClassName(momClass) ==
              L"HLAobjectRoot.HLAmanager.HLAfederate" &&
          federateHandleAttribute.isValid() && reflectedObjectsAttribute.isValid() &&
          reflectionsReceivedAttribute.isValid() && reliable.isValid() &&
          receiver.rtiAmbassador().getTransportationTypeName(reliable) == L"HLAreliable",
      "Joined-federate MOM reflection-count lookup did not resolve the standard surface");
  rti::AttributeHandleSet const momAttributes{
      federateHandleAttribute,
      reflectedObjectsAttribute,
      reflectionsReceivedAttribute};
  receiver.rtiAmbassador().subscribeObjectClassAttributes(
      momClass,
      momAttributes,
      true,
      L"");

  auto const findReceiverMomReflection = [&]() -> std::optional<ReflectionRecord> {
    auto const reflections = receiver.recorder().reflections();
    auto const expectedFederateHandle = copyBytes(receiverFederate.encode());
    auto const iterator = std::find_if(
        reflections.begin(),
        reflections.end(),
        [&](ReflectionRecord const& reflection) {
          auto const value = reflection.values.find(federateHandleAttribute);
          return reflection.present && value != reflection.values.end() &&
              copyBytes(value->second) == expectedFederateHandle;
        });
    if (iterator == reflections.end()) {
      return std::nullopt;
    }
    return *iterator;
  };
  waitFor(
      receiver,
      [&] { return findReceiverMomReflection().has_value(); },
      options,
      "joined-federate MOM reflection-count self discovery");
  auto const initialMomReflection = findReceiverMomReflection();
  require(
      initialMomReflection.has_value() && initialMomReflection->object.isValid() &&
          receiver.rtiAmbassador().getKnownObjectClassHandle(
              initialMomReflection->object) == momClass,
      "Joined-federate MOM reflection-count discovery returned the wrong standard object");
  auto const receiverMomObject = initialMomReflection->object;

  auto const findCountReflection = [&](std::size_t before)
      -> std::optional<ReflectionRecord> {
    auto const reflections = receiver.recorder().reflections();
    if (before > reflections.size()) {
      return std::nullopt;
    }
    auto const iterator = std::find_if(
        reflections.begin() + static_cast<std::ptrdiff_t>(before),
        reflections.end(),
        [&](ReflectionRecord const& reflection) {
          return reflection.present && reflection.object == receiverMomObject &&
              reflection.values.count(reflectedObjectsAttribute) == 1U &&
              reflection.values.count(reflectionsReceivedAttribute) == 1U;
        });
    if (iterator == reflections.end()) {
      return std::nullopt;
    }
    return *iterator;
  };
  auto decodeCounts = [&](ReflectionRecord const& reflection,
                          std::string const& description) {
    require(
        reflection.values.size() == 2U && reflection.transportation == reliable &&
            reflection.tag.empty() && !reflection.producer.isValid() &&
            !reflection.regions.has_value(),
        description + " returned non-standard MOM reflection metadata");
    rti::HLAinteger32BE reflectedObjects;
    rti::HLAinteger32BE reflectionsReceived;
    reflectedObjects.decode(reflection.values.at(reflectedObjectsAttribute));
    reflectionsReceived.decode(reflection.values.at(reflectionsReceivedAttribute));
    require(
        reflectedObjects.get() >= 0 && reflectionsReceived.get() >= 0,
        description + " returned a negative reflection count");
    return std::pair<std::int32_t, std::int32_t>{
        reflectedObjects.get(),
        reflectionsReceived.get()};
  };
  auto requestCounts = [&](std::string const& description) {
    auto const before = receiver.recorder().reflections().size();
    receiver.rtiAmbassador().requestAttributeValueUpdate(
        receiverMomObject,
        rti::AttributeHandleSet{
            reflectedObjectsAttribute,
            reflectionsReceivedAttribute},
        rti::VariableLengthData{});
    waitFor(
        receiver,
        [&] { return findCountReflection(before).has_value(); },
        options,
        description);
    auto const reflection = findCountReflection(before);
    require(reflection.has_value(), description + " produced no count reflection");
    return decodeCounts(*reflection, description);
  };

  auto const initialCounts = requestCounts(
      "joined-federate MOM reflection-count initial direct request");
  require(
      initialCounts.first == 0 && initialCounts.second == 0,
      "Joined-federate MOM reflection-count initial values were not zero");

  publisher.join(
      options.ownerFederateName + L"-mom-reflection-count-publisher",
      options.federateType,
      federation);
  auto const publisherClass = publisher.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const publisherAttribute = publisher.rtiAmbassador().getAttributeHandle(
      publisherClass,
      options.attributeName);
  require(
      publisherClass.isValid() &&
          publisher.rtiAmbassador().getObjectClassName(publisherClass) ==
              options.objectClassName &&
          publisherAttribute.isValid() &&
          publisher.rtiAmbassador().getAttributeName(
              publisherClass,
              publisherAttribute) == options.attributeName,
      "Joined-federate MOM reflection-count adapter object lookup did not round-trip");
  auto const receiverClass = receiver.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const receiverAttribute = receiver.rtiAmbassador().getAttributeHandle(
      receiverClass,
      options.attributeName);
  require(
      receiverClass.isValid() && receiverAttribute.isValid(),
      "Joined-federate MOM reflection-count receiver object lookup returned invalid handles");
  publisher.rtiAmbassador().publishObjectClassAttributes(
      publisherClass,
      rti::AttributeHandleSet{publisherAttribute});
  receiver.rtiAmbassador().subscribeObjectClassAttributes(
      receiverClass,
      rti::AttributeHandleSet{receiverAttribute},
      true,
      L"");

  auto const objectOne = publisher.rtiAmbassador().registerObjectInstance(publisherClass);
  auto const objectTwo = publisher.rtiAmbassador().registerObjectInstance(publisherClass);
  require(
      objectOne.isValid() && objectTwo.isValid(),
      "Joined-federate MOM reflection-count registration returned an invalid handle");
  waitFor(
      receiver,
      [&] {
        return receiver.recorder().hasDiscovery(objectOne) &&
            receiver.recorder().hasDiscovery(objectTwo);
      },
      options,
      "joined-federate MOM reflection-count object discovery");

  auto const applicationReflectionCount = [&](rti::ObjectInstanceHandle const& object) {
    auto const reflections = receiver.recorder().reflections();
    auto const timedReflections = receiver.recorder().timedReflections();
    auto const receiveOrderCount = static_cast<std::size_t>(std::count_if(
        reflections.begin(),
        reflections.end(),
        [&](ReflectionRecord const& reflection) {
          return reflection.present && reflection.object == object;
        }));
    auto const timestampedCount = static_cast<std::size_t>(std::count_if(
        timedReflections.begin(),
        timedReflections.end(),
        [&](TimedReflectionRecord const& reflection) {
          return reflection.object == object;
        }));
    return receiveOrderCount + timestampedCount;
  };
  auto sendReceiveOrderUpdate = [&](rti::ObjectInstanceHandle const& object,
                                    std::uint8_t value,
                                    std::size_t expectedReflections,
                                    std::string const& description) {
    publisher.rtiAmbassador().updateAttributeValues(
        object,
        rti::AttributeHandleValueMap{{
            publisherAttribute,
            rti::HLAbyte{static_cast<rti::Octet>(value)}.encode()}},
        rti::VariableLengthData{});
    waitFor(
        receiver,
        [&] { return applicationReflectionCount(object) >= expectedReflections; },
        options,
        description);
  };

  sendReceiveOrderUpdate(
      objectOne,
      0x31U,
      1U,
      "joined-federate MOM reflection-count first object reflection");
  auto const firstCounts = requestCounts(
      "joined-federate MOM reflection-count after first reflection");
  require(
      firstCounts.first == 1 && firstCounts.second == 1,
      "Joined-federate MOM reflection-count first values were incorrect");

  sendReceiveOrderUpdate(
      objectOne,
      0x32U,
      2U,
      "joined-federate MOM reflection-count repeated object reflection");
  auto const secondCounts = requestCounts(
      "joined-federate MOM reflection-count after repeated reflection");
  require(
      secondCounts.first == 1 && secondCounts.second == 2,
      "Joined-federate MOM reflection-count repeated-object values were incorrect");

  sendReceiveOrderUpdate(
      objectTwo,
      0x33U,
      1U,
      "joined-federate MOM reflection-count second object reflection");
  auto const thirdCounts = requestCounts(
      "joined-federate MOM reflection-count after second object");
  require(
      thirdCounts.first == 2 && thirdCounts.second == 3,
      "Joined-federate MOM reflection-count distinct-object values were incorrect");

  publisher.rtiAmbassador().changeAttributeOrderType(
      objectTwo,
      rti::AttributeHandleSet{publisherAttribute},
      rti::TIMESTAMP);
  auto publisherTime = makeTimeContext(publisher);
  auto receiverTime = makeTimeContext(receiver);
  require(
      publisherTime.factory->getName() == receiverTime.factory->getName(),
      "Joined-federate MOM reflection-count members selected different logical-time factories");
  receiver.rtiAmbassador().enableTimeConstrained();
  waitFor(
      receiver,
      [&] { return receiver.recorder().timeConstrainedEnabled().size() >= 1U; },
      options,
      "joined-federate MOM reflection-count time-constrained callback");
  publisher.rtiAmbassador().enableTimeRegulation(*publisherTime.epsilon);
  waitFor(
      publisher,
      [&] { return publisher.recorder().timeRegulationEnabled().size() >= 1U; },
      options,
      "joined-federate MOM reflection-count time-regulation callback");
  auto const timestamp = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      2U);
  auto const retraction = publisher.rtiAmbassador().updateAttributeValues(
      objectTwo,
      rti::AttributeHandleValueMap{{
          publisherAttribute,
          rti::HLAbyte{0x34U}.encode()}},
      rti::VariableLengthData{},
      *timestamp);
  require(
      retraction.isValid(),
      "Joined-federate MOM reflection-count timestamped update returned no retraction");
  auto const receiverTimestamp = timeAfter(
      *receiverTime.factory,
      *receiverTime.initial,
      *receiverTime.epsilon,
      2U);
  receiver.rtiAmbassador().timeAdvanceRequest(*receiverTimestamp);
  publisher.rtiAmbassador().timeAdvanceRequest(*timestamp);
  waitFor(
      receiver,
      publisher,
      [&] {
        return receiver.recorder().timeAdvanceGrants().size() >= 1U &&
            publisher.recorder().timeAdvanceGrants().size() >= 1U;
      },
      options,
      "joined-federate MOM reflection-count timestamped grants");
  waitFor(
      receiver,
      [&] { return applicationReflectionCount(objectTwo) >= 2U; },
      options,
      "joined-federate MOM reflection-count timestamped reflection");
  auto const afterTimestampedCounts = requestCounts(
      "joined-federate MOM reflection-count after timestamped reflection");
  require(
      afterTimestampedCounts.first == 2 && afterTimestampedCounts.second == 4,
      "Joined-federate MOM reflection-count timestamped values were incorrect");

  auto const setTiming = receiver.rtiAmbassador().getInteractionClassHandle(
      L"HLAinteractionRoot.HLAmanager.HLAfederate.HLAadjust.HLAsetTiming");
  auto const timingFederate = receiver.rtiAmbassador().getParameterHandle(
      setTiming,
      L"HLAfederate");
  auto const reportPeriod = receiver.rtiAmbassador().getParameterHandle(
      setTiming,
      L"HLAreportPeriod");
  require(
      setTiming.isValid() && timingFederate.isValid() && reportPeriod.isValid() &&
          receiver.rtiAmbassador().getInteractionClassName(setTiming) ==
              L"HLAinteractionRoot.HLAmanager.HLAfederate.HLAadjust.HLAsetTiming" &&
          receiver.rtiAmbassador().getParameterName(setTiming, timingFederate) ==
              L"HLAfederate" &&
          receiver.rtiAmbassador().getParameterName(setTiming, reportPeriod) ==
              L"HLAreportPeriod",
      "Joined-federate MOM reflection-count HLAsetTiming lookup did not round-trip");
  auto const beforePeriodic = receiver.recorder().reflections().size();
  receiver.rtiAmbassador().sendInteraction(
      setTiming,
      rti::ParameterHandleValueMap{
          {timingFederate, receiverFederate.encode()},
          {reportPeriod, rti::HLAinteger32BE{1}.encode()}},
      rti::VariableLengthData{});
  waitFor(
      receiver,
      [&] { return findCountReflection(beforePeriodic).has_value(); },
      options,
      "joined-federate MOM reflection-count periodic reflection");
  auto const periodicReflection = findCountReflection(beforePeriodic);
  require(
      periodicReflection.has_value(),
      "Joined-federate MOM reflection-count periodic report was missing");
  auto const periodicCounts = decodeCounts(
      *periodicReflection,
      "joined-federate MOM reflection-count periodic report");
  require(
      periodicCounts.first == 2 && periodicCounts.second == 4,
      "Joined-federate MOM reflection-count periodic values were incorrect");
  receiver.rtiAmbassador().sendInteraction(
      setTiming,
      rti::ParameterHandleValueMap{
          {timingFederate, receiverFederate.encode()},
          {reportPeriod, rti::HLAinteger32BE{0}.encode()}},
      rti::VariableLengthData{});

  receiver.rtiAmbassador().unsubscribeObjectClassAttributes(
      receiverClass,
      rti::AttributeHandleSet{receiverAttribute});
  receiver.rtiAmbassador().unsubscribeObjectClassAttributes(momClass, momAttributes);
  publisher.rtiAmbassador().unpublishObjectClassAttributes(
      publisherClass,
      rti::AttributeHandleSet{publisherAttribute});
  receiver.resign(rti::NO_ACTION);
  publisher.resign(rti::DELETE_OBJECTS);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  receiver.disconnect();
  publisher.disconnect();
}

void scenarioJoinedFederateMomTimeStateDurations(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.mimFom.empty(),
      "Joined-federate MOM time-duration testing requires an adapter-supplied standard MIM");
  require(
      !options.logicalTimeImplementationName.empty(),
      "Joined-federate MOM time-duration testing requires an adapter-supplied logical-time implementation");

  Session subject(options, model, "owner");
  Session observer(options, model, "member");
  auto const federation = federationName(options, "joined-federate-mom-time-state-durations");
  subject.connect();
  observer.connect();
  subject.rtiAmbassador().createFederationExecutionWithMIM(
      federation,
      std::vector<std::wstring>{options.fom.wstring()},
      options.mimFom.wstring(),
      options.logicalTimeImplementationName);
  observer.join(
      options.memberFederateName + L"-mom-duration-observer",
      options.federateType,
      federation);

  auto const observerFederateClass = observer.rtiAmbassador().getObjectClassHandle(
      L"HLAobjectRoot.HLAmanager.HLAfederate");
  require(
      observerFederateClass.isValid() &&
          observer.rtiAmbassador().getObjectClassName(observerFederateClass) ==
              L"HLAobjectRoot.HLAmanager.HLAfederate",
      "Joined-federate MOM time-duration lookup did not round-trip the standard class");
  auto const federateHandleAttribute = observer.rtiAmbassador().getAttributeHandle(
      observerFederateClass,
      L"HLAfederateHandle");
  auto const timeGrantedAttribute = observer.rtiAmbassador().getAttributeHandle(
      observerFederateClass,
      L"HLAtimeGrantedTime");
  auto const timeAdvancingAttribute = observer.rtiAmbassador().getAttributeHandle(
      observerFederateClass,
      L"HLAtimeAdvancingTime");
  require(
      federateHandleAttribute.isValid() && timeGrantedAttribute.isValid() &&
          timeAdvancingAttribute.isValid() &&
          observer.rtiAmbassador().getAttributeName(
              observerFederateClass,
              federateHandleAttribute) == L"HLAfederateHandle" &&
          observer.rtiAmbassador().getAttributeName(
              observerFederateClass,
              timeGrantedAttribute) == L"HLAtimeGrantedTime" &&
          observer.rtiAmbassador().getAttributeName(
              observerFederateClass,
              timeAdvancingAttribute) == L"HLAtimeAdvancingTime",
      "Joined-federate MOM time-duration lookup returned inconsistent standard attributes");

  auto const reliable = observer.rtiAmbassador().getTransportationTypeHandle(L"HLAreliable");
  require(
      reliable.isValid() &&
          observer.rtiAmbassador().getTransportationTypeName(reliable) == L"HLAreliable",
      "Joined-federate MOM time-duration lookup could not resolve HLAreliable");
  rti::AttributeHandleSet const momAttributes{
      federateHandleAttribute,
      timeGrantedAttribute,
      timeAdvancingAttribute};
  observer.rtiAmbassador().subscribeObjectClassAttributes(
      observerFederateClass,
      momAttributes,
      true,
      L"");

  subject.join(
      options.ownerFederateName + L"-mom-duration-subject",
      options.federateType,
      federation);
  auto const subjectFederate = subject.federateHandle();
  auto const expectedFederateHandle = copyBytes(subjectFederate.encode());

  auto findSubjectMomReflection = [&]() -> std::optional<ReflectionRecord> {
    auto const reflections = observer.recorder().reflections();
    auto const iterator = std::find_if(
        reflections.begin(),
        reflections.end(),
        [&](ReflectionRecord const& reflection) {
          auto const value = reflection.values.find(federateHandleAttribute);
          return reflection.present && value != reflection.values.end() &&
              copyBytes(value->second) == expectedFederateHandle;
        });
    if (iterator == reflections.end()) {
      return std::nullopt;
    }
    return *iterator;
  };
  waitFor(
      observer,
      [&] { return findSubjectMomReflection().has_value(); },
      options,
      "joined-federate MOM time-duration subject discovery");
  auto const initial = findSubjectMomReflection();
  require(
      initial.has_value() && initial->object.isValid() &&
          observer.rtiAmbassador().getKnownObjectClassHandle(initial->object) ==
              observerFederateClass,
      "Joined-federate MOM time-duration discovery returned the wrong standard object");
  auto const subjectMomObject = initial->object;
  require(
      initial->values.count(timeGrantedAttribute) == 0U &&
          initial->values.count(timeAdvancingAttribute) == 0U,
      "Joined-federate MOM time-duration initial reflection was not conditional");

  auto const findDurationReflection = [&](std::size_t before)
      -> std::optional<ReflectionRecord> {
    auto const reflections = observer.recorder().reflections();
    auto const begin = reflections.begin() + static_cast<std::ptrdiff_t>(before);
    auto const iterator = std::find_if(
        begin,
        reflections.end(),
        [&](ReflectionRecord const& reflection) {
          return reflection.present && reflection.object == subjectMomObject &&
              reflection.values.count(timeGrantedAttribute) == 1U &&
              reflection.values.count(timeAdvancingAttribute) == 1U;
        });
    if (iterator == reflections.end()) {
      return std::nullopt;
    }
    return *iterator;
  };
  auto decodeDuration = [&](ReflectionRecord const& reflection,
                            rti::AttributeHandle const& attribute,
                            std::string const& description) {
    require(
        reflection.values.at(attribute).size() == 4U,
        description + " did not use the official four-octet HLAinteger32BE encoding");
    rti::HLAinteger32BE decoded;
    decoded.decode(reflection.values.at(attribute));
    require(decoded.get() >= 0, description + " returned a negative duration");
    return decoded.get();
  };
  auto requireDurationReflectionMetadata = [&](ReflectionRecord const& reflection,
                                               std::string const& description) {
    require(
        reflection.values.size() == 2U && reflection.transportation == reliable &&
            reflection.tag.empty() && !reflection.producer.isValid() &&
            !reflection.regions.has_value(),
        description + " returned non-standard MOM reflection metadata");
    static_cast<void>(decodeDuration(
        reflection,
        timeGrantedAttribute,
        description + " HLAtimeGrantedTime"));
    static_cast<void>(decodeDuration(
        reflection,
        timeAdvancingAttribute,
        description + " HLAtimeAdvancingTime"));
  };
  auto waitForDurationReflection = [&](std::size_t before,
                                       std::string const& description) {
    waitFor(
        observer,
        [&] { return findDurationReflection(before).has_value(); },
        options,
        description);
    auto const reflection = findDurationReflection(before);
    require(reflection.has_value(), description + " produced no duration reflection");
    requireDurationReflectionMetadata(*reflection, description);
    return *reflection;
  };

  // Request Attribute Value Update is a direct current-value path even though
  // these MIM attributes are declared Periodic.  The values use the official
  // HLAmsec/HLAinteger32BE representation and are non-negative durations.
  auto const beforeDirect = observer.recorder().reflections().size();
  observer.rtiAmbassador().requestAttributeValueUpdate(
      subjectMomObject,
      rti::AttributeHandleSet{timeGrantedAttribute, timeAdvancingAttribute},
      rti::VariableLengthData{});
  auto const direct = waitForDurationReflection(
      beforeDirect,
      "joined-federate MOM time-duration direct value request");

  auto const setTiming = observer.rtiAmbassador().getInteractionClassHandle(
      L"HLAinteractionRoot.HLAmanager.HLAfederate.HLAadjust.HLAsetTiming");
  auto const federateParameter = observer.rtiAmbassador().getParameterHandle(
      setTiming,
      L"HLAfederate");
  auto const periodParameter = observer.rtiAmbassador().getParameterHandle(
      setTiming,
      L"HLAreportPeriod");
  require(
      setTiming.isValid() && federateParameter.isValid() && periodParameter.isValid(),
      "Joined-federate MOM time-duration HLAsetTiming lookup returned an invalid handle");
  observer.rtiAmbassador().sendInteraction(
      setTiming,
      rti::ParameterHandleValueMap{
          {federateParameter, subjectFederate.encode()},
          {periodParameter, rti::HLAinteger32BE{1}.encode()}},
      rti::VariableLengthData{});
  auto const periodic = waitForDurationReflection(
      observer.recorder().reflections().size(),
      "joined-federate MOM time-duration periodic reflection");
  static_cast<void>(direct);
  static_cast<void>(periodic);

  observer.rtiAmbassador().sendInteraction(
      setTiming,
      rti::ParameterHandleValueMap{
          {federateParameter, subjectFederate.encode()},
          {periodParameter, rti::HLAinteger32BE{0}.encode()}},
      rti::VariableLengthData{});
  observer.rtiAmbassador().unsubscribeObjectClassAttributes(
      observerFederateClass,
      momAttributes);
  observer.resign(rti::NO_ACTION);
  subject.resign(rti::NO_ACTION);
  subject.rtiAmbassador().destroyFederationExecution(federation);
  observer.disconnect();
  subject.disconnect();
}

void scenarioOrderTypeControls(Options const& options, rti::CallbackModel model) {
  require(
      !options.logicalTimeImplementationName.empty(),
      "Order-type control test requires an adapter-supplied logical-time implementation");

  Session publisher(options, model, "owner");
  Session receiver(options, model, "member");
  auto const federation = federationName(options, "order-type-controls");
  publisher.connect();
  receiver.connect();
  publisher.rtiAmbassador().createFederationExecution(
      federation,
      options.fom.wstring(),
      options.logicalTimeImplementationName);
  publisher.join(options.ownerFederateName, options.federateType, federation);
  receiver.join(
      options.memberFederateName + L"-order-controls",
      options.federateType,
      federation);

  auto const publisherClass = publisher.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const receiverClass = receiver.rtiAmbassador().getObjectClassHandle(
      options.objectClassName);
  auto const publisherAttribute = publisher.rtiAmbassador().getAttributeHandle(
      publisherClass,
      options.attributeName);
  auto const receiverAttribute = receiver.rtiAmbassador().getAttributeHandle(
      receiverClass,
      options.attributeName);
  auto const publisherInteraction =
      publisher.rtiAmbassador().getInteractionClassHandle(options.interactionClassName);
  auto const receiverInteraction =
      receiver.rtiAmbassador().getInteractionClassHandle(options.interactionClassName);
  auto const publisherParameter = publisher.rtiAmbassador().getParameterHandle(
      publisherInteraction,
      options.parameterName);
  auto const receiverParameter = receiver.rtiAmbassador().getParameterHandle(
      receiverInteraction,
      options.parameterName);
  require(
      publisherClass.isValid() && receiverClass.isValid() &&
          publisherAttribute.isValid() && receiverAttribute.isValid() &&
          publisherInteraction.isValid() && receiverInteraction.isValid() &&
          publisherParameter.isValid() && receiverParameter.isValid(),
      "Order-type control lookup returned an invalid adapter-supplied handle");

  rti::AttributeHandleSet const publisherAttributes{publisherAttribute};
  rti::AttributeHandleSet const receiverAttributes{receiverAttribute};
  publisher.rtiAmbassador().publishObjectClassAttributes(
      publisherClass,
      publisherAttributes);
  receiver.rtiAmbassador().subscribeObjectClassAttributes(
      receiverClass,
      receiverAttributes,
      true);
  publisher.rtiAmbassador().publishInteractionClass(publisherInteraction);
  receiver.rtiAmbassador().subscribeInteractionClass(receiverInteraction, true);

  // Establish a known class default, then verify that a later default change
  // affects only later registrations.  The explicit instance change covers
  // the per-object override independently of the FOM's initial default.
  publisher.rtiAmbassador().changeDefaultAttributeOrderType(
      publisherClass,
      publisherAttributes,
      rti::RECEIVE);
  auto const receiveObject = publisher.rtiAmbassador().registerObjectInstance(
      publisherClass);
  require(receiveObject.isValid(), "Receive-order registration returned an invalid object");
  waitFor(
      receiver,
      [&] { return receiver.recorder().hasDiscovery(receiveObject); },
      options,
      "Receive-order object discovery");

  publisher.rtiAmbassador().changeDefaultAttributeOrderType(
      publisherClass,
      publisherAttributes,
      rti::TIMESTAMP);
  auto const defaultTimestampObject =
      publisher.rtiAmbassador().registerObjectInstance(publisherClass);
  require(
      defaultTimestampObject.isValid(),
      "Timestamp-order default registration returned an invalid object");
  waitFor(
      receiver,
      [&] { return receiver.recorder().hasDiscovery(defaultTimestampObject); },
      options,
      "Timestamp-order default object discovery");

  publisher.rtiAmbassador().changeDefaultAttributeOrderType(
      publisherClass,
      publisherAttributes,
      rti::RECEIVE);
  auto const explicitTimestampObject =
      publisher.rtiAmbassador().registerObjectInstance(publisherClass);
  require(
      explicitTimestampObject.isValid(),
      "Explicit timestamp-order registration returned an invalid object");
  waitFor(
      receiver,
      [&] { return receiver.recorder().hasDiscovery(explicitTimestampObject); },
      options,
      "Explicit timestamp-order object discovery");
  publisher.rtiAmbassador().changeAttributeOrderType(
      explicitTimestampObject,
      publisherAttributes,
      rti::TIMESTAMP);

  auto publisherTime = makeTimeContext(publisher);
  auto receiverTime = makeTimeContext(receiver);
  require(
      publisherTime.factory->getName() == receiverTime.factory->getName(),
      "Order-type control members selected different logical-time factories");
  auto const lookaheadTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      5U);
  auto lookahead = publisherTime.factory->makeZero();
  require(lookahead != nullptr, "Order-type control could not allocate lookahead");
  lookahead->setToDifference(*lookaheadTime, *publisherTime.initial);
  receiver.rtiAmbassador().enableTimeConstrained();
  waitFor(
      receiver,
      [&] { return receiver.recorder().timeConstrainedEnabled().size() >= 1U; },
      options,
      "Order-type control time-constrained callback");
  receiver.rtiAmbassador().enableAsynchronousDelivery();
  publisher.rtiAmbassador().enableTimeRegulation(*lookahead);
  waitFor(
      publisher,
      [&] { return publisher.recorder().timeRegulationEnabled().size() >= 1U; },
      options,
      "Order-type control time-regulation callback");

  auto const timestamp = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      6U);
  std::vector<std::uint8_t> const receiveBytes{0x11U};
  std::vector<std::uint8_t> const defaultTimestampBytes{0x22U};
  std::vector<std::uint8_t> const explicitTimestampBytes{0x33U};
  std::vector<std::uint8_t> const attributeTagBytes{0x4FU, 0x52, 0x44};
  rti::AttributeHandleValueMap receiveValues;
  receiveValues.emplace(
      publisherAttribute,
      rti::VariableLengthData(receiveBytes.data(), receiveBytes.size()));
  rti::AttributeHandleValueMap defaultTimestampValues;
  defaultTimestampValues.emplace(
      publisherAttribute,
      rti::VariableLengthData(
          defaultTimestampBytes.data(),
          defaultTimestampBytes.size()));
  rti::AttributeHandleValueMap explicitTimestampValues;
  explicitTimestampValues.emplace(
      publisherAttribute,
      rti::VariableLengthData(
          explicitTimestampBytes.data(),
          explicitTimestampBytes.size()));
  rti::VariableLengthData attributeTag(
      attributeTagBytes.data(),
      attributeTagBytes.size());

  publisher.rtiAmbassador().updateAttributeValues(
      receiveObject,
      receiveValues,
      attributeTag);
  auto const defaultTimestampRetraction =
      publisher.rtiAmbassador().updateAttributeValues(
          defaultTimestampObject,
          defaultTimestampValues,
          attributeTag,
          *timestamp);
  auto const explicitTimestampRetraction =
      publisher.rtiAmbassador().updateAttributeValues(
          explicitTimestampObject,
          explicitTimestampValues,
          attributeTag,
          *timestamp);
  require(
      defaultTimestampRetraction.isValid() &&
          explicitTimestampRetraction.isValid(),
      "Order-type control returned the wrong retraction validity");

  auto const receiverTarget = timeAfter(
      *receiverTime.factory,
      *receiverTime.initial,
      *receiverTime.epsilon,
      6U);
  auto const publisherTarget = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      6U);
  receiver.rtiAmbassador().timeAdvanceRequest(*receiverTarget);
  publisher.rtiAmbassador().timeAdvanceRequest(*publisherTarget);
  waitForSessions(
      {&publisher, &receiver},
      [&] { return receiver.recorder().timedReflections().size() >= 2U; },
      options,
      "Order-type control timestamped attribute deliveries");
  waitForSessions(
      {&publisher, &receiver},
      [&] { return receiver.recorder().reflections().size() >= 1U; },
      options,
      "Order-type control ordinary attribute delivery");
  waitFor(
      publisher,
      [&] { return publisher.recorder().timeAdvanceGrants().size() >= 1U; },
      options,
      "Order-type control publisher time advance grant");
  require(
      receiver.recorder().reflections().size() == 1U &&
          receiver.recorder().timedReflections().size() == 2U,
      "Order-type control delivered the wrong ordinary/timestamped split");

  auto const ordinaryReflection = receiver.recorder().reflections().front();
  require(
      ordinaryReflection.object == receiveObject &&
          ordinaryReflection.values.size() == 1U &&
          ordinaryReflection.values.count(receiverAttribute) == 1U &&
          ordinaryReflection.tag == attributeTagBytes,
      "Receive-order attribute reflection did not preserve the object or payload");
  auto const timedReflections = receiver.recorder().timedReflections();
  for (auto const& reflection : timedReflections) {
    require(
        (reflection.object == defaultTimestampObject ||
         reflection.object == explicitTimestampObject) &&
            reflection.values.size() == 1U &&
            reflection.values.count(receiverAttribute) == 1U &&
            reflection.tag == attributeTagBytes &&
            reflection.time == encodeTime(*timestamp) &&
            reflection.sentOrder == rti::TIMESTAMP &&
            reflection.receivedOrder == rti::TIMESTAMP &&
            reflection.retractionPresent && reflection.regions == std::nullopt,
        "Timestamp-order attribute reflection returned the wrong metadata");
  }
  require(
      timedReflections.at(0).object != timedReflections.at(1).object,
      "Order-type control collapsed the two timestamped object instances");
  auto const findTimedRetraction = [&](rti::ObjectInstanceHandle const& object) {
    for (auto const& reflection : timedReflections) {
      if (reflection.object == object) {
        return reflection.retraction;
      }
    }
    return std::vector<std::uint8_t>{};
  };
  require(
      findTimedRetraction(defaultTimestampObject) ==
          copyBytes(defaultTimestampRetraction.encode()) &&
          findTimedRetraction(explicitTimestampObject) ==
              copyBytes(explicitTimestampRetraction.encode()),
      "Timestamp-order attribute reflection returned the wrong retraction handle");

  publisher.rtiAmbassador().changeInteractionOrderType(
      publisherInteraction,
      rti::RECEIVE);
  std::vector<std::uint8_t> const parameterBytes{0x49U, 0x4EU, 0x54};
  std::vector<std::uint8_t> const interactionTagBytes{0x49U, 0x4EU, 0x54};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      publisherParameter,
      rti::VariableLengthData(parameterBytes.data(), parameterBytes.size()));
  rti::VariableLengthData interactionTag(
      interactionTagBytes.data(),
      interactionTagBytes.size());
  auto const interactionTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      12U);
  auto const interactionRetraction = publisher.rtiAmbassador().sendInteraction(
      publisherInteraction,
      parameters,
      interactionTag,
      *interactionTime);
  require(
      !interactionRetraction.isValid(),
      "Receive-order interaction unexpectedly returned a retraction handle");
  waitFor(
      receiver,
      [&] { return receiver.recorder().timedInteractions().size() >= 1U; },
      options,
      "Order-type control receive-order interaction");
  require(
      receiver.recorder().timedInteractions().size() == 1U &&
          receiver.recorder().interactions().empty(),
      "Receive-order interaction used the wrong callback overload");
  auto const interaction = receiver.recorder().timedInteractions().front();
  require(
      interaction.interaction == receiverInteraction &&
          interaction.parameters.size() == 1U &&
          interaction.parameters.count(receiverParameter) == 1U &&
          interaction.parameters.at(receiverParameter).size() == parameterBytes.size() &&
          copyBytes(interaction.parameters.at(receiverParameter)) == parameterBytes &&
          interaction.tag == interactionTagBytes &&
          interaction.time == encodeTime(*interactionTime) &&
          interaction.sentOrder == rti::RECEIVE &&
          interaction.receivedOrder == rti::RECEIVE &&
          !interaction.retractionPresent &&
          interaction.regions == std::nullopt,
      "Receive-order interaction did not preserve the adapter FOM payload");

  receiver.rtiAmbassador().disableTimeConstrained();
  publisher.rtiAmbassador().disableTimeRegulation();
  receiver.rtiAmbassador().unsubscribeInteractionClass(receiverInteraction);
  publisher.rtiAmbassador().unpublishInteractionClass(publisherInteraction);
  receiver.rtiAmbassador().unsubscribeObjectClassAttributes(
      receiverClass,
      receiverAttributes);
  publisher.rtiAmbassador().unpublishObjectClassAttributes(
      publisherClass,
      publisherAttributes);
  receiver.resign(rti::NO_ACTION);
  publisher.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  receiver.disconnect();
  publisher.disconnect();
}

void scenarioOrderTypeControlsContract(
    Options const& options,
    rti::CallbackModel model) {
  scenarioOrderTypeControls(options, model);
}

void scenarioFederationSaveRestore(Options const& options, rti::CallbackModel model) {
  Session lifecycle(options, model, "save-restore-lifecycle");
  std::wstring const lifecycleSaveLabel = L"tck-save-restore-lifecycle-save";
  std::wstring const lifecycleRestoreLabel = L"tck-save-restore-lifecycle-restore";
  auto checkSaveRestoreLifecycle = [&](std::wstring const& expected,
                                        std::string const& phase) {
    requireException(
        [&] { lifecycle.rtiAmbassador().requestFederationSave(lifecycleSaveLabel); },
        expected,
        "requesting a federation save " + phase);
    requireException(
        [&] { lifecycle.rtiAmbassador().federateSaveBegun(); },
        expected,
        "beginning a federate save " + phase);
    requireException(
        [&] { lifecycle.rtiAmbassador().federateSaveComplete(); },
        expected,
        "completing a federate save " + phase);
    requireException(
        [&] { lifecycle.rtiAmbassador().federateSaveNotComplete(); },
        expected,
        "reporting an incomplete federate save " + phase);
    requireException(
        [&] { lifecycle.rtiAmbassador().abortFederationSave(); },
        expected,
        "aborting a federation save " + phase);
    requireException(
        [&] { lifecycle.rtiAmbassador().queryFederationSaveStatus(); },
        expected,
        "querying federation save status " + phase);
    requireException(
        [&] { lifecycle.rtiAmbassador().requestFederationRestore(lifecycleRestoreLabel); },
        expected,
        "requesting a federation restore " + phase);
    requireException(
        [&] { lifecycle.rtiAmbassador().federateRestoreComplete(); },
        expected,
        "completing a federate restore " + phase);
    requireException(
        [&] { lifecycle.rtiAmbassador().federateRestoreNotComplete(); },
        expected,
        "reporting an incomplete federate restore " + phase);
    requireException(
        [&] { lifecycle.rtiAmbassador().abortFederationRestore(); },
        expected,
        "aborting a federation restore " + phase);
    requireException(
        [&] { lifecycle.rtiAmbassador().queryFederationRestoreStatus(); },
        expected,
        "querying federation restore status " + phase);
  };
  checkSaveRestoreLifecycle(L"NotConnected", "before connection");
  lifecycle.connect();
  checkSaveRestoreLifecycle(L"FederateNotExecutionMember", "before joining an execution");
  lifecycle.disconnect();

  Session owner(options, model, "owner");
  Session peer(options, model, "member");
  auto const federation = federationName(options, "federation-save-restore");
  connectAndJoin(owner, peer, options, federation, options.fom);

  auto lifecycleTime = makeTimeContext(owner);
  requireException(
      [&] {
        lifecycle.rtiAmbassador().requestFederationSave(
            lifecycleSaveLabel,
            *lifecycleTime.initial);
      },
      L"NotConnected",
      "requesting a timestamped federation save before connection");
  lifecycle.connect();
  requireException(
      [&] {
        lifecycle.rtiAmbassador().requestFederationSave(
            lifecycleSaveLabel,
            *lifecycleTime.initial);
      },
      L"FederateNotExecutionMember",
      "requesting a timestamped federation save before joining an execution");
  lifecycle.disconnect();

  requireException(
      [&] { owner.rtiAmbassador().federateSaveBegun(); },
      L"SaveNotInitiated",
      "federateSaveBegun before a save request");
  requireException(
      [&] { owner.rtiAmbassador().federateSaveComplete(); },
      L"FederateHasNotBegunSave",
      "federateSaveComplete before save preparation");
  requireException(
      [&] { owner.rtiAmbassador().federateSaveNotComplete(); },
      L"FederateHasNotBegunSave",
      "federateSaveNotComplete before save preparation");
  requireException(
      [&] { owner.rtiAmbassador().abortFederationSave(); },
      L"SaveNotInProgress",
      "abortFederationSave without a save in progress");
  requireException(
      [&] { owner.rtiAmbassador().federateRestoreComplete(); },
      L"RestoreNotRequested",
      "federateRestoreComplete before a restore request");
  requireException(
      [&] { owner.rtiAmbassador().federateRestoreNotComplete(); },
      L"RestoreNotRequested",
      "federateRestoreNotComplete before a restore request");
  requireException(
      [&] { owner.rtiAmbassador().abortFederationRestore(); },
      L"RestoreNotInProgress",
      "abortFederationRestore without a restore in progress");

  auto const ownerHandle = owner.federateHandle();
  auto const peerHandle = peer.federateHandle();
  std::wstring const saveLabel = L"tck-save-restore";
  owner.rtiAmbassador().requestFederationSave(saveLabel);
  waitForSessions(
      {&owner, &peer},
      [&] {
        return owner.federateSaveInitiations().size() >= 1U &&
            peer.federateSaveInitiations().size() >= 1U;
      },
      options,
      "federate save initiation callbacks");
  require(owner.federateSaveInitiations().front() == saveLabel &&
              peer.federateSaveInitiations().front() == saveLabel,
          "federate save initiation returned the wrong label");
  require(owner.federateSaveTimes().empty() && peer.federateSaveTimes().empty(),
          "untimed federation save unexpectedly used a timestamped callback");

  auto const saveStatusBefore = owner.federationSaveStatusResponses().size();
  owner.rtiAmbassador().queryFederationSaveStatus();
  waitFor(
      owner,
      [&] { return owner.federationSaveStatusResponses().size() > saveStatusBefore; },
      options,
      "in-progress federation save status");
  auto const instructed = owner.federationSaveStatusResponses().back();
  require(instructed.size() == 2U,
          "federation save status omitted a joined federate");
  auto const findSaveStatus = [&](rti::FederateHandle const& handle,
                                  rti::SaveStatus expected,
                                  std::string const& description) {
    auto const found = std::find_if(
        instructed.begin(),
        instructed.end(),
        [&](auto const& entry) { return entry.first == handle; });
    require(found != instructed.end(), description + " omitted a federate handle");
    require(found->second == expected, description + " returned the wrong state");
  };
  findSaveStatus(ownerHandle, rti::FEDERATE_INSTRUCTED_TO_SAVE, "owner save status");
  findSaveStatus(peerHandle, rti::FEDERATE_INSTRUCTED_TO_SAVE, "peer save status");

  owner.rtiAmbassador().federateSaveBegun();
  peer.rtiAmbassador().federateSaveBegun();
  auto const savingStatusBefore = owner.federationSaveStatusResponses().size();
  owner.rtiAmbassador().queryFederationSaveStatus();
  waitFor(
      owner,
      [&] {
        return owner.federationSaveStatusResponses().size() > savingStatusBefore;
      },
      options,
      "saving federation save status");
  auto const saving = owner.federationSaveStatusResponses().back();
  require(saving.size() == 2U,
          "saving federation status omitted a joined federate");
  for (auto const& entry : saving) {
    require(entry.second == rti::FEDERATE_SAVING,
            "federateSaveBegun did not advance the save status");
  }

  owner.rtiAmbassador().federateSaveComplete();
  require(owner.federationSavedCount() == 0U,
          "federationSaved arrived before every federate completed its save");
  peer.rtiAmbassador().federateSaveComplete();
  waitForSessions(
      {&owner, &peer},
      [&] {
        return owner.federationSavedCount() >= 1U &&
            peer.federationSavedCount() >= 1U;
      },
      options,
      "federation saved callbacks");
  require(owner.federationNotSavedReasons().empty() &&
              peer.federationNotSavedReasons().empty(),
          "successful federation save reported a failure");

  auto const restoreRequestBefore = owner.federationRestoreRequestsSucceeded().size();
  owner.rtiAmbassador().requestFederationRestore(saveLabel);
  waitForSessions(
      {&owner, &peer},
      [&] {
        return owner.federationRestoreRequestsSucceeded().size() > restoreRequestBefore &&
            owner.federationRestoreBegunCount() >= 1U &&
            peer.federationRestoreBegunCount() >= 1U &&
            owner.federateRestoreInitiations().size() >= 1U &&
            peer.federateRestoreInitiations().size() >= 1U;
      },
      options,
      "federation restore initiation callbacks");
  require(owner.federationRestoreRequestsSucceeded().back() == saveLabel,
          "restore request confirmation returned the wrong label");
  require(owner.federationRestoreRequestsFailed().empty() &&
              peer.federationRestoreRequestsFailed().empty(),
          "successful restore request reported a failure");

  auto const ownerRestore = owner.federateRestoreInitiations().back();
  auto const peerRestore = peer.federateRestoreInitiations().back();
  require(ownerRestore.label == saveLabel && peerRestore.label == saveLabel,
          "restore initiation returned the wrong save label");
  require(ownerRestore.federateName == options.ownerFederateName &&
              peerRestore.federateName == options.memberFederateName,
          "restore initiation returned the wrong federate name");
  require(ownerRestore.postRestoreFederateHandle.isValid() &&
              peerRestore.postRestoreFederateHandle.isValid(),
          "restore initiation returned an invalid post-restore handle");

  auto const restoreStatusBefore = owner.federationRestoreStatusResponses().size();
  owner.rtiAmbassador().queryFederationRestoreStatus();
  waitFor(
      owner,
      [&] {
        return owner.federationRestoreStatusResponses().size() > restoreStatusBefore;
      },
      options,
      "in-progress federation restore status");
  auto const restoring = owner.federationRestoreStatusResponses().back();
  require(restoring.size() == 2U,
          "restoring federation status omitted a joined federate");
  for (auto const& entry : restoring) {
    require(entry.status == rti::FEDERATE_RESTORING,
            "restore initiation did not advance the restore status");
  }

  owner.rtiAmbassador().federateRestoreComplete();
  peer.rtiAmbassador().federateRestoreComplete();
  waitForSessions(
      {&owner, &peer},
      [&] {
        return owner.federationRestoredCount() >= 1U &&
            peer.federationRestoredCount() >= 1U;
      },
      options,
      "federation restored callbacks");
  require(owner.federationNotRestoredReasons().empty() &&
              peer.federationNotRestoredReasons().empty(),
          "successful federation restore reported a failure");
  require(
      owner.rtiAmbassador().getFederateHandle(options.ownerFederateName) ==
          ownerRestore.postRestoreFederateHandle,
      "owner post-restore federate handle did not become authoritative");
  require(
      peer.rtiAmbassador().getFederateHandle(options.memberFederateName) ==
          peerRestore.postRestoreFederateHandle,
      "peer post-restore federate handle did not become authoritative");
  require(
      owner.rtiAmbassador().getFederateName(ownerRestore.postRestoreFederateHandle) ==
          options.ownerFederateName,
      "owner post-restore handle-to-name lookup did not round-trip");
  require(
      peer.rtiAmbassador().getFederateName(peerRestore.postRestoreFederateHandle) ==
          options.memberFederateName,
      "peer post-restore handle-to-name lookup did not round-trip");

  auto const restoredStatusBefore = owner.federationRestoreStatusResponses().size();
  owner.rtiAmbassador().queryFederationRestoreStatus();
  waitFor(
      owner,
      [&] {
        return owner.federationRestoreStatusResponses().size() > restoredStatusBefore;
      },
      options,
      "completed federation restore status");
  auto const restoredStatus = owner.federationRestoreStatusResponses().back();
  require(restoredStatus.size() == 2U,
          "completed federation restore status omitted a joined federate");
  for (auto const& entry : restoredStatus) {
    require(entry.status == rti::NO_RESTORE_IN_PROGRESS,
            "completed federation restore retained an active status");
  }

  // Exercise the standard negative completion paths after the successful
  // round trip.  These do not depend on a private save-file format.
  std::wstring const failedSaveLabel = L"tck-save-failure";
  owner.rtiAmbassador().requestFederationSave(failedSaveLabel);
  waitForSessions(
      {&owner, &peer},
      [&] {
        return owner.federateSaveInitiations().size() >= 2U &&
            peer.federateSaveInitiations().size() >= 2U;
      },
      options,
      "failed federation save initiation");
  owner.rtiAmbassador().federateSaveBegun();
  peer.rtiAmbassador().federateSaveBegun();
  auto const failedSaveBefore = owner.federationNotSavedReasons().size();
  peer.rtiAmbassador().federateSaveNotComplete();
  waitForSessions(
      {&owner, &peer},
      [&] {
        return owner.federationNotSavedReasons().size() > failedSaveBefore &&
            peer.federationNotSavedReasons().size() > failedSaveBefore;
      },
      options,
      "federation save failure callbacks");
  require(owner.federationNotSavedReasons().back() ==
              rti::FEDERATE_REPORTED_FAILURE_DURING_SAVE &&
              peer.federationNotSavedReasons().back() ==
                  rti::FEDERATE_REPORTED_FAILURE_DURING_SAVE,
          "federateSaveNotComplete returned the wrong failure reason");

  std::wstring const abortedSaveLabel = L"tck-save-abort";
  owner.rtiAmbassador().requestFederationSave(abortedSaveLabel);
  waitForSessions(
      {&owner, &peer},
      [&] {
        return owner.federateSaveInitiations().size() >= 3U &&
            peer.federateSaveInitiations().size() >= 3U;
      },
      options,
      "aborted federation save initiation");
  auto const abortedSaveBefore = owner.federationNotSavedReasons().size();
  owner.rtiAmbassador().abortFederationSave();
  waitForSessions(
      {&owner, &peer},
      [&] {
        return owner.federationNotSavedReasons().size() > abortedSaveBefore &&
            peer.federationNotSavedReasons().size() > abortedSaveBefore;
      },
      options,
      "federation save abort callbacks");
  require(owner.federationNotSavedReasons().back() == rti::SAVE_ABORTED &&
              peer.federationNotSavedReasons().back() == rti::SAVE_ABORTED,
          "abortFederationSave returned the wrong failure reason");

  peer.resign(rti::NO_ACTION);
  owner.resign(rti::NO_ACTION);
  owner.rtiAmbassador().destroyFederationExecution(federation);
  peer.disconnect();
  owner.disconnect();
}

void scenarioFederationSaveRestoreInterlocks(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.ddmFom.empty(),
      "Federation save/restore interlocks require an adapter-supplied dimensional FOM");
  require(
      !options.logicalTimeImplementationName.empty(),
      "Federation save/restore interlocks require an adapter-supplied logical-time implementation");

  Session owner(options, model, "owner");
  Session peer(options, model, "member");
  auto const federation = federationName(options, "federation-save-restore-interlocks");
  connectAndJoin(owner, peer, options, federation, options.ddmFom);

  auto const ownerHandles = ddmHandles(owner, options);
  auto const peerHandles = ddmHandles(peer, options);
  rti::AttributeHandleSet const ownerAttributes{ownerHandles.attribute};
  rti::AttributeHandleSet const peerAttributes{peerHandles.attribute};
  rti::InteractionClassHandleSet const ownerInteractions{ownerHandles.interactionClass};
  rti::InteractionClassHandleSet const peerInteractions{peerHandles.interactionClass};

  owner.rtiAmbassador().publishObjectClassAttributes(
      ownerHandles.objectClass,
      ownerAttributes);
  peer.rtiAmbassador().subscribeObjectClassAttributes(
      peerHandles.objectClass,
      peerAttributes,
      true,
      L"");
  owner.rtiAmbassador().publishInteractionClass(ownerHandles.interactionClass);
  peer.rtiAmbassador().subscribeInteractionClass(
      peerHandles.interactionClass,
      true);
  owner.rtiAmbassador().publishObjectClassDirectedInteractions(
      ownerHandles.objectClass,
      ownerInteractions);
  peer.rtiAmbassador().subscribeObjectClassDirectedInteractions(
      peerHandles.objectClass,
      peerInteractions);

  auto const object = owner.rtiAmbassador().registerObjectInstance(
      ownerHandles.objectClass);
  require(
      object.isValid(),
      "save/restore interlock setup returned an invalid object handle");

  auto const region = createDdmRegion(
      owner,
      ownerHandles,
      1UL,
      5UL,
      1UL,
      5UL);
  rti::AttributeHandleSetRegionHandleSetPairVector const attributeRegions{{
      ownerAttributes,
      rti::RegionHandleSet{region},
  }};
  rti::RegionHandleSet const regions{region};
  rti::AttributeHandleValueMap const emptyAttributes;
  rti::ParameterHandleValueMap const emptyParameters;
  rti::VariableLengthData const emptyTag;
  rti::AttributeHandleSet divestedAttributes;
  auto const reliable = owner.rtiAmbassador().getTransportationTypeHandle(
      L"HLAreliable");
  require(
      reliable.isValid(),
      "save/restore interlock setup returned an invalid transportation handle");
  auto const ownerFederate = owner.federateHandle();
  auto const ownerTime = makeTimeContext(owner);
  auto const interlockTime = ownerTime.factory->makeInitial();
  require(
      interlockTime != nullptr,
      "save/restore interlock setup returned no working logical time");

  auto checkInterlocks = [&](std::wstring const& expected,
                             std::string const& phase) {
    auto check = [&](auto operation, std::string const& description) {
      requireException(
          operation,
          expected,
          description + " during " + phase);
    };

    check(
        [&] {
          owner.rtiAmbassador().publishObjectClassAttributes(
              ownerHandles.objectClass,
              ownerAttributes);
        },
        "publishing object-class attributes");
    check(
        [&] {
          owner.rtiAmbassador().unpublishObjectClass(ownerHandles.objectClass);
        },
        "unpublishing an object class");
    check(
        [&] {
          owner.rtiAmbassador().unpublishObjectClassAttributes(
              ownerHandles.objectClass,
              ownerAttributes);
        },
        "unpublishing object-class attributes");
    check(
        [&] {
          peer.rtiAmbassador().subscribeObjectClassAttributes(
              peerHandles.objectClass,
              peerAttributes,
              true,
              L"");
        },
        "subscribing to object-class attributes");
    check(
        [&] {
          peer.rtiAmbassador().unsubscribeObjectClass(peerHandles.objectClass);
        },
        "unsubscribing an object class");
    check(
        [&] {
          peer.rtiAmbassador().unsubscribeObjectClassAttributes(
              peerHandles.objectClass,
              peerAttributes);
        },
        "unsubscribing object-class attributes");

    check(
        [&] {
          owner.rtiAmbassador().publishInteractionClass(
              ownerHandles.interactionClass);
        },
        "publishing an interaction class");
    check(
        [&] {
          owner.rtiAmbassador().unpublishInteractionClass(
              ownerHandles.interactionClass);
        },
        "unpublishing an interaction class");
    check(
        [&] {
          peer.rtiAmbassador().subscribeInteractionClass(
              peerHandles.interactionClass,
              true);
        },
        "subscribing to an interaction class");
    check(
        [&] {
          peer.rtiAmbassador().unsubscribeInteractionClass(
              peerHandles.interactionClass);
        },
        "unsubscribing an interaction class");

    check(
        [&] {
          owner.rtiAmbassador().publishObjectClassDirectedInteractions(
              ownerHandles.objectClass,
              ownerInteractions);
        },
        "publishing directed interactions");
    check(
        [&] {
          owner.rtiAmbassador().unpublishObjectClassDirectedInteractions(
              ownerHandles.objectClass);
        },
        "unpublishing all directed interactions");
    check(
        [&] {
          owner.rtiAmbassador().unpublishObjectClassDirectedInteractions(
              ownerHandles.objectClass,
              ownerInteractions);
        },
        "unpublishing selected directed interactions");
    check(
        [&] {
          peer.rtiAmbassador().subscribeObjectClassDirectedInteractions(
              peerHandles.objectClass,
              peerInteractions);
        },
        "subscribing to directed interactions");
    check(
        [&] {
          peer.rtiAmbassador().unsubscribeObjectClassDirectedInteractions(
              peerHandles.objectClass);
        },
        "unsubscribing all directed interactions");
    check(
        [&] {
          peer.rtiAmbassador().unsubscribeObjectClassDirectedInteractions(
              peerHandles.objectClass,
              peerInteractions);
        },
        "unsubscribing selected directed interactions");

    check(
        [&] {
          owner.rtiAmbassador().changeAttributeOrderType(
              object,
              ownerAttributes,
              rti::RECEIVE);
        },
        "changing object-attribute order");
    check(
        [&] {
          owner.rtiAmbassador().changeDefaultAttributeOrderType(
              ownerHandles.objectClass,
              ownerAttributes,
              rti::RECEIVE);
        },
        "changing default object-attribute order");
    check(
        [&] {
          owner.rtiAmbassador().changeInteractionOrderType(
              ownerHandles.interactionClass,
              rti::RECEIVE);
        },
        "changing interaction order");
    check(
        [&] {
          owner.rtiAmbassador().requestAttributeTransportationTypeChange(
              object,
              ownerAttributes,
              reliable);
        },
        "requesting an attribute transportation change");
    check(
        [&] {
          owner.rtiAmbassador().changeDefaultAttributeTransportationType(
              ownerHandles.objectClass,
              ownerAttributes,
              reliable);
        },
        "changing default attribute transportation");
    check(
        [&] {
          owner.rtiAmbassador().queryAttributeTransportationType(
              object,
              ownerHandles.attribute);
        },
        "querying attribute transportation");
    check(
        [&] {
          owner.rtiAmbassador().requestInteractionTransportationTypeChange(
              ownerHandles.interactionClass,
              reliable);
        },
        "requesting an interaction transportation change");
    check(
        [&] {
          owner.rtiAmbassador().queryInteractionTransportationType(
              ownerFederate,
              ownerHandles.interactionClass);
        },
        "querying interaction transportation");

    check(
        [&] {
          owner.rtiAmbassador().queryAttributeOwnership(
              object,
              ownerAttributes);
        },
        "querying attribute ownership");
    check(
        [&] {
          owner.rtiAmbassador().isAttributeOwnedByFederate(
              object,
              ownerHandles.attribute);
        },
        "querying attribute ownership by federate");
    check(
        [&] {
          owner.rtiAmbassador().negotiatedAttributeOwnershipDivestiture(
              object,
              ownerAttributes,
              emptyTag);
        },
        "requesting negotiated divestiture");
    check(
        [&] {
          owner.rtiAmbassador().confirmDivestiture(
              object,
              ownerAttributes,
              emptyTag);
        },
        "confirming divestiture");
    check(
        [&] {
          owner.rtiAmbassador().cancelNegotiatedAttributeOwnershipDivestiture(
              object,
              ownerAttributes);
        },
        "cancelling negotiated divestiture");
    check(
        [&] {
          owner.rtiAmbassador().unconditionalAttributeOwnershipDivestiture(
              object,
              ownerAttributes,
              emptyTag);
        },
        "requesting unconditional divestiture");
    check(
        [&] {
          owner.rtiAmbassador().attributeOwnershipReleaseDenied(
              object,
              ownerAttributes,
              emptyTag);
        },
        "reporting denied ownership release");
    check(
        [&] {
          owner.rtiAmbassador().attributeOwnershipDivestitureIfWanted(
              object,
              ownerAttributes,
              emptyTag,
              divestedAttributes);
        },
        "requesting conditional divestiture");
    check(
        [&] {
          owner.rtiAmbassador().cancelAttributeOwnershipAcquisition(
              object,
              ownerAttributes);
        },
        "cancelling ownership acquisition");

    check(
        [&] {
          owner.rtiAmbassador().registerObjectInstance(
              ownerHandles.objectClass);
        },
        "registering an object instance");
    check(
        [&] {
          owner.rtiAmbassador().createRegion(
              rti::DimensionHandleSet{
                  ownerHandles.firstDimension,
                  ownerHandles.secondDimension});
        },
        "creating a region");
    check(
        [&] {
          owner.rtiAmbassador().updateAttributeValues(
              object,
              emptyAttributes,
              emptyTag);
        },
        "updating attribute values");
    check(
        [&] {
          owner.rtiAmbassador().sendInteraction(
              ownerHandles.interactionClass,
              emptyParameters,
              emptyTag);
        },
        "sending an interaction");
    check(
        [&] {
          owner.rtiAmbassador().attributeOwnershipAcquisition(
              object,
              ownerAttributes,
              emptyTag);
        },
        "acquiring attribute ownership");

    check(
        [&] {
          owner.rtiAmbassador().timeAdvanceRequest(*interlockTime);
        },
        "requesting a time advance");
    check(
        [&] {
          owner.rtiAmbassador().enableTimeRegulation(*ownerTime.epsilon);
        },
        "enabling time regulation");
    check(
        [&] {
          owner.rtiAmbassador().disableTimeRegulation();
        },
        "disabling time regulation");
    check(
        [&] {
          owner.rtiAmbassador().enableTimeConstrained();
        },
        "enabling time constrained");
    check(
        [&] {
          owner.rtiAmbassador().disableTimeConstrained();
        },
        "disabling time constrained");
    check(
        [&] {
          owner.rtiAmbassador().queryLogicalTime(*interlockTime);
        },
        "querying logical time");
    check(
        [&] {
          owner.rtiAmbassador().queryGALT(*interlockTime);
        },
        "querying GALT");
    check(
        [&] {
          owner.rtiAmbassador().queryLITS(*interlockTime);
        },
        "querying LITS");
    check(
        [&] {
          owner.rtiAmbassador().queryLookahead(*ownerTime.epsilon);
        },
        "querying lookahead");
    check(
        [&] {
          owner.rtiAmbassador().modifyLookahead(*ownerTime.epsilon);
        },
        "modifying lookahead");

    check(
        [&] {
          static_cast<void>(
              owner.rtiAmbassador().getAttributeScopeAdvisorySwitch());
        },
        "getting the attribute-scope advisory switch");
    check(
        [&] {
          owner.rtiAmbassador().setAttributeScopeAdvisorySwitch(false);
        },
        "setting the attribute-scope advisory switch");

    check(
        [&] {
          owner.rtiAmbassador().registerObjectInstanceWithRegions(
              ownerHandles.objectClass,
              attributeRegions);
        },
        "registering an object instance with regions");
    check(
        [&] {
          owner.rtiAmbassador().associateRegionsForUpdates(
              object,
              attributeRegions);
        },
        "associating regions for updates");
    check(
        [&] {
          owner.rtiAmbassador().unassociateRegionsForUpdates(
              object,
              attributeRegions);
        },
        "unassociating regions for updates");
    check(
        [&] {
          owner.rtiAmbassador().subscribeObjectClassAttributesWithRegions(
              ownerHandles.objectClass,
              attributeRegions);
        },
        "subscribing to regional object attributes");
    check(
        [&] {
          owner.rtiAmbassador().unsubscribeObjectClassAttributesWithRegions(
              ownerHandles.objectClass,
              attributeRegions);
        },
        "unsubscribing regional object attributes");
    check(
        [&] {
          owner.rtiAmbassador().requestAttributeValueUpdateWithRegions(
              ownerHandles.objectClass,
              attributeRegions,
              emptyTag);
        },
        "requesting regional attribute values");
    check(
        [&] {
          owner.rtiAmbassador().subscribeInteractionClassWithRegions(
              ownerHandles.interactionClass,
              regions);
        },
        "subscribing to regional interactions");
    check(
        [&] {
          owner.rtiAmbassador().unsubscribeInteractionClassWithRegions(
              ownerHandles.interactionClass,
              regions);
        },
        "unsubscribing regional interactions");
    check(
        [&] {
          owner.rtiAmbassador().sendInteractionWithRegions(
              ownerHandles.interactionClass,
              emptyParameters,
              regions,
              emptyTag);
        },
        "sending a regional interaction");

    rti::FederateHandleSet const synchronizationSet{ownerFederate};
    check(
        [&] {
          owner.rtiAmbassador().registerFederationSynchronizationPoint(
              L"tck-interlock-sync",
              emptyTag);
        },
        "registering a synchronization point");
    check(
        [&] {
          owner.rtiAmbassador().registerFederationSynchronizationPoint(
              L"tck-interlock-sync-set",
              emptyTag,
              synchronizationSet);
        },
        "registering an explicit-set synchronization point");
    check(
        [&] {
          owner.rtiAmbassador().synchronizationPointAchieved(
              L"tck-interlock-sync");
        },
        "achieving a synchronization point");
  };

  std::wstring const saveLabel = L"tck-save-restore-interlocks";
  owner.rtiAmbassador().requestFederationSave(saveLabel);
  waitForSessions(
      {&owner, &peer},
      [&] {
        return owner.federateSaveInitiations().size() >= 1U &&
            peer.federateSaveInitiations().size() >= 1U;
      },
      options,
      "save/restore interlock save initiation callbacks");
  owner.rtiAmbassador().federateSaveBegun();
  peer.rtiAmbassador().federateSaveBegun();
  checkInterlocks(L"SaveInProgress", "federation save");
  owner.rtiAmbassador().federateSaveComplete();
  peer.rtiAmbassador().federateSaveComplete();
  waitForSessions(
      {&owner, &peer},
      [&] {
        return owner.federationSavedCount() >= 1U &&
            peer.federationSavedCount() >= 1U;
      },
      options,
      "save/restore interlock save completion callbacks");
  require(
      owner.federationNotSavedReasons().empty() &&
          peer.federationNotSavedReasons().empty(),
      "save/restore interlock save reported a failure");

  owner.rtiAmbassador().requestFederationRestore(saveLabel);
  waitForSessions(
      {&owner, &peer},
      [&] {
        return owner.federationRestoreRequestsSucceeded().size() >= 1U &&
            owner.federationRestoreBegunCount() >= 1U &&
            peer.federationRestoreBegunCount() >= 1U &&
            owner.federateRestoreInitiations().size() >= 1U &&
            peer.federateRestoreInitiations().size() >= 1U;
      },
      options,
      "save/restore interlock restore initiation callbacks");
  checkInterlocks(L"RestoreInProgress", "federation restore");
  owner.rtiAmbassador().federateRestoreComplete();
  peer.rtiAmbassador().federateRestoreComplete();
  waitForSessions(
      {&owner, &peer},
      [&] {
        return owner.federationRestoredCount() >= 1U &&
            peer.federationRestoredCount() >= 1U;
      },
      options,
      "save/restore interlock restore completion callbacks");
  require(
      owner.federationNotRestoredReasons().empty() &&
          peer.federationNotRestoredReasons().empty(),
      "save/restore interlock restore reported a failure");

  owner.resign(rti::CANCEL_THEN_DELETE_THEN_DIVEST);
  peer.resign(rti::NO_ACTION);
  owner.rtiAmbassador().destroyFederationExecution(federation);
}

void scenarioTimedFederationSaveRestore(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.logicalTimeImplementationName.empty(),
      "Timed federation save/restore requires an adapter-supplied logical-time implementation");

  Session regulator(options, model, "owner");
  Session constrained(options, model, "member");
  auto const federation = federationName(options, "timed-federation-save-restore");
  connectAndJoin(regulator, constrained, options, federation, options.fom);

  auto regulatorTime = makeTimeContext(regulator);
  auto constrainedTime = makeTimeContext(constrained);
  enableTimestampedRoles(
      regulator,
      constrained,
      regulatorTime,
      constrainedTime,
      options,
      "timed federation save/restore");

  rti::ObjectClassHandle regulatorClass;
  rti::AttributeHandle regulatorAttribute;
  rti::InteractionClassHandle regulatorInteraction;
  rti::ParameterHandle regulatorParameter;
  handles(
      regulator,
      options,
      regulatorClass,
      regulatorAttribute,
      regulatorInteraction,
      regulatorParameter);
  auto const constrainedInteraction = constrained.rtiAmbassador().getInteractionClassHandle(
      options.interactionClassName);
  auto const constrainedParameter = constrained.rtiAmbassador().getParameterHandle(
      constrainedInteraction,
      options.parameterName);
  require(
      constrainedInteraction.isValid() && constrainedParameter.isValid(),
      "Timed federation save/restore constrained interaction lookup returned an invalid handle");

  regulator.rtiAmbassador().publishInteractionClass(regulatorInteraction);
  constrained.rtiAmbassador().subscribeInteractionClass(constrainedInteraction, true);
  regulator.rtiAmbassador().changeInteractionOrderType(
      regulatorInteraction,
      rti::TIMESTAMP);

  std::vector<std::uint8_t> payloadBytes{0x54U, 0x53U, 0x4FU};
  std::vector<std::uint8_t> tagBytes{0x53U, 0x41U, 0x56U, 0x45U};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      regulatorParameter,
      rti::VariableLengthData(payloadBytes.data(), payloadBytes.size()));
  rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());

  auto const saveTime = timeAfter(
      *regulatorTime.factory,
      *regulatorTime.initial,
      *regulatorTime.epsilon,
      2U);
  auto const queuedTime = timeAfter(
      *regulatorTime.factory,
      *regulatorTime.initial,
      *regulatorTime.epsilon,
      4U);
  auto const releaseTime = timeAfter(
      *regulatorTime.factory,
      *regulatorTime.initial,
      *regulatorTime.epsilon,
      6U);
  auto const retraction = regulator.rtiAmbassador().sendInteraction(
      regulatorInteraction,
      parameters,
      tag,
      *queuedTime);
  require(
      retraction.isValid(),
      "Timed federation save/restore returned an invalid message retraction handle");

  std::wstring const saveLabel = L"tck-timed-save-restore";
  regulator.rtiAmbassador().requestFederationSave(saveLabel, *saveTime);
  constrained.rtiAmbassador().timeAdvanceRequest(*saveTime);
  regulator.rtiAmbassador().timeAdvanceRequest(*saveTime);
  waitForSessions(
      {&regulator, &constrained},
      [&] {
        return regulator.federateSaveTimes().size() >= 1U &&
            constrained.federateSaveTimes().size() >= 1U;
      },
      options,
      "timed federate save initiation callbacks");
  auto const regulatorSaveTimes = regulator.federateSaveTimes();
  auto const constrainedSaveTimes = constrained.federateSaveTimes();
  require(
      regulatorSaveTimes.front().encoded == encodeTime(*saveTime) &&
          constrainedSaveTimes.front().encoded == encodeTime(*saveTime),
      "timed federate save initiation returned the wrong timestamp");
  require(
      regulator.federateSaveInitiations().front() == saveLabel &&
          constrained.federateSaveInitiations().front() == saveLabel,
      "timed federate save initiation returned the wrong label");

  regulator.rtiAmbassador().federateSaveBegun();
  constrained.rtiAmbassador().federateSaveBegun();
  regulator.rtiAmbassador().federateSaveComplete();
  constrained.rtiAmbassador().federateSaveComplete();
  waitForSessions(
      {&regulator, &constrained},
      [&] {
        return regulator.federationSavedCount() >= 1U &&
            constrained.federationSavedCount() >= 1U;
      },
      options,
      "timed federation saved callbacks");
  require(
      regulator.federationNotSavedReasons().empty() &&
          constrained.federationNotSavedReasons().empty(),
      "successful timed federation save reported a failure");

  regulator.rtiAmbassador().requestFederationRestore(saveLabel);
  waitForSessions(
      {&regulator, &constrained},
      [&] {
        return regulator.federationRestoreRequestsSucceeded().size() >= 1U &&
            regulator.federationRestoreBegunCount() >= 1U &&
            constrained.federationRestoreBegunCount() >= 1U &&
            regulator.federateRestoreInitiations().size() >= 1U &&
            constrained.federateRestoreInitiations().size() >= 1U;
      },
      options,
      "timed federation restore initiation callbacks");
  require(
      regulator.federationRestoreRequestsSucceeded().back() == saveLabel &&
          regulator.federationRestoreRequestsFailed().empty() &&
          constrained.federationRestoreRequestsFailed().empty(),
      "timed federation restore request returned an unexpected result");
  auto const regulatorRestore = regulator.federateRestoreInitiations().back();
  auto const constrainedRestore = constrained.federateRestoreInitiations().back();
  require(
      regulatorRestore.label == saveLabel && constrainedRestore.label == saveLabel &&
          regulatorRestore.federateName == options.ownerFederateName &&
          constrainedRestore.federateName == options.memberFederateName &&
          regulatorRestore.postRestoreFederateHandle.isValid() &&
          constrainedRestore.postRestoreFederateHandle.isValid(),
      "timed federation restore initiation returned incorrect identity data");

  regulator.rtiAmbassador().federateRestoreComplete();
  constrained.rtiAmbassador().federateRestoreComplete();
  waitForSessions(
      {&regulator, &constrained},
      [&] {
        return regulator.federationRestoredCount() >= 1U &&
            constrained.federationRestoredCount() >= 1U;
      },
      options,
      "timed federation restored callbacks");
  require(
      regulator.federationNotRestoredReasons().empty() &&
          constrained.federationNotRestoredReasons().empty(),
      "successful timed federation restore reported a failure");
  require(
      regulator.rtiAmbassador().getFederateHandle(options.ownerFederateName) ==
              regulatorRestore.postRestoreFederateHandle &&
          constrained.rtiAmbassador().getFederateHandle(options.memberFederateName) ==
              constrainedRestore.postRestoreFederateHandle,
      "timed federation restore did not rebind federate handles");

  constrained.recorder().clearTimedInteractions();
  constrained.recorder().clearFlushQueueGrants();
  constrained.recorder().clearCallbackOrder();
  constrained.recorder().clearRetractions();
  constrained.rtiAmbassador().flushQueueRequest(*releaseTime);
  waitFor(
      constrained,
      [&] {
        return constrained.recorder().timedInteractions().size() >= 1U &&
            constrained.recorder().flushQueueGrants().size() >= 1U;
      },
      options,
      "restored timestamped interaction and Flush Queue grant");
  auto const restoredInteractions = constrained.recorder().timedInteractions();
  require(
      restoredInteractions.size() == 1U,
      "timed federation restore delivered an unexpected number of interactions");
  auto const& restoredInteraction = restoredInteractions.front();
  require(
      restoredInteraction.interaction == constrainedInteraction &&
          restoredInteraction.parameters.size() == 1U &&
          restoredInteraction.parameters.count(constrainedParameter) == 1U &&
          copyBytes(restoredInteraction.parameters.at(constrainedParameter)) == payloadBytes &&
          restoredInteraction.tag == tagBytes &&
          restoredInteraction.producer == regulatorRestore.postRestoreFederateHandle &&
          restoredInteraction.time == encodeTime(*queuedTime) &&
          restoredInteraction.sentOrder == rti::TIMESTAMP &&
          restoredInteraction.receivedOrder == rti::TIMESTAMP &&
          restoredInteraction.retractionPresent,
      "restored timestamped interaction changed its public delivery data");
  auto const callbackOrder = constrained.recorder().callbackOrder();
  auto const interactionCallback = std::find(
      callbackOrder.begin(), callbackOrder.end(), "interaction");
  auto const grantCallback = std::find(
      callbackOrder.begin(), callbackOrder.end(), "flush-grant");
  require(
      interactionCallback != callbackOrder.end() && grantCallback != callbackOrder.end() &&
          interactionCallback < grantCallback,
      "restored timestamped interaction was not delivered before its Flush Queue grant");

  regulator.rtiAmbassador().retract(retraction);
  waitFor(
      constrained,
      [&] { return constrained.recorder().retractions().size() >= 1U; },
      options,
      "restored message retraction callback");
  auto const retractions = constrained.recorder().retractions();
  require(
      retractions.front().valid &&
          retractions.front().encoded == copyBytes(retraction.encode()),
      "restored message retraction returned the wrong handle");
  requireException(
      [&] { regulator.rtiAmbassador().retract(retraction); },
      L"MessageCanNoLongerBeRetracted",
      "second retraction of the restored message");

  constrained.rtiAmbassador().disableTimeConstrained();
  regulator.rtiAmbassador().disableTimeRegulation();
  constrained.rtiAmbassador().unsubscribeInteractionClass(constrainedInteraction);
  regulator.rtiAmbassador().unpublishInteractionClass(regulatorInteraction);
  constrained.resign(rti::NO_ACTION);
  regulator.resign(rti::NO_ACTION);
  regulator.rtiAmbassador().destroyFederationExecution(federation);
  constrained.disconnect();
  regulator.disconnect();
}

void scenarioTimedRegionalInteractionSaveRestore(
    Options const& options,
    rti::CallbackModel model) {
  require(
      !options.ddmFom.empty(),
      "Timed regional interaction save/restore requires an adapter-supplied dimensional FOM");
  require(
      !options.logicalTimeImplementationName.empty(),
      "Timed regional interaction save/restore requires an adapter-supplied logical-time implementation");

  Session publisher(options, model, "owner");
  Session receiver(options, model, "member");
  auto const federation = federationName(
      options,
      "timed-regional-interaction-save-restore");
  connectAndJoin(publisher, receiver, options, federation, options.ddmFom);

  auto const publisherHandles = ddmHandles(publisher, options);
  auto const receiverHandles = ddmHandles(receiver, options);
  verifyDdmClassDimensions(
      publisher,
      options,
      publisherHandles,
      "timed regional interaction save/restore");
  publisher.rtiAmbassador().publishInteractionClass(
      publisherHandles.interactionClass);
  publisher.rtiAmbassador().changeInteractionOrderType(
      publisherHandles.interactionClass,
      rti::TIMESTAMP);

  auto const sourceRegion = createDdmRegion(
      publisher,
      publisherHandles,
      1UL,
      5UL,
      1UL,
      5UL);
  auto const receiverRegion = createDdmRegion(
      receiver,
      receiverHandles,
      2UL,
      6UL,
      2UL,
      6UL);
  auto const sourceRegionSet = rti::RegionHandleSet{sourceRegion};
  auto const receiverRegionSet = rti::RegionHandleSet{receiverRegion};
  receiver.rtiAmbassador().setConveyRegionDesignatorSetsSwitch(true);
  require(
      receiver.rtiAmbassador().getConveyRegionDesignatorSetsSwitch(),
      "timed regional interaction save/restore did not enable region designator callbacks");
  receiver.rtiAmbassador().subscribeInteractionClassWithRegions(
      receiverHandles.interactionClass,
      receiverRegionSet,
      true);

  auto publisherTime = makeTimeContext(publisher);
  auto receiverTime = makeTimeContext(receiver);
  enableTimestampedRoles(
      publisher,
      receiver,
      publisherTime,
      receiverTime,
      options,
      "timed regional interaction save/restore");

  std::vector<std::uint8_t> const parameterBytes{
      0x54U, 0x49U, 0x4DU, 0x45U};
  std::vector<std::uint8_t> const tagBytes{0x52U, 0x45U, 0x47U};
  rti::ParameterHandleValueMap parameters;
  parameters.emplace(
      publisherHandles.parameter,
      rti::VariableLengthData(parameterBytes.data(), parameterBytes.size()));
  rti::VariableLengthData tag(tagBytes.data(), tagBytes.size());

  auto const saveTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      6U);
  auto const queuedTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      8U);
  auto const releaseTime = timeAfter(
      *publisherTime.factory,
      *publisherTime.initial,
      *publisherTime.epsilon,
      10U);
  auto const retraction = publisher.rtiAmbassador().sendInteractionWithRegions(
      publisherHandles.interactionClass,
      parameters,
      sourceRegionSet,
      tag,
      *queuedTime);
  require(
      retraction.isValid(),
      "timed regional interaction save/restore returned an invalid retraction handle");
  require(
      receiver.recorder().timedInteractions().empty(),
      "timed regional interaction save/restore delivered before the save frontier");

  std::wstring const saveLabel = L"tck-timed-regional-interaction-save-restore";
  publisher.rtiAmbassador().requestFederationSave(saveLabel, *saveTime);
  receiver.rtiAmbassador().timeAdvanceRequest(*saveTime);
  publisher.rtiAmbassador().timeAdvanceRequest(*saveTime);
  waitForSessions(
      {&publisher, &receiver},
      [&] {
        return publisher.federateSaveTimes().size() >= 1U &&
            receiver.federateSaveTimes().size() >= 1U;
      },
      options,
      "timed regional interaction save initiation callbacks");
  require(
      publisher.federateSaveTimes().front().encoded == encodeTime(*saveTime) &&
          receiver.federateSaveTimes().front().encoded == encodeTime(*saveTime),
      "timed regional interaction save initiation returned the wrong timestamp");

  publisher.rtiAmbassador().federateSaveBegun();
  receiver.rtiAmbassador().federateSaveBegun();
  publisher.rtiAmbassador().federateSaveComplete();
  receiver.rtiAmbassador().federateSaveComplete();
  waitForSessions(
      {&publisher, &receiver},
      [&] {
        return publisher.federationSavedCount() >= 1U &&
            receiver.federationSavedCount() >= 1U;
      },
      options,
      "timed regional interaction saved callbacks");
  require(
      publisher.federationNotSavedReasons().empty() &&
          receiver.federationNotSavedReasons().empty(),
      "timed regional interaction save reported a failure");

  // Cancel the queued message in the live execution. Restore must roll back
  // to the saved state and make the same public retraction handle deliverable.
  publisher.rtiAmbassador().retract(retraction);
  publisher.recorder().clearCallbackOrder();
  receiver.recorder().clearTimedInteractions();
  receiver.recorder().clearFlushQueueGrants();
  receiver.recorder().clearRetractions();
  receiver.recorder().clearCallbackOrder();

  publisher.rtiAmbassador().requestFederationRestore(saveLabel);
  waitForSessions(
      {&publisher, &receiver},
      [&] {
        return publisher.federationRestoreRequestsSucceeded().size() >= 1U &&
            publisher.federationRestoreBegunCount() >= 1U &&
            receiver.federationRestoreBegunCount() >= 1U &&
            publisher.federateRestoreInitiations().size() >= 1U &&
            receiver.federateRestoreInitiations().size() >= 1U;
      },
      options,
      "timed regional interaction restore initiation callbacks");
  require(
      publisher.federationRestoreRequestsSucceeded().back() == saveLabel &&
          publisher.federationRestoreRequestsFailed().empty() &&
          receiver.federationRestoreRequestsFailed().empty(),
      "timed regional interaction restore request returned an unexpected result");
  auto const publisherRestore = publisher.federateRestoreInitiations().back();
  auto const receiverRestore = receiver.federateRestoreInitiations().back();
  require(
      publisherRestore.label == saveLabel && receiverRestore.label == saveLabel &&
          publisherRestore.postRestoreFederateHandle.isValid() &&
          receiverRestore.postRestoreFederateHandle.isValid(),
      "timed regional interaction restore returned invalid identity data");

  publisher.rtiAmbassador().federateRestoreComplete();
  receiver.rtiAmbassador().federateRestoreComplete();
  waitForSessions(
      {&publisher, &receiver},
      [&] {
        return publisher.federationRestoredCount() >= 1U &&
            receiver.federationRestoredCount() >= 1U;
      },
      options,
      "timed regional interaction restored callbacks");
  require(
      publisher.federationNotRestoredReasons().empty() &&
          receiver.federationNotRestoredReasons().empty(),
      "timed regional interaction restore reported a failure");

  receiver.rtiAmbassador().flushQueueRequest(*releaseTime);
  waitFor(
      receiver,
      [&] {
        return receiver.recorder().timedInteractions().size() >= 1U &&
            receiver.recorder().flushQueueGrants().size() >= 1U;
      },
      options,
      "restored regional interaction and Flush Queue grant");
  auto const interactions = receiver.recorder().timedInteractions();
  require(
      interactions.size() == 1U,
      "timed regional interaction restore delivered an unexpected interaction count");
  auto const& interaction = interactions.front();
  require(
      interaction.interaction == receiverHandles.interactionClass &&
          interaction.parameters.size() == 1U &&
          interaction.parameters.count(receiverHandles.parameter) == 1U &&
          copyBytes(interaction.parameters.at(receiverHandles.parameter)) == parameterBytes &&
          interaction.tag == tagBytes &&
          interaction.producer == publisherRestore.postRestoreFederateHandle &&
          interaction.time == encodeTime(*queuedTime) &&
          interaction.sentOrder == rti::TIMESTAMP &&
          interaction.receivedOrder == rti::TIMESTAMP &&
          interaction.retractionPresent &&
          interaction.retraction == copyBytes(retraction.encode()) &&
          interaction.regions.has_value() && interaction.regions->size() == 1U &&
          interaction.regions->count(sourceRegion) == 1U,
      "timed regional interaction restore changed its public delivery data");
  auto const callbackOrder = receiver.recorder().callbackOrder();
  auto const interactionCallback = std::find(
      callbackOrder.begin(), callbackOrder.end(), "interaction");
  auto const grantCallback = std::find(
      callbackOrder.begin(), callbackOrder.end(), "flush-grant");
  require(
      interactionCallback != callbackOrder.end() && grantCallback != callbackOrder.end() &&
          interactionCallback < grantCallback,
      "restored regional interaction was not delivered before its Flush Queue grant");

  publisher.rtiAmbassador().retract(retraction);
  waitFor(
      receiver,
      [&] { return receiver.recorder().retractions().size() >= 1U; },
      options,
      "restored regional interaction retraction callback");
  require(
      receiver.recorder().retractions().front().valid &&
          receiver.recorder().retractions().front().encoded == copyBytes(retraction.encode()),
      "restored regional interaction retraction returned the wrong handle");
  requireException(
      [&] { publisher.rtiAmbassador().retract(retraction); },
      L"MessageCanNoLongerBeRetracted",
      "second retraction of restored regional interaction");

  receiver.rtiAmbassador().disableTimeConstrained();
  publisher.rtiAmbassador().disableTimeRegulation();
  receiver.rtiAmbassador().unsubscribeInteractionClassWithRegions(
      receiverHandles.interactionClass,
      receiverRegionSet);
  receiver.rtiAmbassador().deleteRegion(receiverRegion);
  publisher.rtiAmbassador().deleteRegion(sourceRegion);
  receiver.resign(rti::NO_ACTION);
  publisher.resign(rti::NO_ACTION);
  publisher.rtiAmbassador().destroyFederationExecution(federation);
  receiver.disconnect();
  publisher.disconnect();
}

